const PY_SOURCES = {
 "core/__init__.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Cœur de calcul de web-measures, exécuté dans le navigateur par Pyodide (repris du plugin\nQGIS « Visionneuse Panoramax », qui n'en a plus depuis le 29/10/2026).\n\nTriangulation, points 3D, terrain, précision GPS, calages, inclinaison automatique, axe de\nla route et mesures : du Python pur (numpy en option, pour l'inclinaison automatique). Ce qui\ndépend de la page (réseau, altitude NGF, décodage d'une photo, tâches de fond) passe par\nhost.py, que py/web_host.py remplit au démarrage. Essais sans réseau : tests/coeur/.\n\"\"\"\n",
 "core/autotilt.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Inclinaison d'une photo 360° calculée d'après ses verticales, sans clic.\n\nUne caméra montée sur un véhicule penche avec lui (pente de la route, dévers, virages) : 1 à\n3° sur les photos imajbox, autant d'erreur de visée. Sur une photo équirectangulaire\nde niveau, les arêtes verticales du monde (angles de façades, poteaux, encadrements) restent\nverticales dans l'image ; la caméra penchée, elles s'inclinent selon une loi connue.\n\n1. Bandes de BAND_DEG d'élévation, au-dessus de l'horizon (le sol, les véhicules et la\n   voiture de prise de vue sont en dessous) : pour chaque pente possible, somme du gradient\n   horizontal le long de droites de cette pente (transformée de Radon locale). Une arête\n   rectiligne y fait un pic net : sa position et sa pente donnent un segment.\n2. Chaque segment impose, comme un objet vertical cliqué (calibration.tilt_from_verticals),\n   que la vraie verticale soit dans le plan qui contient la caméra et le segment. Moindres\n   carrés sur des centaines de segments, rejet itératif des segments qui ne sont pas vraiment\n   verticaux (arbres, toits, objets penchés).\n\nValidé à Pouilly-en-Auxois (photos imajbox) : une inclinaison imposée de 1° est retrouvée à\n0,05° près ; il faut des bâtiments ou des poteaux tout autour (en campagne : pas assez de\nverticales, voir terrain_tilt pour l'estimation par le LiDAR HD).\n\nCalculs numpy seuls (sans OpenCV) ; la photo est décodée réduite et rognée à la\nbande utile (host.decode_band), en arrière-plan (host.run_task).\n\"\"\"\n\nimport importlib.util\nimport math\n\nfrom . import calibration, host, metadata, precision\n\nHAS_NUMPY = importlib.util.find_spec(\"numpy\") is not None  # calcul des verticales\n\nELEV_MIN, ELEV_MAX = 3.0, 45.0  # bande analysée (degrés au-dessus de l'horizon)\nBAND_DEG = 2.5  # hauteur d'une bande d'analyse (degrés) : arêtes courtes ou coupées comprises\n# Pente maximale retenue (pixels par pixel, ~6,8°) : une verticale vue à 45° au-dessus de\n# l'horizon penche de deux fois l'inclinaison de la caméra (jusqu'à 3° sur l'imajbox)\nMAX_SLOPE = 0.12\nSLOPE_RANGE = 0.13  # pentes calculées, de part et d'autre\nSLOPES = 131\nWIDTH = 6144  # largeur de travail (photo HD imajbox : 12 288, décodée au demi)\nMIN_SEGMENTS = 40\nMAX_SIGMA = 0.25  # incertitude maximale acceptée (degrés)\nEDGE_BIN = 0.3  # degrés de cap : segments d'une même arête (incertitude)\nFLOOR = math.radians(0.05)  # dispersion minimale des segments retenus (radians)\n\n\ndef segments(band, row0, height, width, azimuth):\n    \"\"\"Segments quasi verticaux de la bande : liste de ((cap, élév.) bas, (cap, élév.) haut),\n    directions brutes (cap de la photo `azimuth` ajouté, comme les clics).\"\"\"\n    import numpy as np\n\n    deg = 180.0 / height\n    rows = max(8, int(round(BAND_DEG / deg)))\n    gx = np.zeros_like(band)\n    gx[:, 1:-1] = band[:, 2:] - band[:, :-2]\n    slopes = np.linspace(-SLOPE_RANGE, SLOPE_RANGE, SLOPES)\n    offs = np.arange(rows) - (rows - 1) / 2.0\n    # Somme le long de x + b·(r − milieu), interpolée entre deux colonnes : pour chaque pente,\n    # la ligne r est lue décalée de base[r] (poids 1 − frac[r]) et de base[r] + 1 (frac[r]).\n    # Les décalages entiers possibles sont peu nombreux : chaque fenêtre est décalée une fois\n    # pour chacun, puis chaque pente lit d'un coup ses lignes dans ces copies et en fait la\n    # somme pondérée (einsum). Mêmes calculs qu'une ligne après l'autre, en 2 appels à numpy\n    # par pente au lieu de 4 par ligne : environ 3 fois plus rapide en Python natif, et bien\n    # plus dans le navigateur (Pyodide, où chaque appel coûte cher et où le produit matriciel\n    # n'est pas optimisé).\n    plan = []\n    for b in slopes:\n        shift = b * offs\n        base = np.floor(shift).astype(int)\n        frac = (shift - base).astype(np.float32)\n        plan.append((np.stack([base, base + 1]), np.stack([1 - frac, frac])))\n    low = min(int(p[0].min()) for p in plan)\n    high = max(int(p[0].max()) for p in plan)\n    lines = np.arange(rows)\n    out = []\n\n    def direction(px, py):\n        return ((px + 0.5) / width * 360.0 - 180.0 + azimuth) % 360, 90.0 - (py + 0.5) * deg\n\n    for top in range(0, band.shape[0] - rows + 1, rows // 2):\n        win = gx[top:top + rows]\n        shifted = np.stack([np.roll(win, -d, axis=1) for d in range(low, high + 1)])  # (décalage, ligne, x)\n        acc = np.empty((SLOPES, width), np.float32)\n        for k, (shifts, weights) in enumerate(plan):\n            acc[k] = np.einsum(\"kr,krx->x\", weights, shifted[shifts - low, lines])\n        acc = np.abs(acc)\n        best = acc.argmax(axis=0)\n        peak = acc[best, np.arange(width)]\n        thr = max(5.0 * rows, 4.0 * float(np.median(peak)))\n        local = peak >= np.maximum.reduce([np.roll(peak, d) for d in range(-4, 5)])\n        yc = row0 + top + (rows - 1) / 2.0\n        half = rows / 2.0\n        xs = np.nonzero(local & (peak > thr))[0]\n        xs = xs[np.abs(slopes[best[xs]]) <= MAX_SLOPE]  # pente dans la plage cherchée\n        if not len(xs):\n            continue\n        for xc, b, ok in zip(*_refine(win, xs, slopes[best[xs]], offs)):\n            if ok:\n                out.append((direction(xc + b * half, yc + half), direction(xc - b * half, yc - half)))\n    return out\n\n\ndef _refine(win, xs, slopes, offs, reach=5):\n    \"\"\"Position et pente précises des arêtes détectées aux colonnes `xs` avec les pentes\n    approchées `slopes` : centre du gradient sur chaque ligne (autour de la droite approchée),\n    puis droite des moindres carrés. Toutes les arêtes de la fenêtre à la fois (un appel à numpy\n    par étape pour toutes, et non par arête : plusieurs fois plus rapide, surtout dans Pyodide).\n    Rend (x au milieu de la bande, pente, ok) en tableaux ; ok faux si l'arête n'est pas\n    rectiligne ou pas continue sur toute la bande.\"\"\"\n    import numpy as np\n\n    width = win.shape[1]\n    a, b = xs.astype(float), slopes.astype(float)\n    ok = np.ones(len(xs), bool)\n    span = np.arange(-reach, reach + 1)\n    lines = np.arange(win.shape[0])[None, :, None]\n    for _ in range(3):  # recentrée sur la droite trouvée : moins d'effet de la grille des pixels\n        pred = a[:, None] + b[:, None] * offs  # (arête, ligne)\n        cols = np.round(pred).astype(int)[:, :, None] + span  # (arête, ligne, colonne voisine)\n        g = win[lines, cols % width]\n        sign = np.where(g.sum(axis=(1, 2)) >= 0, 1.0, -1.0).astype(win.dtype)\n        wts = np.clip(sign[:, None, None] * g, 0, None)\n        total = wts.sum(axis=2)\n        strong = np.where(total.any(axis=1)[:, None], total > 0.3 * np.median(total, axis=1)[:, None], total > 0)\n        ok &= strong.mean(axis=1) >= 0.8  # sinon arête interrompue\n        centre = (wts * cols).sum(axis=2) / np.where(strong, total, 1)\n        # Droite des moindres carrés sur les lignes nettes (m), écrite directement\n        m = strong.astype(float)\n        count = np.maximum(m.sum(axis=1), 1)\n        om, cm = (m * offs).sum(axis=1) / count, (m * centre).sum(axis=1) / count\n        do = (offs - om[:, None]) * m\n        den = (do * do).sum(axis=1)\n        b = np.where(ok, (do * (centre - cm[:, None])).sum(axis=1) / np.where(den > 0, den, 1), b)\n        a = np.where(ok, cm - b * om, a)\n    res = centre - (a[:, None] + b[:, None] * offs)\n    mean = (m * res).sum(axis=1) / count\n    ok &= np.sqrt((m * (res - mean[:, None]) ** 2).sum(axis=1) / count) <= 0.4  # sinon pas rectiligne\n    return a, b, ok\n\n\ndef fit(pairs):\n    \"\"\"Verticale vraie d'après des segments (voir calibration.tilt_from_verticals), avec rejet\n    itératif des segments qui s'en écartent. Retourne le dict de tilt_from_verticals\n    complété de sigma (incertitude, degrés), segments (retenus), auto=True, ou None si les\n    segments sont trop peu nombreux ou mal répartis.\"\"\"\n    normals, yaws = [], []\n    for bottom, top in pairs:\n        n = calibration._cross(calibration.vector(*bottom), calibration.vector(*top))\n        norm = math.sqrt(calibration._dot(n, n))\n        if norm > 0:\n            normals.append((n[0] / norm, n[1] / norm, n[2] / norm))\n            yaws.append(bottom[0])\n    keep = list(range(len(normals)))\n    up = (0.0, 0.0, 1.0)\n    for _ in range(8):\n        if len(keep) < 3:\n            return None\n        a11 = a12 = a22 = r1 = r2 = 0.0\n        for i in keep:\n            nx, ny, nz = normals[i]\n            a11 += nx * nx\n            a12 += nx * ny\n            a22 += ny * ny\n            r1 -= nx * nz\n            r2 -= ny * nz\n        det = a11 * a22 - a12 * a12\n        if det <= 0:\n            return None\n        a, b = (a22 * r1 - a12 * r2) / det, (a11 * r2 - a12 * r1) / det\n        up = calibration._unit((a, b, 1.0))\n        res = [calibration._dot(normals[i], up) for i in range(len(normals))]\n        kept = sorted(abs(res[i]) for i in keep)\n        sigma = max(1.4826 * kept[len(kept) // 2], FLOOR)\n        new = [i for i in range(len(normals)) if abs(res[i]) < 3 * sigma]\n        if new == keep:\n            break\n        keep = new\n    if len(keep) < MIN_SEGMENTS:\n        return None\n    # Incertitude : écart-type des segments sur l'information apportée, dans la direction la\n    # moins contrainte (segments mal répartis autour de la photo : une composante mal connue)\n    # Une arête donne un segment par bande qu'elle traverse : leurs erreurs ne sont pas\n    # indépendantes, on compte les arêtes distinctes (cap à EDGE_BIN° près).\n    lam = (a11 + a22) / 2 - math.sqrt(((a11 - a22) / 2) ** 2 + a12 * a12)\n    edges = len({round(yaws[i] / EDGE_BIN) for i in keep})\n    sigma_deg = math.degrees(sigma / math.sqrt(max(lam, 1e-12))) * math.sqrt(len(keep) / max(edges, 1))\n    if sigma_deg > MAX_SIGMA:\n        return None\n    tilt = math.degrees(math.acos(min(1.0, up[2])))\n    if tilt > calibration.MAX_TILT:\n        return None\n    return {\"up\": up, \"tilt\": tilt, \"toward\": math.degrees(math.atan2(up[0], up[1])) % 360,\n            \"residual\": math.degrees(sigma), \"partial\": False, \"count\": len(keep), \"sigma\": sigma_deg,\n            \"auto\": True}\n\n\ndef estimate(data, azimuth):\n    \"\"\"Inclinaison de la photo (octets JPEG, cap du centre de l'image) : dict de fit, ou None.\n    Photo décodée par l'hôte (host.decode_band), réduite à WIDTH et rognée à la bande utile.\"\"\"\n    band = host.decode_band(data, WIDTH, ELEV_MIN, ELEV_MAX)\n    if band is None:\n        return None\n    return fit(segments(*band, azimuth))\n\n\ndef lidar_url(lon, lat, heading):\n    \"\"\"URL des altitudes LiDAR HD sous le véhicule (voir calibration.lidar_points).\"\"\"\n    return precision.lidar_url(calibration.lidar_points(lon, lat, heading))\n\n\ndef fetch_ground(lon, lat, heading, done):\n    \"\"\"Altitudes du sol sous le véhicule : LiDAR HD, sinon RGE ALTI (precision.fetch_terrain).\"\"\"\n    precision.fetch_terrain(calibration.lidar_points(lon, lat, heading), done, timeout_ms=None)\n\n\ndef is_360(item):\n    \"\"\"Photo équirectangulaire (360°) ?\"\"\"\n    props = item.get(\"properties\", {}) or {}\n    try:\n        if float((props.get(\"pers:interior_orientation\") or {}).get(\"field_of_view\") or 0) >= 360:\n            return True\n    except (TypeError, ValueError):\n        pass\n    return (props.get(\"exif\") or {}).get(\"Xmp.GPano.ProjectionType\") == \"equirectangular\"\n\n\n\n\nclass TiltChecker:\n    \"\"\"Inclinaison automatique des photos : verticales de la photo HD (en arrière-plan) et\n    pente et dévers du LiDAR HD sous le véhicule. Le résultat est rangé dans le calage\n    (Calibration.set_auto), qui le conserve d'une session à l'autre ; une photo déjà\n    analysée ne l'est pas à nouveau. Seule la dernière photo demandée est analysée : celle\n    qu'on quitte est abandonnée (téléchargement interrompu, rien d'enregistré), elle sera\n    reprise si on y revient.\"\"\"\n\n    def __init__(self):\n        self._pending = {}  # photo -> rappels en attente\n        self._replies = {}  # photo -> téléchargement de la photo HD en cours\n        self.current = None  # dernière photo demandée\n        self.run = None  # calcul en arrière-plan : host.run_task, ou celui-ci (tests)\n\n    def pending(self, pic):\n        return pic in self._pending\n\n    def check(self, item, cal, done=None):\n        \"\"\"Lance l'analyse de la photo (fiche STAC) si elle n'a ni inclinaison calée à la main\n        sur deux objets ou plus, ni inclinaison automatique ; done() quand elle est rangée dans `cal` (ou abandonnée).\"\"\"\n        pic = item.get(\"id\")\n        callbacks = [done] if done else []\n        if pic != self.current:\n            self._abandon_others(pic)\n        self.current = pic\n        if not pic or cal.manual_complete(pic) or pic in cal.auto:\n            for cb in callbacks:\n                cb()\n            return\n        if pic in self._pending:\n            self._pending[pic] += callbacks\n            return\n        heading = metadata.precise_heading(item)\n        heading = metadata.item_heading(item) if heading is None else heading\n        try:\n            lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        except (KeyError, TypeError, ValueError):\n            lon = lat = None\n        if heading is None or lon is None or not is_360(item):\n            for cb in callbacks:\n                cb()\n            return\n        self._pending[pic] = callbacks\n        state = {}\n\n        def finish():\n            if self.current != pic:\n                return  # photo quittée : abandonnée (voir _abandon_others)\n            if \"lidar\" not in state or \"verticals\" not in state:\n                return  # l'autre moitié n'est pas encore arrivée\n            if state[\"lidar_error\"] and state[\"verticals\"] is None:\n                entry = None  # service injoignable : à refaire plus tard\n            else:\n                entry = {\"sequence\": item.get(\"collection\"), \"heading\": float(heading),\n                         \"verticals\": state[\"verticals\"], \"lidar\": state[\"lidar\"]}\n            for cb in [None] + self._pending.pop(pic, []):\n                if cb is None:\n                    if entry is not None:\n                        cal.set_auto(pic, entry)\n                else:\n                    cb()\n\n        def got_lidar(ground, source, error):\n            z = [] if error else list(ground or [])\n            ok = len(z) == len(calibration.LIDAR_GRID) and None not in z\n            state[\"lidar\"] = list(calibration.lidar_slopes(z)) if ok else None\n            state[\"lidar_error\"] = bool(error)\n            finish()\n\n        def got_image(data, error):\n            self._replies.pop(pic, None)\n            if self.current != pic:\n                return  # photo quittée pendant le téléchargement : pas de calcul\n            if error or not data:\n                analysed(None)\n            else:\n                (self.run or host.run_task)(estimate, (bytes(data), float(heading)), analysed)\n\n        def analysed(res):\n            state[\"verticals\"] = ({\"up\": list(res[\"up\"]), \"count\": res[\"count\"], \"sigma\": res[\"sigma\"]}\n                                  if res else None)\n            finish()\n\n        fetch_ground(lon, lat, heading, got_lidar)\n        href = ((item.get(\"assets\") or {}).get(\"hd\") or {}).get(\"href\")\n        if href and HAS_NUMPY:\n            self._replies[pic] = host.fetch(href, got_image, prefer_cache=True)\n        else:\n            analysed(None)\n\n    def _abandon_others(self, keep):\n        \"\"\"Abandonne l'analyse des photos autres que `keep` : téléchargements interrompus,\n        rappels oubliés, rien d'enregistré.\"\"\"\n        for pic in [p for p in self._pending if p != keep]:\n            self._pending.pop(pic, None)\n            reply = self._replies.pop(pic, None)\n            try:\n                if reply is not None:\n                    reply.abort()\n            except (AttributeError, RuntimeError):  # déjà terminé ou détruit\n                pass\n",
 "core/calibration.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Calage des photos : correction d'inclinaison et recalage du cap.\n\n- Inclinaison (par photo) : une caméra 360 est rarement parfaitement de niveau.\n  On clique le pied puis le sommet d'objets verticaux (poteau, angle de façade) :\n  chacun impose que la vraie verticale soit dans le plan qui contient la caméra\n  et l'objet. Un objet corrige la pente vue de côté dans sa direction ; deux\n  objets à peu près à angle droit corrigent l'inclinaison complète. Sans clic,\n  l'inclinaison est calculée d'après les verticales de la photo (autotilt.py), ou à\n  défaut estimée par la pente et le dévers du LiDAR HD sous le véhicule, quand la\n  séquence a montré que la caméra penche avec lui (voir lidar_model).\n- Hauteur de caméra (par séquence) : on mesure une longueur connue, au sol\n  (trait de marquage, place de stationnement) ou en hauteur (objet de hauteur\n  connue). Les longueurs mesurées étant à peu près proportionnelles à la\n  hauteur de la caméra, on cherche celle qui redonne la longueur connue.\n- Cap et position (par séquence, autour des photos utilisées) : on clique dans\n  la photo un repère visible sur la carte, puis ce repère sur la carte. Les\n  repères donnent, par relèvement, le décalage de cap et de position GPS des\n  photos, chacun gardant son a priori (cap et position d'origine à leur\n  précision) : un repère seul corrige surtout le cap, sans jamais le dégrader ;\n  trois repères ou plus bien répartis autour de la photo recalent la position.\n\nDirections : (cap absolu en degrés, 0 = nord, sens horaire ; élévation en\ndegrés). Les corrections s'appliquent dans cet ordre : inclinaison, puis cap.\nCalage gardé dans le navigateur (clé « calage », src/app.js) d'une séance à l'autre, jusqu'à\nce qu'il soit refait ou effacé ; exportable et importable (fichier JSON, dossier de travail).\n\"\"\"\n\nimport math\n\nfrom . import ground\nfrom .triangulation import _local, offset\n\nOBJECT_ERROR = 0.2  # écart d'un objet vertical cliqué à la verticale vraie (degrés : clics, objet)\nUNCALIBRATED = 2.0  # inclinaison d'une photo non calée (degrés) : 1 à 3° mesurés sur l'imajbox\nMAX_TILT = 10.0  # au-delà, les clics sont sûrement faux (objet penché, pied/sommet inversés)\nMIN_SPAN = 3.0  # écart d'élévation minimal entre pied et sommet (degrés)\nMAX_LEAN = 30.0  # écart de cap maximal entre pied et sommet d'un même objet vertical\nMAX_OFFSET = 20.0  # au-delà, le repère cliqué sur la carte n'est sûrement pas le bon\nMIN_LANDMARK = 5.0  # distance minimale du repère (m)\nAIM_ERROR = 0.1  # précision d'un clic dans la photo zoomée (degrés)\nMAP_ERROR = 0.5  # précision de position du repère sur la carte (m)\nDEFAULT_ACCURACY = 3.0  # précision GPS supposée quand la photo ne l'indique pas (m)\nSURVEY_PRIOR = 0.5  # précision du cap d'origine, matériel de relevé (degrés)\nPRIOR = 3.0  # précision du cap d'origine, autres appareils (boussole, trajectoire GPS)\nREACH = 300.0  # portée du recalage (m) autour des photos qui l'ont servi : le GPS dérive au-delà\nOUTLIER = 4.0  # un repère qui s'écarte de plus de OUTLIER écarts-types des autres est refusé\n# Inclinaison estimée par le LiDAR HD : plan du sol ajusté sous le véhicule, sur une grille de\n# LIDAR_ALONG m devant et derrière la caméra et LIDAR_ACROSS m à droite et à gauche (sous les\n# roues) ; la grille atténue l'arrondi au centimètre des altitudes du service. Validé à\n# Pouilly-en-Auxois (imajbox, 18 photos) : 0,4° d'écart en long et 0,5° en travers avec les\n# verticales.\nLIDAR_ALONG, LIDAR_ACROSS = 1.5, 0.8\nLIDAR_GRID = [(a * LIDAR_ALONG, c * LIDAR_ACROSS) for a in (-1, -0.5, 0, 0.5, 1) for c in (-1, 0, 1)]\nLIDAR_MIN_PHOTOS = 3  # photos de la séquence calées par leurs verticales pour valider le modèle\nLIDAR_MAX_SIGMA = 0.8  # au-delà, la caméra ne suit pas le véhicule (portée à pied, stabilisée)\nLIDAR_MIN_SIGMA = 0.3\n\n\nCAMERA_MIN, CAMERA_MAX = 0.3, 6.0  # plage de hauteurs de caméra admises (m)\n\n\ndef _fr(value, digits=1):\n    return \"{:.{}f}\".format(value, digits).replace(\".\", \",\")\n\n\nclass CalibrationError(ValueError):\n    \"\"\"Clics inexploitables (message destiné à l'utilisateur).\"\"\"\n\n\ndef vector(yaw, elev):\n    \"\"\"Vecteur unitaire (est, nord, haut) d'une direction.\"\"\"\n    y, e = math.radians(yaw), math.radians(elev)\n    return (math.sin(y) * math.cos(e), math.cos(y) * math.cos(e), math.sin(e))\n\n\ndef angles(v):\n    \"\"\"Direction (cap, élévation) d'un vecteur.\"\"\"\n    x, y, z = v\n    return math.degrees(math.atan2(x, y)) % 360, math.degrees(math.atan2(z, math.hypot(x, y)))\n\n\ndef _cross(a, b):\n    return (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])\n\n\ndef _dot(a, b):\n    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]\n\n\ndef _unit(v):\n    n = math.sqrt(_dot(v, v))\n    return (v[0] / n, v[1] / n, v[2] / n)\n\n\ndef tilt_from_verticals(verticals, prior=None):\n    \"\"\"Verticale vraie dans le repère de la photo, d'après des objets verticaux.\n\n    verticals : liste de ((cap, élév.) du pied, (cap, élév.) du sommet).\n    prior : (up, sigma en degrés), inclinaison déjà connue (calcul automatique) qui complète\n    les objets cliqués : chaque objet ne corrige que la composante qu'il voit, l'autre reste\n    celle de l'a priori.\n    Retourne un dict : up (vecteur unitaire), tilt (degrés), toward (cap vers\n    lequel le haut de la caméra penche), residual (écart moyen des objets à la\n    verticale retenue, degrés, None avec un seul objet), partial (vrai si un\n    seul objet ou des objets alignés, sans a priori : seule une composante est corrigée),\n    sigma (incertitude, degrés, dans la direction la moins contrainte).\n    \"\"\"\n    normals = []\n    for bottom, top in verticals:\n        if top[1] - bottom[1] < MIN_SPAN:\n            raise CalibrationError(\"Cliquez d'abord le pied, puis le sommet de l'objet vertical, \"\n                                   \"assez haut (au moins {:.0f}° plus haut).\".format(MIN_SPAN))\n        if abs((top[0] - bottom[0] + 540) % 360 - 180) > MAX_LEAN:\n            raise CalibrationError(\"Le pied et le sommet ne semblent pas appartenir au même objet vertical.\")\n        normals.append(_unit(_cross(vector(*bottom), vector(*top))))\n    # Verticale vraie (a, b, 1) : n·(a, b, 1) = 0 pour chaque objet, moindres carrés.\n    # Un léger amortissement donne la plus petite correction compatible quand les objets\n    # ne suffisent pas (un seul objet, ou objets dans la même direction).\n    # Chaque objet pèse 1 / OBJECT_ERROR² ; l'a priori, 1 / sigma² sur chaque composante.\n    w = 1.0 / math.radians(OBJECT_ERROR) ** 2\n    a11 = a12 = a22 = r1 = r2 = 0.0\n    for nx, ny, nz in normals:\n        a11 += w * nx * nx\n        a12 += w * nx * ny\n        a22 += w * ny * ny\n        r1 -= w * nx * nz\n        r2 -= w * ny * nz\n    seen = (a11, a12, a22)  # information des seuls objets\n    if prior is not None:\n        pup, psigma = prior\n        wp = 1.0 / math.radians(max(psigma, 0.01)) ** 2\n        a11, a22 = a11 + wp, a22 + wp\n        r1, r2 = r1 + wp * pup[0] / pup[2], r2 + wp * pup[1] / pup[2]\n        damp = 0.0\n    else:\n        damp = 1e-6 * max(a11 + a22, 1e-12)\n        a11, a22 = a11 + damp, a22 + damp\n    det = a11 * a22 - a12 * a12\n    a, b = (a22 * r1 - a12 * r2) / det, (a11 * r2 - a12 * r1) / det\n    up = _unit((a, b, 1.0))\n    tilt = math.degrees(math.acos(min(1.0, up[2])))\n    if tilt > MAX_TILT:\n        raise CalibrationError(\"Inclinaison trouvée de {:.0f}° : objet pas vraiment vertical ou clics \"\n                               \"imprécis. Recommencez sur un autre objet.\".format(tilt))\n    # Partiel si les plans des objets se coupent mal (objets dans la même direction)\n    s11, s12, s22 = seen\n    partial = prior is None and (len(normals) < 2 or s11 * s22 - s12 * s12 < 0.1 * ((s11 + s22) / 2) ** 2)\n    lam = (a11 + a22) / 2 - math.sqrt(((a11 - a22) / 2) ** 2 + a12 * a12)  # moins contrainte\n    residual = None\n    if len(normals) > 1:\n        residual = math.degrees(math.sqrt(sum(math.asin(min(1.0, abs(_dot(n, up)))) ** 2\n                                              for n in normals) / len(normals)))\n    sigma = UNCALIBRATED if partial else math.degrees(1.0 / math.sqrt(max(lam, 1e-12)))\n    if residual is not None and not partial:\n        sigma = max(sigma, residual / math.sqrt(len(normals)))\n    return {\"up\": up, \"tilt\": tilt, \"toward\": math.degrees(math.atan2(up[0], up[1])) % 360,\n            \"residual\": residual, \"partial\": partial, \"count\": len(normals), \"sigma\": sigma}\n\n\ndef tilt_components(up, heading):\n    \"\"\"(avant, droite) en degrés : de combien la verticale vraie, vue de la caméra, penche\n    vers l'avant (cap `heading`) et vers la droite. Une caméra qui monte une pente de p° voit\n    la verticale pencher de p° vers l'avant ; inclinée vers la gauche, vers la droite.\"\"\"\n    h = math.radians(heading)\n    return (math.degrees(math.atan2(up[0] * math.sin(h) + up[1] * math.cos(h), up[2])),\n            math.degrees(math.atan2(up[0] * math.cos(h) - up[1] * math.sin(h), up[2])))\n\n\ndef up_from_components(forward, right, heading):\n    \"\"\"Verticale vraie (repère de la photo) penchée de forward° vers l'avant et right° vers la\n    droite (inverse de tilt_components).\"\"\"\n    h = math.radians(heading)\n    f, r = math.tan(math.radians(forward)), math.tan(math.radians(right))\n    return _unit((f * math.sin(h) + r * math.cos(h), f * math.cos(h) - r * math.sin(h), 1.0))\n\n\ndef lidar_points(lon, lat, heading):\n    \"\"\"Points du sol où lire le LiDAR HD : grille LIDAR_GRID (en avant, à droite) autour de\n    la caméra.\"\"\"\n    out = []\n    for along, right in LIDAR_GRID:\n        p = offset(lon, lat, heading, along) if along else (lon, lat)\n        out.append(offset(p[0], p[1], heading + 90, right) if right else p)\n    return out\n\n\ndef lidar_slopes(z):\n    \"\"\"(pente en long, dévers) en degrés du plan ajusté sur les altitudes des lidar_points\n    (grille symétrique : les pentes sont des moyennes pondérées indépendantes). La verticale\n    penche vers l'avant en montée, vers la droite quand la droite est plus haute.\"\"\"\n    sa = sum(a * h for (a, _), h in zip(LIDAR_GRID, z)) / sum(a * a for a, _ in LIDAR_GRID)\n    sc = sum(c * h for (_, c), h in zip(LIDAR_GRID, z)) / sum(c * c for _, c in LIDAR_GRID)\n    return math.degrees(math.atan(sa)), math.degrees(math.atan(sc))\n\n\ndef lidar_model(entries):\n    \"\"\"Modèle de la séquence : la caméra penche-t-elle avec le véhicule ? entries : inclinaisons\n    automatiques des photos de la séquence (voir Calibration.auto). Retourne le décalage moyen\n    (avant, droite) entre verticales et LiDAR (fixation de la caméra), l'écart-type sigma et le\n    nombre de photos, ou None si trop peu de photos le vérifient ou si l'écart est trop grand.\"\"\"\n    diffs = []\n    for e in entries:\n        v, lidar = e.get(\"verticals\"), e.get(\"lidar\")\n        if v and lidar:\n            f, r = tilt_components(v[\"up\"], e[\"heading\"])\n            diffs.append((f - lidar[0], r - lidar[1]))\n    if len(diffs) < LIDAR_MIN_PHOTOS:\n        return None\n    n = len(diffs)\n    mf, mr = sum(d[0] for d in diffs) / n, sum(d[1] for d in diffs) / n\n    sigma = math.sqrt(sum((d[0] - mf) ** 2 + (d[1] - mr) ** 2 for d in diffs) / (2 * max(n - 1, 1)))\n    if sigma > LIDAR_MAX_SIGMA:\n        return None\n    return {\"offset\": (mf, mr), \"sigma\": max(sigma, LIDAR_MIN_SIGMA), \"count\": n}\n\n\ndef untilt(up, yaw, elev, inverse=False):\n    \"\"\"Direction corrigée : rotation qui ramène la verticale `up` au zénith. inverse : la\n    rotation contraire, d'une direction vraie à la direction vue par la caméra penchée.\"\"\"\n    v = vector(yaw, elev)\n    k = (up[1], -up[0], 0.0)  # up × zénith\n    s = math.hypot(k[0], k[1])\n    if s < 1e-12:\n        return yaw % 360, elev\n    k = (k[0] / s, k[1] / s, 0.0)\n    c = up[2]\n    if inverse:\n        s = -s\n    kxv, kv = _cross(k, v), _dot(k, v)\n    r = tuple(v[i] * c + kxv[i] * s + k[i] * kv * (1 - c) for i in range(3))  # Rodrigues\n    return angles(r)\n\n\ndef _reference_length(kind, camera_height, clicks):\n    \"\"\"Longueur mesurée (m) avec une hauteur de caméra donnée : distance entre deux\n    points au sol (\"ground\") ou hauteur d'un objet, pied puis sommet (\"height\").\"\"\"\n    if kind == \"height\":\n        return ground.measure_height(camera_height, *clicks)[\"value\"]\n    ground_z = (clicks[0].get(\"profile\") or ground.flat_profile())[0][1]  # même caméra pour les deux clics\n    (_, p, z1), (_, q, z2) = (ground._ground_point(camera_height, c, ground_z) for c in clicks)\n    x, y = _local(q[0], q[1], p[0], p[1])\n    return math.sqrt(x * x + y * y + (z2 - z1) ** 2)\n\n\ndef _solve_height(kind, clicks, known):\n    \"\"\"Hauteur de caméra qui redonne la longueur connue (dichotomie : la longueur\n    mesurée croît avec la hauteur de caméra).\"\"\"\n    def excess(h):\n        try:\n            return _reference_length(kind, h, clicks) - known\n        except ground.GroundError:\n            return float(\"inf\")  # point trop loin : caméra trop haute\n\n    lo, hi = CAMERA_MIN, CAMERA_MAX\n    if excess(lo) > 0:\n        raise CalibrationError(\"Longueur mesurée trop grande même avec une caméra à {} m : vérifiez la \"\n                               \"longueur connue et les clics.\".format(str(CAMERA_MIN).replace(\".\", \",\")))\n    if excess(hi) < 0:\n        raise CalibrationError(\"Longueur mesurée trop petite même avec une caméra à {} m : vérifiez la \"\n                               \"longueur connue et les clics.\".format(str(CAMERA_MAX).replace(\".\", \",\")))\n    for _ in range(40):\n        mid = (lo + hi) / 2.0\n        if excess(mid) > 0:\n            hi = mid\n        else:\n            lo = mid\n    return (lo + hi) / 2.0\n\n\ndef camera_height(kind, clicks, known, tilt_sigma=None):\n    \"\"\"Hauteur de caméra (m) et son incertitude, d'après une longueur connue.\n\n    kind : \"ground\" (deux clics au sol) ou \"height\" (pied au sol, puis sommet) ;\n    clicks : dicts avec elev (corrigée de l'inclinaison), yaw, lon, lat, profile.\n    L'incertitude combine (somme quadratique) l'inclinaison de la photo, commune aux deux\n    clics (tilt_sigma degrés, UNCALIBRATED par défaut), et la visée de chaque clic (AIM_ERROR).\n    \"\"\"\n    if known <= 0:\n        raise CalibrationError(\"Indiquez la longueur connue.\")\n    if kind == \"height\" and clicks[0].get(\"pic\") != clicks[1].get(\"pic\"):\n        raise CalibrationError(\"Le pied et le sommet doivent être cliqués sur la même photo.\")\n    try:\n        h = _solve_height(kind, clicks, known)\n    except ground.GroundError as exc:\n        raise CalibrationError(str(exc))\n    tilt_sigma = UNCALIBRATED if tilt_sigma is None else tilt_sigma\n    groups = []\n    for north, east in ((tilt_sigma, 0.0), (0.0, tilt_sigma)):\n        variants = []\n        for sign in (-1, 1):\n            up = up_from_components(sign * north, sign * east, 0.0)\n            variants.append([dict(c, **dict(zip((\"yaw\", \"elev\"), untilt(up, c[\"yaw\"], c[\"elev\"])))) for c in clicks])\n        groups.append(variants)\n    for i in range(len(clicks)):\n        variants = []\n        for sign in (-1, 1):\n            moved = [dict(c) for c in clicks]\n            moved[i][\"elev\"] += sign * AIM_ERROR\n            variants.append(moved)\n        groups.append(variants)\n    total = 0.0\n    for variants in groups:\n        worst = 0.0\n        for moved in variants:\n            try:\n                worst = max(worst, abs(_solve_height(kind, moved, known) - h))\n            except (CalibrationError, ground.GroundError):\n                worst = max(worst, h)  # référence trop loin pour être fiable\n        total += worst * worst\n    return h, max(math.sqrt(total), 0.005)\n\n\nclass Calibration:\n    \"\"\"Calages : inclinaison par photo ; cap, position et hauteur de caméra par séquence.\n\n    Seules les observations sont conservées (clics et repères) : les corrections en sont\n    recalculées. to_dict / load permettent de les enregistrer (dans le navigateur), merge\n    d'y ajouter un calage enregistré ailleurs (fichier importé) ;\n    `changed`, s'il est défini, est appelé après chaque modification.\n    \"\"\"\n\n    FORMAT = 1  # version du format enregistré\n\n    def __init__(self):\n        self.verticals = {}  # pic -> [((cap, élév.) pied, (cap, élév.) sommet)]\n        self.landmarks = {}  # séquence -> [dicts : pic, lon, lat, yaw, elev, mlon, mlat, accuracy, prior]\n        # séquence -> calages de la hauteur de caméra : dicts kind, known, clicks (clics bruts,\n        # recalculés avec le calage actuel, voir camera), ou (hauteur, incertitude) enregistrés\n        # par une version précédente (valeur figée)\n        self.heights = {}\n        self._cameras = {}  # séquence -> hauteur recalculée (cache, vidé à chaque modification)\n        # pic -> inclinaison automatique : sequence, heading (cap du centre de l'image),\n        # verticals (up, count, sigma : d'après les verticales de la photo, ou None), lidar\n        # ((pente, dévers) en degrés sous le véhicule, ou None)\n        self.auto = {}\n        self._tilts = {}\n        self._models = {}  # séquence -> lidar_model (cache)\n        self.lidar = True  # False sur un pont : pente du terrain sous l'ouvrage, pas celle du tablier\n        self.changed = None\n\n    def _notify(self):\n        self._cameras = {}  # l'inclinaison ou le cap ont pu changer : hauteurs à recalculer\n        if self.changed is not None:\n            self.changed()\n\n    # Enregistrement --------------------------------------------------------\n    def to_dict(self):\n        return {\n            \"format\": self.FORMAT,\n            \"verticals\": {pic: [[list(b), list(t)] for b, t in v] for pic, v in self.verticals.items()},\n            \"landmarks\": self.landmarks,\n            \"heights\": {seq: [o if isinstance(o, dict) else list(o) for o in obs] for seq, obs in self.heights.items()},\n            \"auto\": self.auto,\n        }\n\n    def load(self, data):\n        \"\"\"Remplace le calage par celui enregistré (dict de to_dict, ou None : calage vide).\n        Les entrées illisibles sont ignorées. Ne déclenche pas `changed`.\"\"\"\n        self.verticals, self.landmarks, self.heights, self._tilts = {}, {}, {}, {}\n        self.auto, self._models, self._cameras = {}, {}, {}\n        if not isinstance(data, dict) or data.get(\"format\") != self.FORMAT:\n            return\n        keys = (\"pic\", \"lon\", \"lat\", \"yaw\", \"elev\", \"mlon\", \"mlat\", \"accuracy\", \"prior\")\n        try:\n            for pic, verticals in (data.get(\"verticals\") or {}).items():\n                verticals = [((float(b[0]), float(b[1])), (float(t[0]), float(t[1]))) for b, t in verticals]\n                try:\n                    self._tilts[pic] = tilt_from_verticals(verticals)\n                    self.verticals[pic] = verticals\n                except CalibrationError:\n                    pass\n            for seq, obs in (data.get(\"landmarks\") or {}).items():\n                obs = [{k: (o[k] if k == \"pic\" else float(o[k])) for k in keys} for o in obs]\n                if obs:\n                    self.landmarks[seq] = obs\n            for seq, obs in (data.get(\"heights\") or {}).items():\n                obs = [o for o in (_height_obs(o) for o in obs) if o is not None]\n                if obs:\n                    self.heights[seq] = obs\n            for pic, entry in (data.get(\"auto\") or {}).items():\n                entry = _auto_entry(entry)\n                if entry:\n                    self.auto[pic] = entry\n        except (TypeError, ValueError, KeyError, IndexError, AttributeError):\n            pass  # format abîmé : on garde ce qui a pu être lu\n\n    def merge(self, data):\n        \"\"\"Ajoute le calage enregistré `data` (dict de to_dict) pour les photos et séquences\n        qui n'en ont pas encore : le calage en cours, plus récent, l'emporte. Ne déclenche pas\n        `changed`. Retourne le nombre de photos et séquences ajoutées.\"\"\"\n        other = Calibration()\n        other.load(data)\n        added = 0\n        for mine, theirs in ((self.verticals, other.verticals), (self.landmarks, other.landmarks),\n                             (self.heights, other.heights), (self.auto, other.auto)):\n            for key, obs in theirs.items():\n                if key not in mine:\n                    mine[key] = obs\n                    added += 1\n        for pic, tilt in other._tilts.items():\n            self._tilts.setdefault(pic, tilt)\n        self._models, self._cameras = {}, {}\n        return added\n\n    # Inclinaison ---------------------------------------------------------\n    def add_vertical(self, pic, bottom, top):\n        verticals = self.verticals.get(pic, []) + [(bottom, top)]\n        result = tilt_from_verticals(verticals)  # lève CalibrationError sans rien garder\n        self.verticals[pic], self._tilts[pic] = verticals, result\n        self._notify()\n        return result\n\n    def tilt(self, pic):\n        \"\"\"Inclinaison de la photo (dict de tilt_from_verticals, avec sigma en degrés), ou None.\n        Dans l'ordre : calée à la main sur deux objets ou plus (source \"clics\") ; calée à la\n        main sur un objet et complétée par l'inclinaison automatique (\"clics + verticales\",\n        \"clics + lidar\") ; calculée d'après les verticales de la photo (\"verticales\") ;\n        estimée par le LiDAR HD (\"lidar\").\"\"\"\n        manual, auto = self._tilts.get(pic), self.auto_tilt(pic)\n        if manual and (not manual[\"partial\"] or auto is None):\n            return dict(manual, source=\"clics\")\n        if manual:\n            combined = tilt_from_verticals(self.verticals[pic], (auto[\"up\"], auto[\"sigma\"]))\n            return dict(combined, source=\"clics + \" + auto[\"source\"])\n        return auto\n\n    def manual_complete(self, pic):\n        \"\"\"Inclinaison calée à la main sur assez d'objets pour se passer du calcul automatique.\"\"\"\n        manual = self._tilts.get(pic)\n        return bool(manual) and not manual[\"partial\"]\n\n    def auto_tilt(self, pic):\n        \"\"\"Inclinaison automatique de la photo (verticales, sinon LiDAR HD), ou None.\"\"\"\n        entry = self.auto.get(pic)\n        if not entry:\n            return None\n        v = entry.get(\"verticals\")\n        if v:\n            up = tuple(v[\"up\"])\n            return {\"up\": up, \"tilt\": math.degrees(math.acos(min(1.0, up[2]))),\n                    \"toward\": math.degrees(math.atan2(up[0], up[1])) % 360, \"residual\": None, \"partial\": False,\n                    \"count\": v[\"count\"], \"sigma\": v[\"sigma\"], \"source\": \"verticales\"}\n        model = self.lidar_model(entry.get(\"sequence\")) if self.lidar else None\n        if model and entry.get(\"lidar\"):\n            f = entry[\"lidar\"][0] + model[\"offset\"][0]\n            r = entry[\"lidar\"][1] + model[\"offset\"][1]\n            up = up_from_components(f, r, entry[\"heading\"])\n            return {\"up\": up, \"tilt\": math.hypot(f, r), \"toward\": math.degrees(math.atan2(up[0], up[1])) % 360,\n                    \"residual\": None, \"partial\": False, \"count\": model[\"count\"], \"sigma\": model[\"sigma\"],\n                    \"source\": \"lidar\"}\n        return None\n\n    def set_auto(self, pic, entry):\n        \"\"\"Inclinaison automatique de la photo (voir self.auto), enregistrée.\"\"\"\n        self.auto[pic] = entry\n        self._models.pop(entry.get(\"sequence\"), None)\n        self._notify()\n\n    def lidar_model(self, sequence):\n        \"\"\"Modèle LiDAR de la séquence (voir lidar_model), ou None.\"\"\"\n        if sequence is None:\n            return None\n        if sequence not in self._models:\n            self._models[sequence] = lidar_model([e for e in self.auto.values() if e.get(\"sequence\") == sequence])\n        return self._models[sequence]\n\n    def clear_tilt(self, pic):\n        self.verticals.pop(pic, None)\n        self._tilts.pop(pic, None)\n        self._notify()\n\n    def untilted(self, pic, yaw, elev):\n        t = self.tilt(pic)\n        return untilt(t[\"up\"], yaw, elev) if t else (yaw % 360, elev)\n\n    # Hauteur de caméra --------------------------------------------------------\n    def add_camera_height(self, sequence, kind, clicks, known):\n        \"\"\"Calage de la hauteur de caméra sur une longueur connue (clics corrigés du calage\n        actuel). Les clics bruts sont conservés : la hauteur est recalculée si l'inclinaison ou\n        le cap de la photo changent ensuite (voir camera). Plus appelé par la page depuis le 16/10/2026 (calage de la\n        hauteur retiré) : décrit la forme des hauteurs gardées, et sert aux essais.\"\"\"\n        h, sigma = camera_height(kind, clicks, known, self._tilt_sigma(clicks[0].get(\"pic\")))\n        keep = (\"pic\", \"sequence\", \"lon\", \"lat\", \"gps\", \"raw\", \"yaw\", \"elev\", \"profile\")\n        obs = {\"kind\": kind, \"known\": float(known),\n               \"clicks\": [{k: c[k] for k in keep if c.get(k) is not None} for c in clicks]}\n        self.heights.setdefault(sequence, []).append(obs)\n        self._notify()\n        return {\"height\": h, \"sigma\": sigma}\n\n    def _height_of(self, sequence, obs):\n        \"\"\"(hauteur, incertitude) d'un calage de la hauteur de caméra, avec le calage actuel.\"\"\"\n        if not isinstance(obs, dict):\n            return tuple(obs)\n        clicks = []\n        for c in obs[\"clicks\"]:\n            if c.get(\"raw\"):  # direction brute : corrigée du calage actuel\n                lon, lat = c.get(\"gps\") or (c[\"lon\"], c[\"lat\"])\n                yaw, elev = self.correct(c.get(\"pic\"), sequence, c[\"raw\"][0], c[\"raw\"][1], lon, lat)\n            else:  # direction déjà corrigée, figée\n                yaw, elev = c[\"yaw\"], c[\"elev\"]\n            clicks.append(dict(c, yaw=yaw, elev=elev))\n        try:\n            return camera_height(obs[\"kind\"], clicks, obs[\"known\"], self._tilt_sigma(clicks[0].get(\"pic\")))\n        except (CalibrationError, ground.GroundError):\n            return None\n\n    def _tilt_sigma(self, pic):\n        \"\"\"Incertitude (degrés) de l'inclinaison de la photo, UNCALIBRATED sans calage.\"\"\"\n        t = self.tilt(pic) if pic else None\n        return t[\"sigma\"] if t and t.get(\"sigma\") is not None else UNCALIBRATED\n\n    def camera(self, sequence):\n        \"\"\"Hauteur de caméra calée de la séquence : dict height, sigma, count, legacy (calages\n        d'une version précédente, figés), ou None.\"\"\"\n        obs_list = self.heights.get(sequence) or []\n        key = (id(obs_list), len(obs_list))  # calages ajoutés ou remplacés directement\n        if self._cameras.get(sequence, (None,))[0] == key:\n            return self._cameras[sequence][1]\n        values, legacy = [], 0\n        for o in obs_list:\n            v = self._height_of(sequence, o)\n            if v is not None:\n                values.append(v)\n                legacy += not isinstance(o, dict)\n        res = None\n        if values:\n            sw = sum(1.0 / s ** 2 for _, s in values)\n            res = {\"height\": sum(h / s ** 2 for h, s in values) / sw, \"sigma\": 1.0 / math.sqrt(sw),\n                   \"count\": len(values), \"legacy\": legacy}\n        self._cameras[sequence] = (key, res)\n        return res\n\n    # Cap -------------------------------------------------------------------\n    def add_landmark(self, sequence, pic, lon, lat, yaw, elev, mlon, mlat, accuracy, survey):\n        \"\"\"Repère : clic (cap, élév. bruts) depuis la photo en (lon, lat), repère en (mlon, mlat). Plus appelé par la\n        page depuis le 16/10/2026 (calage du cap retiré) : décrit la forme des repères gardés, et sert aux essais.\"\"\"\n        obs = {\"pic\": pic, \"lon\": lon, \"lat\": lat, \"yaw\": yaw, \"elev\": elev, \"mlon\": mlon, \"mlat\": mlat,\n               \"accuracy\": DEFAULT_ACCURACY if accuracy is None else float(accuracy),\n               \"prior\": SURVEY_PRIOR if survey else PRIOR}\n        offset, sigma, dist = self._landmark_offset(obs)\n        if dist < MIN_LANDMARK:\n            raise CalibrationError(\"Repère à {} m de la photo : choisissez un repère plus éloigné.\".format(_fr(dist)))\n        # L'écart toléré tient compte du décalage de position GPS possible (repère proche)\n        if abs(offset) > MAX_OFFSET + math.degrees(math.atan2(2 * obs[\"accuracy\"], dist)):\n            raise CalibrationError(\"Écart de cap de {:.0f}° : ce n'est sûrement pas le même repère sur la \"\n                                   \"carte et dans la photo.\".format(offset))\n        others = self.landmarks.get(sequence, [])\n        if len(others) >= 3:\n            # Contrôle : direction du repère prédite par les autres repères seuls\n            pose = self._solve_pose(others)\n            yaw, _ = self.untilted(obs[\"pic\"], obs[\"yaw\"], obs[\"elev\"])\n            x, y = _local(obs[\"mlon\"], obs[\"mlat\"], obs[\"lon\"], obs[\"lat\"])\n            x, y = x - pose[\"shift\"][0], y - pose[\"shift\"][1]\n            r = abs((math.degrees(math.atan2(x, y)) - yaw - pose[\"offset\"] + 540) % 360 - 180)\n            spread = math.hypot(AIM_ERROR, math.degrees(math.atan2(MAP_ERROR, dist)), pose[\"sigma\"],\n                                math.degrees(math.atan2(pose[\"shift_sigma\"], dist)))\n            if r > max(1.0, OUTLIER * spread):\n                raise CalibrationError(\"Ce repère s'écarte de {}° de ce que prévoient les précédents : repère \"\n                                       \"mal pointé sur la carte ou dans la photo ?\".format(_fr(r)))\n        self.landmarks.setdefault(sequence, []).append(obs)\n        self._notify()\n        return {\"offset\": offset, \"sigma\": sigma, \"distance\": dist}\n\n    def _landmark_offset(self, obs):\n        \"\"\"(décalage de cap, précision, distance) d'un repère seul, avec l'inclinaison actuelle\n        et sans recalage de position.\"\"\"\n        yaw, _ = self.untilted(obs[\"pic\"], obs[\"yaw\"], obs[\"elev\"])\n        x, y = _local(obs[\"mlon\"], obs[\"mlat\"], obs[\"lon\"], obs[\"lat\"])\n        dist = math.hypot(x, y)\n        bearing = math.degrees(math.atan2(x, y))\n        offset = (bearing - yaw + 540) % 360 - 180\n        position = math.degrees(math.atan2(math.hypot(obs[\"accuracy\"], MAP_ERROR), max(dist, 1e-6)))\n        return offset, math.hypot(position, AIM_ERROR), dist\n\n    def _solve_pose(self, obs):\n        \"\"\"Relèvement : décalage de cap et de position communs aux photos des repères.\n\n        Moindres carrés (Gauss-Newton) sur (cap, est, nord), chaque inconnue gardant\n        son a priori : décalage de cap nul à ±prior, position GPS juste à ±accuracy.\n        Un repère corrige surtout le cap ; trois repères ou plus bien répartis autour\n        des photos recalent aussi la position.\n        \"\"\"\n        lon0 = sum(o[\"lon\"] for o in obs) / len(obs)\n        lat0 = sum(o[\"lat\"] for o in obs) / len(obs)\n        rows = []\n        for o in obs:\n            yaw, _ = self.untilted(o[\"pic\"], o[\"yaw\"], o[\"elev\"])\n            px, py = _local(o[\"lon\"], o[\"lat\"], lon0, lat0)\n            mx, my = _local(o[\"mlon\"], o[\"mlat\"], lon0, lat0)\n            dist = max(math.hypot(mx - px, my - py), 1e-6)\n            sigma = math.radians(math.hypot(AIM_ERROR, math.degrees(math.atan2(MAP_ERROR, dist))))\n            rows.append((px, py, mx, my, math.radians(yaw), 1.0 / sigma ** 2))\n        prior = (1.0 / math.radians(obs[0][\"prior\"]) ** 2,\n                 1.0 / obs[0][\"accuracy\"] ** 2, 1.0 / obs[0][\"accuracy\"] ** 2)\n        p = [0.0, 0.0, 0.0]  # décalage de cap (radians), décalage de position est, nord (m)\n\n        def residuals(p):\n            out = []\n            for px, py, mx, my, yaw, w in rows:\n                dx, dy = mx - px - p[1], my - py - p[2]\n                r = (math.atan2(dx, dy) - yaw - p[0] + 3 * math.pi) % (2 * math.pi) - math.pi\n                d2 = dx * dx + dy * dy\n                out.append((r, (-1.0, -dy / d2, dx / d2), w))\n            return out\n\n        for _ in range(10):\n            n = [[prior[i] if i == j else 0.0 for j in range(3)] for i in range(3)]\n            g = [-prior[i] * p[i] for i in range(3)]\n            for r, jac, w in residuals(p):\n                for i in range(3):\n                    g[i] -= w * jac[i] * r\n                    for j in range(3):\n                        n[i][j] += w * jac[i] * jac[j]\n            cov = _inverse3(n)\n            step = [sum(cov[i][j] * g[j] for j in range(3)) for i in range(3)]\n            p = [p[i] + step[i] for i in range(3)]\n            if max(abs(step[0]) * 1e3, abs(step[1]), abs(step[2])) < 1e-6:\n                break\n        res = residuals(p)\n        # Grand axe de l'ellipse d'incertitude de la position\n        a, b, c = cov[1][1], cov[1][2], cov[2][2]\n        major = math.sqrt(max((a + c) / 2 + math.sqrt(((a - c) / 2) ** 2 + b * b), 0.0))\n        return {\n            \"offset\": math.degrees(p[0]), \"sigma\": math.degrees(math.sqrt(cov[0][0])),\n            \"shift\": (p[1], p[2]), \"shift_sigma\": major,\n            # Position recalée : trois repères au moins, et nettement mieux connue qu'au GPS\n            \"positioned\": len(obs) >= 3 and major < 0.7 * obs[0][\"accuracy\"],\n            \"residual\": math.degrees(math.sqrt(sum(r * r for r, _, _ in res) / len(res))),\n            \"residuals\": [math.degrees(r) for r, _, _ in res],\n            \"count\": len(obs), \"prior\": obs[0][\"prior\"], \"accuracy\": obs[0][\"accuracy\"],\n            \"photos\": [(o[\"lon\"], o[\"lat\"]) for o in obs],\n        }\n\n    def pose(self, sequence, lon=None, lat=None):\n        \"\"\"Recalage de la séquence (voir _solve_pose), ou None. Avec (lon, lat), None aussi\n        si la photo est à plus de REACH m des photos qui ont servi au recalage : la dérive\n        du GPS au fil de la séquence le rendrait faux.\"\"\"\n        obs = self.landmarks.get(sequence) if sequence else None\n        if not obs:\n            return None\n        result = self._solve_pose(obs)\n        if lon is not None and lat is not None:\n            if min(math.hypot(*_local(lon, lat, plon, plat)) for plon, plat in result[\"photos\"]) > REACH:\n                return None\n        return result\n\n    # Application -----------------------------------------------------------\n    def correct(self, pic, sequence, yaw, elev, lon=None, lat=None):\n        \"\"\"Direction corrigée (inclinaison de la photo, puis cap de la séquence).\"\"\"\n        yaw, elev = self.untilted(pic, yaw, elev)\n        pose = self.pose(sequence, lon, lat)\n        if pose:\n            yaw = (yaw + pose[\"offset\"]) % 360\n        return yaw, elev\n\n    def uncorrect(self, pic, sequence, yaw, elev, lon=None, lat=None):\n        \"\"\"Inverse de correct : direction vue dans la photo (brute) d'une direction vraie.\"\"\"\n        pose = self.pose(sequence, lon, lat)\n        if pose:\n            yaw = (yaw - pose[\"offset\"]) % 360\n        t = self.tilt(pic)\n        return untilt(t[\"up\"], yaw, elev, inverse=True) if t else (yaw % 360, elev)\n\n    def position(self, sequence, lon, lat):\n        \"\"\"Position recalée de la photo : (lon, lat, précision en m), ou None si la\n        position n'a pas été recalée (moins de trois repères bien répartis).\"\"\"\n        pose = self.pose(sequence, lon, lat)\n        if not pose or not pose[\"positioned\"]:\n            return None\n        sx, sy = pose[\"shift\"]\n        lon, lat = offset(lon, lat, math.degrees(math.atan2(sx, sy)), math.hypot(sx, sy))\n        return lon, lat, pose[\"shift_sigma\"]\n\n    def heading_error(self, sequence, lon=None, lat=None):\n        \"\"\"Erreur de visée (degrés) d'une séquence recalée, ou None si elle ne l'est pas.\"\"\"\n        pose = self.pose(sequence, lon, lat)\n        return math.hypot(pose[\"sigma\"], AIM_ERROR) if pose else None\n\n\ndef _height_obs(o):\n    \"\"\"Calage de la hauteur de caméra relu (voir Calibration.heights), ou None si illisible.\"\"\"\n    try:\n        if isinstance(o, dict):\n            clicks = []\n            for c in o[\"clicks\"]:\n                clicks.append({\n                    \"pic\": c.get(\"pic\"), \"sequence\": c.get(\"sequence\"),\n                    \"lon\": float(c[\"lon\"]), \"lat\": float(c[\"lat\"]),\n                    \"gps\": [float(v) for v in c[\"gps\"]] if c.get(\"gps\") else None,\n                    \"raw\": [float(c[\"raw\"][0]), float(c[\"raw\"][1])] if c.get(\"raw\") else None,\n                    \"yaw\": float(c[\"yaw\"]) if c.get(\"yaw\") is not None else None,\n                    \"elev\": float(c[\"elev\"]) if c.get(\"elev\") is not None else None,\n                    \"profile\": [(float(d), float(z)) for d, z in c[\"profile\"]] if c.get(\"profile\") else None})\n            if o.get(\"kind\") not in (\"ground\", \"height\") or len(clicks) != 2 or float(o[\"known\"]) <= 0:\n                return None\n            if any(c[\"raw\"] is None and (c[\"yaw\"] is None or c[\"elev\"] is None) for c in clicks):\n                return None\n            return {\"kind\": o[\"kind\"], \"known\": float(o[\"known\"]), \"clicks\": clicks}\n        h, s = float(o[0]), float(o[1])\n        return (h, s) if s > 0 else None\n    except (TypeError, ValueError, KeyError, IndexError, AttributeError):\n        return None\n\n\ndef _auto_entry(entry):\n    \"\"\"Inclinaison automatique relue (voir Calibration.auto), ou None si illisible.\"\"\"\n    try:\n        out = {\"sequence\": entry.get(\"sequence\"), \"heading\": float(entry[\"heading\"]), \"verticals\": None,\n               \"lidar\": None}\n        v = entry.get(\"verticals\")\n        if v:\n            up = _unit(tuple(float(c) for c in v[\"up\"]))\n            out[\"verticals\"] = {\"up\": list(up), \"count\": int(v[\"count\"]), \"sigma\": float(v[\"sigma\"])}\n        if entry.get(\"lidar\"):\n            out[\"lidar\"] = [float(entry[\"lidar\"][0]), float(entry[\"lidar\"][1])]\n        return out\n    except (TypeError, ValueError, KeyError, IndexError, AttributeError, ZeroDivisionError):\n        return None\n\n\ndef _inverse3(m):\n    \"\"\"Inverse d'une matrice 3×3 (symétrique définie positive ici).\"\"\"\n    a, b, c = m[0]\n    d, e, f = m[1]\n    g, h, i = m[2]\n    co = [[e * i - f * h, -(d * i - f * g), d * h - e * g],\n          [-(b * i - c * h), a * i - c * g, -(a * h - b * g)],\n          [b * f - c * e, -(a * f - c * d), a * e - b * d]]\n    det = a * co[0][0] + b * co[0][1] + c * co[0][2]\n    return [[co[j][i] / det for j in range(3)] for i in range(3)]\n",
 "core/capture.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Capture « virtuelle » Full HD de la vue affichée : calcul de l'image.\n\nPlutôt qu'une capture d'écran (limitée à la taille du panneau), on recalcule la\nvue à partir de la photo originale en haute définition, avec le même cadrage\nque la visionneuse : cap, inclinaison et champ de vision.\n\n- Photo 360° (équirectangulaire) : projection perspective de la sphère.\n- Photo classique : reprojection de l'image plane selon la vue demandée.\n\nTableaux numpy RGB (numpy importé à l'usage : le cœur s'importe sans lui). Décodage,\ncartouche et enregistrement : la page (src/app.js, capture HD).\n\"\"\"\n\nimport datetime as _dt\nimport math\nimport re\n\nOUT_W, OUT_H = 1920, 1080\nBACKGROUND = (40, 40, 40)\n\n\ndef _view_rays(heading, pitch, vfov, width, height):\n    \"\"\"Directions (unitaires) de chaque pixel de la vue, en repère monde.\n\n    Repère : x = est, y = haut, z = nord. heading en degrés (0 = nord),\n    pitch en degrés (positif = vers le haut), vfov = champ vertical en degrés.\n    \"\"\"\n    import numpy as np\n\n    f = (height / 2.0) / math.tan(math.radians(vfov) / 2.0)\n    u = (np.arange(width, dtype=np.float64) + 0.5 - width / 2.0) / f\n    v = (height / 2.0 - np.arange(height, dtype=np.float64) - 0.5) / f\n    x, y = np.meshgrid(u, v)\n    z = np.ones_like(x)\n    # inclinaison (rotation autour de l'axe x)\n    p = math.radians(pitch)\n    y2 = y * math.cos(p) + z * math.sin(p)\n    z2 = -y * math.sin(p) + z * math.cos(p)\n    # cap (rotation autour de l'axe vertical, sens horaire depuis le nord)\n    h = math.radians(heading)\n    x3 = x * math.cos(h) + z2 * math.sin(h)\n    z3 = -x * math.sin(h) + z2 * math.cos(h)\n    n = np.sqrt(x3 * x3 + y2 * y2 + z3 * z3)\n    return x3 / n, y2 / n, z3 / n\n\n\ndef _bilinear(src, xs, ys, valid=None):\n\n    import numpy as np\n    h, w, _ = src.shape\n    x0 = np.floor(xs).astype(np.int64)\n    y0 = np.floor(ys).astype(np.int64)\n    fx = (xs - x0)[..., None]\n    fy = (ys - y0)[..., None]\n    x1, y1 = x0 + 1, y0 + 1\n    if valid is None:  # 360° : bouclage horizontal\n        x0 %= w\n        x1 %= w\n    else:\n        x0 = np.clip(x0, 0, w - 1)\n        x1 = np.clip(x1, 0, w - 1)\n    y0 = np.clip(y0, 0, h - 1)\n    y1 = np.clip(y1, 0, h - 1)\n    s = src.astype(np.float32)\n    out = (s[y0, x0] * (1 - fx) * (1 - fy) + s[y0, x1] * fx * (1 - fy)\n           + s[y1, x0] * (1 - fx) * fy + s[y1, x1] * fx * fy)\n    if valid is not None:\n        out[~valid] = BACKGROUND\n    return out\n\n\ndef _tilted_rays(dx, dy, dz, up):\n    \"\"\"Directions vraies (x = est, y = haut, z = nord) exprimées dans le repère d'une caméra\n    penchée dont la verticale vraie est `up` (est, nord, haut ; voir core/calibration.py) : rotation\n    qui amène le zénith sur up, inverse de calibration.untilt.\"\"\"\n    ux, uy, uz = up\n    s = math.hypot(ux, uy)\n    if s < 1e-12:\n        return dx, dy, dz\n    kx, ky = -uy / s, ux / s  # zénith × up, normé\n    c = uz\n    ve, vn, vu = dx, dz, dy\n    kv = kx * ve + ky * vn\n    re = ve * c + (ky * vu) * s + kx * kv * (1 - c)\n    rn = vn * c + (-kx * vu) * s + ky * kv * (1 - c)\n    ru = vu * c + (kx * vn - ky * ve) * s\n    return re, ru, rn\n\n\ndef render_view(src, azimuth, is360, heading, pitch, vfov, photo_hfov=None,\n                width=OUT_W, height=OUT_H, up=None):\n    \"\"\"Calcule la vue (tableau numpy RGB) à partir de la photo source. up : verticale vraie de\n    la photo (calage de l'inclinaison), pour une vue redressée (verticales verticales).\"\"\"\n    import numpy as np\n\n    dx, dy, dz = _view_rays(heading, pitch, vfov, width, height)\n    if up is not None:\n        dx, dy, dz = _tilted_rays(dx, dy, dz, up)\n    sh, sw, _ = src.shape\n    a = math.radians(azimuth or 0.0)\n    # Directions exprimées dans le repère de la photo (centre de l'image = azimut)\n    px = dx * math.cos(a) - dz * math.sin(a)\n    pz = dx * math.sin(a) + dz * math.cos(a)\n    py = dy\n    if is360:\n        lon = np.arctan2(px, pz)  # -pi..pi, 0 = centre de l'image\n        lat = np.arcsin(np.clip(py, -1, 1))\n        xs = (lon / (2 * math.pi) + 0.5) * sw - 0.5\n        ys = (0.5 - lat / math.pi) * sh - 0.5\n        return _bilinear(src, xs, ys)\n    # Photo classique : plan image perpendiculaire à l'axe de prise de vue\n    hfov = photo_hfov or 70.0\n    f = (sw / 2.0) / math.tan(math.radians(hfov) / 2.0)\n    with np.errstate(divide=\"ignore\", invalid=\"ignore\"):\n        xs = sw / 2.0 + f * px / pz - 0.5\n        ys = sh / 2.0 - f * py / pz - 0.5\n    valid = (pz > 1e-6) & (xs >= 0) & (xs <= sw - 1) & (ys >= 0) & (ys <= sh - 1)\n    xs = np.where(valid, xs, 0)\n    ys = np.where(valid, ys, 0)\n    return _bilinear(src, xs, ys, valid)\n\n\ndef caption_for(item, heading):\n    \"\"\"Texte d'attribution : auteur, date, cap, licence (obligation des licences Panoramax).\"\"\"\n    props = item.get(\"properties\", {}) or {}\n    providers = props.get(\"providers\") or item.get(\"providers\") or []\n    names = [p.get(\"name\") for p in providers if isinstance(p, dict) and p.get(\"name\")]\n    author = names[0] if names else None\n    date = french_date(props.get(\"datetime\"))\n    lic = license_name(item)\n    parts = [\"Panoramax\"]\n    if author:\n        parts.append(\"© \" + author)\n    if date:\n        parts.append(date)\n    if heading is not None:\n        parts.append(\"cap {:.0f}°\".format(heading % 360))\n    if lic:\n        parts.append(str(lic))\n    return \"  ·  \".join(parts)\n\n\ndef french_date(stamp):\n    \"\"\"Date de prise de vue à l'heure de Paris (UTC+1, UTC+2 l'été), en toutes lettres (23 mai 2025) ; date lue telle\n    quelle si l'heure manque ou ne se lit pas, \"\" sans date. Règle européenne d'heure d'été écrite ici :\n    zoneinfo n'a pas toujours ses données dans le navigateur.\"\"\"\n    stamp = stamp or \"\"\n    try:\n        when = _dt.datetime.fromisoformat(stamp.replace(\"Z\", \"+00:00\"))\n    except ValueError:\n        when = None\n    if when is None or when.tzinfo is None:\n        try:\n            return long_date(_dt.date.fromisoformat(stamp[:10]))\n        except ValueError:\n            return stamp[:10]\n    when = when.astimezone(_dt.timezone.utc).replace(tzinfo=None)\n\n    def last_sunday(month):  # dernier dimanche du mois, 1 h UTC : changement d'heure\n        day = _dt.datetime(when.year, month, 31, 1)\n        return day - _dt.timedelta(days=(day.weekday() + 1) % 7)\n    summer = last_sunday(3) <= when < last_sunday(10)\n    return long_date(when + _dt.timedelta(hours=2 if summer else 1))\n\n\nMONTHS = (\"janvier\", \"février\", \"mars\", \"avril\", \"mai\", \"juin\", \"juillet\", \"août\", \"septembre\", \"octobre\",\n          \"novembre\", \"décembre\")\n\n\ndef long_date(day):\n    \"\"\"23 mai 2025, 1er juin 2025.\"\"\"\n    return \"{} {} {}\".format(\"1er\" if day.day == 1 else day.day, MONTHS[day.month - 1], day.year)\n\n\ndef license_name(item):\n    \"\"\"Licence de la photo, réduite à sa catégorie (« etalab-2.0 », « CC-BY-SA-4.0 ») : champ\n    license de la fiche, sinon le code entre parenthèses du titre du lien (« License for this\n    object (etalab-2.0) »), sinon d'après l'adresse de la licence. None si inconnue.\"\"\"\n    props = item.get(\"properties\", {}) or {}\n    lic = props.get(\"license\") or item.get(\"license\")\n    if lic and lic != \"proprietary\":\n        return str(lic)\n    for link in item.get(\"links\", []) or []:\n        if link.get(\"rel\") == \"license\":\n            title = link.get(\"title\") or \"\"\n            code = re.search(r\"\\(([^()]+)\\)\\s*$\", title)\n            return code.group(1) if code else (title or _license_label(link.get(\"href\", \"\")))\n    return str(lic) if lic else None\n\n\ndef _license_label(href):\n    h = href.lower()\n    if \"by-sa/4.0\" in h:\n        return \"CC BY-SA 4.0\"\n    if \"by/4.0\" in h:\n        return \"CC BY 4.0\"\n    if \"etalab\" in h or \"licence-ouverte\" in h:\n        return \"Licence Ouverte 2.0\"\n    return href\n",
 "core/filters.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Filtre des photos : date, type de caméra, précision GPS, producteur.\n\nAppliqué aux photos ouvertes par un clic sur la carte (propriétés des fiches STAC, voir\nPhotoFilter.matches). Le filaire de la carte est filtré par la page elle-même, sur les\nattributs des tuiles vectorielles (src/carte.js, mêmes critères). Mémorisation : la page.\n\"\"\"\n\nKINDS = ((\"Tous types\", None), (\"360°\", \"360\"), (\"Classiques\", \"flat\"))\n\n\nclass PhotoFilter:\n    \"\"\"Critères du filtre ; None : critère inactif.\n\n    since : date minimale \"AAAA-MM-JJ\" ; kind : \"360\" ou \"flat\" ; max_gps : précision\n    GPS maximale (m) ; producer : (identifiant du compte, nom) du producteur.\"\"\"\n\n    def __init__(self, since=None, kind=None, max_gps=None, producer=None):\n        self.since, self.kind, self.max_gps, self.producer = since, kind, max_gps, producer\n\n    def __eq__(self, other):\n        return isinstance(other, PhotoFilter) and vars(self) == vars(other)\n\n    def active(self):\n        return any(v is not None for v in vars(self).values())\n\n    # Fiches STAC --------------------------------------------------------------\n    def matches(self, item):\n        \"\"\"La photo (fiche STAC de l'API) passe-t-elle le filtre ? Une date, une précision GPS\n        ou un producteur absents de la fiche font refuser la photo pour ce critère.\"\"\"\n        props = item.get(\"properties\") or {}\n        if self.since and str(props.get(\"datetime\") or \"\")[:10] < self.since:\n            return False\n        if self.kind:  # angle de vue souvent absent des photos classiques (téléphones) : 360 seulement si déclaré\n            fov = (props.get(\"pers:interior_orientation\") or {}).get(\"field_of_view\") or 0\n            if (float(fov) >= 360) != (self.kind == \"360\"):\n                return False\n        if self.max_gps is not None:\n            gps = props.get(\"quality:horizontal_accuracy\")\n            if gps is None or float(gps) > self.max_gps:\n                return False\n        if self.producer:\n            ids = {p.get(\"id\") for p in item.get(\"providers\") or props.get(\"providers\") or []}\n            if self.producer[0] not in ids:\n                return False\n        return True\n\n    def describe(self):\n        \"\"\"Résumé du filtre, pour les messages (\"\" s'il est inactif).\"\"\"\n        parts = []\n        if self.since:\n            parts.append(\"depuis le {}\".format(\"/\".join(reversed(self.since.split(\"-\")))))\n        if self.kind:\n            parts.append(dict((v, k) for k, v in KINDS)[self.kind].lower())\n        if self.max_gps is not None:\n            parts.append(\"GPS ≤ {} m\".format(str(self.max_gps).rstrip(\"0\").rstrip(\".\").replace(\".\", \",\")))\n        if self.producer:\n            parts.append(\"producteur « {} »\".format(self.producer[1]))\n        return \", \".join(parts)\n\n\ndef item_producer(item):\n    \"\"\"(identifiant du compte, nom) du producteur de la photo, ou None.\"\"\"\n    for p in (item or {}).get(\"providers\") or ((item or {}).get(\"properties\") or {}).get(\"providers\") or []:\n        if \"producer\" in (p.get(\"roles\") or []) and p.get(\"id\"):\n            return p[\"id\"], p.get(\"name\") or p[\"id\"]\n    return None\n",
 "core/geometry.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Points 3D à partir des clics, pour les mesures (voir measures.py).\n\nUn clic ne donne qu'une direction ; le point 3D est l'intersection du rayon de\nvisée avec une surface :\n- le terrain (même calcul que les mesures au sol, voir ground.py) ;\n- un plan vertical : face à la caméra et passant par le pied de l'objet (hauteur).\n\nRepère local (est, nord, altitude) en mètres, centré sur un point de référence\n(lon0, lat0). La caméra est à la position (recalée) de la photo, à la hauteur de\ncaméra au-dessus du sol sous la photo, donné par le profil de terrain du clic.\nLes mesures sont ensuite des calculs sur ces points : distance 3D et sa\ndécomposition (horizontale, verticale, le long de la route et en travers).\nModule sans dépendance, testé seul (tests/coeur/).\n\"\"\"\n\nimport math\n\nfrom . import ground\nfrom .triangulation import _geographic, _local\n\nMAX_RANGE = 100.0  # portée maximale d'un point sur un plan (m)\nGRAZING = 15.0  # en dessous de cet angle d'incidence sur un plan, la mesure devient imprécise\n\n\nclass GeometryError(ValueError):\n    \"\"\"Clic inexploitable (message destiné à l'utilisateur).\"\"\"\n\n\ndef direction(yaw, elev):\n    \"\"\"Vecteur unitaire (est, nord, haut) d'une direction en degrés.\"\"\"\n    y, e = math.radians(yaw), math.radians(elev)\n    return (math.sin(y) * math.cos(e), math.cos(y) * math.cos(e), math.sin(e))\n\n\ndef to_geographic(p, origin):\n    lon, lat = _geographic(p[0], p[1], origin[0], origin[1])\n    return lon, lat, p[2]\n\n\ndef camera(click, camera_height, origin, ground_z=None):\n    \"\"\"Centre optique (repère local) et direction de visée d'un clic. ground_z : altitude\n    du sol sous la photo, à donner pour qu'elle soit la même pour tous les clics d'une\n    photo (celle du profil du clic dépend de la direction visée).\"\"\"\n    if ground_z is None:\n        ground_z = (click.get(\"profile\") or ground.flat_profile())[0][1]\n    x, y = _local(click[\"lon\"], click[\"lat\"], origin[0], origin[1])\n    return (x, y, ground_z + camera_height), direction(click[\"yaw\"], click[\"elev\"])\n\n\ndef on_ground(click, camera_height, origin, ground_z=None):\n    \"\"\"Point au sol (rayon ∩ terrain), comme ground._ground_point. ground_z : altitude du sol\n    sous la photo, la même pour tous ses clics (voir ground.anchored et camera).\"\"\"\n    profile = ground.anchored(click.get(\"profile\") or ground.flat_profile(), ground_z)\n    s, z = ground.intersect(profile, camera_height, click[\"elev\"])\n    x, y = _local(click[\"lon\"], click[\"lat\"], origin[0], origin[1])\n    a = math.radians(click[\"yaw\"])\n    return (x + s * math.sin(a), y + s * math.cos(a), z), 90.0\n\n\ndef on_plane(click, camera_height, origin, point, normal, ground_z=None):\n    \"\"\"Point sur le plan (point, normale). Retourne (point, angle d'incidence en degrés).\"\"\"\n    c, u = camera(click, camera_height, origin, ground_z)\n    nu = sum(n * v for n, v in zip(normal, u))\n    if abs(nu) < 1e-6:\n        raise GeometryError(\"Visée parallèle au plan : cliquez un point plus face à la caméra.\")\n    t = sum(n * (p - q) for n, p, q in zip(normal, point, c)) / nu\n    if t <= 0.1:\n        raise GeometryError(\"Le point visé est derrière le plan de mesure : vérifiez la surface choisie.\")\n    if t * math.hypot(u[0], u[1]) > MAX_RANGE:\n        raise GeometryError(\"Point à plus de {:.0f} m sur le plan de mesure : visez plus près.\".format(MAX_RANGE))\n    norm = math.sqrt(sum(n * n for n in normal))\n    return tuple(q + t * v for q, v in zip(c, u)), math.degrees(math.asin(min(1.0, abs(nu) / norm)))\n\n\ndef vertical_plane(a, b):\n    \"\"\"Plan vertical passant par deux points (repère local) : (point, normale horizontale).\"\"\"\n    dx, dy = b[0] - a[0], b[1] - a[1]\n    if math.hypot(dx, dy) < 0.2:\n        raise GeometryError(\"Les deux points de la façade sont trop proches : cliquez ses deux extrémités.\")\n    return a, (-dy, dx, 0.0)\n\n\ndef facing_plane(cam, point):\n    \"\"\"Plan vertical passant par `point`, face à la caméra (normale horizontale vers elle).\"\"\"\n    dx, dy = point[0] - cam[0], point[1] - cam[1]\n    if math.hypot(dx, dy) < 0.1:\n        raise GeometryError(\"Point trop proche de la caméra.\")\n    return point, (dx, dy, 0.0)\n\n\ndef decompose(p, q, axis=None):\n    \"\"\"Distance de p à q : dict d3, horizontal, vertical (q − p), along et across (le long\n    de l'axe de la route et en travers, si l'axe est connu).\"\"\"\n    dx, dy, dz = q[0] - p[0], q[1] - p[1], q[2] - p[2]\n    out = {\"d3\": math.sqrt(dx * dx + dy * dy + dz * dz), \"horizontal\": math.hypot(dx, dy), \"vertical\": dz,\n           \"along\": None, \"across\": None}\n    if axis is not None:\n        ax, ay = math.sin(math.radians(axis)), math.cos(math.radians(axis))\n        out[\"along\"] = abs(dx * ax + dy * ay)\n        out[\"across\"] = abs(dx * ay - dy * ax)\n    return out\n",
 "core/ground.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Mesures sur une photo par lancer de rayon sur le terrain.\n\nLa caméra est à une hauteur connue au-dessus du sol. Un clic donne une\ndirection (cap, élévation) ; on suit ce rayon jusqu'à ce qu'il passe sous le\nterrain, décrit par un profil d'altitudes le long de la visée (MNT ou service\nd'altimétrie). Sans profil, le sol est supposé plat et horizontal. On en déduit\nla position des points au sol (utilisée par geometry.py pour toutes les mesures)\net la hauteur d'un objet, pied puis sommet (utilisée par le calage de la hauteur\nde caméra, avec le même modèle que les mesures).\n\nLa précision chute vite avec la distance (une erreur d'inclinaison de 0,5°\ndéplace un point situé à 15 m de plus d'un mètre) : réservé aux objets proches.\nModule sans dépendance, testé seul (tests/coeur/).\n\"\"\"\n\nimport math\n\nfrom .triangulation import offset\n\nPITCH_ERROR = 0.5  # erreur d'inclinaison supposée (degrés) pour l'incertitude affichée\nMAX_DISTANCE = 60.0  # longueur du profil de terrain et portée maximale d'une mesure\nFLAT = \"sol plat\"\n\n\nclass GroundError(ValueError):\n    \"\"\"Clic inexploitable (message destiné à l'utilisateur).\"\"\"\n\n\ndef flat_profile():\n    \"\"\"Profil d'un sol plat et horizontal (altitude relative 0).\"\"\"\n    return [(0.0, 0.0), (MAX_DISTANCE, 0.0)]\n\n\ndef intersect(profile, camera_height, elevation):\n    \"\"\"Premier point où le rayon passe sous le terrain.\n\n    profile : [(distance horizontale en m, altitude du terrain)], trié, depuis 0\n    (sous la caméra). Retourne (distance, altitude du sol). Le terrain est\n    linéaire entre deux échantillons : l'intersection y est exacte.\n    \"\"\"\n    z_cam = profile[0][1] + camera_height\n    slope = math.tan(math.radians(elevation))\n    prev_s, prev_f = profile[0][0], camera_height\n    for s, z in profile[1:]:\n        f = z_cam + s * slope - z  # hauteur du rayon au-dessus du terrain\n        if f <= 0:\n            s_hit = prev_s + (s - prev_s) * prev_f / (prev_f - f)\n            k = (s_hit - prev_s) / (s - prev_s) if s > prev_s else 0.0\n            z_prev = z_cam + prev_s * slope - prev_f\n            return s_hit, z_prev + k * (z - z_prev)\n        prev_s, prev_f = s, f\n    raise GroundError(\"Le point visé ne touche pas le sol dans les {:.0f} m : cliquez sur le sol, \"\n                      \"plus près de la photo.\".format(MAX_DISTANCE))\n\n\ndef anchored(profile, ground_z):\n    \"\"\"Profil décalé verticalement pour que le sol sous la caméra soit à ground_z.\n\n    Le profil d'un clic est la droite de pente du terrain dans la direction visée : son\n    altitude sous la caméra varie d'une direction à l'autre (quelques décimètres). Tous les\n    clics d'une même photo doivent partir de la même caméra : sinon chaque point est calculé\n    depuis une hauteur différente, ce qui fausse les dénivelés et décale son repère dans la\n    visionneuse. ground_z None : profil inchangé.\"\"\"\n    if ground_z is None:\n        return profile\n    dz = ground_z - profile[0][1]\n    return [(s, z + dz) for s, z in profile]\n\n\ndef _ground_point(camera_height, click, ground_z=None):\n    s, z = intersect(anchored(click.get(\"profile\") or flat_profile(), ground_z), camera_height, click[\"elev\"])\n    return s, offset(click[\"lon\"], click[\"lat\"], click[\"yaw\"], s), z\n\n\ndef _spread(fn, clicks):\n    \"\"\"Écart maximal du résultat quand chaque élévation varie de ±PITCH_ERROR.\"\"\"\n    ref = fn(clicks)\n    worst = 0.0\n    for i in range(len(clicks)):\n        for sign in (-1, 1):\n            moved = [dict(c) for c in clicks]\n            moved[i][\"elev\"] += sign * PITCH_ERROR\n            try:\n                worst = max(worst, abs(fn(moved) - ref))\n            except GroundError:\n                return float(\"inf\")\n    return worst\n\n\nMAX_TOP_OFFSET = 45.0  # écart de cap maximal entre le pied et le sommet d'un objet (degrés)\n\n\ndef measure_height(camera_height, base, top):\n    \"\"\"Hauteur d'un objet : clic au pied (au sol) puis au sommet, sur la même photo.\n\n    Le sommet est pris dans le plan vertical face à la caméra qui passe par le pied :\n    pour un objet fin (poteau), c'est à la même distance que le pied ; pour un mur\n    face à la caméra, le sommet peut être cliqué un peu de côté. Même modèle que\n    measures.py (plan vertical face à la caméra, voir geometry.py).\n    \"\"\"\n    if base.get(\"pic\") != top.get(\"pic\"):\n        raise GroundError(\"Le pied et le sommet doivent être cliqués sur la même photo.\")\n    profile = base.get(\"profile\") or flat_profile()\n\n    def height(clicks):\n        b, t = clicks\n        s, z_ground = intersect(profile, camera_height, b[\"elev\"])\n        offset_angle = (t[\"yaw\"] - b[\"yaw\"] + 540) % 360 - 180\n        if abs(offset_angle) > MAX_TOP_OFFSET:\n            raise GroundError(\"Le sommet est trop à côté du pied : cliquez-le au-dessus du pied.\")\n        reach = s / math.cos(math.radians(offset_angle))  # distance horizontale jusqu'au plan\n        z_top = profile[0][1] + camera_height + reach * math.tan(math.radians(t[\"elev\"]))\n        return z_top - z_ground\n\n    d, p, _ = _ground_point(camera_height, base)\n    h = height([base, top])\n    if h <= 0:\n        raise GroundError(\"Le sommet est sous le pied : cliquez d'abord au pied, puis au sommet.\")\n    return {\"points\": [p], \"ranges\": [d], \"value\": h, \"uncertainty\": _spread(height, [base, top])}\n",
 "core/host.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Services que l'application hôte fournit au cœur de calcul (voir install).\n\n- fetch(url, callback, prefer_cache=False, timeout_ms=None) : GET asynchrone,\n  callback(octets | None, erreur | None) ; peut renvoyer un objet ayant abort() ;\n- fetch_json(url, callback, prefer_cache=False, timeout_ms=None) : idem, callback(objet JSON\n  | None, erreur | None) ;\n- ngf_altitude(lon, lat, ellipsoïdale) : altitude NGF-IGN69 (grille RAF20), ou None ;\n- decode_band(octets, largeur, élévation min, élévation max) : photo équirectangulaire\n  décodée en niveaux de gris, réduite à `largeur` et rognée à la bande d'élévations\n  (tableau numpy, première ligne, hauteur et largeur de l'image entière), ou None ;\n- run_task(fonction, arguments, done) : calcul en arrière-plan, puis done(résultat ou None) ;\n- api_url : API Panoramax de l'instance choisie.\n\nRempli par py/web_host.py : réseau du navigateur, décodage par canvas, calcul dans le worker.\nLes valeurs par défaut rendent le cœur utilisable sans hôte (tests) : pas de réseau, pas\nd'altitude NGF, calcul immédiat.\n\"\"\"\n\napi_url = \"https://api.panoramax.xyz/api\"\n\n\ndef fetch(url, callback, prefer_cache=False, timeout_ms=None):\n    callback(None, \"pas d'accès réseau\")\n\n\ndef fetch_json(url, callback, prefer_cache=False, timeout_ms=None):\n    callback(None, \"pas d'accès réseau\")\n\n\ndef ngf_altitude(lon, lat, ellipsoidal):\n    return None\n\n\ndef decode_band(data, width, elev_min, elev_max):\n    return None\n\n\ndef run_task(function, args, done):\n    try:\n        result = function(*args)\n    except Exception:  # calcul raté : même effet qu'un résultat vide\n        result = None\n    done(result)\n\n\nSERVICES = (\"fetch\", \"fetch_json\", \"ngf_altitude\", \"decode_band\", \"run_task\", \"api_url\")\n\n\ndef install(**services):\n    \"\"\"Remplace les services par ceux de l'hôte (noms : SERVICES).\"\"\"\n    unknown = set(services) - set(SERVICES)\n    if unknown:\n        raise ValueError(\"services inconnus : {}\".format(\", \".join(sorted(unknown))))\n    globals().update(services)\n",
 "core/measures.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Mesures entre deux points 3D : largeurs, longueur et hauteur.\n\nToutes reposent sur le même moteur (geometry.py) : chaque clic devient un point 3D\nsur une surface, puis la mesure est une grandeur calculée sur ces points.\n\n- \"road\" : largeur perpendiculaire à la chaussée (deux points au sol, composante\n  en travers de l'axe de la route) ;\n- \"width\" : longueur parallèle à la route (distance 3D entre deux points au sol) ;\n- \"height\" : hauteur d'un objet (pied au sol, sommet dans le plan vertical face à\n  la caméra, composante verticale).\n\nLa mesure libre 3D (façade, plans, triangulation 3D entre deux photos) a été retirée le\n15/10/2026 : elle donnait des résultats trop incohérents.\n\nUn point peut être recalé après coup sur la carte : sa position horizontale vient\nalors de la carte, et son altitude du rayon de visée de la photo à cette distance.\nLa mesure est recalculée ; pour une hauteur, elle ne dépend plus ni du terrain ni\nde la hauteur de caméra. Une hauteur peut aussi être calée sur un point triangulé au\npied de l'objet (anchor) : même calcul, avec l'incertitude de la triangulation.\n\"\"\"\n\nimport math\n\nfrom . import calibration, geometry, ground, triangulation\nfrom .calibration import AIM_ERROR, MAP_ERROR, UNCALIBRATED\n\nDEFAULT_CAMERA_HEIGHT = 1.9  # hauteur de caméra par défaut (m)\n\n\ndef _num(value, digits=1):\n    \"\"\"Nombre à la française (virgule décimale).\"\"\"\n    return \"{:.{}f}\".format(value, digits).replace(\".\", \",\")\n\n\nclass NullItem:\n    \"\"\"Dessin d'une mesure sur la carte, quand l'hôte n'en fournit pas (voir MeasureTool.new_item).\"\"\"\n\n    def set_data(self, *args, **kwargs):\n        pass\n\n    def remove(self):\n        pass\n\n\nSURFACE_NAMES = {\"ground\": \"sol\", \"vertical\": \"plan vertical face à la caméra\"}\nPRESET_SURFACES = {\"road\": \"ground\", \"width\": \"ground\", \"height\": \"vertical\"}  # surface de chaque mesure\nCAMERA_RANGE = (0.5, 4.0)  # hauteur de caméra plausible (m) déduite de l'altitude GPS\nCAMERA_SOURCES = {None: 0, \"calée\": 1, \"altitude GPS\": 2}  # champ camera_calee de la couche des mesures\n# Incertitude de la hauteur de caméra (m) selon sa source : altitude GPS d'une position vérifiée\n# (écart-type sur la séquence de Pouilly : 2 cm, plus le LiDAR), sinon valeur saisie (1,7 à 2,2 m\n# selon le véhicule) ; une hauteur calée a sa propre incertitude\nCAMERA_ERRORS = {\"altitude GPS\": 0.05, None: 0.15}\nSELECT_ANGLE = 1.0  # écart maximal (degrés) entre un clic et le repère d'un point pour le sélectionner (session)\nERRORS = (geometry.GeometryError, ground.GroundError)\nKIND_NAMES = {\"road\": \"largeur perpendiculaire à la chaussée\", \"width\": \"longueur parallèle à la route\",\n              \"height\": \"hauteur\"}\n\n\n\n\ndef _ground_z(clicks):\n    \"\"\"Altitude du sol sous chaque photo : celle du premier clic fait sur la photo, la même\n    ensuite pour tous ses clics (le profil d'un clic dépend de la direction visée).\"\"\"\n    out = {}\n    for c in clicks:\n        out.setdefault(c.get(\"pic\"), (c.get(\"profile\") or ground.flat_profile())[0][1])\n    return out\n\n\nclass Measure:\n    \"\"\"Une mesure entre deux points 3D (voir le module).\"\"\"\n\n    def __init__(self, tool, kind, surface):\n        self.tool = tool\n        self.kind, self.surface = kind, surface\n        self.clicks = []  # dicts de tools.photo_click\n        # n° de point -> (lon, lat, orientation en degrés) : point recalé sur la carte, qui fixe\n        # son plan vertical (passant par lui, de normale horizontale orientée vers la caméra\n        # qui l'a visé au moment du recalage)\n        self.overrides = {}\n        self.aimed = set()  # points visés à nouveau après un recalage : sur le plan calé de la mesure\n        # Point triangulé sur lequel la mesure est calée (voir anchor) : lon, lat, uncertainty (m), name\n        self.reference = None\n        self.lifts = {}  # n° de point -> décalage vertical (m) donné au clavier (voir lift)\n        self.result = None\n        self.error = None\n        self.notice = None  # avertissement sur la source d'altitude\n        self.incidence = None  # angle d'incidence le plus rasant sur un plan (degrés)\n        self.item = None\n        self.fid = None  # entité de la couche des mesures, une fois enregistrée\n        self.layer_id = None  # couche de cette entité : un fid ne vaut que dans sa couche\n        self.road = None  # axe de la route au point mesuré (largeur perpendiculaire, voir roads.py)\n        self.road_pending = False  # lecture de cet axe en cours\n\n    def needed(self):\n        return 2\n\n    def add_click(self, click, notice=None):\n        if notice:\n            self.notice = notice\n        self.clicks.append(click)\n        self.compute()\n        if self.error:\n            error = self.error\n            self.clicks.pop()  # clic refusé : on le refait\n            self.compute()\n            self.error = error\n\n    def relocate(self, index, lon, lat):\n        \"\"\"Recale le point n° index à la position (lon, lat) cliquée sur la carte. Son plan\n        vertical est orienté face à la photo qui l'a visé. Sur le plan vertical (hauteur), le\n        pied et le sommet se déplacent ensemble, du même décalage : la mesure garde sa forme,\n        seule sa place change. Un point glissé à la main remplace le point triangulé (anchor).\"\"\"\n        self.reference = None\n        state = dict(self.overrides), set(self.aimed)\n        for k, (lon_k, lat_k) in self._moved(index, lon, lat).items():\n            c = self.clicks[k]\n            x, y = triangulation._local(lon_k, lat_k, c[\"lon\"], c[\"lat\"])\n            self.overrides[k] = (lon_k, lat_k, math.degrees(math.atan2(x, y)))\n            self.aimed.discard(k)  # le point est là où on l'a lâché\n        self.compute()\n        if self.error:\n            error = self.error\n            self.overrides, self.aimed = state\n            self.compute()\n            self.error = error\n\n    def anchor(self, lon, lat, uncertainty, name=\"\"):\n        \"\"\"Cale la mesure terminée sur un point triangulé au pied de l'objet (lon, lat ;\n        uncertainty : son incertitude en m) : le pied y est recalé comme sur la carte (pied et\n        sommet ensemble pour une hauteur), mais l'incertitude de sa position est celle de la\n        triangulation, commune à tous les points de la mesure.\"\"\"\n        self.relocate(0, lon, lat)\n        if not self.error:\n            self.reference = {\"lon\": lon, \"lat\": lat, \"uncertainty\": float(uncertainty), \"name\": name}\n            self.compute()  # incertitude de la triangulation\n\n    def _moved(self, index, lon, lat):\n        \"\"\"Points déplacés quand le point n° index est lâché en (lon, lat) : {n° : (lon, lat)}.\n        Sur le plan vertical, tous ceux de la mesure, du même décalage horizontal.\"\"\"\n        if self.surface != \"vertical\" or len(self.clicks) < self.needed():\n            return {index: (lon, lat)}\n        try:\n            pts, _, origin, _ = self.points()\n        except ERRORS:\n            return {index: (lon, lat)}\n        x, y = triangulation._local(lon, lat, origin[0], origin[1])\n        dx, dy = x - pts[index][0], y - pts[index][1]\n        return {k: geometry.to_geographic((p[0] + dx, p[1] + dy, 0.0), origin)[:2] for k, p in enumerate(pts)}\n\n    def reaim(self, index, click):\n        \"\"\"Vise à nouveau le point n° index : le nouveau clic remplace le sien. Si la mesure a\n        été calée sur la carte, le point est pris sur son plan calé (profondeur de la carte,\n        position fine de la photo), qu'il ait été lui-même recalé ou non ; sinon, sur la\n        surface de la mesure.\"\"\"\n        state = list(self.clicks), set(self.aimed), dict(self.lifts)\n        self.clicks[index] = click\n        self.lifts.pop(index, None)  # le point est là où on l'a visé\n        if self.overrides:\n            self.aimed.add(index)\n        self.compute()\n        if self.error:\n            error = self.error\n            self.clicks, self.aimed, self.lifts = state\n            self.compute()\n            self.error = error\n\n    def lift(self, index, dz):\n        \"\"\"Monte (dz > 0) ou descend le point n° index de dz m à la verticale, au clavier :\n        réglage fin après la visée. Refusé si la mesure devient impossible (sommet sous le pied).\"\"\"\n        state = dict(self.lifts)\n        self.lifts[index] = self.lifts.get(index, 0.0) + dz\n        self.compute()\n        if self.error:\n            error = self.error\n            self.lifts = state\n            self.compute()\n            self.error = error\n\n    # Calcul -------------------------------------------------------------------\n    def points(self, clicks=None, overrides=None, camera_delta=None):\n        \"\"\"Points 3D (repère local centré sur le premier clic) des clics complets,\n        angle d'incidence le plus rasant sur un plan, origine du repère, et pour\n        chaque point le clic dont il vient. camera_delta (photo -> écart de hauteur de caméra,\n        m) sert au calcul de l'incertitude.\"\"\"\n        clicks = self.clicks if clicks is None else clicks\n        overrides = self.overrides if overrides is None else overrides\n        if not clicks:\n            return [], None, None, []\n        origin = (clicks[0][\"lon\"], clicks[0][\"lat\"])\n        ground_z = _ground_z(clicks)\n\n        def zof(click):\n            return ground_z[click.get(\"pic\")]\n\n        def h(click):\n            return self.tool.camera_for(click) + (camera_delta or {}).get(click.get(\"pic\"), 0.0)\n\n        # Plan calé de la mesure, défini par les points glissés sur la carte : vertical, passant\n        # par les deux premiers (le mur tracé sur la carte), ou par le seul glissé, face à la\n        # photo qui l'avait visé\n        anchors = {k: triangulation._local(v[0], v[1], origin[0], origin[1]) + (v[2],)\n                   for k, v in overrides.items()}\n        anchored = None\n        if len(anchors) >= 2:\n            (k1, a1), (k2, a2) = sorted(anchors.items())[:2]\n            if math.hypot(a2[0] - a1[0], a2[1] - a1[1]) >= 0.2:\n                anchored = geometry.vertical_plane((a1[0], a1[1], 0.0), (a2[0], a2[1], 0.0))\n        if anchored is None and anchors:\n            x, y, azimuth = sorted(anchors.items())[0][1]\n            a = math.radians(azimuth)\n            anchored = ((x, y, 0.0), (math.sin(a), math.cos(a), 0.0))\n\n        def fixed(k, p, click):\n            \"\"\"Point k visé à nouveau après un recalage : intersection du rayon et du plan calé.\n            Recalé sur la carte : à la position de la carte, à l'altitude du rayon de visée.\"\"\"\n            if k in self.aimed and anchored is not None:  # plan calé, pas la surface de la mesure\n                return geometry.on_plane(click, h(click), origin, *anchored, ground_z=zof(click))[0]\n            if k not in anchors:\n                return p\n            x, y, _ = anchors[k]\n            cam, u = geometry.camera(click, h(click), origin, zof(click))\n            reach = math.hypot(x - cam[0], y - cam[1])\n            return (x, y, cam[2] + reach * u[2] / max(math.hypot(u[0], u[1]), 1e-9))\n\n        def recaled(k):\n            \"\"\"Point k visé à nouveau dans le plan calé : la surface de la mesure ne sert pas.\"\"\"\n            return k in self.aimed and anchored is not None\n\n        pts, sources, incidence, plane = [], [], None, None\n        if self.surface == \"ground\":\n            for c in clicks:\n                k = len(pts)\n                pts.append(fixed(k, None if recaled(k) else geometry.on_ground(c, h(c), origin, zof(c))[0], c))\n                sources.append(c)\n        else:  # plan vertical face à la caméra\n            first = fixed(0, geometry.on_ground(clicks[0], h(clicks[0]), origin, zof(clicks[0]))[0], clicks[0])\n            cam = geometry.camera(clicks[0], h(clicks[0]), origin, zof(clicks[0]))[0]\n            plane = geometry.facing_plane(cam, first)\n            planar, pts, sources = clicks[1:], [first], [clicks[0]]\n            for c in planar:\n                if recaled(len(pts)):\n                    pts.append(fixed(len(pts), None, c))\n                    sources.append(c)\n                    continue\n                p, angle = geometry.on_plane(c, h(c), origin, *plane, ground_z=zof(c))\n                pts.append(fixed(len(pts), p, c))\n                sources.append(c)\n                incidence = angle if incidence is None else min(incidence, angle)\n        if self.lifts:  # points montés ou descendus au clavier\n            pts = [(p[0], p[1], p[2] + self.lifts.get(k, 0.0)) for k, p in enumerate(pts)]\n        return pts, incidence, origin, sources\n\n    @property\n    def axis(self):\n        \"\"\"Axe de la route retenu (cap en degrés) : au point mesuré si connu (voir roads.py),\n        sinon direction du véhicule à la caméra, portée par le premier clic.\"\"\"\n        return self.road[\"axis\"] if self.road else self.clicks[0].get(\"axis\")\n\n    @property\n    def axis_source(self):\n        if self.road:\n            return self.road[\"source\"]\n        source = self.clicks[0].get(\"axis_source\")\n        return source + \", lecture de la BD TOPO…\" if self.road_pending and source else source\n\n    def _road_axis(self, pts, origin):\n        \"\"\"Axe de la route au milieu des deux bords (voir roads.py), si l'outil sait le lire.\"\"\"\n        lookup = self.tool.road_lookup\n        self.road, self.road_pending = None, False\n        if lookup is None:\n            return\n        mid = ((pts[0][0] + pts[1][0]) / 2, (pts[0][1] + pts[1][1]) / 2, pts[0][2])\n        lon, lat = geometry.to_geographic(mid, origin)[:2]\n        crossing = math.degrees(math.atan2(pts[1][0] - pts[0][0], pts[1][1] - pts[0][1])) % 360\n        res = lookup(lon, lat, crossing, self.clicks[0].get(\"sequence\"))\n        if isinstance(res, dict):\n            self.road = res\n        else:\n            self.road_pending = res == \"pending\"\n\n    def quantity(self, d):\n        \"\"\"Grandeur mesurée d'après la décomposition d (voir geometry.decompose).\"\"\"\n        if self.kind == \"road\":\n            if d[\"across\"] is None:\n                raise geometry.GeometryError(\"Axe de la route inconnu pour cette photo : largeur impossible \"\n                                             \"à calculer.\")\n            return d[\"across\"]\n        if self.kind == \"height\":\n            if d[\"vertical\"] <= 0:\n                raise geometry.GeometryError(\"Le sommet est sous le pied : cliquez d'abord au pied, puis au \"\n                                             \"sommet.\")\n            return abs(d[\"vertical\"])\n        return d[\"d3\"]\n\n    def _value(self, **variant):\n        pts, _, _, _ = self.points(**variant)\n        return self.quantity(geometry.decompose(pts[0], pts[1], self.axis))\n\n    def _spread(self):\n        \"\"\"Incertitude de la mesure (m) : somme quadratique des écarts dus à chaque source\n        d'erreur indépendante, chacune prise à ±1 écart-type :\n        - inclinaison de chaque photo, commune à tous ses clics (tangage et roulis) : celle du\n          calage appliqué, ou UNCALIBRATED sans calage ;\n        - hauteur de caméra de chaque photo (CAMERA_ERRORS, ou celle de la hauteur calée) ;\n        - visée de chaque clic (AIM_ERROR) ;\n        - position de chaque point recalé sur la carte, façade du cadastre.\"\"\"\n        ref = self._value()\n        groups = []  # par source d'erreur : variantes à ±1 écart-type\n        for pic in dict.fromkeys(c.get(\"pic\") for c in self.clicks):\n            sigma = self._tilt_sigma(pic)\n            for comp in ((sigma, 0.0), (0.0, sigma)):\n                groups.append([{\"clicks\": self._tilted_clicks(self.clicks, pic, sign * comp[0], sign * comp[1])}\n                               for sign in (-1, 1)])\n            dh = self._camera_sigma(pic)\n            groups.append([{\"camera_delta\": {pic: sign * dh}} for sign in (-1, 1)])\n        for i in range(len(self.clicks)):\n            for key, step in ((\"elev\", AIM_ERROR), (\"yaw\", AIM_ERROR)):\n                variants = []\n                for sign in (-1, 1):\n                    moved = [dict(x) for x in self.clicks]\n                    moved[i][key] += sign * step\n                    variants.append({\"clicks\": moved})\n                groups.append(variants)\n        if self.reference is not None:  # tous les points calés ensemble sur le point triangulé\n            sigma = self.reference[\"uncertainty\"]\n            for dx, dy in ((1, 0), (0, 1)):\n                groups.append([{\"overrides\": {\n                    k: triangulation._geographic(sign * dx * sigma, sign * dy * sigma, lon, lat) + (azimuth,)\n                    for k, (lon, lat, azimuth) in self.overrides.items()}} for sign in (-1, 1)])\n        else:\n            for k, (lon, lat, azimuth) in self.overrides.items():\n                for dx, dy in ((1, 0), (0, 1)):\n                    variants = []\n                    for sign in (-1, 1):\n                        moved = dict(self.overrides)\n                        moved[k] = triangulation._geographic(sign * dx * MAP_ERROR, sign * dy * MAP_ERROR, lon, lat) + (azimuth,)\n                        variants.append({\"overrides\": moved})\n                    groups.append(variants)\n        total = 0.0\n        for variants in groups:\n            worst = 0.0\n            for variant in variants:\n                try:\n                    worst = max(worst, abs(self._value(**variant) - ref))\n                except ERRORS:\n                    return float(\"inf\")\n            total += worst * worst\n        return math.sqrt(total)\n\n    def _tilt_sigma(self, pic):\n        \"\"\"Incertitude (degrés) de l'inclinaison appliquée aux clics de la photo.\"\"\"\n        cal = self.tool.calibration\n        tilt = cal.tilt(pic) if cal is not None and pic else None\n        return tilt[\"sigma\"] if tilt and tilt.get(\"sigma\") is not None else UNCALIBRATED\n\n    def _camera_sigma(self, pic):\n        \"\"\"Incertitude (m) de la hauteur de caméra de la photo, selon sa source.\"\"\"\n        c = next(x for x in self.clicks if x.get(\"pic\") == pic)\n        _, source = self.tool.camera_info(c)\n        if source == \"calée\":\n            return self.tool.calibration.camera(c.get(\"sequence\"))[\"sigma\"]\n        return CAMERA_ERRORS.get(source, CAMERA_ERRORS[None])\n\n    @staticmethod\n    def _tilted_clicks(clicks, pic, north, east):\n        \"\"\"Clics de la photo pic vus par une caméra penchée en plus de north° vers le nord et\n        east° vers l'est (variation d'inclinaison commune à tous ses clics).\"\"\"\n        up = calibration.up_from_components(north, east, 0.0)\n        out = []\n        for c in clicks:\n            c = dict(c)\n            if c.get(\"pic\") == pic:\n                c[\"yaw\"], c[\"elev\"] = calibration.untilt(up, c[\"yaw\"], c[\"elev\"])\n            out.append(c)\n        return out\n\n    def compute(self):\n        self.result, self.error, self.incidence = None, None, None\n        try:\n            if self.kind == \"height\" and len(self.clicks) == 2 and self.clicks[0].get(\"pic\") != self.clicks[1].get(\"pic\"):\n                raise geometry.GeometryError(\"Le pied et le sommet doivent être cliqués sur la même photo.\")\n            pts, self.incidence, origin, sources = self.points()\n            if len(pts) == 2 and len(self.clicks) == self.needed():\n                if self.kind == \"road\":\n                    self._road_axis(pts, origin)\n                d = geometry.decompose(pts[0], pts[1], self.axis)\n                value = self.quantity(d)\n                lonlat = [geometry.to_geographic(p, origin)[:2] for p in pts]\n                ranges = []\n                for p, c in zip(pts, sources):\n                    cx, cy = triangulation._local(c[\"lon\"], c[\"lat\"], origin[0], origin[1])\n                    ranges.append(math.hypot(p[0] - cx, p[1] - cy))\n                self.result = {\"value\": value, \"decomposition\": d, \"uncertainty\": self._spread(),\n                               \"ranges\": ranges, \"points\": lonlat, \"extra\": None, \"picks\": lonlat,\n                               \"shifts\": self._shifts(pts, origin)}\n                if self.kind == \"road\":\n                    # Trait perpendiculaire à l'axe, à mi-chemin des deux bords cliqués le long de la\n                    # route ; chaque bout est relié en pointillés à son bord cliqué\n                    a = math.radians(self.axis)\n                    ux, uy = math.sin(a), math.cos(a)\n                    half = ((pts[1][0] - pts[0][0]) * ux + (pts[1][1] - pts[0][1]) * uy) / 2.0\n                    start = (pts[0][0] + half * ux, pts[0][1] + half * uy, pts[0][2])\n                    end = (pts[1][0] - half * ux, pts[1][1] - half * uy, pts[0][2])\n                    self.result[\"points\"] = [geometry.to_geographic(p, origin)[:2] for p in (start, end)]\n                    self.result[\"extra\"] = list(lonlat)\n                elif self.kind == \"height\":\n                    self.result[\"points\"] = [lonlat[0]]  # sommet au-dessus du pied\n        except ERRORS as exc:\n            self.error = str(exc)\n        self._draw()\n\n    def _shifts(self, pts, origin):\n        \"\"\"Pour chaque clic, écart (cap, élévation en degrés) entre la direction cliquée et\n        celle où la caméra voit le point 3D qui en résulte : nul pour un point resté sur sa\n        visée, non nul pour un point recalé de côté sur la carte.\"\"\"\n        ground_z = _ground_z(self.clicks)\n        out = []\n        for i, c in enumerate(self.clicks):\n            p = pts[i]\n            z = ground_z[c.get(\"pic\")]\n            cam, _ = geometry.camera(c, self.tool.camera_for(c), origin, z)\n            vx, vy, vz = p[0] - cam[0], p[1] - cam[1], p[2] - cam[2]\n            yaw = math.degrees(math.atan2(vx, vy))\n            elev = math.degrees(math.atan2(vz, math.hypot(vx, vy)))\n            out.append(((yaw - c[\"yaw\"] + 540) % 360 - 180, elev - c[\"elev\"]))\n        return out\n\n    def picks(self):\n        \"\"\"Points recalables sur la carte : [(n° de point, lon, lat)]. Sur le plan vertical\n        face à la caméra (hauteur), seul le pied l'est : le sommet en découle.\"\"\"\n        if self.result:\n            pts = [(k, p[0], p[1]) for k, p in enumerate(self.result[\"picks\"])]\n        else:\n            try:\n                raw, _, origin, _ = self.points()\n            except ERRORS:\n                return []\n            pts = [(k,) + geometry.to_geographic(p, origin)[:2] for k, p in enumerate(raw)]\n        return pts[:1] if self.surface == \"vertical\" else pts\n\n    # Affichage ----------------------------------------------------------------\n    def label(self):\n        if not self.result:\n            return \"\"\n        symbol = \"↕ \" if self._vertical() else \"↔ \"\n        return \"{}{} m ± {} m\".format(symbol, _num(self.result[\"value\"], 2), _num(self.result[\"uncertainty\"], 2))\n\n    def _vertical(self):\n        if self.kind in (\"road\", \"width\"):\n            return False\n        return True  # hauteur\n\n    def _draw(self):\n        if self.result:\n            points, extra = self.result[\"points\"], self.result[\"extra\"]\n            label = \"{} m\".format(_num(self.result[\"value\"], 2))\n        else:\n            points, extra, label = [p[1:] for p in self.picks()], None, \"\"\n        if self.item is None and points:\n            self.item = self.tool.new_item()\n        if self.item is not None:\n            self.item.set_data(points, label, extra)\n\n    def remove(self):\n        if self.item is not None:\n            self.item.remove()\n            self.item = None\n\n    def point_of_click(self, i):\n        \"\"\"N° du point auquel contribue le clic n° i.\"\"\"\n        return i\n\n    def viewer_marks(self, selected=None):\n        \"\"\"Repères dans la visionneuse (dessinés par src/traits.js) : là où la\n        photo voit chaque point 3D, c'est-à-dire à l'endroit cliqué, décalé d'autant que le\n        point a été recalé de côté sur la carte. selected : n° du point sélectionné.\"\"\"\n        shifts = (self.result or {}).get(\"shifts\") or [(0.0, 0.0)] * len(self.clicks)\n        points = []\n        for i, (c, (dyaw, delev)) in enumerate(zip(self.clicks, shifts)):\n            pos = c.get(\"pos\") or [None, None]\n            raw = c.get(\"raw\") or [c[\"yaw\"], c[\"elev\"]]\n            if pos[0] is not None:  # position dans la photo (radians), visionneuse web\n                pos = [pos[0] + math.radians(dyaw), pos[1] + math.radians(delev)]\n            points.append({\"pic\": c.get(\"pic\"), \"yaw\": pos[0], \"pitch\": pos[1],\n                           \"abs_yaw\": raw[0] + dyaw, \"elev\": raw[1] + delev,\n                           \"sel\": selected is not None and self.point_of_click(i) == selected})\n        return {\"points\": points, \"label\": self.label(), \"beside\": bool(self.result) and self._vertical()}\n\n    def status(self):\n        \"\"\"Résultat (mesure complète) ; les consignes de clic sont dans MeasureTool.status.\"\"\"\n        r = self.result\n        d = r[\"decomposition\"]\n        value, unc = _num(r[\"value\"], 2), _num(r[\"uncertainty\"], 2)\n        if self.kind == \"road\":\n            text = (\"Largeur perpendiculaire à la chaussée : {} m (±{} m) · en biais {} m · axe {}° ({})\").format(\n                value, unc, _num(d[\"horizontal\"], 2), _num(self.axis % 180, 0), self.axis_source or \"?\")\n        elif self.kind == \"width\":\n            text = \"Longueur : {} m (±{} m) entre les deux points · à {} et {} m de la photo\".format(\n                value, unc, _num(r[\"ranges\"][0]), _num(r[\"ranges\"][1]))\n            if abs(d[\"vertical\"]) >= 0.05:\n                text += \" · dénivelé {} m\".format(_num(d[\"vertical\"], 2))\n        elif self.kind == \"height\":\n            text = \"Hauteur : {} m (±{} m) · objet à {} m\".format(value, unc, _num(r[\"ranges\"][0]))\n        if self.reference is not None:\n            text += \" · calée sur le point triangulé {}(±{} m)\".format(\n                self.reference[\"name\"] + \" \" if self.reference[\"name\"] else \"\", _num(self.reference[\"uncertainty\"], 2))\n        elif self.overrides:\n            text += \" · {} point{} recalé{} sur la carte\".format(\n                len(self.overrides), *((\"s\", \"s\") if len(self.overrides) > 1 else (\"\", \"\")))\n            if self.aimed:\n                text += \", dont {} visé{} à nouveau dans son plan\".format(\n                    len(self.aimed), \"s\" if len(self.aimed) > 1 else \"\")\n        moved = {k: dz for k, dz in self.lifts.items() if abs(dz) >= 0.005}\n        if moved:\n            text += \" · \" + \", \".join(\"{} {} de {} cm\".format(\n                \"pied\" if self.kind == \"height\" and k == 0 else \"sommet\" if self.kind == \"height\" else \"point {}\".format(k + 1),\n                \"monté\" if dz > 0 else \"descendu\", _num(abs(dz) * 100, 0)) for k, dz in sorted(moved.items())) + \" au clavier\"\n        if self.incidence is not None and self.incidence < geometry.GRAZING:\n            text += \". Visée rasante sur le plan ({}°) : mesure imprécise, prenez une photo plus en face\".format(\n                _num(self.incidence, 0))\n        if self.reference is not None and not self.aimed and len(self.overrides) == len(self.clicks):\n            return text + \". Profondeur du point triangulé : terrain et hauteur de caméra sans effet.\"\n        height, source = self.tool.camera_info(self.clicks[0])\n        text += \". Terrain : {}, caméra à {} m{}.\".format(ground.FLAT, _num(height, 2),\n                                                        \" ({})\".format(source) if source else \"\")\n        if self.notice:\n            text += \" ({}.)\".format(self.notice)\n        return text + \" Point mal placé : glissez-le sur la carte.\"\n\n\nclass MeasureTool:\n    \"\"\"Mesure en cours, mesures terminées gardées à l'écran et réglages.\"\"\"\n\n    def __init__(self, canvas):\n        self.canvas = canvas\n        self.mode = \"road\"  # \"road\", \"width\" ou \"height\"\n        self.camera_height = DEFAULT_CAMERA_HEIGHT  # hauteur saisie dans le panneau\n        self.road_lookup = None  # roads.RoadAxisProvider.lookup : axe de la route au point mesuré\n        self.calibration = None  # calibration.Calibration : hauteur calée par séquence\n        self.error = None\n        self.current = None\n        self.done = []  # mesures terminées, gardées à l'écran jusqu'à clear_all\n        self.selected = None  # (mesure, n° de point) à viser à nouveau dans la visionneuse\n\n    def new_item(self):\n        \"\"\"Dessin d'une mesure sur la carte : set_data(points, libellé, extras) et remove(). Rien ici : la page dessine la\n        carte d'après App.map_geojson.\"\"\"\n        return NullItem()\n\n    # Réglages ---------------------------------------------------------------\n    def set_mode(self, mode):\n        if mode != self.mode:\n            self.finish()\n            self.mode = mode\n\n    def set_camera_height(self, value):\n        self.camera_height = float(value)\n        if self.current is not None:\n            self.current.compute()\n\n    def camera_info(self, click):\n        \"\"\"(hauteur de caméra du clic, source) ; source \"calée\" ou None : hauteur calée pour la séquence,\n        sinon le réglage du panneau. Les mesures n'en dépendent pas (point triangulé, direction des clics) ;\n        la hauteur mesurée (altitude RTK moins sol LiDAR) et la monture du CD21 sont prises par la page\n        (Session.camera_of) pour le tablier d'un pont, les objets au sol et l'export.\"\"\"\n        sequence = click.get(\"sequence\")\n        cam = self.calibration.camera(sequence) if self.calibration and sequence else None\n        return (cam[\"height\"], \"calée\") if cam else (self.camera_height, None)\n\n    def camera_for(self, click):\n        return self.camera_info(click)[0]\n\n    # Clics --------------------------------------------------------------------\n\n    def cancel_selection(self):\n        \"\"\"Annule la sélection d'un point. Retourne True s'il y en avait une.\"\"\"\n        if self.selected is None:\n            return False\n        self.selected = None\n        return True\n\n    def add_click(self, click, notice=None):\n        self.error = None\n        if self.selected is not None:  # visée à nouveau du point sélectionné\n            measure, index = self.selected\n            self.selected = None\n            if notice:\n                measure.notice = notice\n            measure.reaim(index, click)\n            if measure.error:\n                return measure.error + \" \" + (measure.status() if measure.result else \"\")\n            return measure.status()\n        if self.current is None or len(self.current.clicks) >= self.current.needed():\n            self.finish()  # nouvelle mesure, la précédente reste affichée\n            self.current = Measure(self, self.mode, PRESET_SURFACES[self.mode])\n        self.current.add_click(click, notice)\n        return self.status()\n\n    def finish(self):\n        \"\"\"Termine la mesure en cours : réussie, elle reste affichée (visionneuse et carte)\n        jusqu'à clear_all ; sinon elle est abandonnée.\"\"\"\n        if self.current is not None:\n            if self.current.result:\n                self.done.append(self.current)\n            else:\n                self.current.remove()\n        self.current, self.selected = None, None\n\n    def clear(self):\n        \"\"\"Efface la mesure en cours (les mesures terminées restent affichées).\"\"\"\n        if self.current is not None:\n            self.current.remove()\n        self.current, self.error, self.selected = None, None, None\n\n    def clear_all(self):\n        \"\"\"Efface aussi les mesures terminées.\"\"\"\n        self.clear()\n        for m in self.done:\n            m.remove()\n        self.done = []\n\n    def remove(self):\n        self.clear_all()\n\n    def measures(self):\n        \"\"\"Toutes les mesures affichées (terminées, puis en cours).\"\"\"\n        return self.done + ([self.current] if self.current is not None else [])\n\n    def recompute_roads(self):\n        \"\"\"Axe de la route arrivé (voir roads.py) : largeurs perpendiculaires recalculées.\n        Retourne le nombre de mesures concernées.\"\"\"\n        roads = [m for m in self.measures() if m.kind == \"road\" and len(m.clicks) == m.needed()]\n        for m in roads:\n            m.compute()\n        return len(roads)\n\n    # Recalage sur la carte ----------------------------------------------------\n    def handles(self):\n        \"\"\"Poignées déplaçables sur la carte : [(clé, lon, lat)], clé (\"point\", mesure,\n        n° de point).\"\"\"\n        return [((\"point\", m, k), lon, lat) for m in self.measures() for k, lon, lat in m.picks()]\n\n    def move_handle(self, key, lon, lat):\n        \"\"\"Recale une poignée à (lon, lat). Retourne le texte à afficher dans le panneau.\"\"\"\n        measure, index = key[1], key[2]\n        measure.relocate(index, lon, lat)\n        if measure.error:\n            return measure.error + \" Recalage annulé.\"\n        return measure.status() if measure.result else self.status()\n\n    # Visionneuse ----------------------------------------------------------------\n    def _marks(self, m):\n        return m.viewer_marks(self.selected[1] if self.selected and self.selected[0] is m else None)\n\n    def viewer_marks(self):\n        if self.current is None:\n            return {\"points\": [], \"label\": \"\", \"beside\": False}\n        return self._marks(self.current)\n\n    def status(self):\n        prefix = (self.error + \" \") if self.error else \"\"\n        if self.selected is not None:\n            measure, index = self.selected\n            where = (\" : il sera placé dans le plan calé sur la carte\" if measure.overrides else\n                     \" : il sera replacé sur la {}\".format(SURFACE_NAMES[measure.surface]))\n            return (\"Point {} sélectionné{}. Cliquez sa position exacte dans la photo (zoomez pour être précis), \"\n                    \"ou « Effacer » pour annuler.\").format(index + 1, where)\n        m = self.current\n        if m is not None and m.result:\n            return m.status()\n        n = len(m.clicks) if m is not None else 0\n        if m is not None and m.error:\n            prefix = m.error + \" \"\n        hints = {\n            \"road\": (\"Cliquez au pied du premier bord (bordure, marquage, limite de chaussée…).\",\n                     \"Cliquez au pied du bord opposé, pas forcément juste en face : la largeur est prise \"\n                     \"perpendiculairement à la route.\"),\n            \"width\": (\"Cliquez au sol à une extrémité de l'objet.\",\n                      \"Cliquez au sol à l'autre extrémité : la distance directe entre les deux points est mesurée.\"),\n            \"height\": (\"Cliquez dans la photo au pied de l'objet, exactement au contact du sol.\",\n                       \"Cliquez au sommet de l'objet, sur la même photo.\"),\n        }[self.mode]\n        return prefix + hints[min(n, 1)]\n",
 "core/metadata.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Fiches des photos Panoramax (STAC) : cap, précision et altitude GPS, liens, recherche.\nSans réseau : les fiches sont lues par la page (host.fetch_json).\"\"\"\n\nimport math\nfrom urllib.parse import urlencode, urlsplit\n\n\ndef search_url(lon, lat, radius_m=25, limit=20, collection=None, api_url=\"https://api.panoramax.xyz/api\"):\n    \"\"\"URL de recherche STAC des photos autour d'un point (bbox carrée), éventuellement d'une\n    seule séquence.\"\"\"\n    dlat = radius_m / 111320.0\n    dlon = radius_m / (111320.0 * max(math.cos(math.radians(lat)), 0.01))\n    bbox = \"{:.7f},{:.7f},{:.7f},{:.7f}\".format(lon - dlon, lat - dlat, lon + dlon, lat + dlat)\n    params = {\"bbox\": bbox, \"limit\": limit}\n    if collection:\n        params[\"collections\"] = collection\n    return \"{}/search?{}\".format(api_url, urlencode(params))\n\n\ndef item_heading(item):\n    props = item.get(\"properties\", {}) or {}\n    for key in (\"view:azimuth\", \"heading\"):\n        if props.get(key) is not None:\n            try:\n                return float(props[key])\n            except (TypeError, ValueError):\n                pass\n    return None\n\n\ndef precise_heading(item):\n    \"\"\"Cap de la photo au centième de degré, tiré de l'EXIF (GPSImgDirection), ou None.\n\n    L'API arrondit view:azimuth au degré : jusqu'à 0,5° d'erreur de visée, soit\n    17 cm à 20 m. La valeur EXIF n'est retenue que si elle concorde avec\n    view:azimuth (même mesure, non arrondie), pas si l'API a corrigé le cap.\n    \"\"\"\n    rounded = item_heading(item)\n    exif = ((item.get(\"properties\", {}) or {}).get(\"exif\") or {}).get(\"Exif.GPSInfo.GPSImgDirection\")\n    if rounded is None or not exif:\n        return None\n    try:\n        num, _, den = str(exif).partition(\"/\")\n        value = float(num) / float(den or 1)\n    except (TypeError, ValueError, ZeroDivisionError):\n        return None\n    return value % 360 if abs((value - rounded + 540) % 360 - 180) < 1.0 else None\n\n\ndef _exif_number(item, key):\n    \"\"\"Valeur numérique d'une balise EXIF de la fiche (rationnel « a/b » ou nombre), ou None.\"\"\"\n    value = ((item.get(\"properties\", {}) or {}).get(\"exif\") or {}).get(key)\n    try:\n        num, _, den = str(value).partition(\"/\")\n        return float(num) / float(den or 1)\n    except (TypeError, ValueError, ZeroDivisionError):\n        return None\n\n\ndef exif_accuracy(item):\n    \"\"\"Précision horizontale de la position (m) déclarée dans l'EXIF de la photo\n    (GPSHPositioningError), ou None si la photo ne la déclare pas.\"\"\"\n    value = _exif_number(item, \"Exif.GPSInfo.GPSHPositioningError\")\n    return value if value is not None and value > 0 else None\n\n\ndef gps_differential(item):\n    \"\"\"La position de la photo a-t-elle reçu une correction différentielle (EXIF GPSDifferential) ?\n    DGPS ou RTK : la précision réelle reste à vérifier (voir precision.py).\"\"\"\n    return _exif_number(item, \"Exif.GPSInfo.GPSDifferential\") == 1\n\n\ndef item_accuracy(item):\n    \"\"\"Précision horizontale de la position GPS de la photo (m), ou None si inconnue : celle\n    déclarée dans l'EXIF, sinon celle annoncée par Panoramax (souvent générique).\"\"\"\n    value = exif_accuracy(item)\n    if value is not None:\n        return value\n    value = (item.get(\"properties\", {}) or {}).get(\"quality:horizontal_accuracy\")\n    try:\n        value = float(value)\n    except (TypeError, ValueError):\n        return None\n    return value if value > 0 else None\n\n\ndef item_altitude(item):\n    \"\"\"Altitude GPS ellipsoïdale de la caméra (m, EXIF GPSAltitude), ou None. Souvent imprécise :\n    à n'utiliser que pour une position vérifiée (voir precision.py).\"\"\"\n    altitude = _exif_number(item, \"Exif.GPSInfo.GPSAltitude\")\n    if altitude is None:\n        return None\n    return -altitude if _exif_number(item, \"Exif.GPSInfo.GPSAltitudeRef\") == 1 else altitude\n\n\ndef item_link(item, rel):\n    for link in item.get(\"links\", []) or []:\n        if link.get(\"rel\") == rel and link.get(\"href\"):\n            return link[\"href\"]\n    return None\n\n\ndef id_from_href(href):\n    \"\"\"Dernier segment d'une URL d'item STAC (= identifiant de la photo).\"\"\"\n    return urlsplit(href).path.rstrip(\"/\").rsplit(\"/\", 1)[-1] if href else None\n\n\ndef sequence_axis(item, prev_item, next_item):\n    \"\"\"Direction de déplacement le long de la séquence (cap en degrés), ou None.\n\n    Calculée entre les photos voisines (précédente et suivante, fiches STAC ou None) pour\n    suivre l'axe de la voie, plutôt que l'orientation de la caméra.\n    \"\"\"\n    def position(feat):\n        try:\n            return [float(v) for v in feat[\"geometry\"][\"coordinates\"][:2]]\n        except (KeyError, TypeError, ValueError):\n            return None\n\n    here = position(item)\n    a = position(prev_item) if prev_item else None\n    b = position(next_item) if next_item else None\n    a, b = (a or here), (b or here)\n    if a is None or b is None or a == b:\n        return None\n    dx = (b[0] - a[0]) * math.cos(math.radians((a[1] + b[1]) / 2))\n    dy = b[1] - a[1]\n    if math.hypot(dx, dy) * 111320.0 < 0.5:  # photos quasi confondues (arrêt) : direction peu fiable\n        return None\n    return math.degrees(math.atan2(dx, dy)) % 360\n",
 "core/precision.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Précision de la position GPS des photos, vérifiée d'après leurs métadonnées.\n\nPanoramax annonce souvent une précision générique (2 m pour le matériel de relevé). Une\nphoto est jugée précise (au décimètre) :\n- si son EXIF déclare une précision (GPSHPositioningError) d'au plus PRECISE_ACCURACY ;\n- ou si sa position a reçu une correction différentielle (GPSDifferential) et que cela se\n  vérifie sur sa séquence : pour les photos voisines, l'altitude GPS (convertie en NGF)\n  moins le sol LiDAR HD sous la photo, c'est-à-dire la hauteur de la caméra, est constante\n  à MAX_SPREAD près, sans dériver de plus de MAX_DRIFT. Un GPS non recalé (DGPS, GPS\n  simple) varie de plusieurs décimètres. Si la portion de séquence autour de la photo est\n  refusée (pont, défaut du LiDAR), d'autres portions de la séquence sont essayées : une\n  seule vérifiée suffit pour toute la séquence.\n  C'est le cas des photos imajbox 360 HD (RTK et centrale inertielle : 4,7 cm sur 100\n  photos à Pouilly-en-Auxois).\n\nUne photo précise donne la hauteur de caméra par son altitude moins le sol LiDAR (voir\nSession._camera_height). Les mesures ne sont pleinement fiables qu'avec à la\nfois une position vérifiée précise et le LiDAR HD sous la photo ; sinon l'outil est en\nmode dégradé (hauteur de caméra et inclinaison à caler, sol approximatif sans LiDAR) :\nune fenêtre l'annonce à l'activation de la mesure (src/app.js, « alerte-rtk »).\n\nUne vérification par séquence (deux requêtes : fiches des photos voisines, altitudes\nLiDAR), en arrière-plan ; le résultat est gardé pour la session.\n\"\"\"\n\nimport math\nimport statistics\nfrom urllib.parse import urlencode\n\nfrom . import host, metadata\n\nPRECISE_ACCURACY = 0.20  # m : précision déclarée suffisante pour la hauteur de caméra par l'altitude\nVERIFIED_ACCURACY = 0.10  # m : précision retenue pour une séquence vérifiée\nCHECK_RADIUS = 60.0  # m autour de la photo pour les photos voisines de la séquence\nCHECK_PHOTOS = 20\n# Portion autour de la photo refusée : autres portions de la même séquence essayées (une\n# seule vérifiée suffit, la séquence est relevée avec le même matériel)\nOTHER_PORTIONS = 2\nOTHER_RADIUS = 1000.0  # m\nOTHER_SEARCH = 100  # photos de la séquence parmi lesquelles choisir les autres portions\nMIN_PHOTOS = 8\n# Hauteur de caméra entre photos voisines : écart-type et dérive maximaux. Le sol LiDAR HD\n# (±10 cm), les bordures, le dévers et la suspension du véhicule la font varier de plus\n# de 10 cm sur des séquences RTK (Pouilly-en-Auxois, 2026-10-15 : 5 points sur 72 refusés\n# à 10 cm, de 10,5 à 19,8 cm, ou dérive de 11 cm) ; un GPS non recalé varie de plusieurs\n# décimètres.\nMAX_SPREAD = 0.20  # m : écart-type\nMAX_DRIFT = 0.15  # m : écart entre les deux moitiés de la portion vérifiée\nOUTLIER = 4.0  # photos écartées au-delà de OUTLIER écarts médians absolus (corrigés)\nMIN_MAD = 0.02  # m : écart médian minimal (photos très régulières)\nCAMERA_RANGE = (0.5, 4.0)  # hauteur de caméra plausible (m)\nELEVATION_URL = \"https://data.geopf.fr/altimetrie/1.0/calcul/alti/rest/elevation.json\"\nLIDAR_RESOURCE = \"ign_lidar_hd_mnt_mono_wld\"  # MNT LiDAR HD 50 cm, publié département par département\nRGE_RESOURCE = \"ign_rge_alti_wld\"  # RGE ALTI 1 m, tout le territoire : en secours du LiDAR HD\nTERRAINS = ((\"LiDAR HD\", LIDAR_RESOURCE), (\"RGE ALTI\", RGE_RESOURCE))  # sources du sol, dans l'ordre\nNODATA_BELOW = -9999.0  # le service IGN renvoie -99999 hors de sa couverture\nTIMEOUT_MS = 5000  # délai de réponse du service d'altimétrie\n\n\ndef lidar_url(points, resource=LIDAR_RESOURCE):\n    \"\"\"URL des altitudes du sol (MNT LiDAR HD, ou resource) sous des points [(lon, lat)].\"\"\"\n    return ELEVATION_URL + \"?\" + urlencode({\n        \"lon\": \"|\".join(\"{:.7f}\".format(lon) for lon, _ in points),\n        \"lat\": \"|\".join(\"{:.7f}\".format(lat) for _, lat in points),\n        \"resource\": resource, \"zonly\": \"true\"}, safe=\"|\")\n\n\ndef fetch_terrain(points, done, timeout_ms=TIMEOUT_MS):\n    \"\"\"Altitudes du sol sous des points [(lon, lat)] : MNT LiDAR HD ; s'il manque sous l'un\n    d'eux (pas encore publié là), RGE ALTI pour tous (une seule source pour des altitudes\n    comparées entre elles). done(altitudes (None hors couverture), source (nom de TERRAINS, ou\n    None si aucune altitude), erreur). Le RGE ALTI injoignable : les altitudes LiDAR HD lues.\"\"\"\n    def step(k, previous=None):\n        name, resource = TERRAINS[k]\n\n        def got(data, error):\n            if error:\n                if previous is None:\n                    done(None, None, error)\n                else:\n                    done(previous, TERRAINS[0][0] if any(z is not None for z in previous) else None, None)\n                return\n            zs = _ground(data)\n            complete = len(zs) == len(points) and None not in zs\n            if complete or k + 1 == len(TERRAINS):\n                done(zs, name if any(z is not None for z in zs) else None, None)\n            else:\n                step(k + 1, zs)\n\n        host.fetch_json(lidar_url(points, resource), got, timeout_ms=timeout_ms)\n\n    step(0)\n\n\ndef _ground(data):\n    \"\"\"Altitudes d'une réponse du service d'altimétrie (None hors couverture).\"\"\"\n    out = []\n    for z in (data or {}).get(\"elevations\") or []:\n        try:\n            z = float(z[\"z\"] if isinstance(z, dict) else z)\n        except (KeyError, TypeError, ValueError):\n            z = None\n        out.append(z if z is not None and z > NODATA_BELOW else None)\n    return out\n\n\ndef result(precise, accuracy=None, lidar=None, reason=\"\", count=0, spread=None, height=None, transient=False,\n           terrain=None):\n    \"\"\"Résultat d'une vérification : precise, accuracy (m, ou None : celle de la photo), lidar (modèle\n    de terrain publié sous la photo, None si inconnu), terrain (sa source : « LiDAR HD » ou, en\n    secours, « RGE ALTI »), reason (texte), count et spread pour une séquence vérifiée, height :\n    hauteur de caméra calculée (altitude GPS moins sol ; médiane de la séquence vérifiée, ou celle\n    de la photo de précision déclarée), None si inconnue. transient : obtenu malgré un service\n    injoignable, donc pas gardé pour la session (vérification refaite).\"\"\"\n    return {\"precise\": precise, \"accuracy\": accuracy, \"lidar\": lidar, \"reason\": reason, \"count\": count,\n            \"spread\": spread, \"height\": height, \"transient\": transient,\n            \"terrain\": terrain or (TERRAINS[0][0] if lidar else None)}\n\n\ndef terrain_name(res):\n    \"\"\"Source du sol d'une vérification (« LiDAR HD » si elle ne le dit pas).\"\"\"\n    return (res or {}).get(\"terrain\") or TERRAINS[0][0]\n\n\ndef degraded(res):\n    \"\"\"Mode dégradé : il manque la position vérifiée précise ou le LiDAR HD sous la photo\n    (False tant que la vérification n'est pas faite).\"\"\"\n    return bool(res) and not (res[\"precise\"] and res[\"lidar\"] is True)\n\n\ndef camera_suggestion(res):\n    \"\"\"Hauteur de caméra calculée à proposer dans le panneau : (hauteur, explication), ou None.\"\"\"\n    if not res or not res[\"precise\"] or res[\"lidar\"] is not True or res.get(\"height\") is None:\n        return None\n    if res[\"count\"]:\n        how = \"médiane de {} photos de la séquence, écart-type {:.0f} cm\".format(res[\"count\"], res[\"spread\"] * 100)\n    else:\n        how = \"photo de précision déclarée ±{:.0f} cm\".format(res[\"accuracy\"] * 100)\n    return res[\"height\"], (\"Hauteur de caméra calculée : altitude GPS de la caméra (NGF) moins le sol {} \"\n                           \"({}). Cliquer pour remplir le champ « Caméra à ».\".format(terrain_name(res), how))\n\n\ndef computed_text(res):\n    \"\"\"Précision GPS calculée, à côté de celle annoncée par la photo : résultat de la vérification\n    (hauteur de caméra constante au-dessus du sol LiDAR HD ou RGE ALTI), ou pourquoi elle manque.\"\"\"\n    def cm(value):\n        return \"{:.0f}\".format(value * 100)\n\n    if not res:\n        return \"en cours…\"\n    if res[\"precise\"]:\n        accuracy = \"±{} m\".format(\"{:.2f}\".format(res[\"accuracy\"]).replace(\".\", \",\"))\n        if res.get(\"count\"):\n            return \"{} (hauteur de caméra constante à {} cm, {})\".format(accuracy, cm(res[\"spread\"]), terrain_name(res))\n        return \"{} (précision déclarée dans la photo)\".format(accuracy)\n    if res[\"lidar\"] is False:\n        return \"impossible (pas de LiDAR HD ni de RGE ALTI)\"\n    if res[\"lidar\"] is None:\n        return \"impossible pour l'instant (service d'altimétrie indisponible)\"\n    reason = res.get(\"reason\") or \"\"\n    prefix = \"position non vérifiée : \"\n    return \"non vérifiée ({})\".format(reason[len(prefix):] if reason.startswith(prefix) else reason)\n\n\ndef state_text(res, accuracy=None, tilt=None):\n    \"\"\"Ligne d'état du panneau : précision de la position, présence du LiDAR HD et, si\n    `tilt` (texte, manquante) est donné, inclinaison de la photo.\"\"\"\n    tilt_text, tilt_missing = tilt or (\"\", False)\n    if not res:\n        text = \"Position GPS et LiDAR HD : vérification en cours…\"\n        return \"⚠ {} · {}\".format(text, tilt_text) if tilt_missing else (\n            \"{} · {}\".format(text, tilt_text) if tilt_text else text)\n    if res[\"precise\"]:\n        position = \"Position GPS vérifiée (±{} m)\".format(\"{:.2f}\".format(res[\"accuracy\"]).replace(\".\", \",\"))\n    elif accuracy is not None:\n        position = \"Position GPS non vérifiée (±{} m annoncés)\".format(\"{:g}\".format(accuracy).replace(\".\", \",\"))\n    else:\n        position = \"Position GPS non vérifiée\"\n    lidar = {True: terrain_name(res), False: \"pas de modèle de terrain\", None: \"terrain non vérifié\"}[res[\"lidar\"]]\n    text = \" · \".join(t for t in (position, lidar, tilt_text) if t)\n    if degraded(res):\n        return \"⚠ \" + text + \" : mode de mesure dégradé\"\n    if tilt_missing:\n        return \"⚠ \" + text + \" : calez-la sur deux objets verticaux\"\n    return text\n\n\ndef verify_heights(pts):\n    \"\"\"Vérification d'une séquence d'après la hauteur de caméra (altitude GPS NGF moins sol\n    LiDAR HD) de photos voisines [(lon, lat, hauteur)] : résultat (voir result).\n\n    Robuste : les photos dont la hauteur s'écarte de plus de OUTLIER écarts (écart médian\n    absolu) sont écartées (pont, défaut du LiDAR, arrêt sous un arbre) ; la dispersion des\n    autres doit rester sous MAX_SPREAD. La hauteur doit aussi être la même sur les deux\n    moitiés de la portion vérifiée (à MAX_DRIFT près) : un GPS non recalé peut être lisse\n    sur quelques photos, mais il dérive.\"\"\"\n    heights = [h for _, _, h in pts]\n    median = statistics.median(heights)\n    mad = 1.4826 * statistics.median(abs(h - median) for h in heights)\n    kept = [p for p in pts if abs(p[2] - median) <= OUTLIER * max(mad, MIN_MAD)]\n    if len(kept) < MIN_PHOTOS:\n        return result(False, lidar=True, reason=\"hauteur de caméra trop dispersée ({} photos sur {})\".format(\n            len(kept), len(pts)))\n    spread, height = statistics.pstdev([h for _, _, h in kept]), statistics.median([h for _, _, h in kept])\n    # Deux moitiés le long de la trajectoire (axe principal des positions)\n    lon0, lat0 = kept[0][0], kept[0][1]\n    xy = [((lon - lon0) * 111320.0 * math.cos(math.radians(lat0)), (lat - lat0) * 111320.0) for lon, lat, _ in kept]\n    mx, my = sum(x for x, _ in xy) / len(xy), sum(y for _, y in xy) / len(xy)\n    sxx = sum((x - mx) ** 2 for x, _ in xy)\n    syy = sum((y - my) ** 2 for _, y in xy)\n    sxy = sum((x - mx) * (y - my) for x, y in xy)\n    a = 0.5 * math.atan2(2 * sxy, sxx - syy)\n    order = sorted(range(len(kept)), key=lambda i: xy[i][0] * math.cos(a) + xy[i][1] * math.sin(a))\n    half = len(order) // 2\n    drift = abs(statistics.median(kept[i][2] for i in order[:half]) -\n                statistics.median(kept[i][2] for i in order[half:]))\n    precise = spread <= MAX_SPREAD and drift <= MAX_DRIFT and CAMERA_RANGE[0] <= height <= CAMERA_RANGE[1]\n    dropped = len(pts) - len(kept)\n    note = \" ({} écartée{})\".format(dropped, \"s\" if dropped > 1 else \"\") if dropped else \"\"\n    if precise:\n        reason = \"position vérifiée : hauteur de caméra constante à {:.0f} cm près sur {} photos{}\".format(\n            spread * 100, len(kept), note)\n    elif drift > MAX_DRIFT and spread <= MAX_SPREAD:\n        reason = \"position non vérifiée : hauteur de caméra qui dérive de {:.0f} cm le long de la séquence\".format(\n            drift * 100)\n    else:\n        reason = \"position non vérifiée : hauteur de caméra variable de {:.0f} cm sur {} photos\".format(\n            spread * 100, len(kept))\n    return result(precise, VERIFIED_ACCURACY if precise else None, True, reason, len(kept), spread, height)\n\n\nclass PrecisionChecker:\n    \"\"\"Vérifications par séquence, gardées pour la session.\"\"\"\n\n    def __init__(self):\n        self._results = {}  # séquence -> résultat\n        self._pending = {}  # séquence -> rappels en attente du résultat\n\n    def known(self, item):\n        \"\"\"Résultat déjà connu pour la séquence de la photo, ou None.\"\"\"\n        return self._results.get((item or {}).get(\"collection\"))\n\n    def check(self, item, callback):\n        \"\"\"Précision de la photo (fiche STAC) : callback(résultat) dès qu'il est connu.\"\"\"\n        sequence = item.get(\"collection\")\n        if sequence in self._results:\n            callback(self._results[sequence])\n            return\n        # Photo sans séquence : vérifiée seule (deux photos sans séquence ne partagent rien)\n        key = sequence if sequence is not None else (\"photo\", item.get(\"id\"))\n        if key in self._pending:\n            self._pending[key].append(callback)\n            return\n        self._pending[key] = [callback]\n\n        def done(res):\n            if sequence is not None and not res.get(\"transient\"):\n                self._results[sequence] = res\n            for cb in self._pending.pop(key, []):\n                cb(res)\n\n        try:\n            lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        except (KeyError, TypeError, ValueError):\n            done(result(False, reason=\"position de la photo inconnue\"))\n            return\n        accuracy = metadata.exif_accuracy(item)\n        if accuracy is not None and accuracy <= PRECISE_ACCURACY:\n            self._check_lidar(lon, lat, done, \"précision déclarée dans les métadonnées de la photo\", accuracy,\n                              host.ngf_altitude(lon, lat, metadata.item_altitude(item)))\n        elif metadata.gps_differential(item) and sequence:\n            self._check_sequence(item, sequence, lon, lat, done)\n        else:\n            self._check_lidar(lon, lat, done, \"pas de correction différentielle déclarée\")\n\n    def _check_lidar(self, lon, lat, done, reason, accuracy=None, camera_alt=None, transient=False):\n        \"\"\"Le LiDAR HD est-il publié sous la photo ? accuracy : précision déclarée suffisante, ou None ;\n        camera_alt : altitude NGF de la caméra, pour la hauteur de caméra d'une photo précise ;\n        transient : une étape précédente n'a pas pu joindre son service.\"\"\"\n        def got(ground, source, error):\n            lidar = None if error else bool(ground and ground[0] is not None)\n            height = None\n            if lidar and accuracy is not None and camera_alt is not None:\n                height = camera_alt - ground[0]\n                if not CAMERA_RANGE[0] <= height <= CAMERA_RANGE[1]:\n                    height = None\n            done(result(accuracy is not None, accuracy, lidar, reason, height=height,\n                        transient=transient or bool(error), terrain=source))\n\n        fetch_terrain([(lon, lat)], got)\n\n    def _check_sequence(self, item, sequence, lon, lat, done):\n        \"\"\"Portion de la séquence autour de la photo ; en cas d'échec, d'autres portions (voir\n        _other_portions) : une seule vérifiée suffit pour toute la séquence.\"\"\"\n        def first(kind, value):\n            if kind == \"photos\":\n                self._check_lidar(lon, lat, done, \"photos voisines indisponibles ({})\".format(value), transient=True)\n            elif kind == \"few\":\n                self._check_lidar(lon, lat, done, \"altitude GPS inexploitable ({} photos voisines)\".format(value))\n            elif kind == \"ground\":\n                done(result(False, reason=\"service d'altimétrie IGN indisponible ({})\".format(value), transient=True))\n            elif value[\"precise\"] or value[\"lidar\"] is not True:\n                done(value)  # vérifiée, ou pas de modèle de terrain ici : rien à chercher ailleurs\n            else:\n                self._other_portions(sequence, lon, lat, value, done)\n\n        self._portion(sequence, lon, lat, first)\n\n    def _portion(self, sequence, lon, lat, callback):\n        \"\"\"Vérifie la portion de séquence autour de (lon, lat) : callback(genre, valeur), genre\n        « photos » ou « ground » (service injoignable, valeur : l'erreur), « few » (trop peu\n        d'altitudes GPS, valeur : leur nombre) ou « result » (valeur : résultat).\"\"\"\n        def got_photos(data, error):\n            if error:\n                callback(\"photos\", error)\n                return\n            photos = []\n            for feat in (data or {}).get(\"features\") or []:\n                try:\n                    plon, plat = (float(v) for v in feat[\"geometry\"][\"coordinates\"][:2])\n                except (KeyError, TypeError, ValueError):\n                    continue\n                ngf = host.ngf_altitude(plon, plat, metadata.item_altitude(feat))\n                if ngf is not None and feat.get(\"collection\", sequence) == sequence:\n                    photos.append((plon, plat, ngf))\n            if len(photos) < MIN_PHOTOS:\n                callback(\"few\", len(photos))\n                return\n            fetch_terrain([(p[0], p[1]) for p in photos],\n                          lambda ground, source, error: got_ground(photos, ground, source, error))\n\n        def got_ground(photos, ground, source, error):\n            if error:\n                callback(\"ground\", error)\n                return\n            pts = [(plon, plat, ngf - g) for (plon, plat, ngf), g in zip(photos, ground) if g is not None]\n            if len(pts) < MIN_PHOTOS:\n                callback(\"result\", result(False, lidar=False,\n                                          reason=\"pas de modèle de terrain (LiDAR HD, RGE ALTI) pour vérifier la position\"))\n                return\n            res = verify_heights(pts)\n            res[\"terrain\"] = source\n            callback(\"result\", res)\n\n        host.fetch_json(metadata.search_url(lon, lat, CHECK_RADIUS, CHECK_PHOTOS, sequence, host.api_url), got_photos)\n\n    def _other_portions(self, sequence, lon, lat, failed, done):\n        \"\"\"Portion autour de la photo refusée (failed) : jusqu'à OTHER_PORTIONS autres portions de\n        la séquence, à moins de OTHER_RADIUS, essayées l'une après l'autre (le service d'altimétrie\n        limite les rafales). La première vérifiée vaut pour toute la séquence ; si aucune ne\n        l'est, failed est retenu.\"\"\"\n        def got_photos(data, error):\n            if error:\n                done(dict(failed, transient=True))  # à refaire plus tard\n                return\n            centers, taken = [], [(lon, lat)]\n            candidates = []\n            for feat in (data or {}).get(\"features\") or []:\n                try:\n                    plon, plat = (float(v) for v in feat[\"geometry\"][\"coordinates\"][:2])\n                except (KeyError, TypeError, ValueError):\n                    continue\n                if feat.get(\"collection\", sequence) == sequence:\n                    candidates.append((plon, plat))\n            # Les plus éloignées d'abord, assez loin les unes des autres pour ne pas se recouvrir\n            candidates.sort(key=lambda p: -_metres(p, (lon, lat)))\n            for p in candidates:\n                if len(centers) < OTHER_PORTIONS and all(_metres(p, q) >= 2 * CHECK_RADIUS for q in taken):\n                    centers.append(p)\n                    taken.append(p)\n            try_next(centers, 0)\n\n        def try_next(centers, tried):\n            if not centers:\n                if tried:\n                    plural = \"s\" if tried > 1 else \"\"\n                    done(dict(failed, reason=\"{} ; {} autre{p} portion{p} de la séquence non vérifiée{p}\".format(\n                        failed[\"reason\"], tried, p=plural)))\n                else:\n                    done(failed)\n                return\n            (clon, clat), rest = centers[0], centers[1:]\n\n            def got(kind, value):\n                if kind in (\"photos\", \"ground\"):\n                    done(dict(failed, transient=True))\n                elif kind == \"result\" and value[\"precise\"]:\n                    distance = _metres((clon, clat), (lon, lat))\n                    done(dict(value, reason=\"{}, à {:.0f} m de la photo (même séquence)\".format(\n                        value[\"reason\"], round(distance, -1))))\n                else:\n                    try_next(rest, tried + 1)\n\n            self._portion(sequence, clon, clat, got)\n\n        host.fetch_json(metadata.search_url(lon, lat, OTHER_RADIUS, OTHER_SEARCH, sequence, host.api_url), got_photos)\n\n\ndef _metres(a, b):\n    \"\"\"Distance (m) entre deux (lon, lat) proches.\"\"\"\n    dx = (b[0] - a[0]) * 111320.0 * math.cos(math.radians((a[1] + b[1]) / 2))\n    return math.hypot(dx, (b[1] - a[1]) * 111320.0)\n",
 "core/roads.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Axe de la route à l'endroit mesuré, pour la largeur perpendiculaire à la chaussée.\n\nLa direction du véhicule à la caméra n'est pas celle de la route au point mesuré, 10 à 20 m\nplus loin : en courbe, l'écart y atteint 3 à 5° (8 à 16° en courbe serrée), et aux carrefours\noù le véhicule tourne, la trajectoire coupe la route. Tests sur 419 points de la séquence imajbox\nde Pouilly-en-Auxois (12/10/2026) : les tronçons de la BD TOPO s'accordent avec la trajectoire\nà 0,4° en ligne droite et 0,8° en courbe, et suivent la route aux carrefours.\n\n1. BD TOPO (IGN, service WFS de la Géoplateforme, sans clé) : parmi les tronçons à moins de\n   MAX_DISTANCE m du milieu des deux bords cliqués, ceux plutôt perpendiculaires au segment\n   cliqué (une largeur traverse la route : à un carrefour, cela désigne la rue mesurée) ; le\n   plus proche donne l'axe, direction locale du tronçon sur ±TANGENT m.\n2. À défaut (hors de France, service injoignable, aucun tronçon) : direction de la trajectoire\n   de la séquence au plus près du point mesuré (photos voisines du milieu).\n3. À défaut : direction du véhicule à la caméra (axe porté par les clics).\n\nLes tronçons sont lus par maille d'environ 100 m, une fois par session ; une panne n'est pas\ngardée (nouvel essai après RETRY s). Les mêmes tronçons disent si une photo est prise sur un\npont (on_bridge) : le MNT LiDAR HD y donne le terrain sous l'ouvrage, pas le tablier.\n\"\"\"\n\nimport math\nimport time\nfrom urllib.parse import urlencode\n\nfrom . import host, metadata, triangulation\n\nWFS_URL = \"https://data.geopf.fr/wfs/ows\"\nLAYER = \"BDTOPO_V3:troncon_de_route\"\nCELL = 0.001  # degré (~100 m) : maille de lecture des tronçons\nMARGIN = 30.0  # m autour de la maille : tronçons proches d'un point du bord de la maille\nMAX_DISTANCE = 15.0  # m entre le milieu des bords cliqués et le tronçon\nTANGENT = 10.0  # m de part et d'autre : direction locale du tronçon\nMIN_CROSSING = 45.0  # degrés minimum entre le tronçon et le segment cliqué\nTRACK_RADIUS = 20.0  # m : photos de la séquence autour du point mesuré\nTRACK_PHOTOS = 3\nRETRY = 30.0  # s avant de réinterroger un service en panne\nPENDING = \"pending\"  # résultat de lookup quand une lecture est en cours\nBRIDGE_REACH = 8.0  # m entre la photo et un tronçon en pont : demi-chaussée et précision GPS\nBRIDGE_ANGLE = 30.0  # degrés au plus entre le tronçon en pont et le sens de la séquence\nBRIDGE_LEFT = MARGIN  # m : photo sortie du pont, aucun tronçon en pont plus près (photos d'approche)\n# Natures de la BD TOPO retenues comme voies carrossables : routes revêtues, ni route empierrée, chemin, sentier, piste cyclable ou escalier\nDRIVABLE_NATURES = {\"Route à 1 chaussée\", \"Route à 2 chaussées\", \"Rond-point\", \"Bretelle\", \"Type autoroutier\"}\nCLOSED_ACCESS = {\"Restreint aux ayants droit\", \"Physiquement impossible\"}  # accès des véhicules légers : voie non ouverte\n# Chemins nommés que la BD TOPO classe en « Route à 1 chaussée » (« CHE DE L ARGENTALET ») : seul leur nom les distingue\nPATH_NAMES = {\"CHE\", \"CHEM\", \"CHEMIN\"}\n\n\ndef _axis_diff(a, b):\n    \"\"\"Écart entre deux directions de droite (modulo 180°).\"\"\"\n    d = abs((a - b) % 180)\n    return min(d, 180 - d)\n\n\ndef _cell(lon, lat):\n    return int(math.floor(lon / CELL)), int(math.floor(lat / CELL))\n\n\ndef wfs_url(cell):\n    \"\"\"URL des tronçons de route de la maille (et de MARGIN m autour).\"\"\"\n    lon0, lat0 = cell[0] * CELL, cell[1] * CELL\n    dlat = MARGIN / 111320.0\n    dlon = MARGIN / (111320.0 * math.cos(math.radians(lat0 + CELL / 2)))\n    return WFS_URL + \"?\" + urlencode({\n        \"SERVICE\": \"WFS\", \"VERSION\": \"2.0.0\", \"REQUEST\": \"GetFeature\", \"TYPENAMES\": LAYER,\n        \"OUTPUTFORMAT\": \"application/json\", \"SRSNAME\": \"EPSG:4326\", \"COUNT\": 500,\n        \"BBOX\": \"{:.7f},{:.7f},{:.7f},{:.7f},urn:ogc:def:crs:EPSG::4326\".format(\n            lat0 - dlat, lon0 - dlon, lat0 + CELL + dlat, lon0 + CELL + dlon)})\n\n\ndef parse_sections(data):\n    \"\"\"Tronçons d'une réponse WFS (GeoJSON) : liste de dicts line ([(lon, lat)]), name, level\n    (position par rapport au sol : 1 ou plus sur un pont, -1 en tunnel), drivable (voie carrossable ouverte, ni privée,\n    ni chemin d'après son nom s'il n'a pas de numéro).\"\"\"\n    out = []\n    for feat in (data or {}).get(\"features\") or []:\n        geom = feat.get(\"geometry\") or {}\n        props = feat.get(\"properties\") or {}\n        lines = geom.get(\"coordinates\") or []\n        if geom.get(\"type\") == \"LineString\":\n            lines = [lines]\n        elif geom.get(\"type\") != \"MultiLineString\":\n            continue\n        name = props.get(\"cpx_numero\") or props.get(\"nom_collaboratif_gauche\") or props.get(\"nature\") or \"\"\n        try:\n            level = int(props.get(\"position_par_rapport_au_sol\") or 0)\n        except (TypeError, ValueError):\n            level = 0\n        for line in lines:\n            try:\n                pts = [(float(c[0]), float(c[1])) for c in line]\n            except (TypeError, ValueError, IndexError):\n                continue\n            if len(pts) >= 2:\n                out.append({\"line\": pts, \"name\": str(name), \"level\": level,\n                            \"drivable\": props.get(\"nature\") in DRIVABLE_NATURES and not props.get(\"prive\")\n                            and props.get(\"acces_vehicule_leger\") not in CLOSED_ACCESS\n                            and str(name).split(\" \")[0] not in PATH_NAMES})\n    return out\n\n\ndef _project(line, x, y):\n    \"\"\"(distance, abscisse curviligne) du point de la polyligne le plus proche de (x, y).\"\"\"\n    best, s = (float(\"inf\"), 0.0), 0.0\n    for (ax, ay), (bx, by) in zip(line, line[1:]):\n        length = math.hypot(bx - ax, by - ay)\n        if length == 0:\n            continue\n        t = max(0.0, min(1.0, ((x - ax) * (bx - ax) + (y - ay) * (by - ay)) / length ** 2))\n        d = math.hypot(x - ax - t * (bx - ax), y - ay - t * (by - ay))\n        if d < best[0]:\n            best = (d, s + t * length)\n        s += length\n    return best\n\n\ndef _at(line, s):\n    \"\"\"Point de la polyligne à l'abscisse curviligne s (bornée).\"\"\"\n    acc = 0.0\n    for (ax, ay), (bx, by) in zip(line, line[1:]):\n        length = math.hypot(bx - ax, by - ay)\n        if length > 0 and acc + length >= s:\n            t = max(0.0, (s - acc) / length)\n            return ax + t * (bx - ax), ay + t * (by - ay)\n        acc += length\n    return line[-1]\n\n\ndef road_axis(sections, lon, lat, crossing):\n    \"\"\"Axe de la route (dict axis, source, distance) au point (lon, lat), d'après les tronçons :\n    le plus proche à moins de MAX_DISTANCE m parmi ceux qui coupent la direction `crossing`\n    (cap du segment cliqué) d'au moins MIN_CROSSING°, ou None.\"\"\"\n    best = None\n    for sec in sections:\n        line = [triangulation._local(p[0], p[1], lon, lat) for p in sec[\"line\"]]\n        d, s = _project(line, 0.0, 0.0)\n        if d > MAX_DISTANCE or (best and d >= best[\"distance\"]):\n            continue\n        a, b = _at(line, s - TANGENT), _at(line, s + TANGENT)\n        if math.hypot(b[0] - a[0], b[1] - a[1]) < 1.0:\n            continue\n        axis = math.degrees(math.atan2(b[0] - a[0], b[1] - a[1])) % 360\n        if crossing is not None and _axis_diff(axis, crossing) < MIN_CROSSING:\n            continue  # rue parallèle au segment cliqué : pas celle qu'il traverse\n        source = \"BD TOPO\" + (\", \" + sec[\"name\"] if sec[\"name\"] else \"\")\n        best = {\"axis\": axis, \"source\": source, \"distance\": d}\n    return best\n\n\ndef on_bridge(sections, lon, lat, axis=None, reach=BRIDGE_REACH):\n    \"\"\"Tronçon en pont (dict de parse_sections) sous la photo prise en (lon, lat) : à moins de\n    reach m et, si l'axe de la séquence est connu, dans son sens (à BRIDGE_ANGLE° près :\n    une photo prise sous le pont, sur la voie franchie, n'est pas dessus). None sinon.\"\"\"\n    for sec in sections:\n        if sec.get(\"level\", 0) <= 0:\n            continue\n        line = [triangulation._local(p[0], p[1], lon, lat) for p in sec[\"line\"]]\n        d, s = _project(line, 0.0, 0.0)\n        if d > reach:\n            continue\n        a, b = _at(line, s - TANGENT), _at(line, s + TANGENT)\n        if axis is not None and math.hypot(b[0] - a[0], b[1] - a[1]) >= 1.0 and \\\n                _axis_diff(math.degrees(math.atan2(b[0] - a[0], b[1] - a[1])), axis) > BRIDGE_ANGLE:\n            continue\n        return sec\n    return None\n\n\ndef trajectory_axis(features, sequence, lon, lat):\n    \"\"\"Direction de la trajectoire de la séquence près de (lon, lat) : axe principal des\n    positions de ses photos à moins de TRACK_RADIUS m (dict axis, source), ou None.\"\"\"\n    pts = []\n    for feat in (features or {}).get(\"features\") or []:\n        if sequence and feat.get(\"collection\", sequence) != sequence:\n            continue\n        try:\n            x, y = triangulation._local(*(float(v) for v in feat[\"geometry\"][\"coordinates\"][:2]), lon, lat)\n        except (KeyError, TypeError, ValueError):\n            continue\n        if math.hypot(x, y) <= TRACK_RADIUS:\n            pts.append((x, y))\n    if len(pts) < TRACK_PHOTOS:\n        return None\n    mx, my = sum(p[0] for p in pts) / len(pts), sum(p[1] for p in pts) / len(pts)\n    sxx = sum((p[0] - mx) ** 2 for p in pts)\n    syy = sum((p[1] - my) ** 2 for p in pts)\n    sxy = sum((p[0] - mx) * (p[1] - my) for p in pts)\n    if sxx + syy < 4.0:\n        return None  # photos quasi confondues (arrêt)\n    angle = 0.5 * math.atan2(2 * sxy, sxx - syy)  # depuis l'est, sens trigonométrique\n    return {\"axis\": (90.0 - math.degrees(angle)) % 360, \"source\": \"trajectoire au point mesuré\"}\n\n\nclass RoadAxisProvider:\n    \"\"\"Axe de la route au point mesuré (voir le module), avec lectures en cache.\n\n    lookup est synchrone : il rend l'axe si les données sont là, PENDING si une lecture\n    vient d'être lancée (ready() sera appelé à son arrivée), None sinon.\"\"\"\n\n    def __init__(self):\n        self._sections = {}  # maille -> tronçons\n        self._tracks = {}  # (séquence, maille) -> réponse de la recherche des photos\n        self._pending = set()\n        self._failed = {}  # clé -> heure de la panne\n        self.ready = None  # appelé quand une lecture arrive\n\n    def lookup(self, lon, lat, crossing, sequence=None):\n        cell = _cell(lon, lat)\n        sections = self._get((\"bdtopo\", cell), self._sections, cell, lambda: wfs_url(cell), parse_sections)\n        if sections is PENDING:\n            return PENDING\n        res = road_axis(sections or [], lon, lat, crossing)\n        if res or not sequence:\n            return res\n        key = (sequence, cell)\n        track = self._get((\"track\",) + key, self._tracks, key,\n                          lambda: metadata.search_url(lon, lat, TRACK_RADIUS + 10, 20, sequence, host.api_url), lambda data: data)\n        if track is PENDING:\n            return PENDING\n        return trajectory_axis(track, sequence, lon, lat) if track else None\n\n    def bridge(self, lon, lat, axis=None, reach=BRIDGE_REACH):\n        \"\"\"Tronçon en pont sous la photo (voir on_bridge), False s'il n'y en a pas, None si la\n        BD TOPO est injoignable, ou PENDING pendant la lecture (ready() sera appelé à son\n        arrivée). reach : au plus MARGIN (tronçons lus autour de la maille).\"\"\"\n        cell = _cell(lon, lat)\n        sections = self._get((\"bdtopo\", cell), self._sections, cell, lambda: wfs_url(cell), parse_sections)\n        if sections is PENDING or sections is None:\n            return sections\n        return on_bridge(sections, lon, lat, axis, reach) or False\n\n    def _get(self, key, cache, cache_key, url, parse):\n        \"\"\"Données en cache, PENDING (lecture lancée ou en cours), ou None (panne récente).\"\"\"\n        if cache_key in cache:\n            return cache[cache_key]\n        if key in self._pending:\n            return PENDING\n        if time.monotonic() - self._failed.get(key, -RETRY) < RETRY:\n            return None\n        self._pending.add(key)\n\n        def done(data, error):\n            self._pending.discard(key)\n            if error:\n                self._failed[key] = time.monotonic()\n            else:\n                cache[cache_key] = parse(data)\n            if self.ready is not None:\n                self.ready()\n\n        host.fetch_json(url(), done, timeout_ms=15000)\n        return PENDING if key in self._pending else self._get(key, cache, cache_key, url, parse)\n",
 "core/session.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Session de mesure, indépendante de l'affichage : ce que la page (py/web_app.App, qui en hérite)\nrelie à sa visionneuse, à sa carte et à son panneau.\n\n- points de référence et mesure libre : visées cliquées dans les photos, triangulées\n  (tools.Triangulator) ;\n- hauteur : sommet (et pied) cliqués dans la photo → mesure (measures.MeasureTool) calée sur\n  le point de référence (Measure.anchor) ; largeur : bord opposé sur la droite perpendiculaire\n  à la route (widths.PerpendicularWidth) ;\n- recalage d'un point (clic sur sa croix, nouvelle visée, flèches du clavier), consignes,\n  repères de la visionneuse (photo affichée, projetés sur les autres photos), points à cadrer\n  sur la carte ;\n- calages : inclinaison, cap et position (tools.CalibrationTool) ;\n- photo affichée : précision GPS vérifiée (precision.PrecisionChecker), inclinaison\n  automatique (autotilt.TiltChecker), axe de la séquence entre les photos voisines.\n\nL'hôte appelle les méthodes de Session (clics en radians dans le repère de la photo, comme\nles donnent les visionneuses) ; elles renvoient le texte à afficher, ou des données Python\nsimples (listes, dictionnaires). Quand une lecture réseau ou un calcul aboutit après coup,\nSession appelle notify() pour que l'hôte se redessine. Le dessin sur la carte passe par les\nnew_item des outils, que l'hôte remplace (ou par ses propres sous-classes des outils, passées\nau constructeur).\n\"\"\"\n\nimport math\nimport traceback\n\nfrom . import autotilt, calibration, geometry, host, measures, metadata, precision, roads, tools, triangulation, widths\n\nGROUND_MODES = (\"road\", \"height\")  # mesures appuyées sur un point de référence\nCALIBRATION_MODES = (\"tilt\",)  # calage du cap (« heading ») : plus d'entrée dans la page depuis le 16/10/2026\nMODES = GROUND_MODES + (\"tri\",) + CALIBRATION_MODES\nREF_MODES = (\"height\", \"road\")  # mesures appuyées sur un point de référence triangulé\nNUDGE = 0.01  # pas (m) d'un point de largeur déplacé aux flèches du clavier\nVERTICAL_LENGTH = 12.0  # m : verticale tracée au-dessus du point de référence d'une hauteur\nNUDGE_WORDS = {\"left\": \"vers la gauche\", \"right\": \"vers la droite\", \"up\": \"en s'éloignant\",\n               \"down\": \"en se rapprochant\"}\n# Triangulation et mesures qui s'y appuient : acceptées hors RTK, mais signalées\nRTK_WARNING = (\" ⚠ Photo sans position GPS RTK vérifiée : mesure probablement incohérente \"\n               \"(la triangulation demande des positions précises).\")\n# Fenêtre d'avertissement, une fois par séquence sans RTK vérifié (voir Session.take_rtk_alert)\nRTK_ALERT = (\"La localisation des images de cette séquence est trop imprécise pour fonctionner. \"\n             \"Un GPS avec corrections RTK est requis.\")\n# Photo sur un pont d'après la BD TOPO : proposition de cocher « Sur un pont » (voir take_bridge_alert)\nBRIDGE_ALERT = (\"D'après la BD TOPO de l'IGN, cette photo est prise sur un pont{}. Le modèle de terrain \"\n                \"(LiDAR HD, RGE ALTI) y donne le \"\n                \"terrain sous l'ouvrage, plusieurs mètres sous le tablier : les mesures seraient fausses. \"\n                \"Cocher « Sur un pont » (sol tiré des photos au lieu du modèle de terrain) ?\")\nBRIDGE_ASKED_RADIUS = 200.0  # m : pas de nouvelle proposition près d'un pont déjà proposé\n# Photo sortie du pont, case cochée : proposition de la décocher (voir take_bridge_alert)\nBRIDGE_LEFT_ALERT = (\"D'après la BD TOPO de l'IGN, cette photo n'est plus sur un pont. Décocher « Sur un pont » \"\n                     \"pour utiliser de nouveau le modèle de terrain (LiDAR HD, RGE ALTI), plus précis hors \"\n                     \"des ponts ?\")\n\n\nclass Session:\n    def __init__(self, notify=None, tool=None, triangulator=None, calibrator=None, calibration_store=None,\n                 precision_checker=None, tilt_checker=None):\n        \"\"\"notify : fonction de l'hôte, appelée quand une lecture réseau ou un calcul aboutit\n        après coup. tool, triangulator, calibrator : outils de l'hôte (sous-classes de\n        measures.MeasureTool, tools.Triangulator, tools.CalibrationTool qui dessinent sur sa\n        carte), sinon ceux du cœur ; calibration_store : calage de l'hôte (calibration.Calibration) ;\n        precision_checker, tilt_checker : vérificateurs de l'hôte, partagés pour ne pas refaire ses\n        requêtes (precision.PrecisionChecker, autotilt.TiltChecker).\"\"\"\n        self.notify = notify or (lambda: None)\n        self.calibration = calibration_store if calibration_store is not None else calibration.Calibration()\n        self.roads = roads.RoadAxisProvider()\n        self.precision = precision_checker if precision_checker is not None else precision.PrecisionChecker()\n        self.tilts = tilt_checker if tilt_checker is not None else autotilt.TiltChecker()\n        self.roads.ready = self._roads_ready\n        self.tool = tool if tool is not None else measures.MeasureTool(None)\n        self.tool.calibration = self.calibration\n        self.tool.road_lookup = self.roads.lookup\n        self.triangulator = triangulator if triangulator is not None else tools.Triangulator()\n        self.triangulator.AIM = \"Cliquez sur l'objet dans la photo\"\n        self.triangulator.AIM_AGAIN = \"cliquez sur le même objet\"\n        self.triangulator.ground_lookup = self._ground_lookup  # sol (LiDAR HD, RGE ALTI) au point visé\n        self.triangulator.across = lambda: self._aim_across() if self.mode == \"road\" else None  # voir sight_spread\n        self.triangulator.ground_changed = lambda: self.notify()\n        self.ground_cache = {}  # (lon, lat) arrondis -> (altitude du sol ou None, incertitude, source)\n        self.bridge = False  # « Sur un pont » : LiDAR HD ignoré (voir set_bridge)\n        self.calibrator = (calibrator if calibrator is not None\n                           else tools.CalibrationTool(self.calibration, self.current_ids))\n        self.mode = \"road\"\n        self.tool.set_mode(\"road\")\n        self.item = None  # fiche STAC de la photo affichée\n        # Fiches des photos affichées (id -> fiche) : leurs visées et leurs clics se recalculent\n        # quand leur calage ou leur précision change (voir _recompute)\n        self.photo_items = {}\n        self.quality = None  # vérification de sa précision (voir precision.PrecisionChecker)\n        self.neighbours = {}  # fiches des photos voisines (axe de la séquence) : id -> fiche\n        self.message = \"\"\n        self.points = []  # points triangulés gardés : (lon, lat, attributs)\n        self.links = []  # distances entre deux points gardés : (n° du premier, n° du second, attributs)\n        self.named = 0  # points gardés depuis le début : nom du suivant (A, B… voir _point_name)\n        self.proposal = None  # (n°, n°) : distance à proposer après l'effacement du point qui les reliait\n        # Hauteur, largeur : point de référence triangulé (lon, lat, uncertainty, name, sequences ;\n        # largeur : road, axe de la route en ce point, None en cours de lecture), validé : les\n        # mesures suivantes s'y appuient, depuis n'importe quelle photo, jusqu'au prochain\n        # (new_reference) ; None : à trianguler d'abord\n        self.ref_point = None\n        # largeur : (mesure, 0 pour le point de référence ou 1 pour le bord) à recaler ; (None, 0) :\n        # point de référence sur lequel aucune largeur ne s'appuie encore\n        self.width_sel = None\n        # Hauteur : point de référence sélectionné (aucune hauteur ne s'y appuie encore), à recaler\n        # sur sa verticale\n        self.ref_sel = False\n        # Largeur ou hauteur faite depuis le point de référence : seuls ses points s'ajustent (sur la\n        # droite de mesure ou la verticale) jusqu'à « Nouvelle mesure depuis A » (new_measure)\n        self.measure_done = False\n        self.last_free = None  # mesure libre : n° du dernier point gardé, relié au suivant\n        self.point_views = {}  # nom d'un point gardé -> {photo : [cap, élévation] de sa visée (radians)}\n        self._handles = []  # clés des poignées de la carte, dans l'ordre de handles()\n        self.calibration_version = 0  # augmente à chaque changement du calage (à enregistrer)\n        self.active = False  # bouton « Mesure » : clics dans la photo pour mesurer\n        self.rtk_alerted = set()  # séquences sans RTK déjà signalées par une fenêtre (take_rtk_alert)\n        self.bridge_asked = []  # (lon, lat) des photos où « Sur un pont » a été proposé (take_bridge_alert)\n        self._bridge_waiting = False  # tronçons BD TOPO en lecture pour take_bridge_alert\n        self.bridge_left_asked = False  # case cochée : sortie du pont déjà proposée (take_bridge_alert)\n        self.epoch = 0  # change quand les clics en cours sont abandonnés\n        # Hauteur, largeur : photo de la première visée du point de référence, sur laquelle la\n        # mesure se fera ; l'hôte y revient après la validation (take_goto)\n        self.ref_photo = None\n        self.goto = None  # photo à afficher, demandée une fois à l'hôte (voir take_goto)\n        # Largeur dont le bord B est en cours de triangulation (start_edge_b), ou None\n        self.b_aiming = None\n        # Cadrage à faire sur la photo de référence après une validation (take_frame) : \"reference\"\n        # (le point A), une largeur (sa mesure entière), ou None\n        self.frame_request = None\n\n    def current_ids(self):\n        item = self.item or {}\n        return item.get(\"id\"), item.get(\"collection\")\n\n    def _active(self):\n        \"\"\"Outil du mode : MeasureTool, Triangulator ou CalibrationTool.\"\"\"\n        if self._aiming():\n            return self.triangulator\n        if self.mode in CALIBRATION_MODES:\n            if self.calibrator.mode != self.mode:\n                self.calibrator.set_mode(self.mode)\n            return self.calibrator\n        self.tool.set_mode(self.mode)\n        return self.tool\n\n    def _aiming(self):\n        \"\"\"Les clics dans la photo sont-ils des visées de triangulation ? En triangulation, en\n        hauteur ou largeur tant que le point de référence n'est pas validé, et pendant la\n        triangulation du bord B d'une largeur (start_edge_b).\"\"\"\n        return self.mode == \"tri\" or (self.mode in REF_MODES and self.ref_point is None) or self.b_aiming is not None\n\n    def _calibration_changed(self, pics=None):\n        \"\"\"Calage changé (des photos pics, de toutes si None) : à enregistrer, et ce qui en\n        dépend recalculé.\"\"\"\n        self.calibration_version += 1\n        self._recompute(pics)\n\n    def _ground_lookup(self, lon, lat, done):\n        \"\"\"Altitude du sol au point (lon, lat) : MNT LiDAR HD, sinon RGE ALTI (voir\n        precision.fetch_terrain). done(z, incertitude (m), source), z None hors couverture ou\n        service injoignable (alors non gardée : redemandée la fois suivante).\"\"\"\n        key = (round(lon, 6), round(lat, 6))\n        if key in self.ground_cache:\n            done(*self.ground_cache[key])\n            return\n\n        def got(ground, source, error):\n            if error:\n                done(None, None, None)\n                return\n            z = (ground or [None])[0]\n            sigma = triangulation.RGE_ALTI_ERROR if source == \"RGE ALTI\" else triangulation.LIDAR_ERROR\n            self.ground_cache[key] = (z, sigma, source)\n            if len(self.ground_cache) > 500:\n                self.ground_cache.pop(next(iter(self.ground_cache)))\n            done(z, sigma, source)\n\n        precision.fetch_terrain([(lon, lat)], got)\n\n    def _ref_ground(self, asks=0):\n        \"\"\"Point de référence au sol en 3D : altitude du MNT LiDAR HD lue à sa position (sauf\n        déjà lue tout près), puis le point et ses mesures recalés avec elle (voir\n        tools.Triangulator._ask_ground, son équivalent pendant les visées).\"\"\"\n        ref = self.ref_point\n        if not ref or ref.get(\"moved\") or self.bridge or asks >= tools.GROUND_ASKS:\n            return\n        try:\n            r = tools.solve_on_ground(ref[\"sightings\"], True, ref.get(\"ground_z\"))\n        except triangulation.TriangulationError:\n            return\n        gz = ref.get(\"ground_z\")\n        if r[\"method\"] != \"3d\" or (gz and tools._metres(gz[:2], (r[\"lon\"], r[\"lat\"])) < tools.GROUND_REUSE):\n            return\n        lon, lat = r[\"lon\"], r[\"lat\"]\n\n        def got(z, sigma=None, source=None):\n            if z is None or self.ref_point is not ref or ref.get(\"moved\"):\n                return\n            ref[\"ground_z\"] = (lon, lat, z, sigma or triangulation.LIDAR_ERROR, source or precision.TERRAINS[0][0])\n            self._recompute(set(), force_reference=True)\n            self._ref_ground(asks + 1)\n            self.notify()\n\n        self._ground_lookup(lon, lat, got)\n\n    def _recompute(self, pics=None, force_reference=False):\n        \"\"\"Visées, point de référence et mesures recalculés depuis leurs directions brutes, avec\n        le calage et la précision actuels des photos pics (toutes si None) : le résultat ne\n        dépend pas de l'ordre dans lequel arrivent les clics, la vérification RTK et les calages\n        (automatiques ou faits à la main avant ou après).\"\"\"\n        def touched(pic):\n            return pics is None or pic in pics\n\n        try:\n            if any([self._resight(s) for s in self.triangulator.sightings if touched(s[\"pic\"])]):\n                self.triangulator.recompute()\n            clicked = self._reclick(touched)\n            moved = self._recompute_reference(touched, force_reference)\n            for m in self.tool.measures():\n                if m in clicked or (moved and m in moved):\n                    if isinstance(m, widths.PerpendicularWidth):\n                        m.clicks[0] = m._edge_mark(m.clicks[1])  # repère de A dans la photo du bord\n                        m.compute()\n                    elif m.reference is not None:  # hauteur calée sur un point triangulé\n                        ref = m.reference\n                        if self.ref_point and ref[\"name\"] == self.ref_point[\"name\"]:\n                            self._anchor_on(m, self.ref_point)\n                        else:  # point de référence précédent : calage gardé\n                            m.anchor(ref[\"lon\"], ref[\"lat\"], ref[\"uncertainty\"], ref[\"name\"])\n                    else:\n                        m.compute()\n            self._recompute_edges_b(touched, force_reference)\n            if moved is not None and not force_reference:\n                self._ref_ground()  # altitude LiDAR à relire si le point s'est éloigné\n        except Exception:\n            traceback.print_exc()\n\n    def _resight(self, s):\n        \"\"\"Visée s recalculée depuis sa direction brute (calage, précision de sa photo). Retourne\n        True si elle a pu l'être.\"\"\"\n        item = self.photo_items.get(s[\"pic\"])\n        if item is None or not s.get(\"raw\"):\n            return False\n        new = tools.photo_sighting(item, s[\"raw\"][0], s[\"raw\"][1], self.calibration, self.precision.known(item))\n        if new is None:\n            return False\n        view = s.get(\"view\")\n        s.clear()\n        s.update(new)\n        if view is not None:\n            s[\"view\"] = view\n        return True\n\n    CLICK_KEYS = (\"yaw\", \"elev\", \"lon\", \"lat\", \"gps\", \"gps_accuracy\", \"accuracy\")\n\n    def _reclick(self, touched):\n        \"\"\"Clics des mesures sur les photos touchées recalculés depuis leur direction brute.\n        Retourne les mesures dont un clic a changé.\"\"\"\n        out = []\n        for m in self.tool.measures():\n            changed = False\n            for c in m.clicks:\n                item = self.photo_items.get(c.get(\"pic\"))\n                if item is None or not c.get(\"raw\") or not touched(c.get(\"pic\")):\n                    continue\n                new = tools.photo_click(item, c[\"raw\"][0], c[\"raw\"][1], self.calibration, self.precision.known(item),\n                                        c.get(\"pos\"), c.get(\"axis\"))\n                if new is not None:\n                    c.update({k: new[k] for k in self.CLICK_KEYS})\n                    changed = True\n            if changed:\n                out.append(m)\n        return out\n\n    def _recompute_reference(self, touched, force=False):\n        \"\"\"Point de référence dont une visée a été recalculée (ou force : son altitude LiDAR\n        vient d'arriver) : triangulé à nouveau, ses largeurs et ses hauteurs recalées sur lui.\n        Laissé tel quel s'il a été déplacé à la main (recalage le long de la droite de mesure).\n        Retourne ses mesures (à recalculer), ou None s'il n'a pas bougé.\"\"\"\n        ref = self.ref_point\n        if not ref or ref.get(\"moved\"):\n            return None\n        if not any([self._resight(s) for s in ref.get(\"sightings\", []) if touched(s[\"pic\"])]) and not force:\n            return None\n        try:\n            r = tools.solve_on_ground(ref[\"sightings\"], True, self._lidar_z(ref))\n        except triangulation.TriangulationError:\n            return None\n        ref.update(lon=r[\"lon\"], lat=r[\"lat\"], uncertainty=r[\"uncertainty\"], cov=r.get(\"cov\"))\n        self._edge_moved(ref, [])  # son point gardé (export) suit\n        mates = [w for w in self._widths() if w.edge is ref]\n        mates += [m for m in self._heights() if (m.reference or {}).get(\"name\") == ref[\"name\"]]\n        return mates\n\n    # Réglages ------------------------------------------------------------------------\n    def set_active(self, on):\n        \"\"\"Bouton « Mesure » : activé, les clics dans la photo mesurent (l'inclinaison de la\n        photo est calculée au premier clic, voir _check_tilt) ; désactivé, les mesures en cours\n        sont terminées (les mesures réussies restent affichées), comme dans le plugin. Les\n        visées de la triangulation restent : on peut désactiver la mesure pour aller viser\n        depuis une autre photo.\"\"\"\n        self.active = bool(on)\n        self.message = \"\"\n        if not self.active:\n            self._clear_measures(keep_sightings=True)\n        return self.status()\n\n    def _check_tilt(self):\n        \"\"\"Inclinaison automatique de la photo affichée, en mesure ou en calage seulement, lancée\n        au premier clic sur la photo et non à son arrivée : le calcul (photo HD, recherche des\n        verticales) occupe le processeur quelques secondes et ferait saccader la vue pendant qu'on\n        cherche l'objet ; les clics faits avant son résultat sont recalculés à son arrivée\n        (_recompute). La mesure libre s'en passe (calcul long évité ; sans elle, ses visées\n        comptent surtout par leur cap).\"\"\"\n        if self.active and self.item and self.mode != \"tri\":\n            pic = self.item.get(\"id\")\n            before = self.calibration.auto.get(pic)\n            self.tilts.check(self.item, self.calibration, lambda: self._on_tilt(pic, before))\n\n    def set_mode(self, mode):\n        if mode not in MODES:\n            return self.status()\n        self._clear_measures()\n        self.mode = mode\n        self.ref_point = None\n        self.width_sel = None\n        self.measure_done = False\n        self.ref_sel = False\n        self.message = \"\"\n        self._active()\n        return self.status()\n\n    def _clear_measures(self, keep_sightings=False):\n        \"\"\"Termine les mesures en cours (réussies, elles restent affichées) ; le calage déjà\n        fait est conservé (comme le plugin à un changement de mode).\"\"\"\n        self.epoch += 1\n        self.b_aiming = None\n        if not keep_sightings:\n            self.triangulator.clear()\n        self.tool.finish()\n        self.calibrator.reset()\n\n    def set_camera_height(self, value):\n        self.tool.set_camera_height(float(value))\n        return self.status()\n\n    def set_bridge(self, value):\n        \"\"\"« Sur un pont » : le MNT LiDAR HD donne le terrain sous l'ouvrage (la voie franchie,\n        plusieurs mètres plus bas), pas le tablier. Les points au sol se calent alors sur le sol\n        tiré des photos (altitude GPS des caméras moins leur hauteur) et l'inclinaison automatique\n        se passe de la pente LiDAR. Les altitudes déjà lues sont gardées : décocher les reprend.\"\"\"\n        if value and not self.bridge:\n            self.bridge_left_asked = False  # nouvelle sortie à proposer\n        self.bridge = bool(value)\n        self.triangulator.lidar = self.calibration.lidar = not self.bridge\n        self._recompute(force_reference=True)\n        self.triangulator.recompute()\n        self._ref_ground()\n        return self.status()\n\n    def _lidar_z(self, point):\n        \"\"\"Altitude LiDAR HD lue au point triangulé (lon, lat, z), ou None (pas lue, ou sur un pont).\"\"\"\n        return None if self.bridge else point.get(\"ground_z\")\n\n    def set_api_url(self, url):\n        \"\"\"Instance Panoramax choisie : recherches du cœur (précision GPS, trajectoire).\"\"\"\n        host.api_url = url\n        self.neighbours = {}\n\n    # Photo affichée ------------------------------------------------------------------\n    def set_picture(self, item):\n        \"\"\"Photo affichée dans la visionneuse : sa fiche STAC.\"\"\"\n        self.item = item\n        pic = item.get(\"id\")\n        self.photo_items[pic] = item\n        if len(self.photo_items) > 500:  # les plus anciennes, sans visée ni clic récents\n            self.photo_items.pop(next(iter(self.photo_items)))\n        self.quality = self.precision.known(item)\n        before = self.quality\n        self.precision.check(item, lambda res: self._on_precision(pic, res, before))\n        for rel in (\"prev\", \"next\"):  # voisines : axe de la séquence\n            nid = metadata.id_from_href(metadata.item_link(item, rel))\n            if nid and nid not in self.neighbours:\n                host.fetch_json(\"{}/search?ids={}\".format(host.api_url, nid),\n                                    lambda data, error, nid=nid: self._on_neighbour(nid, data))\n        return self.status()\n\n    def _on_neighbour(self, nid, data):\n        features = (data or {}).get(\"features\") or []\n        if features:\n            self.neighbours[nid] = features[0]\n            if len(self.neighbours) > 200:\n                self.neighbours.pop(next(iter(self.neighbours)))\n\n    def _axis(self, item):\n        def neighbour(rel):\n            return self.neighbours.get(metadata.id_from_href(metadata.item_link(item, rel)))\n        return metadata.sequence_axis(item, neighbour(\"prev\"), neighbour(\"next\"))\n\n    def _on_precision(self, pic, res, before=None):\n        \"\"\"Précision de la séquence de la photo pic arrivée : visées et clics faits avant sur ses\n        photos recalculés (altitude RTK, sol LiDAR, précision vérifiée).\"\"\"\n        if res is not before:\n            sequence = (self.photo_items.get(pic) or {}).get(\"collection\")\n            self._recompute({p for p, it in self.photo_items.items() if it.get(\"collection\") == sequence} | {pic})\n        if pic == (self.item or {}).get(\"id\"):  # photo encore affichée\n            self.quality = res\n        self.notify()\n\n    def _on_tilt(self, pic, before=None):\n        \"\"\"Inclinaison automatique arrivée : clics, visées et point de référence de la photo\n        recalculés (voir _recompute). Rien si elle n'a pas changé (check rappelle aussi sans\n        calcul : photo déjà calée, non 360°, sans cap) : ni calage réenregistré, ni affichage refait.\"\"\"\n        if self.calibration.auto.get(pic) == before:\n            return\n        self._calibration_changed({pic})\n        self.notify()\n\n    def _heading(self):\n        \"\"\"Cap du centre de l'image (degrés) : EXIF précis, sinon view:azimuth.\"\"\"\n        precise = metadata.precise_heading(self.item)\n        return precise if precise is not None else (metadata.item_heading(self.item) or 0.0)\n\n    # Clics -------------------------------------------------------------------------------\n    def click(self, yaw, pitch):\n        \"\"\"Clic dans la photo affichée : direction dans le repère de la photo (radians, cap\n        relatif au centre de l'image, comme le donne la visionneuse).\"\"\"\n        if not self.active:\n            return self.status()\n        if not self.item:\n            self.message = \"Photo en cours de chargement : cliquez à nouveau.\"\n            return self.status()\n        self._check_tilt()\n        if self._aiming():\n            return self.aim(yaw, pitch)\n        raw_yaw = (math.degrees(yaw) + self._heading()) % 360\n        click = tools.photo_click(self.item, raw_yaw, math.degrees(pitch), self.calibration, self.quality,\n                                  [yaw, pitch], self._axis(self.item))\n        if click is None:\n            self.message = \"Position de la photo inconnue.\"\n            return self.status()\n        self.message = \"\"\n        tool = self._active()\n        if self.mode == \"road\":\n            return self._width_click(click)\n        if self.mode == \"height\" and self.ref_sel:  # point de référence recalé sur sa verticale\n            self.ref_sel = False\n            dz = self._recale_ref_foot(pitch)\n            self.message = (\"Pied au point de référence {} recalé de {} cm sur sa verticale, sur cette photo.\").format(\n                self.ref_point[\"name\"], measures._num(abs(dz) * 100, 0))\n            return self.status()\n        if self.mode == \"height\" and tool.selected is not None and \\\n                click.get(\"pic\") != tool.selected[0].clicks[0].get(\"pic\"):\n            self.message = (\"Ce point se recale par un clic sur la photo de sa mesure (le pied et le sommet \"\n                            \"y sont visés ensemble) ; ici, flèches ↑ ↓ : 1 cm ; Entrée pour terminer.\")\n            return self.status()\n        if self.mode == \"height\" and tool.selected is None and (\n                tool.current is None or len(tool.current.clicks) >= tool.current.needed()):\n            near = self._height_near(click)\n            if near is not None:  # clic sur la croix d'un pied ou d'un sommet : sélectionné\n                tool.selected = near\n                return self.status()\n            if self._ref_near(click):  # croix du point de référence seule : sélectionnée\n                self.ref_sel = True\n                return self.status()\n            if self._locked():  # pas d'autre hauteur sans « Nouvelle mesure depuis A »\n                self.message = self._locked_text()\n                return self.status()\n        if self.mode == \"height\":\n            return self._height_click(click)\n        tool.add_click(click)  # calage de l'inclinaison ou du cap\n        self._after_calibration(tool)\n        return self.status()\n\n    def _height_click(self, click):\n        \"\"\"Hauteur, étape 2 : le sommet (le pied est la visée du point de référence faite\n        depuis cette photo), sinon le pied puis le sommet, ou la nouvelle visée du point\n        sélectionné. Sans profil du terrain : calée sur le point de référence, la hauteur n'en\n        dépend pas.\"\"\"\n        tool = self.tool\n        selected = tool.selected\n        reaimed = selected is not None\n        if not reaimed and (tool.current is None or len(tool.current.clicks) >= tool.current.needed()):\n            foot = self._reference_foot()\n            if foot is not None:\n                tool.add_click(foot)\n        text = tool.add_click(click)\n        self.message = text if reaimed else \"\"  # point recalé : son résultat ; sinon la suite (status)\n        if reaimed:\n            self._sync_ref_foot(*selected)\n        self._anchor_height()\n        return self.status()\n\n    def _sync_ref_foot(self, m, index):\n        \"\"\"Pied d'une hauteur appuyée sur le point de référence recalé à la main (flèches, clic) :\n        gardé comme pied du point de référence sur cette photo (ref[\"feet\"]), pour que les\n        hauteurs suivantes depuis lui (« Nouvelle mesure depuis A ») partent du pied corrigé.\"\"\"\n        ref = self.ref_point\n        if index != 0 or not ref or (m.reference or {}).get(\"name\") != ref[\"name\"] or not m.result:\n            return\n        p = m.viewer_marks()[\"points\"][0]  # pied tel que la photo de la mesure le voit maintenant\n        if p[\"yaw\"] is not None and p[\"pitch\"] is not None:\n            ref.setdefault(\"feet\", {})[m.clicks[0].get(\"pic\")] = [p[\"yaw\"], p[\"pitch\"]]\n\n    def select_point(self, yaw, pitch):\n        \"\"\"Clic droit dans la photo : sélectionne le point de hauteur ou de largeur dont la croix\n        est sous le clic, depuis n'importe quelle photo, pour le recaler (clic gauche, flèches du\n        clavier, Entrée pour terminer).\"\"\"\n        if not self.active or not self.item or self.mode not in REF_MODES:\n            return self.status()\n        click = tools.photo_click(self.item, (math.degrees(yaw) + self._heading()) % 360, math.degrees(pitch),\n                                  self.calibration, self.quality, [yaw, pitch], self._axis(self.item))\n        if click is None:\n            return self.status()\n        self.message = \"\"\n        if self.mode == \"road\":\n            self.width_sel = self._width_near(click)\n            found = self.width_sel is not None\n        else:\n            self.tool.selected = self._height_near(click)\n            self.ref_sel = self.tool.selected is None and self._ref_near(click)\n            found = self.tool.selected is not None or self.ref_sel\n        if not found:\n            self.message = \"Aucune croix de mesure sous le clic droit.\"\n        return self.status()\n\n    def _width_click(self, click):\n        \"\"\"Largeur : le bord opposé, sur la droite perpendiculaire passant par le point de\n        référence (voir core/widths.py). Chaque clic donne une largeur ; un clic (gauche ou droit,\n        voir select_point) sur la croix d'un point le sélectionne, le suivant le recale (voir\n        _recale_width).\"\"\"\n        if self.width_sel is not None:\n            return self._recale_width(click)\n        near = self._width_near(click)\n        if near is not None:  # clic sur la croix d'un point : sélectionné\n            self.width_sel = near\n            return self.status()\n        if self._locked():  # pas d'autre largeur sans « Nouvelle mesure depuis A »\n            self.message = self._locked_text()\n            return self.status()\n        ref = self.ref_point\n        if ref.get(\"road\") is None:\n            self._road_at_reference()\n            if ref.get(\"road\") is None:\n                self.message = \"Axe de la route en cours de lecture (BD TOPO) : cliquez à nouveau dans un instant.\"\n                return self.status()\n        m = widths.PerpendicularWidth(self.tool, ref, ref[\"road\"], click)\n        if m.error:\n            m.remove()\n            self.message = m.error\n            return self.status()\n        self.tool.done.append(m)\n        self.measure_done = True\n        self.message = (m.status() + self._rtk_warning(ref[\"sequences\"] + [click.get(\"sequence\")])\n                        + \" Pour l'ajuster, cliquez une de ses croix. Autre largeur depuis ce point : « Nouvelle mesure \"\n                          \"depuis {} ».\".format(ref[\"name\"]))\n        return self.status()\n\n    def _locked_text(self):\n        name = self.ref_point[\"name\"]\n        if self.mode == \"height\":\n            return (\"Hauteur mesurée depuis le point {0} : cliquez une de ses croix pour l'ajuster (nouveau clic sur \"\n                    \"la photo de la mesure, ou flèches ↑ ↓ : 1 cm sur la verticale ; Entrée pour terminer). Autre \"\n                    \"hauteur depuis ce point : « Nouvelle mesure depuis {0} » ; autre point : « Nouveau point de \"\n                    \"référence ».\").format(name)\n        return (\"Largeur mesurée depuis le point {0} : cliquez une de ses croix pour l'ajuster (nouveau clic ou \"\n                \"flèches du clavier, 1 cm le long de la droite de mesure ; Entrée pour terminer). Autre largeur \"\n                \"depuis ce point : « Nouvelle mesure depuis {0} » ; autre point : « Nouveau point de \"\n                \"référence ».\").format(name)\n\n    def _width_points(self, m):\n        \"\"\"Repères du point de référence et du bord d'une largeur dans la photo affichée :\n        [{yaw, pitch (radians, repère de la photo), abs_yaw, elev (degrés)}]. Le point de\n        référence, projeté au sol comme la droite de mesure (il est dessus), ou là où il a été visé\n        (voir _aim_anchor) ; le bord, là où il a été cliqué sur la photo, projeté au sol sur les\n        autres. Triangulé, le bord est projeté ramené sur la droite de mesure, même sur une photo qui\n        l'a visé : toutes les largeurs d'un point de référence restent sur la même droite (#37).\"\"\"\n        pic = (self.item or {}).get(\"id\")\n        anchor = self._aim_anchor() if m.edge is self.ref_point and pic is not None else None\n        height = anchor[2] if anchor else None  # photo de la visée de A : au niveau du sol visé\n        points = [self._project(plon, plat, height) for plon, plat in m.result[\"points\"]]\n        if anchor:\n            points[0] = anchor[0]  # A là où il a été visé (croix bleue)\n        if pic is not None and pic == m.clicks[1].get(\"pic\") and m.edge_b is None:  # bord cliqué, pas triangulé\n            p = m.viewer_marks()[\"points\"][1]\n            points[1] = {\"yaw\": p[\"yaw\"], \"pitch\": p[\"pitch\"], \"abs_yaw\": p[\"abs_yaw\"], \"elev\": p[\"elev\"]}\n        return points\n\n    def camera_of(self, item, quality, sequence_only=False, mount=True):\n        \"\"\"Hauteur de caméra de la photo item au-dessus du sol : (m, source, incertitude en m), dans l'ordre :\n        - mesurée, altitude RTK moins sol LiDAR HD (quality : vérification de la position ; sequence_only : sur la\n          séquence seulement, pas la photo seule de précision déclarée, prise au-dessus du sol sous elle) ;\n        - calée pour la séquence ;\n        - monture connue du véhicule (_mount_height, mount=False : sans elle) ;\n        - le réglage « Caméra à » (source None).\n        Les mesures (hauteur, largeur, points triangulés) n'en dépendent pas : elle sert aux repères et objets posés\n        au sol, au relevé sur une seule photo, au tablier d'un pont et à l'export. MeasureTool.camera_info, côté\n        mesures, ne connaît que les deux dernières sources (calée, réglage).\"\"\"\n        q = quality or {}\n        h = q.get(\"height\")\n        if (q.get(\"count\") if sequence_only else q.get(\"precise\")) and q.get(\"lidar\") is True and h is not None \\\n                and measures.CAMERA_RANGE[0] <= h <= measures.CAMERA_RANGE[1]:\n            return h, \"altitude GPS\", q.get(\"spread\") or measures.CAMERA_ERRORS[\"altitude GPS\"]\n        cam = self.calibration.camera((item or {}).get(\"collection\"))\n        if cam:\n            return cam[\"height\"], \"calée\", cam[\"sigma\"]\n        known = self._mount_height(item or {}) if mount else None\n        if known:\n            return known[0], \"monture\", known[1]\n        return self.tool.camera_height, None, measures.CAMERA_ERRORS[None]\n\n    def _mount_height(self, item):\n        \"\"\"Monture connue du véhicule de la photo : (hauteur en m, incertitude en m), ou None (la page la connaît\n        pour le CD21 : web_app.App._mount_height).\"\"\"\n        return None\n\n    def _camera_height(self, mount=True):\n        \"\"\"Hauteur de caméra de la photo affichée (camera_of).\"\"\"\n        return self.camera_of(self.item, self.quality, mount=mount)[0]\n\n    def _view_of(self, bearing, elev):\n        \"\"\"Direction vraie (cap, élévation en degrés) vue dans la photo affichée, calage compris\n        (inclinaison, cap) : {yaw, pitch (radians, repère de la photo), abs_yaw, elev (degrés, bruts)}.\"\"\"\n        lon, lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n        yaw, pitch = self.calibration.uncorrect(self.item.get(\"id\"), self.item.get(\"collection\"), bearing % 360, elev,\n                                                lon, lat)\n        return {\"yaw\": math.radians((yaw - self._heading() + 540) % 360 - 180), \"pitch\": math.radians(pitch),\n                \"abs_yaw\": yaw % 360, \"elev\": pitch}\n\n    def _project(self, plon, plat, height=None):\n        \"\"\"Repère dans la photo affichée d'un point de la carte, au sol supposé plat (hauteur de\n        caméra height, sinon celle de la photo, voir _camera_height), calage de la photo compris :\n        {yaw, pitch (radians, repère de la photo), abs_yaw, elev (degrés)}.\"\"\"\n        lon, lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n        x, y = triangulation._local(plon, plat, lon, lat)\n        bearing = math.degrees(math.atan2(x, y))\n        height = self._camera_height() if height is None else height\n        elev = -math.degrees(math.atan2(height, max(math.hypot(x, y), 0.5)))\n        return self._view_of(bearing, elev)\n\n    def _aim_anchor(self):\n        \"\"\"Largeur : point de référence tel qu'il a été visé depuis la photo affichée, si elle a\n        servi à le trianguler (et qu'il n'a pas été déplacé à la main) : (repère de la croix bleue\n        de la visée {yaw, pitch, abs_yaw, elev}, (x, y) du point de la visée à la profondeur de A,\n        en m depuis la photo, hauteur de la caméra au-dessus du sol visé), sinon None. La croix A\n        et la droite de mesure s'y dessinent dans cette photo ; la largeur, elle, se calcule\n        depuis la position triangulée de A.\"\"\"\n        ref, pic = self.ref_point, self.item.get(\"id\")\n        if self.mode != \"road\" or not ref or ref.get(\"moved\"):\n            return None\n        view = self._ref_view(pic)\n        if view is None:\n            return None\n        lon, lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n        heading = self._heading()\n        bearing, elev = self.calibration.correct(pic, self.item.get(\"collection\"),\n                                                 (math.degrees(view[0]) + heading) % 360, math.degrees(view[1]), lon, lat)\n        x, y = triangulation._local(ref[\"lon\"], ref[\"lat\"], lon, lat)\n        a = math.radians(bearing)\n        t = x * math.sin(a) + y * math.cos(a)  # profondeur de A le long de la visée\n        if t < 0.5 or elev > -0.5:\n            return None\n        mark = {\"yaw\": view[0], \"pitch\": view[1], \"abs_yaw\": (math.degrees(view[0]) + heading) % 360,\n                \"elev\": math.degrees(view[1])}\n        return mark, (t * math.sin(a), t * math.cos(a)), -t * math.tan(math.radians(elev))\n\n    def _free_mark_point(self, k):\n        \"\"\"Repère du point gardé n° k dans la photo affichée : là où il a été visé depuis elle,\n        sinon projeté au sol.\"\"\"\n        lon, lat, values = self.points[k]\n        view = self.point_views.get(values[\"nom\"], {}).get(self.item.get(\"id\"))\n        point = {\"yaw\": view[0], \"pitch\": view[1]} if view else self._project(lon, lat)\n        return dict(point, pic=self.item.get(\"id\"))\n\n    def _free_marks(self):\n        \"\"\"Mesure libre : distances (trait et étiquette) et points gardés seuls, dans la photo\n        affichée. Les points de référence des hauteurs et largeurs sont montrés par elles.\"\"\"\n        refs = {(m.reference or {}).get(\"name\") for m in self._heights()} | {m.edge.get(\"name\") for m in self._widths()}\n        refs |= {m.edge_b[\"name\"] for m in self._widths() if m.edge_b}  # bord opposé triangulé : sa largeur le montre\n        if self.ref_point:\n            refs.add(self.ref_point[\"name\"])\n        marks, linked = [], set()\n        for i, j, values in self.links:\n            linked |= {i, j}\n            marks.append({\"points\": [self._free_mark_point(i), self._free_mark_point(j)],\n                          \"label\": \"↔ {} m ± {} m\".format(measures._num(values[\"valeur_m\"], 2),\n                                                          measures._num(values[\"incert_m\"], 2))})\n        for k, (_, _, values) in enumerate(self.points):\n            if k not in linked and values[\"nom\"] not in refs:\n                marks.append({\"points\": [self._free_mark_point(k)], \"label\": \"\"})\n        return marks\n\n    def _reference_mark(self):\n        \"\"\"Croix du point de référence validé dans la photo affichée : là où il a été visé depuis\n        cette photo (largeur : voir _aim_anchor), sinon projeté au sol comme la droite de mesure.\n        None dès qu'une mesure s'y appuie (sa croix le montre).\"\"\"\n        ref, pic = self.ref_point, self.item.get(\"id\")\n        if self.mode == \"road\" and any(m.edge is ref for m in self._widths()):\n            return None\n        if self.mode == \"height\" and any((m.reference or {}).get(\"name\") == ref[\"name\"] for m in self._heights()):\n            return None  # le pied des hauteurs qui s'y appuient le montre\n        view = self._ref_view(pic) if self.mode != \"road\" else None\n        anchor = self._aim_anchor()  # largeur : là où il a été visé depuis cette photo\n        if anchor is not None:\n            point = anchor[0]\n        elif view is not None:\n            point = {\"yaw\": view[0], \"pitch\": view[1]}\n        else:\n            point = self._project(ref[\"lon\"], ref[\"lat\"])\n        # croix sélectionnée (voir width_sel, ref_sel)\n        sel = self.width_sel == (None, 0) if self.mode == \"road\" else self.ref_sel\n        return {\"points\": [dict(point, pic=pic, sel=sel)], \"label\": \"\", \"beside\": False}\n\n    def _heights(self):\n        return [m for m in self.tool.done if m.kind == \"height\" and m.result]\n\n    def _height_points(self, m):\n        \"\"\"Repères du pied et du sommet d'une hauteur dans la photo affichée : [{yaw, pitch\n        (radians, repère de la photo), abs_yaw, elev (degrés)}]. Sur la photo de la mesure, là\n        où ils ont été visés ; sur les autres, projetés depuis leur position 3D, la caméra\n        supposée à l'altitude de celle de la mesure (repères seulement).\"\"\"\n        pic = (self.item or {}).get(\"id\")\n        if pic == m.clicks[0].get(\"pic\"):\n            return [{\"yaw\": p[\"yaw\"], \"pitch\": p[\"pitch\"], \"abs_yaw\": p[\"abs_yaw\"], \"elev\": p[\"elev\"]}\n                    for p in m.viewer_marks()[\"points\"]]\n        pts, _, origin, _ = m.points()\n        c0 = m.clicks[0]\n        z0 = measures._ground_z(m.clicks)[c0.get(\"pic\")]\n        cam_z = geometry.camera(c0, self.tool.camera_for(c0), origin, z0)[0][2]\n        lon, lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n        cx, cy = triangulation._local(lon, lat, *origin)\n        heading, out = self._heading(), []\n        for x, y, z in pts:\n            bearing = math.degrees(math.atan2(x - cx, y - cy))\n            elev = math.degrees(math.atan2(z - cam_z, max(math.hypot(x - cx, y - cy), 0.5)))\n            out.append({\"yaw\": math.radians((bearing - heading + 540) % 360 - 180), \"pitch\": math.radians(elev),\n                        \"abs_yaw\": bearing % 360, \"elev\": elev})\n        return out\n\n    def _ref_near(self, click):\n        \"\"\"Hauteur : clic sur la croix du point de référence, quand aucune hauteur ne s'y appuie\n        (sinon c'est le pied de celles-ci) ?\"\"\"\n        mark = self._reference_mark() if self.mode == \"height\" and self.ref_point and self.item else None\n        if not mark:\n            return False\n        p = mark[\"points\"][0]  # comparé au clic brut (voir _nearest)\n        point = {\"abs_yaw\": (math.degrees(p[\"yaw\"]) + self._heading()) % 360, \"elev\": math.degrees(p[\"pitch\"])}\n        return self._nearest(click, [(None, [point])]) is not None\n\n    def _height_near(self, click):\n        \"\"\"(hauteur, n° de point) dont le repère est le plus près du clic sur la photo\n        affichée (à moins de measures.SELECT_ANGLE degrés), ou None.\"\"\"\n        return self._nearest(click, [(m, self._height_points(m)) for m in self._heights()])\n\n    def _nearest(self, click, candidates):\n        raw = click.get(\"raw\") or [click[\"yaw\"], click[\"elev\"]]\n        best, best_d = None, measures.SELECT_ANGLE\n        for m, points in candidates:\n            for index, p in enumerate(points):\n                dyaw = (raw[0] - p[\"abs_yaw\"] + 540) % 360 - 180\n                d = math.hypot(dyaw * math.cos(math.radians(raw[1])), raw[1] - p[\"elev\"])\n                if d < best_d:\n                    best, best_d = (m, index), d\n        return best\n\n    def _widths(self):\n        return [m for m in self.tool.measures() if isinstance(m, widths.PerpendicularWidth) and m.result]\n\n    def _width_near(self, click):\n        \"\"\"(largeur, n° de point) dont le repère est le plus près du clic (à moins de\n        measures.SELECT_ANGLE degrés), ou None.\"\"\"\n        candidates = [(m, self._width_points(m)) for m in self._widths()]\n        ref = self.ref_point\n        if self.mode == \"road\" and ref is not None and not any(m.edge is ref for m in self._widths()):\n            anchor = self._aim_anchor()\n            candidates.append((None, [anchor[0] if anchor else self._project(ref[\"lon\"], ref[\"lat\"])]))  # sa croix seule\n        return self._nearest(click, candidates)\n\n    def _sel_edge(self, sel=None):\n        \"\"\"Point de référence de la sélection d'une largeur (sel, par défaut width_sel), et axe de\n        la route en ce point (None en cours de lecture).\"\"\"\n        m = (sel or self.width_sel)[0]\n        edge = m.edge if m is not None else self.ref_point\n        road = m.road if m is not None else edge.get(\"road\")\n        return edge, (road or {}).get(\"axis\")\n\n    def _recale_width(self, click):\n        \"\"\"Point sélectionné d'une largeur, recalé par ce clic, sans quitter la droite de mesure :\n        le bord, là où la direction du clic la coupe ; le point de référence de même, et toutes\n        les largeurs qui s'y appuient recalculées (la droite ne bouge pas : il glisse dessus).\"\"\"\n        m, index = self.width_sel\n        self.width_sel = None\n        if index == 1:\n            m.reaim(1, click)\n            self.message = (m.error + \" \" if m.error else \"\") + m.status() + \" Bord recalé.\"\n            return self.status()\n        edge, axis = self._sel_edge((m, index))\n        if axis is None:\n            self.message = \"Axe de la route en cours de lecture (BD TOPO) : cliquez à nouveau dans un instant.\"\n            return self.status()\n        cam = triangulation._local(click[\"lon\"], click[\"lat\"], edge[\"lon\"], edge[\"lat\"])\n        try:\n            _, t, _, _ = widths.cross((0.0, 0.0), axis, cam, click[\"yaw\"])\n        except geometry.GeometryError as e:\n            self.message = \"Point de référence {} non recalé : {}\".format(edge[\"name\"], e)\n            return self.status()\n        refused = self._move_edge(edge, axis, t)\n        if refused:\n            self.message = refused\n            return self.status()\n        self.message = \"Point de référence {} recalé de {} cm le long de la droite de mesure.\".format(\n            edge[\"name\"], measures._num(abs(t) * 100, 0))\n        if m is not None:\n            self.message += \" \" + m.status()\n        return self.status()\n\n    def _move_edge(self, edge, axis, d):\n        \"\"\"Point de référence déplacé de d m le long de la droite de mesure, ses largeurs suivent.\n        Retourne le texte du refus (au-delà d'un bord : remis en place), sinon None.\"\"\"\n        mates = [w for w in self._widths() if w.edge is edge]\n        widths.move_edge(edge, axis, d)\n        self._edge_moved(edge, mates)\n        if any(w.error or w.result is None or w.result[\"value\"] < widths.MIN_WIDTH for w in mates):\n            widths.move_edge(edge, axis, -d)\n            self._edge_moved(edge, mates)\n            return \"Le point de référence ne passe pas au-delà du bord.\"\n        edge[\"moved\"] = True  # déplacé à la main : plus retriangulé (voir _recompute_reference)\n        return None\n\n    def nudge_point(self, key):\n        \"\"\"Flèches du clavier sur le point sélectionné (key : \"left\", \"right\", \"up\", \"down\"),\n        qui reste sélectionné : hauteur, pied ou sommet monté (↑) ou descendu (↓) de 1 cm ;\n        largeur, voir _nudge_width.\"\"\"\n        if key not in NUDGE_WORDS or not self.item:\n            return self.status()\n        if self.mode == \"height\" and self.ref_sel:\n            if key in (\"up\", \"down\"):\n                self._nudge_ref_foot(NUDGE if key == \"up\" else -NUDGE)\n                self.message = \"Pied au point de référence {} {} de 1 cm sur cette photo.\".format(\n                    self.ref_point[\"name\"], \"monté\" if key == \"up\" else \"descendu\")\n            else:\n                self.message = \"← → sans effet : le point de référence reste sur sa verticale.\"\n            self.message += \" Flèches ↑ ↓ : encore 1 cm ; clic : recaler ; Entrée : terminer.\"\n            return self.status()\n        if self.mode == \"height\" and self.tool.selected is not None:\n            m, index = self.tool.selected\n            if key in (\"up\", \"down\"):\n                m.lift(index, NUDGE if key == \"up\" else -NUDGE)\n                self._sync_ref_foot(m, index)\n                self.message = (m.error + \" \" if m.error else \"\") + (m.status() if m.result else \"\")\n            else:\n                self.message = \"← → sans effet sur une hauteur : ↑ ↓ montent ou descendent le point.\"\n            self.message += \" Flèches ↑ ↓ : encore 1 cm ; clic : recaler ; Entrée : terminer.\"\n            return self.status()\n        return self._nudge_width(key)\n\n    def finish_point(self):\n        \"\"\"Touche Entrée : fin du calage du point sélectionné (hauteur ou largeur), qui\n        redevient un point ordinaire ; le résultat de sa mesure s'affiche.\"\"\"\n        if self.ref_sel:\n            self.ref_sel = False\n            self.message = \"\"\n            return self.status()\n        if self.mode == \"height\" and self.tool.selected is not None:\n            m = self.tool.selected[0]\n            self.tool.cancel_selection()\n            self.message = m.status() if m.result else \"\"\n            return self.status()\n        return self.finish_width()\n\n    def _nudge_width(self, key):\n        \"\"\"Flèches du clavier : point sélectionné d'une largeur déplacé de 1 cm le long de la\n        droite de mesure, dans le sens vu sur la photo affichée (key : \"left\", \"right\" ; \"up\" :\n        en s'éloignant de la caméra, \"down\" : en s'en rapprochant). Il reste sélectionné. Le\n        point de référence entraîne toutes les largeurs qui en partent.\"\"\"\n        if self.width_sel is None:\n            return self.status()\n        m, index = self.width_sel\n        if index == 1:\n            d = self._nudge_sign(m.result[\"points\"][1], m.road[\"axis\"], key) * NUDGE\n            m.nudge(d * m.side())  # vers l'extérieur du point de référence : plus large\n            self.message = m.status()\n        else:\n            edge, axis = self._sel_edge()\n            if axis is None:\n                self.message = \"Axe de la route en cours de lecture (BD TOPO) : réessayez dans un instant.\"\n                return self.status()\n            d = self._nudge_sign((edge[\"lon\"], edge[\"lat\"]), axis, key) * NUDGE  # le long de perpendicular(axe)\n            refused = self._move_edge(edge, axis, d)\n            if refused:\n                self.message = refused\n            else:\n                self.message = \"Point de référence {} déplacé de 1 cm {}.{}\".format(\n                    edge[\"name\"], NUDGE_WORDS[key], \" \" + m.status() if m is not None else \"\")\n        self.message += \" Flèches : encore 1 cm ; clic : recaler ; Entrée : terminer.\"\n        return self.status()\n\n    def finish_width(self):\n        \"\"\"Touche Entrée : fin du calage du point sélectionné d'une largeur, qui redevient un\n        point ordinaire ; le résultat de la largeur s'affiche.\"\"\"\n        if self.width_sel is not None:\n            m = self.width_sel[0]\n            self.width_sel = None\n            self.message = m.status() if m is not None and m.result else \"\"\n        return self.status()\n\n    def _nudge_sign(self, point, axis, key):\n        \"\"\"Sens (+1 ou -1, le long de widths.perpendicular(axis)) qui déplace point (lon, lat)\n        vers la droite (ou s'éloigne de la caméra) sur la photo affichée.\"\"\"\n        lon, lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n        x, y = triangulation._local(*point, lon, lat)\n        ux, uy = widths.perpendicular(axis)\n        if key in (\"up\", \"down\"):\n            sign = 1 if x * ux + y * uy > 0 else -1  # +u éloigne de la caméra\n        else:\n            sign = 1 if x * uy - y * ux < 0 else -1  # +u tourne le cap vers la droite (sens horaire)\n        return sign if key in (\"right\", \"up\") else -sign\n\n    def _edge_moved(self, edge, mates):\n        \"\"\"Point de référence déplacé : son point gardé et ses largeurs suivent.\"\"\"\n        for k, (_, _, v) in enumerate(self.points):\n            if v[\"nom\"] == edge[\"name\"]:\n                self.points[k] = (edge[\"lon\"], edge[\"lat\"], v)\n        for w in mates:\n            w.clicks[0] = w._edge_mark(w.clicks[1])\n            w.compute()\n\n    def _aim_across(self):\n        \"\"\"Direction (est, nord) en travers de la route pour le point visé : axe de la largeur (bord B),\n        sinon trajectoire ou orientation de la photo (l'axe du point de référence n'est lu qu'à sa\n        validation), ou None.\"\"\"\n        if self.b_aiming is not None:\n            return widths.perpendicular(self.b_aiming.road[\"axis\"])\n        heading = self._axis(self.item) if self.item else None\n        heading = metadata.item_heading(self.item or {}) if heading is None else heading\n        return None if heading is None else widths.perpendicular(heading)\n\n    def _road_at_reference(self):\n        \"\"\"Axe de la route au point de référence de la largeur : tronçon de la BD TOPO qui\n        longe la trajectoire de la photo, sinon trajectoire de la séquence (voir roads.py).\n        Laisse road à None pendant la lecture (reprise par _roads_ready).\"\"\"\n        ref = self.ref_point\n        track = self._axis(self.item) if self.item else None\n        heading = track if track is not None else metadata.item_heading(self.item or {})\n        res = self.roads.lookup(ref[\"lon\"], ref[\"lat\"], None if heading is None else (heading + 90) % 360,\n                                (self.item or {}).get(\"collection\"))\n        if isinstance(res, dict):\n            ref[\"road\"] = {\"axis\": res[\"axis\"], \"source\": res[\"source\"]}\n        elif res != \"pending\":\n            ref[\"road\"] = {\"axis\": heading or 0.0,\n                           \"source\": \"séquence\" if track is not None else \"orientation de la photo\"}\n\n    def new_reference(self):\n        \"\"\"Hauteur : « Nouveau point de référence » ; les hauteurs déjà faites restent.\"\"\"\n        self.epoch += 1  # pied cliqué en attente de son profil : abandonné\n        self.b_aiming = None\n        self.tool.clear()\n        self.triangulator.clear()\n        self.ref_point = None\n        self.width_sel = None\n        self.measure_done = False\n        self.ref_sel = False\n        self.message = \"\"\n        return self.status()\n\n    # Bord B d'une largeur, triangulé à son tour ---------------------------------------------\n    def _edge_b_candidate(self):\n        \"\"\"Largeur à laquelle proposer de trianguler son bord B : la dernière faite depuis le\n        point de référence, bord cliqué (pas encore triangulé), ou None.\"\"\"\n        ref = self.ref_point\n        if not (self.active and self.mode == \"road\" and ref and self.b_aiming is None):\n            return None\n        mates = [w for w in self._widths() if w.edge is ref]\n        return mates[-1] if mates and mates[-1].edge_b is None else None\n\n    def start_edge_b(self):\n        \"\"\"Bouton « Trianguler le bord B » : le clic de la mesure rapide devient la première visée\n        du bord ; les clics suivants le visent depuis d'autres photos, comme le point de\n        référence (photos proposées, « Valider le point triangulé »), puis la largeur se recalcule\n        entre les deux points triangulés. Hors de la photo de la mesure, la visionneuse ne montre\n        que les visées (voir viewer_marks).\"\"\"\n        m = self._edge_b_candidate()\n        if m is None:\n            return self.status()\n        self.width_sel = None\n        self.triangulator.clear()\n        self.b_aiming = m\n        self.message = \"\"\n        # Le clic de la mesure rapide est la première visée du bord, depuis la photo de la mesure\n        click = m.clicks[1]\n        item = self.photo_items.get(click.get(\"pic\"))\n        if item is not None and click.get(\"raw\"):\n            sighting = tools.photo_sighting(item, click[\"raw\"][0], click[\"raw\"][1], self.calibration,\n                                            self.precision.known(item))\n            if sighting is not None:\n                if click.get(\"pos\") and click[\"pos\"][0] is not None:\n                    sighting[\"view\"] = list(click[\"pos\"])  # croix bleue de la visée\n                self.ref_photo = sighting[\"pic\"]\n                self.triangulator.ground = True\n                self.triangulator.add(sighting)\n        return self.status()\n\n    def _stop_edge_b(self):\n        if self.b_aiming is not None:\n            self.b_aiming = None\n            self.triangulator.clear()\n\n    def _keep_edge_b(self, values):\n        \"\"\"Bord B validé : gardé comme point triangulé (export), la largeur recalculée entre A et\n        lui ; retour sur la photo de référence.\"\"\"\n        r, sightings = self.triangulator.result, list(self.triangulator.sightings)\n        name = getattr(self.b_aiming, \"provisional_name\", None)  # le bord garde sa lettre\n        if not name:\n            name = _point_name(self.named)\n            self.named += 1\n        self.points.append((r[\"lon\"], r[\"lat\"], dict({\"nom\": name}, **values, commentaire=\"\")))\n        self.point_views[name] = {s[\"pic\"]: s[\"view\"] for s in sightings if s.get(\"view\")}\n        ground_z = self.triangulator.ground_z\n        m, self.b_aiming = self.b_aiming, None\n        self.triangulator.clear()\n        m.set_edge_b({\"lon\": r[\"lon\"], \"lat\": r[\"lat\"], \"uncertainty\": r[\"uncertainty\"], \"cov\": r.get(\"cov\"), \"name\": name,\n                      \"sightings\": sightings, \"ground_z\": ground_z})\n        if self.ref_photo and self.ref_photo != (self.item or {}).get(\"id\"):\n            self.goto = self.ref_photo\n        self.frame_request = m  # vue cadrée sur la largeur entière (take_frame)\n        self.message = m.status() + self._rtk_warning([s.get(\"sequence\") for s in sightings])\n        return self.status()\n\n    def _recompute_edges_b(self, touched, force=False):\n        \"\"\"Bords B triangulés dont une visée a été recalculée (calage, précision ; tous si force) :\n        triangulés à nouveau, leur largeur avec.\"\"\"\n        for m in self._widths():\n            b = m.edge_b\n            if b and (any([self._resight(s) for s in b[\"sightings\"] if touched(s[\"pic\"])]) or force):\n                try:\n                    r = tools.solve_on_ground(b[\"sightings\"], True, self._lidar_z(b))\n                except triangulation.TriangulationError:\n                    continue\n                b.update(lon=r[\"lon\"], lat=r[\"lat\"], uncertainty=r[\"uncertainty\"], cov=r.get(\"cov\"))\n                for k, (_, _, v) in enumerate(self.points):\n                    if v[\"nom\"] == b[\"name\"]:\n                        self.points[k] = (b[\"lon\"], b[\"lat\"], v)\n                m.compute()\n\n    def new_measure(self):\n        \"\"\"« Nouvelle mesure depuis A » : la largeur ou la hauteur faite reste, le clic suivant (bord\n        opposé, sommet) en donne une autre depuis le même point de référence.\"\"\"\n        self._stop_edge_b()\n        self.width_sel = None\n        self.tool.cancel_selection()\n        self.measure_done = False\n        self.ref_sel = False\n        self.message = \"\"\n        return self.status()\n\n    def _locked(self):\n        \"\"\"Largeur ou hauteur faite depuis le point de référence (et toujours là) : les clics ne\n        servent plus qu'à ajuster ses points, jusqu'à new_measure.\"\"\"\n        ref = self.ref_point\n        if not self.measure_done or ref is None or self.b_aiming is not None:  # bord B en visée\n            return False\n        if self.mode == \"road\":\n            return any(w.edge is ref for w in self._widths())\n        return self.mode == \"height\" and any((m.reference or {}).get(\"name\") == ref[\"name\"] for m in self._heights())\n\n    def _ref_view(self, pic):\n        \"\"\"Hauteur : [cap, élévation] (radians, repère de la photo pic) du pied au point de\n        référence : recalé sur cette photo (ref[\"feet\"]), sinon sa visée depuis elle, ou None.\"\"\"\n        ref = self.ref_point or {}\n        if pic in ref.get(\"feet\", {}):\n            return ref[\"feet\"][pic]\n        seen = next((s for s in ref.get(\"sightings\", []) if s[\"pic\"] == pic and s.get(\"view\")), None)\n        return list(seen[\"view\"]) if seen else None\n\n    def _ref_distance(self):\n        \"\"\"Distance horizontale (m) de la photo affichée au point de référence.\"\"\"\n        lon, lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n        return max(math.hypot(*triangulation._local(self.ref_point[\"lon\"], self.ref_point[\"lat\"], lon, lat)), 0.5)\n\n    def _recale_ref_foot(self, pitch):\n        \"\"\"Hauteur : pied au point de référence recalé sur la photo affichée, à l'élévation pitch\n        (radians), sur sa verticale (le cap ne change pas) ; les hauteurs suivantes depuis cette\n        photo partent de là.\"\"\"\n        ref, pic = self.ref_point, self.item.get(\"id\")\n        mark = self._reference_mark()\n        yaw = mark[\"points\"][0][\"yaw\"] if mark else self._project(ref[\"lon\"], ref[\"lat\"])[\"yaw\"]\n        old = self._ref_view(pic)\n        ref.setdefault(\"feet\", {})[pic] = [yaw, pitch]\n        dz = (math.tan(pitch) - math.tan(old[1] if old else self._project(ref[\"lon\"], ref[\"lat\"])[\"pitch\"])) \\\n            * self._ref_distance()\n        return dz\n\n    def _nudge_ref_foot(self, dz):\n        \"\"\"Hauteur : pied au point de référence monté (dz > 0) ou descendu de dz m sur la photo\n        affichée.\"\"\"\n        ref, pic = self.ref_point, self.item.get(\"id\")\n        view = self._ref_view(pic)\n        if view is None:\n            p = self._project(ref[\"lon\"], ref[\"lat\"])\n            view = [p[\"yaw\"], p[\"pitch\"]]\n        d = self._ref_distance()\n        ref.setdefault(\"feet\", {})[pic] = [view[0], math.atan((d * math.tan(view[1]) + dz) / d)]\n\n    def _reference_foot(self):\n        \"\"\"Hauteur : clic du pied pris dans la visée du point de référence faite depuis la photo\n        affichée (le pied est le point triangulé), ou recalé sur elle ; None sinon.\"\"\"\n        view = self._ref_view((self.item or {}).get(\"id\")) if self.ref_point else None\n        if view is None:\n            return None\n        yaw, pitch = view\n        return tools.photo_click(self.item, (math.degrees(yaw) + self._heading()) % 360, math.degrees(pitch),\n                                 self.calibration, self.quality, [yaw, pitch], self._axis(self.item))\n\n    def _anchor_height(self):\n        \"\"\"Hauteur terminée : calée sur le point de référence, qui reste pour les suivantes.\"\"\"\n        m = self.tool.current\n        if self.mode != \"height\" or self.ref_point is None or m is None or not m.result or m.reference:\n            return\n        ref = self.ref_point\n        self._anchor_on(m, ref)\n        if m.error:\n            self.message = m.error\n            return\n        self.message = (m.status() + self._rtk_warning(ref[\"sequences\"] + [c.get(\"sequence\") for c in m.clicks])\n                        + \" Pour l'ajuster, cliquez une de ses croix. Autre hauteur depuis ce point : « Nouvelle \"\n                          \"mesure depuis {} ».\".format(ref[\"name\"]))\n        self.measure_done = True\n        self.tool.finish()  # mesure terminée : affichée avec les autres pendant les visées suivantes\n\n    def _anchor_on(self, m, ref):\n        \"\"\"Hauteur m calée sur le point de référence ref : pied sur la visée du pied de sa photo\n        (là où il a été cliqué, ou visé pour la triangulation), à la profondeur du point\n        triangulé. Avec trois visées ou plus, le point triangulé est un compromis qui s'écarte un\n        peu de chacune : le pied reste là où on l'a mis sur la photo de la mesure, la hauteur ne\n        dépendant que de sa distance.\"\"\"\n        c = m.clicks[0]\n        x, y = triangulation._local(ref[\"lon\"], ref[\"lat\"], c[\"lon\"], c[\"lat\"])\n        a = math.radians(c[\"yaw\"])\n        t = x * math.sin(a) + y * math.cos(a)  # profondeur du point le long de la visée du pied\n        lon, lat = (ref[\"lon\"], ref[\"lat\"]) if t < 0.5 else \\\n            triangulation._geographic(t * math.sin(a), t * math.cos(a), c[\"lon\"], c[\"lat\"])\n        m.anchor(lon, lat, ref[\"uncertainty\"], ref[\"name\"])\n\n    def _after_calibration(self, tool):\n        if tool is not self.calibrator:\n            return\n        self._calibration_changed()\n\n    def aim(self, yaw, pitch):\n        \"\"\"Triangulation : visée de la direction cliquée (radians, dans le repère de la photo).\"\"\"\n        if not self.active:\n            return self.status()\n        if not self.item:\n            self.message = \"Aucune photo affichée : impossible de viser.\"\n            return self.status()\n        sighting = tools.photo_sighting(self.item, (math.degrees(yaw) + self._heading()) % 360,\n                                        math.degrees(pitch), self.calibration, self.quality)\n        if sighting is None:\n            self.message = \"Position de la photo inconnue : impossible de viser.\"\n            return self.status()\n        self.message = \"\"\n        sighting[\"view\"] = [yaw, pitch]  # repère de la visée dans la photo (viewer_marks)\n        replaced = any(s[\"pic\"] == sighting[\"pic\"] for s in self.triangulator.sightings)\n        if self.mode in REF_MODES and not self.triangulator.sightings:\n            self.ref_photo = sighting[\"pic\"]  # photo de référence : la mesure s'y fera\n        self.triangulator.ground = self.mode in REF_MODES  # bord de chaussée, pied : au sol\n        self.triangulator.add(sighting)\n        if replaced:  # une visée par photo : un second clic (le sommet ?) remplace la première\n            self.message = \"Visée de cette photo remplacée : une seule visée par photo. \"\n            if self.mode == \"height\":\n                self.message += (\"Étape 1 : visez le pied de l'objet depuis une autre photo (flèches pour changer \"\n                                 \"de photo), puis « Valider le point triangulé » ; le pied et le sommet se cliquent ensuite.\")\n            elif self.mode == \"road\":\n                self.message += (\"Étape 1 : visez le premier bord depuis une autre photo (flèches pour changer \"\n                                 \"de photo), puis « Valider le point triangulé » ; le bord opposé se clique ensuite.\")\n            else:\n                self.message += \"Changez de photo (flèches) pour viser le même objet d'un autre point de vue.\"\n            self.message += self._rtk_warning([s.get(\"sequence\") for s in self.triangulator.sightings])\n        return self.status()\n\n    def keep_point(self):\n        \"\"\"Garde le point triangulé (exporté avec les mesures), puis repart de zéro.\"\"\"\n        values = self.triangulator.attributes()\n        if values is None:\n            self.message = self.triangulator.error or \"Il faut au moins deux visées qui se croisent.\"\n            return self.status()\n        if self.b_aiming is not None:\n            return self._keep_edge_b(values)\n        r = self.triangulator.result\n        sightings = self.triangulator.sightings\n        sequences = [s.get(\"sequence\") for s in sightings]\n        warning = self._rtk_warning(sequences)\n        name = _point_name(self.named)\n        self.named += 1\n        values = dict({\"nom\": name}, **values, commentaire=\"\")\n        self.points.append((r[\"lon\"], r[\"lat\"], values))\n        self.point_views[name] = {s[\"pic\"]: s[\"view\"] for s in sightings if s.get(\"view\")}\n        ground_z = self.triangulator.ground_z  # sol LiDAR lu au point, avant que clear ne l'oublie\n        self.triangulator.clear()\n        if self.mode in REF_MODES:  # point de référence, sans distance au précédent\n            if self.ref_photo and self.ref_photo != (self.item or {}).get(\"id\"):\n                self.goto = self.ref_photo  # retour sur la photo de référence pour la mesure\n            self.frame_request = \"reference\"  # vue cadrée sur A (take_frame)\n            self.ref_point = {\"lon\": r[\"lon\"], \"lat\": r[\"lat\"], \"uncertainty\": r[\"uncertainty\"], \"cov\": r.get(\"cov\"), \"name\": name,\n                              \"sequences\": sequences, \"road\": None, \"sightings\": list(sightings),\n                              \"ground_z\": ground_z}  # sol LiDAR au point, s'il est lu\n            self._ref_ground()  # sinon demandé maintenant\n            if self.mode == \"height\":\n                self.message = (\"Point de référence {} validé (±{} m) : c'est le pied. Cliquez maintenant le sommet \"\n                                \"de l'objet, depuis cette photo ou une autre de la triangulation (à choisir sur la \"\n                                \"carte).\")\n            else:\n                self._road_at_reference()\n                self.message = (\"Point de référence {} validé (±{} m). Cliquez maintenant le bord opposé, au sol, \"\n                                \"sur la photo de référence (ou une autre prise quelques mètres avant ou après) : seule \"\n                                \"la direction du clic compte, la largeur se prend sur la droite tracée.\")\n            self.message = self.message.format(name, measures._num(r[\"uncertainty\"])) + warning\n            return self.status()\n        self.message = \"Point {} gardé (±{} m).\".format(name, measures._num(r[\"uncertainty\"]))\n        if self.last_free is not None:  # mesure libre : distance au point gardé précédent, aussitôt\n            self.message += \" \" + self._link(self.last_free, len(self.points) - 1)\n        self.last_free = len(self.points) - 1\n        self.message += (\" Visez maintenant le point suivant depuis au moins deux photos : sa distance à {} sera \"\n                         \"calculée.\").format(name) + warning\n        return self.status()\n\n    def _link(self, i, j):\n        \"\"\"Distance horizontale entre les points gardés n° i et j (la triangulation donne une\n        position sur la carte), incertitude des deux points combinée, gardée comme une mesure.\n        Retourne le texte à afficher.\"\"\"\n        (lon1, lat1, v1), (lon2, lat2, v2) = self.points[i], self.points[j]\n        x, y = triangulation._local(lon2, lat2, lon1, lat1)\n        value, unc = math.hypot(x, y), math.hypot(v1[\"incert_m\"], v2[\"incert_m\"])\n        self.links.append((i, j, {\"valeur_m\": round(value, 3), \"incert_m\": round(unc, 2), \"commentaire\": \"\"}))\n        return \"Distance {}–{} : {} m (±{} m).\".format(\n            v1[\"nom\"], v2[\"nom\"], measures._num(value, 2), measures._num(unc, 2))\n\n    def move_handle(self, index, lon, lat):\n        \"\"\"Poignée n° index (voir handles) glissée sur la carte en (lon, lat).\"\"\"\n        if not 0 <= index < len(self._handles):\n            return self.status()\n        try:\n            self.message = self.tool.move_handle(self._handles[index], float(lon), float(lat))\n        except Exception:\n            traceback.print_exc()\n            self.message = \"Recalage impossible.\"\n        return self.status()\n\n    def clear(self):\n        \"\"\"« Effacer » : sélection d'un point, mesure en cours, visées, ou calage du mode.\"\"\"\n        self.message = \"\"\n        if self.b_aiming is not None:  # triangulation du bord B abandonnée : la largeur garde son clic\n            self._stop_edge_b()\n            self.message = \"Triangulation du bord abandonnée : la largeur garde le bord cliqué.\"\n            return self.status()\n        tool = self._active()\n        if tool is self.tool and tool.cancel_selection():\n            return self.status()\n        if self.width_sel is not None or self.ref_sel:\n            self.width_sel, self.ref_sel = None, False\n            return self.status()\n        self.epoch += 1\n        nothing_aimed = tool is self.triangulator and not self.triangulator.sightings\n        nothing_clicked = tool is self.tool and self.mode in REF_MODES and (\n            self.tool.current is None or not self.tool.current.clicks)\n        if nothing_aimed or nothing_clicked:  # rien en cours : le dernier point posé\n            return self._undo_point()\n        tool.clear()\n        if tool is self.calibrator:\n            self._calibration_changed()\n        return self.status()\n\n    def _undo_point(self):\n        \"\"\"« Effacer » sans rien en cours : retire le dernier point posé. Hauteur ou largeur : la\n        dernière mesure depuis le point de référence (son sommet, son bord opposé, triangulé ou\n        non), puis, sans mesure, le point de référence lui-même ; mesure libre : le dernier point\n        gardé (et sa distance au précédent).\"\"\"\n        if self.mode == \"tri\":\n            if self.points:\n                self._drop_kept(len(self.points) - 1)\n            return self.status()\n        ref = self.ref_point\n        if ref is None:\n            return self.status()\n        if self.mode == \"road\":\n            mates = [m for m in self._widths() if m.edge is ref]\n        else:\n            mates = [m for m in self._heights() if (m.reference or {}).get(\"name\") == ref[\"name\"]]\n        if mates:\n            m = mates[-1]\n            if getattr(m, \"edge_b\", None):  # bord opposé triangulé : son point gardé avec\n                k = next((k for k, (_, _, v) in enumerate(self.points) if v[\"nom\"] == m.edge_b[\"name\"]), None)\n                if k is not None:\n                    self._drop_kept(k)\n            self.delete_result(\"mesure\", id(m))\n            self.measure_done = False\n            self.message = (\"Bord opposé effacé : cliquez-le à nouveau.\" if self.mode == \"road\"\n                            else \"Sommet effacé : cliquez-le à nouveau.\")\n            return self.status()\n        k = next((k for k, (_, _, v) in enumerate(self.points) if v[\"nom\"] == ref[\"name\"]), None)\n        if k is not None:\n            self._drop_kept(k)\n        self.ref_point, self.width_sel, self.ref_sel, self.measure_done = None, None, False, False\n        self.message = \"Point de référence {} effacé : visez-le à nouveau.\".format(ref[\"name\"])\n        return self.status()\n\n    def _drop_kept(self, k):\n        \"\"\"Retire le point gardé n° k ; si c'était le dernier nommé, sa lettre resservira.\"\"\"\n        name = self.points[k][2][\"nom\"]\n        self.delete_result(\"point\", k)\n        self.proposal = None  # pas de distance proposée : c'est une annulation\n        self.point_views.pop(name, None)\n        if name == _point_name(self.named - 1):\n            self.named -= 1\n\n    def clear_all(self):\n        self.epoch += 1\n        self.b_aiming = None\n        self.frame_request = None\n        self.triangulator.clear()\n        self.tool.clear_all()\n        self.calibrator.reset()\n        self.points, self.links, self.named = [], [], 0\n        self.last_free, self.point_views = None, {}\n        self.ref_point = None\n        self.width_sel = None\n        self.measure_done = False\n        self.ref_sel = False\n        self.message = \"\"\n        return self.status()\n\n    def _roads_ready(self):\n        changed = self.tool.recompute_roads() or self._bridge_waiting  # pont à proposer peut-être\n        self._bridge_waiting = False\n        ref = self.ref_point\n        if ref is not None and self.mode == \"road\" and ref.get(\"road\") is None:  # axe au point de référence\n            self._road_at_reference()\n            changed = changed or ref.get(\"road\") is not None\n        if changed:\n            self.notify()\n\n    # Affichage -----------------------------------------------------------------------\n    def status(self):\n        \"\"\"Texte de la mesure (consigne ou résultat).\"\"\"\n        if not self.active:\n            return self.message or \"Cliquez « 📐 Mesure » pour mesurer dans la photo ou la caler.\"\n        if self.message:\n            return self.message\n        if self.width_sel is not None:\n            if self.width_sel[1] == 0:\n                return (\"Point de référence {} sélectionné : cliquez sa position exacte, depuis cette photo ou une \"\n                        \"autre (seule la direction compte, il reste sur la droite de mesure) ; flèches du clavier : \"\n                        \"1 cm le long de la droite (← → dans la photo, ↑ ↓ en s'éloignant ou en se rapprochant) ; \"\n                        \"Entrée pour terminer.\").format(self._sel_edge()[0].get(\"name\", \"\"))\n            return (\"Bord de la largeur sélectionné : cliquez sa position exacte, depuis cette photo ou une autre \"\n                    \"(seule la direction compte, il reste sur la droite de mesure) ; flèches du clavier : 1 cm le \"\n                    \"long de la droite (← → dans la photo, ↑ ↓ en s'éloignant ou en se rapprochant) ; Entrée \"\n                    \"pour terminer.\")\n        if self.mode == \"height\" and self.ref_sel:\n            return (\"Point de référence {} sélectionné : cliquez la position exacte du pied sur cette photo (il \"\n                    \"reste sur sa verticale), ou flèches du clavier ↑ ↓ : 1 cm ; Entrée pour terminer.\").format(\n                self.ref_point[\"name\"])\n        if self.mode == \"height\" and self.tool.selected is not None:\n            return (\"{} de la hauteur sélectionné : cliquez sa position exacte sur la photo de la mesure, ou \"\n                    \"flèches du clavier ↑ ↓ : 1 cm ; Entrée pour terminer.\").format(\n                \"Pied\" if self.tool.selected[1] == 0 else \"Sommet\")\n        if self.mode == \"tilt\":\n            return self._calibration_text()\n        text = self._active().status()\n        sequences = []\n        if self._aiming():\n            sequences = [s.get(\"sequence\") for s in self.triangulator.sightings]\n        if self.mode == \"tri\":\n            text = \"Mesure libre (distance au point gardé précédent) : \" + text\n        if self.mode == \"height\" and self.ref_point is None:\n            text = (\"Hauteur, étape 1/2 : visez le pied de l'objet depuis au moins deux photos (une visée par \"\n                    \"photo, flèches pour changer de photo). \" + text)\n            if self.triangulator.result is not None:\n                text += \" Puis « Valider le point triangulé ».\"\n        elif self._locked():\n            text = self._locked_text()\n            sequences = self.ref_point[\"sequences\"]\n        elif self.mode == \"height\":\n            current = self.tool.current\n            if (current is None or len(current.clicks) >= current.needed()) and self._reference_foot() is not None:\n                text = (\"Cliquez le sommet de l'objet : le pied est le point {} visé depuis cette photo.\").format(\n                    self.ref_point[\"name\"])\n            elif current is None or len(current.clicks) >= current.needed():\n                text = (\"Cette photo n'a pas servi à viser le point : cliquez le pied puis le sommet, ou passez sur \"\n                        \"une photo de la triangulation (seul le sommet y est à cliquer).\")\n            text = \"Hauteur, étape 2/2 (point {}) : {}\".format(self.ref_point[\"name\"], text)\n            current = self.tool.current\n            sequences = self.ref_point[\"sequences\"] + [c.get(\"sequence\") for c in (current.clicks if current else [])]\n        elif self.mode == \"road\" and self.b_aiming is not None and len(self.triangulator.sightings) == 1:\n            text = (\"Largeur, bord opposé : le clic de la mesure compte comme première visée. Passez à la photo \"\n                    \"suivante (bouton proposé) et visez le même bord ; « Effacer » pour garder le clic.\")\n        elif self.mode == \"road\" and self.b_aiming is not None:\n            text = (\"Largeur, bord opposé : visez-le depuis au moins deux photos, comme le point {} (une visée \"\n                    \"par photo, photos proposées ou flèches). {}\").format(self.ref_point[\"name\"], text)\n            if self.triangulator.result is not None:\n                text += \" Puis « Valider le point triangulé » ; « Effacer » pour garder le bord cliqué.\"\n        elif self.mode == \"road\" and self.ref_point is None:\n            text = (\"Largeur, étape 1/2 : visez le premier bord (pied de bordure, marquage…) depuis au moins deux \"\n                    \"photos (une visée par photo, flèches pour changer de photo). \" + text)\n            if self.triangulator.result is not None:\n                text += \" Puis « Valider le point triangulé ».\"\n        elif self._locked():\n            text = self._locked_text()\n            sequences = self.ref_point[\"sequences\"]\n        elif self.mode == \"road\":\n            road = self.ref_point.get(\"road\")\n            text = (\"Largeur, étape 2/2 (point {}) : cliquez le bord opposé, au sol, depuis une photo prise quelques \"\n                    \"mètres avant ou après le point (pas juste en face) ; la largeur se prend sur la droite tracée{}.\").format(\n                self.ref_point[\"name\"], \" (axe de la route en cours de lecture)\" if road is None\n                else \", perpendiculaire à l'axe {}° ({})\".format(measures._num(road[\"axis\"] % 180, 0), road[\"source\"]))\n            sequences = self.ref_point[\"sequences\"]\n        return text + self._rtk_warning(sequences)\n\n    def _name_marks(self, marks):\n        \"\"\"Étiquettes des noms des points triangulés dans la photo affichée, sans croix (« name ») :\n        point de référence des largeurs et des hauteurs, à sa croix (repère du point de référence\n        en cours, point 0 de ses mesures) ; points gardés de la mesure libre. side : côté de la\n        croix opposé à la mesure (« left », « right », « above », « below »), pour ne pas la\n        masquer ; dessous par défaut (une hauteur monte, une largeur s'étend sur les côtés).\n        Points d'arrivée des hauteurs et largeurs (sommet, bord) : nommés dans l'étiquette de leur\n        mesure (« end » de viewer_marks), pas ici.\"\"\"\n        pic = self.item.get(\"id\")\n        at = {}  # nom -> (repère, repère de l'autre bout de la mesure ou None)\n        ref = self.ref_point\n        if ref is not None and self.active and self.mode in REF_MODES:\n            mark = self._reference_mark()\n            if mark:\n                at[ref[\"name\"]] = (mark[\"points\"][0], None)\n        ends = set()  # points d'arrivée des hauteurs et largeurs : nommés dans leur étiquette\n        starts = {(ref or {}).get(\"name\")} | {w.edge.get(\"name\") for w in self._widths()} | {\n            (m.reference or {}).get(\"name\") for m in self._heights()}  # points de départ : nommés à part\n        for w in self._widths():\n            points = self._width_points(w)\n            at.setdefault(w.edge.get(\"name\"), (points[0], points[1]))\n            ends.add(self._end_name(w)[\"name\"])\n        for m in self._heights():\n            if m.reference and m.reference.get(\"name\"):\n                points = self._height_points(m)\n                at.setdefault(m.reference[\"name\"], (points[0], points[1] if len(points) > 1 else None))\n                if len(points) > 1:\n                    ends.add(self._end_name(m)[\"name\"])\n        partner = {}\n        for i, j, _ in self.links:  # mesure libre : à l'opposé du point relié\n            partner.setdefault(i, j)\n            partner.setdefault(j, i)\n        for k, (_, _, values) in enumerate(self.points):\n            if values[\"nom\"] not in at and values[\"nom\"] not in ends:\n                other = self._free_mark_point(partner[k]) if k in partner else None\n                at[values[\"nom\"]] = (self._free_mark_point(k), other)\n        # Traits des mesures de la photo : un nom qui tombe à l'intérieur de l'un d'eux (sommet\n        # d'une hauteur plus courte sous une plus haute, bord sur une largeur plus longue) est\n        # mis sur le côté du trait, pas dessus\n        lines = [[q for q in m[\"points\"] if q.get(\"pic\", pic) == pic and q.get(\"yaw\") is not None]\n                 for m in marks if m.get(\"label\") and not m.get(\"name\")]\n        lines = [(q[0], q[-1]) for q in lines if len(q) >= 2]\n        return [{\"points\": [dict(p, pic=pic, sel=False)], \"label\": name, \"name\": True,\n                 \"side\": _beside_line(p, lines) or _away(p, other)}\n                for name, (p, other) in at.items() if name and p is not None and (name not in ends or name in starts)]\n\n    def _end_name(self, m):\n        \"\"\"Point d'arrivée d'une hauteur (sommet) ou d'une largeur (bord) : {\"name\", \"provisional\"}\n        (bord triangulé : son nom, définitif), ou None (hauteur sans point de référence nommé).\"\"\"\n        if isinstance(m, widths.PerpendicularWidth):\n            if m.edge_b:\n                return {\"name\": m.edge_b[\"name\"], \"provisional\": False}\n            return {\"name\": self._provisional_name(m), \"provisional\": True}\n        if m.reference and m.reference.get(\"name\"):\n            return {\"name\": self._provisional_name(m), \"provisional\": True}\n        return None\n\n    def _provisional_name(self, m):\n        \"\"\"Nom provisoire du bord cliqué d'une largeur ou du sommet d'une hauteur (lettre suivante\n        des points gardés), donné une fois ; le bord le garde s'il est triangulé ensuite (voir\n        _keep_edge_b).\"\"\"\n        if not getattr(m, \"provisional_name\", None):\n            m.provisional_name = _point_name(self.named)\n            self.named += 1\n        return m.provisional_name\n\n    def _calibration_text(self):\n        \"\"\"Consigne du calage de l'inclinaison, étape par étape, avec ce qui est déjà fait.\"\"\"\n        tool, pic = self.calibrator, (self.item or {}).get(\"id\")\n        prefix = (tool.error + \" \") if tool.error else \"\"\n        waiting = len(tool.clicks)\n        done = len(self.calibration.verticals.get(pic, []))\n        if waiting:\n            return prefix + (\"Calage de l'inclinaison, objet {} : cliquez maintenant son sommet, le plus haut \"\n                             \"possible sur la même verticale (zoomez pour être précis).\").format(done + 1)\n        if done == 0:\n            return prefix + (\"Calage de l'inclinaison, objet 1 sur 2 : cliquez le pied d'un objet bien vertical \"\n                             \"(poteau, angle de façade, montant de panneau), au ras du sol, puis son sommet.\")\n        if done == 1:\n            return prefix + (\"1 objet calé : l'inclinaison n'est corrigée qu'en partie. Objet 2 sur 2 : cliquez le \"\n                             \"pied puis le sommet d'un autre objet vertical, à environ 90° du premier dans la \"\n                             \"photo (sur le côté si le premier est devant).\")\n        tilt = self.calibration.tilt(pic) or {}\n        sigma = \" (±{}°)\".format(measures._num(tilt[\"sigma\"], 2)) if tilt.get(\"sigma\") is not None else \"\"\n        return prefix + (\"Inclinaison calée sur {} objets{} : c'est fait pour cette photo. Un objet de plus \"\n                         \"l'affine ; sinon, passez à un mode de mesure.\").format(done, sigma)\n\n    def _rtk_warning(self, sequences):\n        \"\"\"RTK_WARNING si l'une des séquences n'a pas de position RTK vérifiée (vérification\n        terminée), sinon \"\".\"\"\"\n        for sequence in dict.fromkeys(s for s in sequences if s):\n            res = self.precision.known({\"collection\": sequence})\n            if res is not None and not res.get(\"precise\"):\n                return RTK_WARNING\n        return \"\"\n\n    def state(self):\n        \"\"\"État de la photo affichée (dictionnaire) : ligne de qualité, calage, hauteur de caméra\n        proposée, raisons du mode dégradé…\"\"\"\n        item, pic = self.item, (self.item or {}).get(\"id\")\n        candidate = self._edge_b_candidate()\n        lon = lat = None\n        try:\n            lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        except (KeyError, TypeError, ValueError):\n            pass\n        suggestion = precision.camera_suggestion(self.quality) if item else None\n        tilt = tools.tilt_state(self.calibration, pic, bool(pic) and self.tilts.pending(pic))\n        sequence = (item or {}).get(\"collection\")\n        return ({\n            \"quality\": precision.state_text(self.quality, metadata.item_accuracy(item), tilt) if item else \"\",\n            \"computed\": precision.computed_text(self.quality) if item else \"\",  # précision GPS calculée\n            \"calibration\": tools.calibration_text(self.calibration, pic, sequence, lon, lat) if item else \"\",\n            \"camera\": [round(suggestion[0], 2), suggestion[1]] if suggestion else None,\n            \"point\": self.triangulator.result is not None,\n            \"aiming\": self._aiming(),\n            \"point_sel\": self.width_sel is not None or self.ref_sel or (\n                self.mode == \"height\" and self.tool.selected is not None),\n            # bouton « Nouvelle mesure depuis A » : nom du point de référence, ou None\n            \"new_measure\": self.ref_point[\"name\"] if self._locked() else None,\n            # largeur : bouton « Trianguler le point B » proposé (nom provisoire du bord cliqué,\n            # ou None), et triangulation de ce bord en cours\n            \"edge_b\": self._provisional_name(candidate) if candidate is not None else None,\n            \"edge_b_aiming\": self.b_aiming is not None,\n            \"active\": self.active,\n            \"lights\": self._lights(pic) if item else [],\n            \"guide\": self.guide(),\n        })\n\n    # Visées guidées (hauteur, largeur) -----------------------------------------------------\n    def take_frame(self):\n        \"\"\"Points à cadrer dans la vue ([[cap, élévation]] en radians, repère de la photo), une\n        seule fois, quand la photo de référence est affichée après une validation : le point A\n        (point de référence validé), ou la largeur entière (bord opposé triangulé). None sinon,\n        ou tant que la photo affichée n'est pas celle de référence.\"\"\"\n        request = self.frame_request\n        if request is None or not self.item or self.item.get(\"id\") != self.ref_photo:\n            return None\n        self.frame_request = None\n        if request == \"reference\":\n            mark = self._reference_mark() if self.ref_point else None\n            points = mark[\"points\"] if mark else []\n        else:\n            points = self._width_points(request) if request.result else []\n        return [[p[\"yaw\"], p[\"pitch\"]] for p in points if p.get(\"yaw\") is not None] or None\n\n    def take_goto(self):\n        \"\"\"Photo à afficher (identifiant), demandée une seule fois, ou None : la photo de\n        référence, après la validation du point (voir keep_point).\"\"\"\n        goto, self.goto = self.goto, None\n        return goto\n\n    def _neighbour(self, pic, rel):\n        \"\"\"Photo précédente (rel \"prev\") ou suivante (\"next\") de pic dans sa séquence, d'après\n        sa fiche (photo déjà affichée), ou None.\"\"\"\n        item = self.photo_items.get(pic)\n        return metadata.id_from_href(metadata.item_link(item, rel)) if item else None\n\n    def _forward(self):\n        \"\"\"Largeur : le point de référence est-il visé vers l'avant de la séquence (la photo\n        suivante s'en rapproche) ? Comparé au sens de déplacement de la photo de référence.\"\"\"\n        item = self.photo_items.get(self.ref_photo)\n        first = next((s for s in self.triangulator.sightings if s[\"pic\"] == self.ref_photo), None)\n        if item is None or first is None:\n            return True\n        axis = self._axis(item)\n        axis = metadata.item_heading(item) if axis is None else axis\n        return axis is None or math.cos(math.radians(first[\"heading\"] - axis)) >= 0\n\n    def guide(self):\n        \"\"\"Visées guidées du point de référence : {\"reference\" : photo de référence, \"choices\" :\n        [{\"id\", \"label\", \"title\", \"lon\", \"lat\"}]} (photos à proposer pour la visée suivante, avec\n        leur position si elle est connue : l'hôte montre de quel côté de la vue elles sont), ou None.\n\n        Hauteur : la photo précédente et la suivante de la référence ; une fois la deuxième\n        visée faite sur l'une, l'autre pour une troisième, de l'autre côté. Largeur : en\n        avançant vers le point, la photo suivante, puis la suivante encore (les photos d'avant\n        la référence le verraient plus loin, sous des visées presque parallèles). La validation\n        reste manuelle ; les flèches permettent toujours un autre choix.\"\"\"\n        if not (self.active and self.mode in REF_MODES and self._aiming() and self.ref_photo):\n            return None\n        sighted = [s[\"pic\"] for s in self.triangulator.sightings]\n        if self.ref_photo not in sighted:\n            return None\n        ref, others = self.ref_photo, [p for p in sighted if p != self.ref_photo]\n        choices = []\n\n        def offer(pic, label, title):\n            if pic and pic not in sighted:\n                feature = self.photo_items.get(pic) or self.neighbours.get(pic) or {}\n                try:  # position, pour que l'hôte montre de quel côté de la vue elle se trouve\n                    lon, lat = (float(v) for v in feature[\"geometry\"][\"coordinates\"][:2])\n                except (KeyError, TypeError, ValueError):\n                    lon = lat = None\n                choices.append({\"id\": pic, \"label\": label, \"title\": title, \"lon\": lon, \"lat\": lat})\n\n        # Rang des photos autour de la référence (négatif : avant elle dans la séquence), pour\n        # nommer chaque photo proposée par rapport à celle qui est affichée\n        rank = {ref: 0}\n\n        def label(pic, third, fallback):\n            here = rank.get((self.item or {}).get(\"id\"))\n            step = None if here is None or pic not in rank else rank[pic] - here\n            if step in (-1, 1):\n                text = \"photo précédente\" if step < 0 else \"photo suivante\"\n            elif step in (-2, 2):\n                text = \"2 photos en arrière\" if step < 0 else \"2 photos en avant\"\n            else:\n                text = fallback\n            return \"3e visée : \" + text if third else text[0].upper() + text[1:]\n\n        if self.mode == \"height\":\n            prev, nxt = self._neighbour(ref, \"prev\"), self._neighbour(ref, \"next\")\n            rank.update({p: k for p, k in ((prev, -1), (nxt, 1)) if p})\n            if not others:\n                offer(prev, label(prev, False, \"photo précédente\"),\n                      \"Viser le même pied depuis la photo précédente de la séquence\")\n                offer(nxt, label(nxt, False, \"photo suivante\"),\n                      \"Viser le même pied depuis la photo suivante de la séquence\")\n            elif len(others) == 1 and others[0] in (prev, nxt):\n                other = prev if others[0] == nxt else nxt\n                offer(other, label(other, True, \"de l'autre côté de la référence\"),\n                      \"Facultatif : viser aussi le pied de l'autre côté de la photo de référence\")\n        else:\n            rel = \"next\" if self._forward() else \"prev\"\n            sign = 1 if rel == \"next\" else -1\n            first = self._neighbour(ref, rel)\n            second = self._neighbour(first, rel) if first else None\n            rank.update({p: k * sign for p, k in ((first, 1), (second, 2)) if p})\n            if not others:\n                offer(first, label(first, False, \"photo vers le point\"),\n                      \"Viser le même bord depuis la photo qui s'en rapproche\")\n            elif others == [first]:\n                offer(second, label(second, True, \"plus loin vers le point\"),\n                      \"Facultatif : viser encore le même bord, en continuant vers lui\")\n        return {\"reference\": ref, \"choices\": choices}\n\n\n    def _lights(self, pic):\n        \"\"\"Voyants de la visionneuse : [(nom, état)], état « ok », « non » ou « attente ».\"\"\"\n        res = self.quality\n\n        def light(value):\n            return \"attente\" if value is None else (\"ok\" if value else \"non\")\n\n        if self.calibration.tilt(pic):\n            tilt = \"ok\"\n        else:\n            tilt = \"attente\" if self.tilts.pending(pic) else \"non\"\n        return [(\"RTK\", light(res[\"precise\"] if res else None)),\n                (precision.terrain_name(res), light(res[\"lidar\"] if res else None)),\n                (\"Inclinaison\", tilt)]\n\n    def viewer_marks(self):\n        \"\"\"Repères de la photo affichée (liste) : pour chaque mesure, points (cap et élévation\n        dans le repère de la photo, radians), libellé, point sélectionné.\"\"\"\n        pic = (self.item or {}).get(\"id\")\n        # Hauteurs et largeurs : visibles depuis toutes les photos (voir _height_points, _width_points)\n        marks = [self.tool._marks(m) for m in self.tool.done\n                 if not isinstance(m, widths.PerpendicularWidth) and not (m.kind == \"height\" and m.result)]\n        if self.item:\n            # Hauteurs et largeurs : étiquette au point d'arrivée (sommet, bord), avec son nom\n            # (« end », provisoire ou non) et les noms des deux bouts (« names »)\n            for m in self._heights():\n                end = self._end_name(m)\n                marks.append({\"points\": [dict(p, pic=pic, sel=self.tool.selected == (m, k))\n                                         for k, p in enumerate(self._height_points(m))],\n                              \"label\": m.label(), \"beside\": True, \"end\": end,\n                              \"names\": [n for n in [(m.reference or {}).get(\"name\"), end and end[\"name\"]] if n]})\n            for m in self._widths():\n                end = self._end_name(m)\n                marks.append({\"points\": [dict(p, pic=pic, sel=self.width_sel == (m, k))\n                                         for k, p in enumerate(self._width_points(m))],\n                              \"label\": m.label(), \"beside\": False, \"end\": end,\n                              \"names\": [n for n in [m.edge.get(\"name\"), end and end[\"name\"]] if n]})\n        if self.item:  # mesure libre : points gardés et distances, depuis toutes les photos\n            marks += self._free_marks()\n        if self.active and self._aiming():  # visées faites depuis cette photo\n            marks = marks + [{\"points\": [{\"pic\": s[\"pic\"], \"yaw\": s[\"view\"][0], \"pitch\": s[\"view\"][1]}\n                                         for s in self.triangulator.sightings if \"view\" in s], \"sighting\": True}]\n        elif self.active and self.mode in GROUND_MODES:  # mesure ou calage en cours\n            marks = marks + [self.tool.viewer_marks()]\n        elif self.active and self.mode in CALIBRATION_MODES:\n            marks = marks + [self.calibrator.viewer_marks()]\n        if self.active and self.mode in REF_MODES and self.ref_point and self.item:\n            marks = marks + [m for m in [self._reference_mark()] if m]\n        if self.item:  # noms des points triangulés (A, B…) à côté de leur croix\n            marks = marks + self._name_marks(marks)\n        road = (self.ref_point or {}).get(\"road\") if self.active and self.mode == \"road\" else None\n        if road and self.item:  # en premier : dessinée sous les traits rouges des largeurs\n            marks = [self._guide_mark(road)] + marks\n        if self.active and self.mode == \"height\" and self.ref_point and self.item:  # de même\n            marks = [self._vertical_mark()] + marks\n        if self.active and self.item and self._aiming() and self.mode in (\"road\", \"tri\"):\n            # Visées faites depuis les autres photos, tracées dans celle-ci : l'objet visé est sur\n            # leur trait (ligne épipolaire), ce qui fixe la profondeur de la visée suivante\n            marks = [self._epipolar_mark(s) for s in self.triangulator.sightings if s[\"pic\"] != pic] + marks\n        if self.b_aiming is not None and pic != self.ref_photo:\n            # Bord opposé visé depuis une autre photo que celle de la mesure : seulement les\n            # visées ; droite, largeurs et point de référence reviennent sur la photo de la mesure\n            marks = [m for m in marks if m.get(\"sighting\") or m.get(\"epipolar\")]\n        out = []\n        for m in marks:\n            points = [p for p in m[\"points\"] if p.get(\"pic\") == pic and p.get(\"yaw\") is not None]\n            if points:\n                out.append({\"points\": [[p[\"yaw\"], p[\"pitch\"], bool(p.get(\"sel\"))] for p in points],\n                            \"label\": m.get(\"label\", \"\"), \"beside\": m.get(\"beside\", False),\n                            \"sighting\": m.get(\"sighting\", False), \"guide\": m.get(\"guide\", False),\n                            \"vertical\": m.get(\"vertical\", False), \"name\": m.get(\"name\", False),\n                            \"epipolar\": m.get(\"epipolar\", False),\n                            \"side\": m.get(\"side\", \"\"), \"provisional\": m.get(\"provisional\", False),\n                            \"end\": m.get(\"end\"), \"names\": m.get(\"names\", [])})\n        return out\n\n    def focus(self):\n        \"\"\"Points à montrer ensemble sur la carte ([[lon, lat]]) pendant une mesure :\n        photo affichée, photos des visées en cours et leur point, point de référence de la\n        hauteur, mesure en cours ou dernière terminée (points et photos).\"\"\"\n        if not self.active or self.mode in CALIBRATION_MODES:\n            return []\n        if self.mode == \"tri\" and not self.triangulator.sightings and self.links:\n            i, j, _ = self.links[-1]  # mesure libre : distance qui vient d'être calculée, seule\n            return [list(self.points[i][:2]), list(self.points[j][:2]), \"segment\"]\n        pts = []\n        try:\n            pts.append([float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2]])\n        except (KeyError, TypeError, ValueError):\n            pass\n        pts += [[s[\"lon\"], s[\"lat\"]] for s in self.triangulator.sightings]\n        if self.triangulator.result:\n            pts.append([self.triangulator.result[\"lon\"], self.triangulator.result[\"lat\"]])\n        if self.mode in REF_MODES and self.ref_point:\n            pts.append([self.ref_point[\"lon\"], self.ref_point[\"lat\"]])\n        if self.mode in GROUND_MODES:\n            m = self.tool.current or (self.tool.done[-1] if self.tool.done else None)\n            if m is not None and m.result:\n                pts += [list(p) for p in m.result[\"picks\"]] + [[c[\"lon\"], c[\"lat\"]] for c in m.clicks]\n        return pts\n\n    def _vertical_mark(self):\n        \"\"\"Hauteur : verticale vraie passant par le point de référence, dans la photo affichée\n        (repère de la visionneuse, tracé vert) : depuis la croix du pied (là où il a été visé\n        depuis cette photo, sinon projeté au sol) jusqu'à VERTICAL_LENGTH m au-dessus. Tracée\n        dans le monde puis ramenée dans la photo par le calage (inclinaison, cap) : sur une photo\n        penchée et calée, elle suit les objets verticaux et non le bord de l'image.\"\"\"\n        item, cal = self.item, self.calibration\n        pic, sequence = item.get(\"id\"), item.get(\"collection\")\n        lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        heading = self._heading()\n        view = self._ref_view(pic)\n        if view is None:\n            p = self._project(self.ref_point[\"lon\"], self.ref_point[\"lat\"])\n            view = [p[\"yaw\"], p[\"pitch\"]]\n        # Pied dans le monde : cap et élévation vrais ; la verticale garde ce cap\n        bearing, elev = cal.correct(pic, sequence, (math.degrees(view[0]) + heading) % 360,\n                                    math.degrees(view[1]), lon, lat)\n        d = self._ref_distance()\n        z0 = d * math.tan(math.radians(max(-89.0, min(89.0, elev))))\n        points = []\n        for k in range(25):\n            e = math.degrees(math.atan2(z0 + k * VERTICAL_LENGTH / 24, d))\n            yaw, pitch = cal.uncorrect(pic, sequence, bearing, e, lon, lat)\n            points.append({\"pic\": pic, \"yaw\": math.radians((yaw - heading + 540) % 360 - 180),\n                           \"pitch\": math.radians(pitch)})\n        return {\"points\": points, \"guide\": True, \"vertical\": True}\n\n    def _epipolar_mark(self, s):\n        \"\"\"Visée s, faite depuis une autre photo, tracée dans la photo affichée : sa demi-droite\n        dans l'espace (cap et inclinaison corrigés du calage, caméras à la hauteur de celle de la\n        photo affichée au-dessus d'un sol plat), de 0,5 m jusqu'un peu au-delà du sol qu'elle\n        touche (80 m au plus). L'objet visé est sur ce trait.\"\"\"\n        lon, lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n        height = self._camera_height()\n        sx, sy = triangulation._local(s[\"lon\"], s[\"lat\"], lon, lat)\n        a, e = math.radians(s[\"heading\"]), math.radians(s.get(\"elev\") or 0.0)\n        reach = 80.0 if e >= -0.002 else min(80.0, height / -math.tan(e) * 1.2 + 1.0)\n        points = []\n        for k in range(41):  # 41 points : reprojetés par la visionneuse à chaque image\n            t = 0.5 * (reach / 0.5) ** (k / 40)  # pas plus serrés près de la caméra de la visée\n            x, y = sx + t * math.sin(a), sy + t * math.cos(a)\n            z = t * math.tan(e)  # hauteur par rapport aux caméras\n            d = math.hypot(x, y)\n            if d < 0.5:\n                continue\n            view = self._view_of(math.degrees(math.atan2(x, y)), math.degrees(math.atan2(z, d)))\n            points.append({\"pic\": self.item.get(\"id\"), \"yaw\": view[\"yaw\"], \"pitch\": view[\"pitch\"]})\n        return {\"points\": points, \"guide\": True, \"epipolar\": True}\n\n    def _guide_mark(self, road):\n        \"\"\"Droite de mesure de la largeur dans la photo affichée (repère de la visionneuse) :\n        points au sol supposé plat, à la hauteur de caméra de la photo, calage compris (comme\n        la croix du point de référence, voir _project) ; sur une photo de la visée de A, par la\n        croix de cette visée (voir _aim_anchor). La mesure n'en dépend pas.\"\"\"\n        lon, lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n        ux, uy = widths.perpendicular(road[\"axis\"])\n        anchor = self._aim_anchor()\n        if anchor:  # photo de la visée de A : droite passant par la croix bleue, au sol visé\n            (ax, ay), height = anchor[1], anchor[2]\n        else:\n            height = self._camera_height()\n            ax, ay = triangulation._local(self.ref_point[\"lon\"], self.ref_point[\"lat\"], lon, lat)\n        points = []\n        for k in range(-20, 21):  # 41 points : reprojetés par la visionneuse à chaque image\n            t = k * widths.GUIDE_LENGTH / 20\n            x, y = ax + t * ux, ay + t * uy\n            d = math.hypot(x, y)\n            if d < 1.0:\n                continue\n            view = self._view_of(math.degrees(math.atan2(x, y)), -math.degrees(math.atan2(height, d)))\n            points.append({\"pic\": self.item.get(\"id\"), \"yaw\": view[\"yaw\"], \"pitch\": view[\"pitch\"]})\n        return {\"points\": points, \"guide\": True}\n\n    def handles(self):\n        \"\"\"Poignées déplaçables sur la carte : [[lon, lat]], repérées par leur rang pour\n        move_handle. Seulement en mesure, comme dans le plugin.\"\"\"\n        handles = self.tool.handles() if self.active and self.mode in GROUND_MODES else []\n        self._handles = [key for key, _, _ in handles]\n        return [[lon, lat] for _, lon, lat in handles]\n\n    def results(self):\n        \"\"\"Mesures terminées et points gardés, pour la liste des résultats de l'hôte.\"\"\"\n        out = [{\"id\": id(m), \"kind\": \"mesure\", \"text\": m.label(), \"comment\": getattr(m, \"comment\", \"\")}\n               for m in self.tool.measures() if m.result]\n        out += [{\"id\": i, \"kind\": \"point\", \"text\": \"Point {} ±{} m\".format(\n                    v[\"nom\"], measures._num(v[\"incert_m\"], 2)), \"comment\": v.get(\"commentaire\", \"\")}\n                for i, (_, _, v) in enumerate(self.points)]\n        out += [{\"id\": k, \"kind\": \"distance\", \"text\": \"↔ {}–{} : {} m ± {} m\".format(\n                    self.points[i][2][\"nom\"], self.points[j][2][\"nom\"], measures._num(v[\"valeur_m\"], 2),\n                    measures._num(v[\"incert_m\"], 2)), \"comment\": v.get(\"commentaire\", \"\")}\n                for k, (i, j, v) in enumerate(self.links)]\n        return out\n\n    def delete_result(self, kind, ident):\n        \"\"\"Efface un résultat de la liste : mesure (et son dessin), point triangulé (et les\n        distances qui le relient ; les autres gardent leur nom) ou distance.\"\"\"\n        if kind == \"mesure\":\n            tool = self.tool\n            for m in tool.measures():\n                if id(m) == ident:\n                    if tool.selected is not None and tool.selected[0] is m:\n                        tool.selected = None\n                    m.remove()\n                    if m is tool.current:\n                        tool.current = None\n                    else:\n                        tool.done.remove(m)\n                    self.message = \"Mesure effacée.\"\n                    self.width_sel = None  # point d'une mesure effacée : plus de sélection\n                    break\n        elif kind == \"point\" and 0 <= ident < len(self.points):\n            name = self.points[ident][2][\"nom\"]\n            self.last_free = None if self.last_free == ident else (\n                None if self.last_free is None else self.last_free - (self.last_free > ident))\n            before = [i for i, j, _ in self.links if j == ident]\n            after = [j for i, j, _ in self.links if i == ident]\n            del self.points[ident]\n            shift = lambda k: k - (k > ident)  # noqa: E731\n            self.links = [(shift(i), shift(j), v) for i, j, v in self.links if ident not in (i, j)]\n            self.message = \"Point {} effacé.\".format(name)\n            # Point au milieu d'une chaîne (A–B–C, B effacé) : la distance A–C est proposée\n            if before and after and not any({i, j} == {shift(before[0]), shift(after[0])} for i, j, _ in self.links):\n                self.proposal = (shift(before[0]), shift(after[0]))\n        elif kind == \"distance\" and 0 <= ident < len(self.links):\n            del self.links[ident]\n            self.message = \"Distance effacée.\"\n        return self.status()\n\n    def take_rtk_alert(self):\n        \"\"\"RTK_ALERT à afficher en fenêtre d'avertissement, une seule fois par séquence : mesure\n        activée sur une photo dont la vérification a conclu à l'absence de position RTK ; None\n        sinon (vérification en cours ou sans conclusion, RTK vérifié, séquence déjà signalée,\n        mesure désactivée).\"\"\"\n        res, item = self.quality, self.item or {}\n        if not self.active or res is None or res.get(\"precise\") or res.get(\"transient\"):\n            return None  # transient : service en panne pendant la vérification, pas de conclusion\n        sequence = item.get(\"collection\") or item.get(\"id\")\n        if sequence in self.rtk_alerted:\n            return None\n        self.rtk_alerted.add(sequence)\n        return RTK_ALERT\n\n    def take_bridge_alert(self):\n        \"\"\"Proposition à afficher en fenêtre, en mesure, d'après la BD TOPO (roads.on_bridge) :\n        {\"check\": True, \"text\": BRIDGE_ALERT} (réponse oui : set_bridge(True)) sur une photo prise\n        sur un pont, case « Sur un pont » décochée, pont pas encore proposé (à BRIDGE_ASKED_RADIUS m\n        près) ; {\"check\": False, \"text\": BRIDGE_LEFT_ALERT} (réponse oui : leave_bridge()) case\n        cochée, sur une photo à plus de roads.BRIDGE_LEFT m de tout tronçon en pont (les photos\n        d'approche visent encore le tablier), une fois par sortie ; None sinon. Pendant la lecture\n        des tronçons : None, et notify() à leur arrivée pour redemander.\"\"\"\n        item = self.item or {}\n        if not self.active or not item or (self.bridge and self.bridge_left_asked):\n            return None\n        try:\n            lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        except (KeyError, TypeError, ValueError):\n            return None\n        if self.bridge:\n            sec = self.roads.bridge(lon, lat, None, roads.BRIDGE_LEFT)\n            self._bridge_waiting = sec is roads.PENDING\n            if sec is not False:  # sur un pont ou tout près, lecture en cours, BD TOPO injoignable\n                return None\n            self.bridge_left_asked = True\n            return {\"check\": False, \"text\": BRIDGE_LEFT_ALERT}\n        if any(tools._metres(p, (lon, lat)) < BRIDGE_ASKED_RADIUS for p in self.bridge_asked):\n            return None\n        axis = self._axis(item)\n        sec = self.roads.bridge(lon, lat, metadata.item_heading(item) if axis is None else axis)\n        self._bridge_waiting = sec is roads.PENDING\n        if not sec or sec is roads.PENDING:\n            return None\n        self.bridge_asked.append((lon, lat))\n        return {\"check\": True, \"text\": BRIDGE_ALERT.format(\" ({})\".format(sec[\"name\"]) if sec.get(\"name\") else \"\")}\n\n    def leave_bridge(self):\n        \"\"\"Sortie du pont acceptée : case décochée, et les ponts déjà proposés pourront l'être de\n        nouveau (on peut y revenir).\"\"\"\n        self.bridge_asked = []\n        return self.set_bridge(False)\n\n    def take_proposal(self):\n        \"\"\"Distance proposée après un effacement ([n°, n°, « A », « C »] ou None), une\n        seule fois.\"\"\"\n        p, self.proposal = self.proposal, None\n        if p is None or max(p) >= len(self.points):\n            return None\n        return [p[0], p[1], self.points[p[0]][2][\"nom\"], self.points[p[1]][2][\"nom\"]]\n\n    def link_points(self, i, j):\n        \"\"\"Distance entre deux points gardés, à la demande (voir take_proposal).\"\"\"\n        if 0 <= i < len(self.points) and 0 <= j < len(self.points) and i != j:\n            self.message = self._link(int(i), int(j))\n        return self.status()\n\n    def set_comment(self, kind, ident, text):\n        \"\"\"Commentaire d'une mesure ou d'un point gardé (champ « commentaire » de l'export).\"\"\"\n        if kind == \"point\":\n            if 0 <= ident < len(self.points):\n                self.points[ident][2][\"commentaire\"] = text\n            return\n        if kind == \"distance\":\n            if 0 <= ident < len(self.links):\n                self.links[ident][2][\"commentaire\"] = text\n            return\n        for m in self.tool.measures():  # rangé sur la mesure : effacée, son commentaire disparaît avec elle\n            if id(m) == ident:\n                m.comment = text\n\n    def has_results(self):\n        return bool(self.points) or bool(self.links) or any(m.result for m in self.tool.measures())\n\n\ndef _point_name(n):\n    \"\"\"Nom du n-ième point gardé (0 : A) : A … Z, puis AA, AB…, comme les colonnes d'un tableur.\"\"\"\n    name = \"\"\n    n += 1\n    while n:\n        n, r = divmod(n - 1, 26)\n        name = chr(65 + r) + name\n    return name\n\n\nON_LINE = math.radians(0.5)  # écart au trait d'une mesure en deçà duquel un nom serait dessus\n\n\ndef _beside_line(p, lines):\n    \"\"\"Côté du nom de la croix p quand elle est à l'intérieur d'un des traits lines ([(début,\n    fin)], repères {yaw, pitch}) : « right » pour un trait plutôt vertical, « below » pour un\n    trait plutôt horizontal ; None si elle n'est sur aucun (ou à un de leurs bouts).\"\"\"\n    if p.get(\"yaw\") is None:\n        return None\n    k = math.cos(p[\"pitch\"])\n    for a, b in lines:\n        ax = ((a[\"yaw\"] - p[\"yaw\"] + math.pi) % (2 * math.pi) - math.pi) * k\n        bx = ((b[\"yaw\"] - p[\"yaw\"] + math.pi) % (2 * math.pi) - math.pi) * k\n        ay, by = a[\"pitch\"] - p[\"pitch\"], b[\"pitch\"] - p[\"pitch\"]\n        dx, dy = bx - ax, by - ay\n        length2 = dx * dx + dy * dy\n        if length2 < ON_LINE ** 2:\n            continue\n        t = -(ax * dx + ay * dy) / length2  # position de p le long du trait (0 : début, 1 : fin)\n        ends = ON_LINE / math.sqrt(length2)\n        if ends < t < 1 - ends and abs(ax * dy - ay * dx) / math.sqrt(length2) < ON_LINE:\n            return \"right\" if abs(dy) > abs(dx) else \"below\"\n    return None\n\n\ndef _away(p, other):\n    \"\"\"Côté de la croix p opposé au point other (repères {yaw, pitch} de la photo, radians) :\n    « left », « right », « above » ou « below » ; « below » sans other.\"\"\"\n    if other is None or other.get(\"yaw\") is None or p.get(\"yaw\") is None:\n        return \"below\"\n    dyaw = ((p[\"yaw\"] - other[\"yaw\"] + math.pi) % (2 * math.pi) - math.pi) * math.cos(p[\"pitch\"])\n    dpitch = p[\"pitch\"] - other[\"pitch\"]\n    if abs(dyaw) >= abs(dpitch):\n        return \"right\" if dyaw > 0 else \"left\"  # le cap croît vers la droite de l'écran\n    return \"above\" if dpitch > 0 else \"below\"\n",
 "core/tools.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Outils de mesure, hors MeasureTool\n(voir measures.py) :\n\n- photo_click : clic dans la photo affichée, converti en direction corrigée du calage,\n  avec la position (recalée), sa précision et l'axe de la route ;\n- Triangulator : visées d'un objet depuis plusieurs photos ;\n- CalibrationTool : clics de calage (inclinaison, cap et position, hauteur de caméra) ;\n- calibration_text, tilt_state : textes du calage et de l'inclinaison de la photo.\n\nLe dessin sur la carte vient de l'hôte (new_item), comme pour MeasureTool.\n\"\"\"\n\nimport math\nfrom datetime import datetime\n\nfrom . import host, metadata, precision, triangulation\nfrom .calibration import REACH, CalibrationError\nfrom .measures import NullItem, _num\n\nLONE_RAY = 60.0  # longueur (m) d'une visée tant qu'elle n'en croise aucune autre\n\n\ndef photo_click(item, yaw, elev, cal, quality=None, pos=None, axis=None):\n    \"\"\"Clic dans la photo `item` (fiche STAC) : direction brute yaw/elev (degrés, cap absolu),\n    corrigée du calage `cal`. quality : vérification de la précision de la photo (voir\n    precision.PrecisionChecker), ou None ; pos : position du clic dans le repère de la photo\n    (radians, visionneuse web) ; axis : axe de la séquence (voir metadata.sequence_axis), à\n    défaut l'orientation de la photo. Retourne le clic (dict) ou None sans position.\"\"\"\n    try:\n        lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n    except (KeyError, TypeError, ValueError):\n        return None\n    axis_source = \"séquence\"\n    if axis is None:\n        axis, axis_source = metadata.item_heading(item), \"orientation de la photo\"\n    pic, sequence = item.get(\"id\", \"\"), item.get(\"collection\")\n    cyaw, celev = cal.correct(pic, sequence, float(yaw), float(elev), lon, lat)\n    accuracy = _accuracy(item, quality)\n    fixed = cal.position(sequence, lon, lat)  # position recalée par les repères de la séquence\n    clon, clat, caccuracy = fixed if fixed else (lon, lat, accuracy)\n    tilt = cal.tilt(pic)\n    return {\"pic\": pic, \"lon\": clon, \"lat\": clat,\n            \"gps\": [lon, lat], \"gps_accuracy\": accuracy,\n            \"yaw\": cyaw, \"elev\": celev, \"raw\": [float(yaw) % 360, float(elev)],\n            \"sequence\": sequence, \"accuracy\": caccuracy,\n            \"precise\": metadata.precise_heading(item) is not None,\n            \"elev_error\": tilt[\"sigma\"] if tilt else None,\n            \"axis\": axis, \"axis_source\": axis_source, \"pos\": pos}\n\n\ndef photo_sighting(item, heading, pitch, cal, quality=None):\n    \"\"\"Visée de triangulation depuis la photo `item` : cap brut du centre de la vue (degrés,\n    cap précis de la photo compris) et son inclinaison, corrigés du calage. Retourne la visée\n    (dict, voir triangulation.solve) ou None sans position. Position vérifiée précise (quality)\n    : aussi l'altitude NGF de la caméra (\"alt\") et, si le LiDAR HD a donné le sol sous la photo,\n    l'altitude de ce sol (\"ground\"), pour la triangulation en 3D (voir triangulation.solve3d).\"\"\"\n    try:\n        lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n    except (KeyError, TypeError, ValueError):\n        return None\n    pic, sequence = item.get(\"id\", \"\"), item.get(\"collection\")\n    heading_raw = heading\n    heading, elev = cal.correct(pic, sequence, float(heading), float(pitch), lon, lat)\n    fixed = cal.position(sequence, lon, lat)\n    clon, clat, accuracy = fixed if fixed else (lon, lat, _accuracy(item, quality))\n    alt = ground = spread = None\n    if quality and quality[\"precise\"]:\n        alt = host.ngf_altitude(lon, lat, metadata.item_altitude(item))\n        if alt is not None and quality.get(\"lidar\") is True and quality.get(\"height\") is not None:\n            ground = alt - quality[\"height\"]  # hauteur de caméra médiane de la séquence\n            spread = quality.get(\"spread\")  # sa dispersion d'une photo à l'autre\n    tilt = cal.tilt(pic)\n    return {\"pic\": pic, \"sequence\": sequence, \"lon\": clon, \"lat\": clat, \"heading\": heading,\n            \"accuracy\": accuracy, \"precise\": metadata.precise_heading(item) is not None,\n            \"heading_error\": cal.heading_error(sequence, lon, lat),\n            \"elev\": elev, \"alt\": alt, \"ground\": ground, \"ground_spread\": spread,\n            \"elev_error\": tilt[\"sigma\"] if tilt else None,\n            \"raw\": [float(heading_raw) % 360, float(pitch)], \"gps\": [lon, lat]}\n\n\ndef _accuracy(item, quality):\n    \"\"\"Précision de la position de la photo : vérifiée (quality), sinon celle des métadonnées.\"\"\"\n    if quality and quality[\"precise\"] and quality[\"accuracy\"] is not None:\n        return quality[\"accuracy\"]\n    return metadata.item_accuracy(item)\n\n\ndef tilt_state(cal, pic, pending=False):\n    \"\"\"(texte, manquante) : inclinaison de la photo pic, pour la ligne d'état (voir\n    precision.state_text). pending : inclinaison automatique en cours de calcul.\"\"\"\n    tilt = cal.tilt(pic) if pic else None\n    if tilt:\n        if tilt[\"source\"] == \"clics\":\n            return \"inclinaison calée à la main\", False\n        if tilt[\"source\"].startswith(\"clics + \"):\n            return \"inclinaison calée à la main et automatiquement (±{:.1f}°)\".format(\n                max(tilt[\"sigma\"], 0.1)).replace(\".\", \",\"), False\n        how = \"verticales de la photo\" if tilt[\"source\"] == \"verticales\" else \"pente et dévers du terrain IGN\"\n        return \"inclinaison calée ({}, ±{:.1f}°)\".format(how, max(tilt[\"sigma\"], 0.1)).replace(\".\", \",\"), False\n    if pending:\n        return \"inclinaison en cours de calcul…\", False\n    return \"inclinaison non calée\", True\n\n\ndef calibration_text(cal, pic, sequence, lon, lat):\n    \"\"\"Calage de la photo et de la séquence affichées (texte, vide sans calage).\"\"\"\n    parts = []\n    tilt = cal.tilt(pic) if pic else None\n    if tilt and tilt.get(\"source\", \"clics\") == \"clics\":\n        parts.append(\"inclinaison {:.1f}° corrigée{} ({} objet{})\".format(\n            tilt[\"tilt\"], \" en partie\" if tilt[\"partial\"] else \"\", tilt[\"count\"],\n            \"s\" if tilt[\"count\"] > 1 else \"\").replace(\".\", \",\"))\n    elif tilt and tilt[\"source\"].startswith(\"clics + \"):\n        parts.append(\"inclinaison {:.1f}° corrigée ({} objet{} cliqué{}, complété{} par {}, ±{:.1f}°)\".format(\n            tilt[\"tilt\"], tilt[\"count\"], *((\"s\", \"s\", \"s\") if tilt[\"count\"] > 1 else (\"\", \"\", \"\")),\n            \"les verticales de la photo\" if tilt[\"source\"].endswith(\"verticales\") else \"le terrain IGN\",\n            max(tilt[\"sigma\"], 0.1)).replace(\".\", \",\"))\n    elif tilt and tilt[\"source\"] == \"verticales\":\n        parts.append(\"inclinaison {:.1f}° corrigée automatiquement ({} verticales de la photo, ±{:.1f}°)\".format(\n            tilt[\"tilt\"], tilt[\"count\"], max(tilt[\"sigma\"], 0.1)).replace(\".\", \",\"))\n    elif tilt:\n        parts.append(\"inclinaison {:.1f}° estimée par la pente et le dévers du terrain IGN (±{:.1f}°, modèle vérifié \"\n                     \"sur {} photos de la séquence)\".format(tilt[\"tilt\"], tilt[\"sigma\"], tilt[\"count\"]).replace(\".\", \",\"))\n    camera = cal.camera(sequence) if sequence else None\n    if camera:\n        text = \"caméra à {:.2f} m (±{:.2f} m, {} référence{})\".format(\n            camera[\"height\"], camera[\"sigma\"], camera[\"count\"], \"s\" if camera[\"count\"] > 1 else \"\").replace(\".\", \",\")\n        if camera.get(\"legacy\"):\n            text += (\", dont {} d'une version précédente, sans l'inclinaison automatique : refaites le calage\"\n                     .format(camera[\"legacy\"]))\n        parts.append(text)\n    pose = cal.pose(sequence, lon, lat) if sequence else None\n    if pose:\n        text = \"cap {:+.2f}° (±{:.2f}°)\".format(pose[\"offset\"], pose[\"sigma\"])\n        if pose[\"positioned\"]:\n            sx, sy = pose[\"shift\"]\n            text += \", position décalée de {:.2f} m vers {:.0f}° (±{:.2f} m)\".format(\n                math.hypot(sx, sy), math.degrees(math.atan2(sx, sy)) % 360, pose[\"shift_sigma\"])\n        text += \" · {} repère{}\".format(pose[\"count\"], \"s\" if pose[\"count\"] > 1 else \"\")\n        if pose[\"count\"] > 3:\n            text += \", écart {:.2f}°\".format(pose[\"residual\"])\n        parts.append(text.replace(\".\", \",\"))\n    elif sequence and cal.landmarks.get(sequence):\n        parts.append(\"recalage de la séquence hors de portée (photo à plus de {:.0f} m des repères)\".format(\n            REACH))\n    return \"Calage : \" + \" · \".join(parts) if parts else \"\"\n\n\nGROUND_REUSE = 1.0  # m : altitude LiDAR lue gardée tant que le point en reste à moins de cette distance\nGROUND_ASKS = 3  # lectures successives au plus pour un même jeu de visées\n\n\ndef _metres(a, b):\n    \"\"\"Distance (m) entre deux (lon, lat).\"\"\"\n    return math.hypot(*triangulation._local(b[0], b[1], a[0], a[1]))\n\n\ndef solve_on_ground(sightings, ground, ground_z):\n    \"\"\"triangulation.solve, avec l'altitude du sol lue au point ground_z (lon, lat, z, incertitude\n    en m, source : « LiDAR HD » ou « RGE ALTI » ; (lon, lat, z) : LiDAR HD) si elle l'a été à moins\n    de GROUND_REUSE m du point trouvé avec le sol tiré des photos ou de celui qu'elle donne : une\n    altitude lue ailleurs, avant un changement des visées, ne sert pas. Le second cas fait\n    converger les relectures (tools.Triangulator._ask_ground) : un sol qui déplace le point de\n    plus de GROUND_REUSE m, relu à sa nouvelle position, resservait sinon une fois sur deux (le\n    point allait et venait). Le résultat dit sa source (\"ground_name\").\"\"\"\n    r = triangulation.solve(sightings, ground)\n    if not (ground and ground_z and r[\"method\"] == \"3d\"):\n        return r\n    z = (ground_z[2], ground_z[3]) if len(ground_z) > 3 else ground_z[2]\n    on = triangulation.solve(sightings, ground, z)\n    if min(_metres(ground_z[:2], (p[\"lon\"], p[\"lat\"])) for p in (r, on)) >= GROUND_REUSE:\n        return r\n    on[\"ground_name\"] = ground_z[4] if len(ground_z) > 4 else precision.TERRAINS[0][0]\n    return on\n\n\nclass Triangulator:\n    \"\"\"Visées en cours et point d'intersection. Le dessin des visées sur la carte vient de\n    l'hôte (new_item), l'enregistrement aussi (attributes donne les valeurs).\"\"\"\n\n    # Consignes de visée (reprises du plugin, réticule et bouton « Viser ») ; dans la page, un clic sur l'objet\n    AIM = \"Placez le réticule sur l'objet puis « Viser »\"\n    AIM_AGAIN = \"visez le même objet puis « Viser » à nouveau\"\n\n    def __init__(self):\n        self.sightings = []  # dicts : pic, lon, lat, heading, accuracy, precise (voir photo_sighting)\n        self.ground = False  # point visé au sol (bord de chaussée, pied) : voir triangulation.solve\n        self.result = None\n        self.error = None\n        self.item = None\n        # Point au sol en 3D : altitude du sol lue à sa position, (lon, lat, z, incertitude, source)\n        # ou None. ground_lookup(lon, lat, done(z ou None, incertitude, source)) est fourni par\n        # l'hôte (session) ; ground_changed()\n        # est appelé quand elle arrive après coup et a déplacé le point.\n        self.ground_z = None\n        self.ground_lookup = None\n        self.ground_changed = lambda: None\n        self._ground_ticket = None\n        self.across = lambda: None  # direction en travers de la route (est, nord) quand un bord est visé, ou None\n        self.lidar = True  # False sur un pont : sol tiré des photos (voir session.Session.set_bridge)\n\n    def new_item(self):\n        \"\"\"Dessin des visées et du point sur la carte : set_data(visées [(lon, lat, lon, lat)],\n        point (lon, lat) ou None), remove(). Remplacé par l'hôte.\"\"\"\n        return NullItem()\n\n    # ------------------------------------------------------------------\n    def add(self, sighting):\n        \"\"\"Ajoute une visée (remplace celle déjà faite depuis la même photo).\"\"\"\n        self.sightings = [s for s in self.sightings if s[\"pic\"] != sighting[\"pic\"]] + [sighting]\n        self._compute()\n        return self.status()\n\n    def clear(self):\n        self.sightings, self.result, self.error = [], None, None\n        self.ground_z, self._ground_ticket = None, None\n        self._draw()\n\n    def recompute(self):\n        \"\"\"Point recalculé après un changement des visées (calage ou précision arrivés après\n        coup, voir session.Session._recompute).\"\"\"\n        self._compute()\n\n    def remove(self):\n        if self.item is not None:\n            self.item.remove()\n            self.item = None\n\n    def _compute(self, asks=0):\n        self.result, self.error = None, None\n        if len(self.sightings) >= 2:\n            try:\n                self.result = solve_on_ground(self.sightings, self.ground, self.ground_z if self.lidar else None)\n            except triangulation.TriangulationError as exc:\n                self.error = str(exc)\n        self._draw()\n        self._ask_ground(asks)\n\n    def _ask_ground(self, asks=0):\n        \"\"\"Point au sol trouvé en 3D : altitude du MNT LiDAR HD lue à sa position (sauf si elle\n        l'a déjà été à moins de GROUND_REUSE m), puis point recalculé avec elle. Relue si le\n        point s'est encore déplacé, au plus GROUND_ASKS fois de suite.\"\"\"\n        r = self.result\n        if not (self.ground and self.lidar and r and r[\"method\"] == \"3d\" and self.ground_lookup) \\\n                or asks >= GROUND_ASKS:\n            return\n        if self.ground_z and _metres(self.ground_z[:2], (r[\"lon\"], r[\"lat\"])) < GROUND_REUSE:\n            return\n        ticket = self._ground_ticket = object()\n        lon, lat = r[\"lon\"], r[\"lat\"]\n\n        def got(z, sigma=triangulation.LIDAR_ERROR, source=precision.TERRAINS[0][0]):\n            if ticket is not self._ground_ticket or z is None:\n                return  # visées changées entre-temps, ou pas de modèle de terrain ici\n            self.ground_z = (lon, lat, z, sigma, source)\n            self._compute(asks + 1)\n            self.ground_changed()\n\n        self.ground_lookup(lon, lat, got)\n\n    def _draw(self):\n        if self.item is None:\n            if not self.sightings:\n                return\n            self.item = self.new_item()\n        rays = []\n        for i, s in enumerate(self.sightings):\n            length = self.result[\"distances\"][i] * 1.15 + 3 if self.result else LONE_RAY\n            end = triangulation.offset(s[\"lon\"], s[\"lat\"], s[\"heading\"], length)\n            rays.append((s[\"lon\"], s[\"lat\"]) + end)\n        self.item.set_data(rays, (self.result[\"lon\"], self.result[\"lat\"]) if self.result else None)\n\n    # ------------------------------------------------------------------\n    def status(self):\n        n = len(self.sightings)\n        if n == 0:\n            return \"{}. Recommencez depuis une autre photo, sur le côté de l'objet.\".format(self.AIM)\n        if n == 1:\n            return \"1 visée. Changez de photo, {}.\".format(self.AIM_AGAIN)\n        if self.error:\n            return \"{} visées : {}\".format(n, self.error)\n        r = self.result\n        text = \"{} visées : point à {} m · croisement {}° · incertitude ±{} m\".format(\n            n, \" / \".join(_num(d) for d in r[\"distances\"]), _num(r[\"angle\"], 0), _num(r[\"uncertainty\"]))\n        if n > 2:\n            text += \" · écart des visées {} m\".format(_num(r[\"rms\"]))\n            if r[\"spread\"] > triangulation.SPREAD_WARNING:\n                text += (\" ⚠ Une visée s'écarte nettement des autres : elle vise peut-être un autre objet (un \"\n                         \"poteau voisin, par exemple). Revisez-la depuis sa photo : la nouvelle visée remplace \"\n                         \"l'ancienne\")\n        across = self.across() if self.ground else None\n        spread = triangulation.sight_spread(self.sightings, r[\"lon\"], r[\"lat\"], self.ground_z, *across) if across else 0.0\n        if spread > triangulation.SIGHT_WARNING:\n            text += (\" ⚠ Les visées ne tombent pas au même endroit du bord (±{} m en travers) : revisez-en une, \"\n                     \"sur le trait vert ou sur un repère net, au besoin depuis une photo plus proche\").format(_num(spread, 2))\n        text += \" · GPS ±{} m\".format(_num(r[\"gps\"]))\n        if r[\"gps_assumed\"]:\n            text += \" (précision inconnue pour certaines photos : {} m supposés)\".format(\n                _num(triangulation.GPS_ACCURACY, 0))\n        if r[\"method\"] == \"3d\":\n            text += \" · profondeur fixée aussi par l'inclinaison des visées (altitudes RTK{})\".format(\n                {\"lidar\": \", sol {} au point\".format(r.get(\"ground_name\", precision.TERRAINS[0][0])),\n                 \"photos\": \", sol tiré des photos\"}.get(r[\"ground_source\"], \"\"))\n        elif r[\"angle\"] < triangulation.WEAK_ANGLE:\n            text += (\". ⚠ Visées presque alignées ({}°) : le point est imprécis dans la profondeur, il peut \"\n                     \"glisser de plusieurs mètres le long de la visée. Visez l'objet quand il est sur le côté de \"\n                     \"la photo, depuis une photo prise avant lui et une autre après\").format(_num(r[\"angle\"], 0))\n        if r[\"gps\"] > triangulation.GPS_WARNING:\n            text += (\". Position GPS des photos imprécise (±{} m) : visez depuis des photos mieux \"\n                     \"positionnées, ou d'autres séquences.\".format(_num(r[\"gps\"])))\n        return text\n\n    def attributes(self):\n        \"\"\"Attributs du point triangulé (export des mesures), ou None sans résultat.\"\"\"\n        r = self.result\n        if r is None:\n            return None\n        return {\n            \"nb_visees\": len(self.sightings),\n            \"angle\": round(r[\"angle\"], 1),\n            \"incert_m\": round(r[\"uncertainty\"], 2),\n            \"ecart_m\": round(r[\"rms\"], 2),\n            \"dist_max_m\": round(max(r[\"distances\"]), 1),\n            \"gps_m\": round(r[\"gps\"], 1),\n            \"photos\": \",\".join(s[\"pic\"] for s in self.sightings),\n            \"date_mesure\": datetime.now().isoformat(timespec=\"seconds\"),\n        }\n\n\nclass CalibrationTool:\n    \"\"\"Clics de calage de l'inclinaison (voir core/calibration.py) : pied et sommet d'objets verticaux. Les calages\n    du cap (repères cliqués dans la photo puis sur la carte) et de la hauteur de caméra (longueur connue), repris\n    du plugin, n'ont plus d'entrée dans la page depuis le 16/10/2026 : seuls leurs calages gardés ou importés\n    servent encore (calibration.Calibration).\"\"\"\n\n    def __init__(self, calibration, current):\n        self.calibration = calibration\n        self.current = current  # () -> (photo, séquence) affichées\n        self.mode = \"tilt\"\n        self.clicks = []  # clics en attente (dicts de tools.photo_click)\n        self.error = None\n        self.last = None  # résultat du dernier calage (texte)\n\n    def set_mode(self, mode):\n        self.mode = mode\n        self.reset()\n\n    def add_click(self, click, notice=None):  # notice : comme MeasureTool.add_click, sans usage ici\n        self.error, self.last = None, None\n        if self.clicks and self.clicks[0][\"pic\"] != click[\"pic\"]:\n            self.clicks = []  # le sommet doit être sur la même photo que le pied\n        self.clicks.append(click)\n        if len(self.clicks) == 2:\n            bottom, top = (tuple(c[\"raw\"]) for c in self.clicks)\n            self.clicks = []\n            try:\n                r = self.calibration.add_vertical(click[\"pic\"], bottom, top)\n            except CalibrationError as exc:\n                self.error = str(exc)\n            else:\n                self.last = \"Inclinaison de la photo : {}° vers {}°{}.\".format(\n                    _num(r[\"tilt\"], 2), _num(r[\"toward\"], 0),\n                    \"\" if r[\"residual\"] is None else \", écart des objets {}°\".format(_num(r[\"residual\"], 2)))\n                if r[\"partial\"]:\n                    self.last += (\" Correction partielle : cliquez un autre objet vertical, à environ 90° \"\n                                  \"du premier, pour corriger toute l'inclinaison.\")\n        return self.status()\n\n    def reset(self):\n        \"\"\"Abandonne les clics en attente (le calage déjà fait est conservé).\"\"\"\n        self.clicks, self.error, self.last = [], None, None\n\n    def clear(self):\n        \"\"\"Efface l'inclinaison calée de la photo affichée.\"\"\"\n        pic, _ = self.current()\n        if pic:\n            self.calibration.clear_tilt(pic)\n        self.reset()\n\n    def viewer_marks(self):\n        points = []\n        for c in self.clicks:\n            pos = c.get(\"pos\") or [None, None]\n            points.append({\"pic\": c.get(\"pic\"), \"yaw\": pos[0], \"pitch\": pos[1],\n                           \"abs_yaw\": c[\"raw\"][0], \"elev\": c[\"raw\"][1]})\n        return {\"points\": points, \"label\": \"\", \"beside\": True}\n\n    def status(self):\n        text = (self.error or self.last or \"\") + (\" \" if self.error or self.last else \"\")\n        if len(self.clicks) == 1:\n            return text + \"Cliquez le sommet du même objet.\"\n        return text + (\"Cliquez le pied puis le sommet d'un objet bien vertical (poteau, angle de façade). \"\n                       \"Deux objets à environ 90° l'un de l'autre corrigent toute l'inclinaison de la photo.\")\n",
 "core/triangulation.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Position d'un objet par intersection de visées (triangulation).\n\nChaque visée part de la position d'une photo dans une direction (cap absolu,\n0 = nord, sens horaire). Le point retenu est celui qui minimise la somme\npondérée des carrés des distances aux demi-droites de visée (moindres carrés) :\ndeux visées suffisent, chaque visée supplémentaire améliore et contrôle le\nrésultat. Le poids d'une visée est l'inverse du carré de son écart latéral\nprobable, qui cumule l'erreur de visée (croissante avec la distance) et la\nprécision de la position GPS de la photo : une visée lointaine ou une photo mal\npositionnée compte moins.\n\nVisées en 3D, seulement quand elles se croisent sous STRONG_ANGLE (au-delà, les caps fixent\nbien le point, et une inclinaison un peu fausse ne ferait que le tirer de côté) : quand toutes\nles photos ont une altitude de caméra vérifiée (RTK), chaque\nvisée garde aussi son inclinaison (élévation corrigée du calage) et devient une demi-droite\ndans l'espace. Des photos prises les unes derrière les autres voient l'objet sous des\ninclinaisons différentes : la profondeur, mal fixée par les seuls caps quand les visées sont\npresque parallèles, l'est alors par les inclinaisons. Pour un point au sol (ground=True :\nbord de chaussée, pied d'un objet), l'altitude du sol, tirée de celle des caméras moins leur\nhauteur au-dessus du sol LiDAR, fixe encore la profondeur. Chaque visée pèse selon ses erreurs\nlatérale (cap, GPS) et verticale (inclinaison, altitude).\n\nCalcul dans un plan tangent local (quelques centaines de mètres au plus) :\nl'erreur due à la projection est négligeable devant la précision du GPS.\nModule sans dépendance, testé seul (tests/coeur/).\n\"\"\"\n\nimport math\n\n# Ellipsoïde WGS 84 (celui des positions GPS) : demi-grand axe (m), carré de l'excentricité\nWGS84_A = 6378137.0\nWGS84_E2 = 0.00669437999014\nHEADING_ERROR = 1.0  # erreur de visée supposée (degrés) pour l'incertitude affichée\n# Matériel de relevé (GPS corrigé à SURVEY_ACCURACY m ou mieux, cap EXIF au centième) :\n# sur les photos imajbox à position RTK, le cap suit la trajectoire à 0,33° près (écart-type).\nSURVEY_HEADING_ERROR = 0.5\nSURVEY_ACCURACY = 2.0\nMIN_ANGLE = 3.0  # en dessous, les visées sont jugées parallèles\nMAX_DISTANCE = 500.0  # au-delà, le résultat n'a plus de sens avec des photos de rue\nGPS_ACCURACY = 3.0  # précision GPS supposée (m) quand la photo ne l'indique pas\nGPS_WARNING = 5.0  # au-delà, la position des photos limite nettement la précision du point\nITERATIONS = 4  # les poids dépendent des distances, donc du point : quelques passes suffisent\n# Visées en 3D (voir solve3d)\nELEV_ERROR = 2.0  # erreur d'inclinaison d'une photo dont l'inclinaison n'est pas calée (degrés)\nCLICK_ERROR = 0.1  # erreur de pointé d'un clic dans la photo (degrés)\nALT_ERROR = 0.05  # erreur relative de l'altitude des caméras d'une position vérifiée (m)\nGROUND_ERROR = 0.10  # écart du sol au point visé à celui tiré des photos : dévers, bordure (m)\nGROUND_SLOPE_ERROR = 0.02  # erreur de pente du sol prolongé au-delà des photos (m par m)\nLIDAR_ERROR = 0.08  # altitude du MNT LiDAR HD lue au point : précision, lissage de la grille de 50 cm (m)\nRGE_ALTI_ERROR = 0.30  # altitude du RGE ALTI (1 m), en secours du LiDAR HD : moins précis par endroits (m)\n# Part commune de l'erreur d'inclinaison des photos d'une séquence (degrés), qui ne se compense\n# pas entre visées : systématique du calage (photo calée), tangage de la fixation sinon\nCOMMON_TILT = 0.1\n# Le calcul 3D ne sert que pour des visées qui se croisent sous STRONG_ANGLE (degrés) : au-delà,\n# les caps suffisent, et une inclinaison un peu fausse ne ferait que déplacer le point\nSTRONG_ANGLE = 20.0\nWEAK_ANGLE = 15.0  # croisement en dessous duquel, en plan, la profondeur devient imprécise (degrés)\nSIGHT_WARNING = 0.6  # m : désaccord des visées d'un bord en travers de la route au-delà duquel les réviser (voir sight_spread)\nLIDAR_NAME = \"LiDAR HD\"\nSPREAD_WARNING = 3.0  # visée écartée du point de plus de 3 fois son erreur attendue : autre objet visé ?\n\n\nclass TriangulationError(ValueError):\n    \"\"\"Visées inexploitables (message destiné à l'utilisateur).\"\"\"\n\n\ndef _radii(lat0):\n    \"\"\"Mètres par radian vers l'est (rayon du parallèle) et vers le nord (rayon de courbure du\n    méridien) à la latitude lat0, sur l'ellipsoïde WGS 84. Une sphère de rayon moyen (6 371 km)\n    faussait les longueurs de 0,3 % en est-ouest et de 0,05 % en nord-sud vers 47° N.\"\"\"\n    s2 = math.sin(math.radians(lat0)) ** 2\n    w = 1.0 - WGS84_E2 * s2\n    return (WGS84_A / math.sqrt(w) * math.cos(math.radians(lat0)),\n            WGS84_A * (1.0 - WGS84_E2) / (w * math.sqrt(w)))\n\n\ndef _local(lon, lat, lon0, lat0):\n    \"\"\"Coordonnées métriques (est, nord) autour de (lon0, lat0), dans le plan tangent à l'ellipsoïde.\"\"\"\n    east, north = _radii(lat0)\n    return (east * math.radians(lon - lon0), north * math.radians(lat - lat0))\n\n\ndef _geographic(x, y, lon0, lat0):\n    \"\"\"Inverse de _local.\"\"\"\n    east, north = _radii(lat0)\n    return (lon0 + math.degrees(x / east), lat0 + math.degrees(y / north))\n\n\ndef offset(lon, lat, heading, distance):\n    \"\"\"Point situé à `distance` mètres de (lon, lat) dans la direction `heading`.\"\"\"\n    a = math.radians(heading)\n    return _geographic(distance * math.sin(a), distance * math.cos(a), lon, lat)\n\n\ndef crossing_angle(h1, h2):\n    \"\"\"Angle entre deux droites de visée, ramené entre 0 et 90°.\"\"\"\n    a = abs(h1 - h2) % 180.0\n    return min(a, 180.0 - a)\n\n\ndef heading_error(sighting):\n    \"\"\"Erreur de visée supposée (degrés) : celle du recalage du cap s'il y en a un\n    (\"heading_error\", voir calibration.py), plus faible pour le matériel de relevé.\"\"\"\n    if sighting.get(\"heading_error\") is not None:\n        return float(sighting[\"heading_error\"])\n    accuracy = sighting.get(\"accuracy\")\n    if sighting.get(\"precise\") and accuracy is not None and accuracy <= SURVEY_ACCURACY:\n        return SURVEY_HEADING_ERROR\n    return HEADING_ERROR\n\n\ndef projected(point, gx, gy):\n    \"\"\"Écart probable (m) de gx·x + gy·y pour un point triangulé (dict avec \"uncertainty\" et, s'il en a,\n    \"cov\" : covariance horizontale c11, c12, c22). Sans covariance (point posé d'un clic) : erreur de\n    même taille dans toutes les directions.\"\"\"\n    cov = point.get(\"cov\")\n    if not cov:\n        return point[\"uncertainty\"] * math.hypot(gx, gy)\n    return math.sqrt(max(gx * gx * cov[0] + 2 * gx * gy * cov[1] + gy * gy * cov[2], 0.0))\n\n\ndef sight_spread(sightings, lon, lat, ground_z, ux, uy):\n    \"\"\"Désaccord des visées d'un point au sol dans la direction (ux, uy), m : plus grand écart au point\n    (lon, lat), dans cette direction, de l'endroit où chaque visée touche le sol. Sur un bord, qui n'a pas de\n    repère le long de son tracé, c'est le signe de visées tombées à des endroits différents, que leur\n    croisement ne montre pas. ground_z : altitude du sol lue au point (voir solve_on_ground), LiDAR HD\n    seulement : l'altitude tirée des visées absorberait leur désaccord, le RGE ALTI est trop imprécis. 0 si les\n    visées ne permettent pas d'en juger : moins de deux, sans cette altitude, sans inclinaison calée\n    (l'erreur d'inclinaison y dominerait), ou presque à l'horizon.\"\"\"\n    if not ground_z or len(sightings) < 2 or (len(ground_z) > 4 and ground_z[4] != LIDAR_NAME):\n        return 0.0\n    z = ground_z[2]\n    worst = 0.0\n    for s in sightings:\n        elev, alt = s.get(\"elev\"), s.get(\"alt\")\n        if s.get(\"elev_error\") is None or elev is None or alt is None or elev > -0.5 or alt <= z:\n            return 0.0\n        d, h = (alt - z) / math.tan(math.radians(-elev)), math.radians(s[\"heading\"])\n        x, y = _local(s[\"lon\"], s[\"lat\"], lon, lat)\n        worst = max(worst, abs((x + d * math.sin(h)) * ux + (y + d * math.cos(h)) * uy))\n    return worst\n\n\ndef _sigma(distance, accuracy, error=HEADING_ERROR):\n    \"\"\"Écart latéral probable d'une visée (m) : erreur de visée et position GPS.\"\"\"\n    lateral = max(distance, 0.0) * math.tan(math.radians(error))\n    return max(math.hypot(lateral, accuracy), 0.05)\n\n\ndef _normal(rays, weights):\n    \"\"\"Normales pondérées  Σ w (I - d dᵀ) : (a11, a12, a22, b1, b2).\"\"\"\n    a11 = a12 = a22 = b1 = b2 = 0.0\n    for (px, py, dx, dy), w in zip(rays, weights):\n        m11, m12, m22 = w * (1 - dx * dx), w * (-dx * dy), w * (1 - dy * dy)\n        a11 += m11\n        a12 += m12\n        a22 += m22\n        b1 += m11 * px + m12 * py\n        b2 += m12 * px + m22 * py\n    return a11, a12, a22, b1, b2\n\n\ndef _distances(rays, x, y):\n    \"\"\"Position du point le long de chaque visée (m).\"\"\"\n    return [(x - px) * dx + (y - py) * dy for px, py, dx, dy in rays]\n\n\ndef _inverse3(m):\n    \"\"\"Inverse d'une matrice 3 × 3 (liste de lignes), ou None si elle est singulière.\"\"\"\n    (a, b, c), (d, e, f), (g, h, i) = m\n    co = [[e * i - f * h, c * h - b * i, b * f - c * e],\n          [f * g - d * i, a * i - c * g, c * d - a * f],\n          [d * h - e * g, b * g - a * h, a * e - b * d]]\n    det = a * co[0][0] + b * co[1][0] + c * co[2][0]\n    if abs(det) < 1e-12:\n        return None\n    return [[v / det for v in row] for row in co]\n\n\ndef _major_axis(c11, c12, c22):\n    \"\"\"Demi grand axe (racine de la plus grande valeur propre) d'une covariance 2 × 2.\"\"\"\n    half = (c11 + c22) / 2.0\n    return math.sqrt(max(half + math.sqrt(max(half * half - (c11 * c22 - c12 * c12), 0.0)), 0.0))\n\n\ndef _ground_at(sightings, x, y, origin):\n    \"\"\"Altitude du sol au point (x, y) tirée des photos, et son erreur (m) : sol sous les\n    photos prolongé le long de leur alignement (pente de la route), ou leur moyenne si elles\n    sont trop proches. L'erreur cumule le dévers (GROUND_ERROR), la dispersion de la hauteur\n    de caméra de la séquence (\"ground_spread\", voir precision.verify_heights) et le\n    prolongement au-delà des photos.\"\"\"\n    pts = [(*_local(s[\"lon\"], s[\"lat\"], *origin), s[\"ground\"]) for s in sightings]\n    spread = max((float(s.get(\"ground_spread\") or 0.0) for s in sightings), default=0.0)\n    a = max(((p, q) for p in pts for q in pts), key=lambda pq: math.hypot(pq[1][0] - pq[0][0], pq[1][1] - pq[0][1]))\n    (x1, y1, z1), (x2, y2, z2) = a\n    length = math.hypot(x2 - x1, y2 - y1)\n    if length < 1.0:\n        beyond = min(math.hypot(x - p[0], y - p[1]) for p in pts)\n        return sum(p[2] for p in pts) / len(pts), math.hypot(GROUND_ERROR, spread, GROUND_SLOPE_ERROR * beyond)\n    t = ((x - x1) * (x2 - x1) + (y - y1) * (y2 - y1)) / length ** 2\n    beyond = max(0.0, -t, t - 1.0) * length\n    return z1 + t * (z2 - z1), math.hypot(GROUND_ERROR, spread, GROUND_SLOPE_ERROR * beyond)\n\n\ndef solve3d(sightings, ground=False, ground_z=None):\n    \"\"\"Intersection des visées dans l'espace (voir l'en-tête du module). sightings : comme\n    solve, avec en plus \"elev\" (inclinaison corrigée, degrés), \"alt\" (altitude de la caméra,\n    m), \"elev_error\" (incertitude de l'inclinaison calée, degrés, ou None) et, pour ground,\n    \"ground\" (altitude du sol sous la photo, m). ground_z : altitude du sol lue au point (m),\n    plus sûre que le sol tiré des photos : nombre (MNT LiDAR HD, ±LIDAR_ERROR) ou (altitude,\n    incertitude en m) pour une autre source. Retourne (x, y, z, covariance 3 × 3,\n    distances horizontales, repère (lon0, lat0)) ou None si les visées ne fixent pas le point.\"\"\"\n    lon0 = sum(s[\"lon\"] for s in sightings) / len(sightings)\n    lat0 = sum(s[\"lat\"] for s in sightings) / len(sightings)\n    rays = []\n    for s in sightings:\n        px, py = _local(s[\"lon\"], s[\"lat\"], lon0, lat0)\n        h, e = math.radians(s[\"heading\"]), math.radians(s[\"elev\"])\n        d = (math.sin(h) * math.cos(e), math.cos(h) * math.cos(e), math.sin(e))\n        side = (math.cos(h), -math.sin(h), 0.0)  # écart latéral, horizontal\n        up = (d[1] * side[2] - d[2] * side[1], d[2] * side[0] - d[0] * side[2], d[0] * side[1] - d[1] * side[0])\n        elev_error = math.hypot(s[\"elev_error\"] if s.get(\"elev_error\") is not None else ELEV_ERROR, CLICK_ERROR)\n        accuracy = GPS_ACCURACY if s.get(\"accuracy\") is None else float(s[\"accuracy\"])\n        rays.append(((px, py, float(s[\"alt\"])), d, side, up, heading_error(s), accuracy, elev_error))\n    point = None\n    for _ in range(ITERATIONS):\n        a = [[0.0] * 3 for _ in range(3)]\n        b = [0.0] * 3\n        for p, d, side, up, herr, acc, eerr in rays:\n            t = 10.0 if point is None else max(sum((point[k] - p[k]) * d[k] for k in range(3)), 0.5)\n            w_side = 1.0 / _sigma(t, acc, herr) ** 2\n            w_up = 1.0 / max(math.hypot(t * math.tan(math.radians(eerr)), ALT_ERROR), 0.01) ** 2\n            for i in range(3):\n                for j in range(3):\n                    m = w_side * side[i] * side[j] + w_up * up[i] * up[j]\n                    a[i][j] += m\n                    b[i] += m * p[j]\n        if ground:  # altitude du point : celle du sol, au point (LiDAR) ou tirée des photos\n            if isinstance(ground_z, tuple):\n                z, sigma = float(ground_z[0]), float(ground_z[1])\n            elif ground_z is not None:\n                z, sigma = float(ground_z), LIDAR_ERROR\n            else:\n                z, sigma = _ground_at(sightings, *(point[:2] if point else (0.0, 0.0)), (lon0, lat0))\n            a[2][2] += 1.0 / sigma ** 2\n            b[2] += z / sigma ** 2\n        inv = _inverse3(a)\n        if inv is None:\n            return None\n        point = [sum(inv[i][j] * b[j] for j in range(3)) for i in range(3)]\n    # Distance horizontale du point à chaque photo, le long de la visée\n    distances = [((point[0] - p[0]) * d[0] + (point[1] - p[1]) * d[1]) / max(math.hypot(d[0], d[1]), 1e-9)\n                 for p, d, *_ in rays]\n    return point[0], point[1], point[2], inv, distances, (lon0, lat0)\n\n\ndef usable3d(sightings, ground=False, ground_z=None):\n    \"\"\"Les visées se prêtent-elles au calcul 3D : inclinaison et altitude de caméra connues\n    pour toutes (et, pour un point au sol sans altitude lue au point, sol sous la photo) ?\"\"\"\n    keys = (\"elev\", \"alt\", \"ground\") if ground and ground_z is None else (\"elev\", \"alt\")\n    return all(s.get(k) is not None for s in sightings for k in keys)\n\n\ndef solve(sightings, ground=False, ground_z=None):\n    \"\"\"Intersection des visées.\n\n    sightings : liste de dicts avec au moins \"lon\", \"lat\", \"heading\", et\n    éventuellement \"accuracy\" (précision de la position GPS en m, None si inconnue)\n    \"precise\" (cap au centième de degré), \"heading_error\" (voir heading_error) et\n    \"sequence\" (erreurs communes aux photos d'une même séquence).\n    Retourne un dict : lon, lat, distances (m, une par visée), angle (° de\n    croisement le plus favorable), rms (écart moyen des visées au point, m),\n    uncertainty (rayon d'incertitude en m pour l'erreur de visée de chaque photo et la\n    précision GPS), gps (précision GPS la moins bonne, m), gps_assumed (vrai si\n    au moins une photo n'indique pas sa précision, GPS_ACCURACY est alors supposé).\n    spread : plus grand écart d'une visée au point, rapporté à son erreur attendue (cap, GPS).\n    En 3D (voir solve3d, usable3d) : aussi z (altitude du point, m), common_tilt (part de\n    l'incertitude due à l'inclinaison commune aux photos d'une séquence, m) ; method vaut \"3d\" ou\n    \"plan\" ; ground_source vaut \"lidar\" (ground_z, altitude du MNT LiDAR HD lue au point),\n    \"photos\" (sol sous les photos) ou None. ground : point au sol (sa profondeur se fixe aussi\n    par l'altitude du sol).\n    Lève TriangulationError si les visées ne permettent pas de conclure.\n    \"\"\"\n    if len(sightings) < 2:\n        raise TriangulationError(\"Il faut au moins deux visées.\")\n    lon0 = sum(s[\"lon\"] for s in sightings) / len(sightings)\n    lat0 = sum(s[\"lat\"] for s in sightings) / len(sightings)\n\n    angle = max(crossing_angle(a[\"heading\"], b[\"heading\"])\n                for i, a in enumerate(sightings) for b in sightings[i + 1:])\n    if angle < STRONG_ANGLE and usable3d(sightings, ground, ground_z):\n        found = solve3d(sightings, ground, ground_z)\n        if found is not None:\n            r = _result3d(sightings, found, angle)\n            r[\"ground_source\"] = (\"lidar\" if ground_z is not None else \"photos\") if ground else None\n            r[\"common_tilt\"] = _common_tilt(sightings, found, ground, ground_z)\n            r[\"uncertainty\"] = math.hypot(r[\"uncertainty\"], r[\"common_tilt\"])\n            return r\n    if angle < MIN_ANGLE:\n        raise TriangulationError(\n            \"Visées presque parallèles ({:.0f}°) : visez l'objet depuis une photo plus \"\n            \"décalée sur le côté.\".format(angle))\n\n    rays, accuracies, errors = [], [], []\n    for s in sightings:\n        px, py = _local(s[\"lon\"], s[\"lat\"], lon0, lat0)\n        h = math.radians(s[\"heading\"])\n        rays.append((px, py, math.sin(h), math.cos(h)))\n        accuracies.append(s.get(\"accuracy\"))\n        errors.append(heading_error(s))\n    gps_assumed = any(a is None for a in accuracies)\n    accuracies = [GPS_ACCURACY if a is None else float(a) for a in accuracies]\n\n    # Normales  Σ w (I - d dᵀ) X = Σ w (I - d dᵀ) P ; première passe sans pondération,\n    # puis poids recalculés à partir des distances au point trouvé.\n    weights = [1.0] * len(rays)\n    for _ in range(ITERATIONS):\n        a11, a12, a22, b1, b2 = _normal(rays, weights)\n        det = a11 * a22 - a12 * a12\n        if abs(det) < 1e-9 * max(a11 + a22, 1e-12) ** 2:\n            raise TriangulationError(\"Visées parallèles : impossible de les croiser.\")\n        x = (a22 * b1 - a12 * b2) / det\n        y = (a11 * b2 - a12 * b1) / det\n        weights = [1.0 / _sigma(t, acc, e) ** 2 for t, acc, e in zip(_distances(rays, x, y), accuracies, errors)]\n\n    distances = _distances(rays, x, y)\n    residuals = [abs((x - px) * dy - (y - py) * dx) for px, py, dx, dy in rays]  # écart perpendiculaire\n    spread = max(r / _sigma(t, acc, e) for r, t, acc, e in zip(residuals, distances, accuracies, errors))\n    if min(distances) < 0.5:\n        raise TriangulationError(\n            \"Les visées ne se croisent pas devant les photos : vérifiez que vous visez \"\n            \"bien le même objet.\")\n    if max(distances) > MAX_DISTANCE:\n        raise TriangulationError(\n            \"Point trouvé à plus de {:.0f} m : visées trop peu sécantes ou objets \"\n            \"différents.\".format(MAX_DISTANCE))\n\n    # Incertitude : chaque visée est décalée latéralement d'environ _sigma (erreur de cap\n    # et position GPS). Covariance du point = (Σ w (I - d dᵀ))⁻¹, w = 1 / décalage² ;\n    # on garde le grand axe.\n    weights = [1.0 / _sigma(t, acc, e) ** 2 for t, acc, e in zip(distances, accuracies, errors)]\n    c11, c12, c22, _, _ = _normal(rays, weights)\n    cdet = c11 * c22 - c12 * c12\n    cov = None\n    if cdet > 0:\n        cov = (c22 / cdet, -c12 / cdet, c11 / cdet)\n        # Valeurs propres de l'inverse = inverses des valeurs propres : on prend la plus petite\n        half = (c11 + c22) / 2.0\n        smallest = half - math.sqrt(max(half * half - cdet, 0.0))\n        uncertainty = 1.0 / math.sqrt(smallest) if smallest > 0 else float(\"inf\")\n    else:\n        uncertainty = float(\"inf\")\n\n    # Photos d'une même séquence : leur décalage de position GPS et leur erreur de cap (fixation\n    # de la caméra) sont presque les mêmes ; ils déplacent le point d'un bloc et ne se compensent\n    # pas entre visées. L'incertitude ne descend pas sous cette part commune.\n    sequences = {s.get(\"sequence\") for s in sightings}\n    if len(sequences) == 1 and None not in sequences:\n        n = len(sightings)\n        common = math.hypot(sum(accuracies) / n,\n                            sum(distances) / n * math.tan(math.radians(sum(errors) / n)))\n        uncertainty = max(uncertainty, common)\n\n    lon, lat = _geographic(x, y, lon0, lat0)\n    return {\n        \"lon\": lon,\n        \"lat\": lat,\n        \"spread\": spread,\n        \"z\": None,\n        \"method\": \"plan\",\n        \"ground_source\": None,\n        \"distances\": distances,\n        \"angle\": angle,\n        \"rms\": math.sqrt(sum(r * r for r in residuals) / len(residuals)),\n        \"uncertainty\": uncertainty,\n        \"cov\": cov,\n        \"gps\": max(accuracies),\n        \"gps_assumed\": gps_assumed,\n    }\n\n\ndef _common_tilt(sightings, found, ground=False, ground_z=None):\n    \"\"\"Déplacement horizontal du point (m) quand l'inclinaison de toutes les visées d'une même\n    séquence varie ensemble de ±COMMON_TILT (photo calée) ou ±ELEV_ERROR (non calée) : part\n    commune de l'erreur d'inclinaison, que la pondération des visées, qui les suppose\n    indépendantes, ne compte pas. Séquences différentes : parts indépendantes, cumulées.\"\"\"\n    x, y = found[0], found[1]\n    total = 0.0\n    for sequence in {s.get(\"sequence\") for s in sightings}:\n        worst = 0.0\n        for sign in (-1, 1):\n            shifted = [dict(s, elev=s[\"elev\"] + sign * (COMMON_TILT if s.get(\"elev_error\") is not None\n                                                        else ELEV_ERROR))\n                       if s.get(\"sequence\") == sequence else s for s in sightings]\n            moved = solve3d(shifted, ground, ground_z)\n            if moved is None:\n                return float(\"inf\")\n            worst = max(worst, math.hypot(moved[0] - x, moved[1] - y))\n        total += worst * worst\n    return math.sqrt(total)\n\n\ndef _result3d(sightings, found, angle):\n    \"\"\"Résultat de solve pour l'intersection dans l'espace (voir solve3d).\"\"\"\n    x, y, z, cov, distances, (lon0, lat0) = found\n    if min(distances) < 0.5:\n        raise TriangulationError(\n            \"Les visées ne se croisent pas devant les photos : vérifiez que vous visez \"\n            \"bien le même objet.\")\n    if max(distances) > MAX_DISTANCE:\n        raise TriangulationError(\n            \"Point trouvé à plus de {:.0f} m : visées trop peu sécantes ou objets \"\n            \"différents.\".format(MAX_DISTANCE))\n    accuracies = [GPS_ACCURACY if s.get(\"accuracy\") is None else float(s[\"accuracy\"]) for s in sightings]\n    uncertainty = _major_axis(cov[0][0], cov[0][1], cov[1][1])\n    sequences = {s.get(\"sequence\") for s in sightings}\n    if len(sequences) == 1 and None not in sequences:  # part commune aux photos d'une séquence (voir solve)\n        n = len(sightings)\n        uncertainty = max(uncertainty, sum(accuracies) / n)\n    residuals = []\n    for s in sightings:\n        px, py = _local(s[\"lon\"], s[\"lat\"], lon0, lat0)\n        h, e = math.radians(s[\"heading\"]), math.radians(s[\"elev\"])\n        d = (math.sin(h) * math.cos(e), math.cos(h) * math.cos(e), math.sin(e))\n        v = (x - px, y - py, z - float(s[\"alt\"]))\n        t = sum(v[k] * d[k] for k in range(3))\n        residuals.append(math.sqrt(max(sum(c * c for c in v) - t * t, 0.0)))\n    spread = max(r / _sigma(t, a, heading_error(s)) for r, t, a, s in zip(residuals, distances, accuracies, sightings))\n    lon, lat = _geographic(x, y, lon0, lat0)\n    return {\n        \"lon\": lon,\n        \"lat\": lat,\n        \"spread\": spread,\n        \"z\": z,\n        \"method\": \"3d\",\n        \"distances\": distances,\n        \"angle\": angle,\n        \"rms\": math.sqrt(sum(r * r for r in residuals) / len(residuals)),\n        \"uncertainty\": uncertainty,\n        \"cov\": (cov[0][0], cov[0][1], cov[1][1]),\n        \"gps\": max(accuracies),\n        \"gps_assumed\": any(s.get(\"accuracy\") is None for s in sightings),\n    }\n\n",
 "core/widths.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Largeur perpendiculaire à la route depuis un point triangulé (application web).\n\nLe premier bord A est un point triangulé (voir triangulation.py). La largeur se prend sur\nla droite passant par A, perpendiculaire à l'axe de la route. Le second bord B est là où la\nvisée d'un clic dans une photo coupe cette droite : le calcul ne garde que la direction\nhorizontale du clic. La visée doit couper la droite franchement : depuis une photo prise\nquelques mètres avant ou après A, pas juste en face.\n\nCe bord cliqué reste une estimation : le clic se pose là où la droite, dessinée à plat à la\nhauteur de A, croise le bord vu dans la photo. Si le sol de B n'est pas à cette hauteur (dévers,\nbordure), la largeur est faussée d'environ |écart latéral caméra-B| · Δh / (H + Δh), H étant la\nhauteur de la caméra au-dessus de A, sans que l'incertitude le compte. Le bord triangulé\n(set_edge_b) n'a pas ce biais. L'incertitude n'est prise qu'en travers de la route : l'erreur\ndes points, surtout le long de la route, n'y pèse presque pas (triangulation.projected).\n\nCalcul dans un plan tangent local centré sur A (voir triangulation._local).\n\"\"\"\n\nimport math\n\nfrom . import geometry, measures, triangulation\nfrom .calibration import AIM_ERROR\n\n# Incertitude de la direction de l'axe de la route (degrés) : tronçon de la BD TOPO (direction\n# locale sur ±10 m, voir roads.py), sinon trajectoire de la séquence (le véhicule ne roule pas\n# toujours parallèlement à la route)\nAXIS_ERROR_BDTOPO = 2.0\nAXIS_ERROR_TRACK = 3.0\nSAME_SEQUENCE_GPS = 0.5  # part de la précision GPS d'une photo qui n'est pas commune à sa séquence (s'annule avec A)\nMIN_ANGLE = 10.0  # angle minimal (degrés) entre la visée et la droite perpendiculaire\nGRAZING_ANGLE = 25.0  # en dessous, visée signalée comme rasante\nGUIDE_LENGTH = 15.0  # m de part et d'autre de A : droite tracée sur la carte et dans la photo\nMIN_WIDTH = 0.01  # m : le bord décalé au clavier ne dépasse pas le point de référence\nPROBE = 0.01  # m : petit déplacement de A pour mesurer la réponse de la largeur\nMIN_TILT_TANGENT = 0.01  # sous cette pente de visée, l'effet de l'inclinaison n'est pas évalué\n\n\ndef too_grazing(angle):\n    \"\"\"Visée à peine au-dessus de MIN_ANGLE : une erreur de cap ou de position la ferait tomber dessous,\n    l'incertitude de la largeur n'est pas évaluable.\"\"\"\n    return geometry.GeometryError(\n        \"Visée trop rasante ({} °) pour estimer la largeur : cliquez le bord depuis une photo prise quelques \"\n        \"mètres avant ou après le point de référence.\".format(measures._num(angle, 0)))\n\n\ndef axis_error(source):\n    \"\"\"Incertitude (degrés) de l'axe de la route selon sa source (voir roads.py).\"\"\"\n    return AXIS_ERROR_BDTOPO if source and source.startswith(\"BD TOPO\") else AXIS_ERROR_TRACK\n\n\ndef heading_error(click):\n    \"\"\"Erreur de cap (degrés) d'un clic : visée dans la photo et cap de la photo (plus faible\n    pour le matériel de relevé, voir triangulation.heading_error).\"\"\"\n    return math.hypot(AIM_ERROR, triangulation.heading_error(click))\n\n\ndef perpendicular(axis):\n    \"\"\"Direction (est, nord) de la droite perpendiculaire à l'axe `axis` (degrés).\"\"\"\n    p = math.radians(axis + 90.0)\n    return math.sin(p), math.cos(p)\n\n\ndef cross(a, axis, cam, heading):\n    \"\"\"Intersection de la visée partant de cam (est, nord) au cap `heading` (degrés) et de la\n    droite passant par a (est, nord), perpendiculaire à l'axe `axis` (degrés).\n\n    Retourne (point, t, s, angle) : point d'intersection (est, nord), son abscisse signée t\n    sur la droite depuis a, la distance s depuis cam, et l'angle (degrés) entre la visée et la\n    droite. Lève geometry.GeometryError si la visée ne coupe pas la droite devant la caméra\n    ou la coupe trop en biais (MIN_ANGLE).\"\"\"\n    ux, uy = perpendicular(axis)\n    h = math.radians(heading)\n    dx, dy = math.sin(h), math.cos(h)\n    # cam + s d = a + t u  :  s d - t u = a - cam\n    det = uy * dx - ux * dy\n    angle = math.degrees(math.asin(min(1.0, abs(det))))\n    if angle < MIN_ANGLE:\n        raise geometry.GeometryError(\n            \"Visée presque parallèle à la droite de mesure ({:.0f}°) : cliquez le bord depuis une photo prise \"\n            \"quelques mètres avant ou après le point de référence.\".format(angle))\n    rx, ry = a[0] - cam[0], a[1] - cam[1]\n    s = (ry * ux - rx * uy) / -det\n    t = (dx * ry - dy * rx) / -det\n    if s <= 0:\n        raise geometry.GeometryError(\"La droite de mesure est derrière la visée.\")\n    return (cam[0] + s * dx, cam[1] + s * dy), t, s, angle\n\n\nclass PerpendicularWidth(measures.Measure):\n    \"\"\"Largeur entre le point triangulé A (edge : lon, lat, uncertainty, name) et le bord B\n    cliqué (voir le module). Rangée avec les mesures de MeasureTool, dont elle a l'interface\n    (liste, export, repères de la visionneuse, dessin sur la carte) ; clicks : A vu de la photo\n    de B (voir _edge_mark : sans direction brute, non recorrigé), puis le clic de B.\"\"\"\n\n    def __init__(self, tool, edge, road, click):\n        super().__init__(tool, \"road\", \"ground\")\n        self.edge = edge\n        self.road = road  # axe de la route en A : dict axis, source (voir roads.py)\n        self.clicks = [self._edge_mark(click), click]\n        self.angle = None\n        self.offset = 0.0  # décalage du bord (m) le long de la droite, au clavier : allonge la largeur\n        # Bord B triangulé à son tour (dict lon, lat, uncertainty, name, sightings), ou None : B\n        # est alors là où la visée du clic coupe la droite (voir set_edge_b)\n        self.edge_b = None\n        self.compute()\n\n    def set_edge_b(self, edge_b):\n        \"\"\"Bord B triangulé (voir edge_b) : la largeur devient la distance de A à B perpendiculaire\n        à l'axe de la route, B ramené sur la droite passant par A ; None : retour au clic.\"\"\"\n        self.edge_b = edge_b\n        self.offset = 0.0\n        self.compute()\n\n    def _edge_mark(self, click):\n        \"\"\"Premier « clic » de la largeur : le point de référence A, vu de la photo du bord (photo,\n        position de sa caméra, axe de la route), pour la liste des clics et l'export. Sa direction\n        n'est ni affichée ni sélectionnée : la session projette A elle-même, avec la hauteur de\n        caméra et le calage de la photo affichée (Session._width_points, Session._project).\"\"\"\n        x, y = triangulation._local(self.edge[\"lon\"], self.edge[\"lat\"], click[\"lon\"], click[\"lat\"])\n        return {\"pic\": click.get(\"pic\"), \"lon\": click[\"lon\"], \"lat\": click[\"lat\"],\n                \"yaw\": math.degrees(math.atan2(x, y)), \"elev\": 0.0, \"pos\": [None, None],\n                \"sequence\": click.get(\"sequence\"), \"axis\": self.road[\"axis\"], \"axis_source\": self.road[\"source\"]}\n\n    def needed(self):\n        return 2\n\n    def picks(self):\n        return []  # ni A (point triangulé) ni B (sur sa visée) ne se glissent sur la carte\n\n    def reaim(self, index, click):\n        if index == 0:\n            self.error = \"Le point de référence ne se vise pas ici : « Nouveau point de référence ».\"\n            return\n        state = list(self.clicks), self.offset, self.edge_b\n        self.clicks = [self._edge_mark(click), click]  # repère de A dans la photo du nouveau clic\n        self.offset, self.edge_b = 0.0, None  # bord revisé d'un clic : plus triangulé\n        self.compute()\n        if self.error:\n            error = self.error\n            self.clicks, self.offset, self.edge_b = state\n            self.compute()\n            self.error = error\n\n    def nudge(self, step):\n        \"\"\"Décale le bord de `step` m le long de la droite de mesure (positif : la largeur\n        s'allonge), sans aller au-delà du point de référence.\"\"\"\n        if self.result:\n            self.offset = max(self.offset + step, MIN_WIDTH - self.result[\"value\"] + self.offset)\n            self.compute()\n\n    def side(self):\n        \"\"\"Côté du bord sur la droite de mesure, vu du point de référence : 1 dans la direction\n        perpendicular(axe), -1 à l'opposé.\"\"\"\n        return 1.0 if (self._across() if self.edge_b else self._width()[1]) >= 0 else -1.0\n\n    def _across(self, daxis=0.0):\n        \"\"\"Bord B triangulé : son abscisse signée sur la droite de mesure depuis A (m), c'est-à-dire\n        la largeur perpendiculaire à l'axe ; daxis : écart pour l'incertitude.\"\"\"\n        bx, by = triangulation._local(self.edge_b[\"lon\"], self.edge_b[\"lat\"], self.edge[\"lon\"], self.edge[\"lat\"])\n        ux, uy = perpendicular(self.road[\"axis\"] + daxis)\n        return bx * ux + by * uy\n\n    def _spread(self, point):\n        \"\"\"Désaccord de ses visées en travers de la route (triangulation.sight_spread), m : point\n        déplacé à la main, sans objet.\"\"\"\n        if point.get(\"moved\"):\n            return 0.0\n        return triangulation.sight_spread(point.get(\"sightings\") or [], point[\"lon\"], point[\"lat\"],\n                                          point.get(\"ground_z\"), *perpendicular(self.road[\"axis\"]))\n\n    def _width(self, da=(0.0, 0.0), daxis=0.0, dheading=0.0, dcam=(0.0, 0.0)):\n        click = self.clicks[1]\n        cam = triangulation._local(click[\"lon\"], click[\"lat\"], self.edge[\"lon\"], self.edge[\"lat\"])\n        return cross(da, self.road[\"axis\"] + daxis, (cam[0] + dcam[0], cam[1] + dcam[1]), click[\"yaw\"] + dheading)\n\n    def _compute_triangulated(self):\n        \"\"\"Largeur depuis le bord B triangulé (voir set_edge_b).\"\"\"\n        t = self._across()\n        ux, uy = perpendicular(self.road[\"axis\"])\n        if self.offset:  # bord décalé au clavier le long de la droite\n            t += self.offset if t >= 0 else -self.offset\n        base = abs(self._across())\n        error = axis_error(self.road[\"source\"])\n        total = (triangulation.projected(self.edge, ux, uy) ** 2 + triangulation.projected(self.edge_b, ux, uy) ** 2\n                 + self._spread(self.edge) ** 2 + self._spread(self.edge_b) ** 2\n                 + max(abs(abs(self._across(k * error)) - base) for k in (-1, 1)) ** 2)\n        click = self.clicks[1]\n        cam = triangulation._local(click[\"lon\"], click[\"lat\"], self.edge[\"lon\"], self.edge[\"lat\"])\n        a = (self.edge[\"lon\"], self.edge[\"lat\"])\n        b = triangulation._geographic(t * ux, t * uy, *a)  # B ramené sur la droite passant par A\n        self.result = {\"value\": abs(t), \"uncertainty\": math.sqrt(total),\n                       \"decomposition\": {\"horizontal\": abs(t), \"vertical\": 0.0, \"along\": 0.0, \"across\": abs(t)},\n                       \"ranges\": [math.hypot(*cam), math.hypot(t * ux - cam[0], t * uy - cam[1])],\n                       \"points\": [a, b], \"extra\": None, \"picks\": [a, b], \"shifts\": [(0.0, 0.0), (0.0, 0.0)]}\n\n    def compute(self):\n        self.result, self.error, self.angle = None, None, None\n        if self.edge_b is not None:\n            self._compute_triangulated()\n            self._draw()\n            return\n        try:\n            (bx, by), t, s, self.angle = self._width()\n            click = self.clicks[1]\n            cam = triangulation._local(click[\"lon\"], click[\"lat\"], self.edge[\"lon\"], self.edge[\"lat\"])\n            shifts = [(0.0, 0.0), (0.0, 0.0)]\n            if self.offset:  # bord décalé au clavier : le long de la droite, son repère suit\n                ux, uy = perpendicular(self.road[\"axis\"])\n                k = self.offset if t >= 0 else -self.offset\n                ox, oy = bx + k * ux, by + k * uy\n                height = self.tool.camera_for(click)\n                d0, d1 = math.hypot(bx - cam[0], by - cam[1]), math.hypot(ox - cam[0], oy - cam[1])\n                dyaw = math.degrees(math.atan2(ox - cam[0], oy - cam[1]) - math.atan2(bx - cam[0], by - cam[1]))\n                shifts[1] = ((dyaw + 540) % 360 - 180,\n                             math.degrees(math.atan2(height, d0) - math.atan2(height, max(d1, 0.1))))\n                bx, by, t, s = ox, oy, t + k, d1\n            sigma_cam = click.get(\"accuracy\") or triangulation.GPS_ACCURACY\n            if click.get(\"sequence\") in (self.edge.get(\"sequences\") or []):\n                sigma_cam *= SAME_SEQUENCE_GPS\n            groups = [[{\"dheading\": k * heading_error(click)} for k in (-1, 1)],\n                      [{\"dcam\": (k * sigma_cam, 0.0)} for k in (-1, 1)], [{\"dcam\": (0.0, k * sigma_cam)} for k in (-1, 1)]]\n            # Axe : la droite tourne avec lui et le clic la suit jusqu'au bord vu, qui ne bouge pas : la largeur\n            # n'y perd que le cosinus\n            total = (abs(t) * (1.0 / math.cos(math.radians(axis_error(self.road[\"source\"]))) - 1.0)) ** 2\n            total += self._tilt_spread(cam, s) ** 2 + self._spread(self.edge) ** 2\n            try:  # position de A : réponse de la largeur à son déplacement, selon sa covariance\n                t0 = self._width()[1]\n                total += triangulation.projected(self.edge, *((self._width(da=da)[1] - t0) / PROBE\n                                                              for da in ((PROBE, 0.0), (0.0, PROBE)))) ** 2\n            except geometry.GeometryError:\n                raise too_grazing(self.angle)\n            for variants in groups:\n                worst = 0.0\n                for variant in variants:\n                    try:\n                        worst = max(worst, abs(abs(self._width(**variant)[1]) - abs(t)))\n                    except geometry.GeometryError:\n                        raise too_grazing(self.angle)\n                total += worst * worst\n            a = (self.edge[\"lon\"], self.edge[\"lat\"])\n            b = triangulation._geographic(bx, by, *a)\n            self.result = {\"value\": abs(t), \"uncertainty\": math.sqrt(total),\n                           \"decomposition\": {\"horizontal\": abs(t), \"vertical\": 0.0, \"along\": 0.0, \"across\": abs(t)},\n                           \"ranges\": [math.hypot(*cam), s], \"points\": [a, b], \"extra\": None, \"picks\": [a, b],\n                           \"shifts\": shifts}\n        except geometry.GeometryError as exc:\n            self.error = str(exc)\n        self._draw()\n\n    def _tilt_spread(self, cam, s):\n        \"\"\"Écart de la largeur (m) dû à l'inclinaison de la photo du clic : A cale la droite dessinée à\n        son cap, mais au cap de B elle est décalée en élévation, donc le clic le long du bord.\"\"\"\n        click = self.clicks[1]\n        tangent = abs(math.tan(math.radians(click.get(\"elev\") or 0.0)))\n        if tangent < MIN_TILT_TANGENT:\n            return 0.0  # clic presque à l'horizon : pas un bord au sol\n        ux, uy = perpendicular(self.road[\"axis\"])\n        lateral_a = -(cam[0] * ux + cam[1] * uy)  # écarts latéraux de A et de B à la caméra\n        lateral_b = lateral_a + self._width()[1]\n        sigma = click.get(\"elev_error\")\n        sigma = triangulation.ELEV_ERROR if sigma is None else sigma\n        return (abs(lateral_b) * math.radians(sigma) / tangent\n                * abs(lateral_b / max(s, 0.5) - lateral_a / max(math.hypot(*cam), 0.5)))\n\n    def label(self):\n        \"\"\"Étiquette ; « ≈ » : bord cliqué, une estimation (voir le module).\"\"\"\n        text = super().label()\n        return text.replace(\"↔ \", \"↔ ≈ \", 1) if text and self.edge_b is None else text\n\n    def guide(self):\n        \"\"\"Extrémités (lon, lat) de la droite de mesure tracée sur la carte.\"\"\"\n        return guide(self.edge, self.road[\"axis\"])\n\n    def status(self):\n        r = self.result\n        if self.edge_b is not None:\n            text = (\"Largeur perpendiculaire à la chaussée : {} m (±{} m) · entre les points triangulés {} et {} · \"\n                    \"axe {}° ({})\").format(\n                measures._num(r[\"value\"], 2), measures._num(r[\"uncertainty\"], 2), self.edge.get(\"name\") or \"A\",\n                self.edge_b.get(\"name\") or \"B\", measures._num(self.road[\"axis\"] % 180, 0), self.road[\"source\"])\n            if self.offset:\n                text += \" · bord décalé de {} cm au clavier\".format(measures._num(self.offset * 100, 0))\n            return text + \".\"\n        text = (\"Largeur perpendiculaire à la chaussée : {} m (±{} m) · depuis le point triangulé {} · axe {}° ({}) \"\n                \"· visée à {}° de la droite\").format(\n            measures._num(r[\"value\"], 2), measures._num(r[\"uncertainty\"], 2), self.edge.get(\"name\") or \"\",\n            measures._num(self.road[\"axis\"] % 180, 0), self.road[\"source\"], measures._num(self.angle, 0))\n        if self.offset:\n            text += \" · bord décalé de {} cm au clavier\".format(measures._num(self.offset * 100, 0))\n        if self.angle < GRAZING_ANGLE:\n            text += \". Visée rasante : un clic depuis une photo plus éloignée le long de la route sera plus précis\"\n        return text + (\". Estimation : un dévers ou une bordure entre les deux bords la fausse (jusqu'à environ 0,5 m pour \"\n                       \"2,5 % sur 6,5 m) ; « Trianguler le point » pour une largeur sûre.\")\n\n\ndef move_edge(edge, axis, distance):\n    \"\"\"Déplace le point de référence edge (dict lon, lat, modifié) de `distance` m le long\n    de la droite perpendiculaire à l'axe `axis` (positif : dans la direction perpendicular).\"\"\"\n    ux, uy = perpendicular(axis)\n    edge[\"lon\"], edge[\"lat\"] = triangulation._geographic(distance * ux, distance * uy, edge[\"lon\"], edge[\"lat\"])\n\n\ndef guide(edge, axis, length=GUIDE_LENGTH):\n    \"\"\"Extrémités (lon, lat) de la droite passant par le point edge (lon, lat),\n    perpendiculaire à l'axe `axis`, sur `length` m de part et d'autre.\"\"\"\n    ux, uy = perpendicular(axis)\n    return [triangulation._geographic(k * length * ux, k * length * uy, edge[\"lon\"], edge[\"lat\"]) for k in (-1, 1)]\n",
 "geoid.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Altitude NGF-IGN69 dans le navigateur : grille RAF20 de l'IGN (ondulation du géoïde),\ncomme le fait PROJ.\n\nLa grille est celle que PROJ télécharge (cdn.proj.org, GeoTIFF de 340 Ko, licence\nouverte Etalab) : 421 × 381 nœuds, 1/30° × 0,025°, France métropolitaine. Lue ici sans\nGDAL : tuiles compressées (deflate), prédicteur des flottants (TIFF, prédicteur 3).\n\"\"\"\n\nimport struct\nimport zlib\nfrom itertools import accumulate\n\nURL = \"https://cdn.proj.org/fr_ign_RAF20.tif\"\nGEOID_RANGE = (30.0, 70.0)  # écart plausible entre ellipsoïde et NGF-IGN69 en France (m), comme le plugin\n\n\nclass GeoidError(ValueError):\n    pass\n\n\ndef _tags(data):\n    bo = \"<\" if data[:2] == b\"II\" else \">\"\n    if data[2:4] != (b\"*\\x00\" if bo == \"<\" else b\"\\x00*\"):\n        raise GeoidError(\"pas un fichier TIFF\")\n    off = struct.unpack(bo + \"I\", data[4:8])[0]\n    n = struct.unpack(bo + \"H\", data[off:off + 2])[0]\n    sizes, formats = {2: 1, 3: 2, 4: 4, 11: 4, 12: 8}, {3: \"H\", 4: \"I\", 11: \"f\", 12: \"d\"}\n    tags = {}\n    for i in range(n):\n        entry = off + 2 + 12 * i\n        tag, kind, count = struct.unpack(bo + \"HHI\", data[entry:entry + 8])\n        size = sizes.get(kind, 1) * count\n        if size <= 4:\n            raw = data[entry + 8:entry + 8 + size]\n        else:\n            start = struct.unpack(bo + \"I\", data[entry + 8:entry + 12])[0]\n            raw = data[start:start + size]\n        fmt = formats.get(kind)\n        tags[tag] = raw if fmt is None else struct.unpack(bo + fmt * count, raw)\n    return bo, tags\n\n\nclass Grid:\n    \"\"\"Grille d'ondulation du géoïde (m), interpolée linéairement entre les nœuds.\"\"\"\n\n    def __init__(self, data):\n        bo, t = _tags(data)\n        self.cols, self.rows = t[256][0], t[257][0]\n        if t[258][0] != 32 or t[339][0] != 3 or t[277][0] != 1:\n            raise GeoidError(\"format de grille inattendu (flottants 32 bits, une bande)\")\n        compression, predictor = t[259][0], t.get(317, (1,))[0]\n        if compression not in (1, 8) or predictor not in (1, 3):\n            raise GeoidError(\"compression de grille non prise en charge\")\n        if t.get(34735) and dict(zip(t[34735][4::4], t[34735][7::4])).get(1025) != 2:\n            raise GeoidError(\"grille attendue aux nœuds (PixelIsPoint)\")\n        self.dx, self.dy = t[33550][0], t[33550][1]\n        self.lon0, self.lat0 = t[33922][3], t[33922][4]\n        tw, th = t[322][0], t[323][0]\n        across = (self.cols + tw - 1) // tw\n        self.values = [[0.0] * self.cols for _ in range(self.rows)]\n        for k, (start, size) in enumerate(zip(t[324], t[325])):\n            raw = data[start:start + size]\n            if compression == 8:\n                raw = zlib.decompress(raw)\n            ty, tx = divmod(k, across)\n            for r in range(th):\n                row = ty * th + r\n                if row >= self.rows:\n                    break\n                line = raw[r * tw * 4:(r + 1) * tw * 4]\n                if predictor == 3:  # octets différenciés, rangés par plan (poids fort d'abord)\n                    line = bytes(v & 0xFF for v in accumulate(line))\n                    line = bytes(b for i in range(tw) for b in (line[i], line[tw + i], line[2 * tw + i],\n                                                                 line[3 * tw + i]))\n                    values = struct.unpack(\">\" + \"f\" * tw, line)\n                else:\n                    values = struct.unpack(bo + \"f\" * tw, line)\n                for c in range(tw):\n                    col = tx * tw + c\n                    if col < self.cols:\n                        self.values[row][col] = values[c]\n\n    def undulation(self, lon, lat):\n        \"\"\"Ondulation du géoïde (m) au point, ou None hors de la grille.\"\"\"\n        x, y = (lon - self.lon0) / self.dx, (self.lat0 - lat) / self.dy\n        if not (0 <= x <= self.cols - 1 and 0 <= y <= self.rows - 1):\n            return None\n        i, j = min(int(x), self.cols - 2), min(int(y), self.rows - 2)\n        fx, fy = x - i, y - j\n        v = self.values\n        return ((v[j][i] * (1 - fx) + v[j][i + 1] * fx) * (1 - fy)\n                + (v[j + 1][i] * (1 - fx) + v[j + 1][i + 1] * fx) * fy)\n\n\ndef ngf_altitude(grid, lon, lat, ellipsoidal):\n    \"\"\"Altitude NGF-IGN69 (m) d'un point d'altitude ellipsoïdale, ou None (pas de grille, hors\n    de France, valeur invraisemblable).\"\"\"\n    if grid is None or ellipsoidal is None:\n        return None\n    n = grid.undulation(float(lon), float(lat))\n    if n is None or not GEOID_RANGE[0] <= n <= GEOID_RANGE[1]:\n        return None\n    return float(ellipsoidal) - n\n",
 "web_app.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Application de mesure dans le navigateur : la session de mesure du cœur\n(core/session.py), reliée à la page (src/app.js), qui en appelle les méthodes ; les résultats\nsont rendus en JSON (texte). Ce qui est propre à la page reste ici : services du navigateur\n(web_host), dessin de la carte en GeoJSON, filtre des photos, calage enregistré dans le\nnavigateur, exports CSV et GeoJSON, capture Full HD. Quand une lecture réseau ou un calcul\naboutit après coup, la session appelle notify() pour que la page se redessine.\n\"\"\"\n\nimport json\nimport math\nimport re\nfrom datetime import datetime\n\nimport web_host\nfrom web_chutes import Chutes, _WAY_KINDS, _deck_at, platform_slope  # noqa: F401 (essais)\nfrom web_nez import Nez\nfrom web_pose import Pose\nfrom core import (autotilt, calibration, capture, filters, host, measures, metadata, precision, roads, session, tools,\n                  triangulation, widths)\nfrom core.session import GROUND_MODES, MODES  # noqa: F401 (modes de la page)\n\n\n# Axe de la route tiré de la trajectoire RTK (voir App._road_at_reference) : sur ±20 m, la position\n# RTK (quelques cm) n'y compte presque pas ; reste l'écart du véhicule à la route, au plus ~0,2 m\nAXIS_ERROR_RTK = 0.5  # degrés\nRTK_SOURCE = \"trajectoire RTK\"\nTRACK_STRAIGHT = 0.10  # m : écart type des photos à leur droite au plus (route droite, pas de changement de voie)\nTRACK_SPAN = 20.0  # m de trajectoire au moins\nTRACK_AGREE = 2.0  # degrés au plus entre la trajectoire et le tronçon de la BD TOPO\n# Droite de mesure tracée sur la mini-carte (ticket #28, App.set_measure_line) : son orientation est\n# connue à l'angle sous lequel MAP_CLICK m d'erreur sur chaque clic voient la longueur tracée\nMAP_SOURCE = \"tracé sur la carte\"\nMAP_LINE_MIN = 4.0  # m au moins entre les deux clics\nMAP_CLICK = 0.3  # m : précision d'un clic sur la mini-carte zoomée\nMAP_HEADING_ERROR = 0.3  # degrés : cap EXIF des photos de relevé (point A posé sur la droite)\nMAP_MIN_ANGLE = 10.0  # degrés au moins entre la visée de A et la droite tracée\n# Relevé : objet posé sur une seule photo (App.releve_single), si la visée descend assez sous l'horizon\nSINGLE_MIN_ELEV = 2.0  # degrés : objet à 70 m au plus pour une caméra à 2,5 m\n# Objet relevé posé d'un clic sur la mini-carte (App.keep_map) : précision des orthophotos IGN (environ 1 m)\nMAP_PLACE_ERROR = 1.0  # m\n# Visées des autres photos tracées dans la photo affichée (Session._epipolar_mark) : sans leurs premiers\n# mètres, vus très en biais, projetés à des milliers de pixels hors de l'écran et redessinés à chaque\n# image par la visionneuse (lenteur, surtout zoomé)\nEPIPOLAR_START = 2.0  # m depuis la caméra de la visée\nEPIPOLAR_NEAR = 3.0  # m au moins de la caméra de la photo affichée\n_core_axis_error = widths.axis_error\n\n\ndef _axis_error(source):\n    \"\"\"widths.axis_error, avec l'axe tiré de la trajectoire RTK ou la droite tracée sur la carte.\"\"\"\n    if source and source.startswith(RTK_SOURCE):\n        return AXIS_ERROR_RTK\n    if source and source.startswith(MAP_SOURCE):  # « tracé sur la carte, ±1,7° »\n        return float(source.rsplit(\"±\", 1)[1].rstrip(\"°\").replace(\",\", \".\"))\n    return _core_axis_error(source)\n\n\nwidths.axis_error = _axis_error  # appelée par les largeurs du cœur\n\n\ndef _straight_track_axis(features, sequence, lon, lat):\n    \"\"\"Direction (degrés, modulo 180) de la trajectoire de la séquence à moins de\n    roads.TRACK_RADIUS m de (lon, lat), si elle est droite (TRACK_STRAIGHT) sur TRACK_SPAN m au\n    moins ; None sinon. Passages aller et retour (sens de la photo) ajustés chacun sur sa voie,\n    avec une direction commune.\"\"\"\n    passes = {}  # sens de roulage -> positions (m)\n    first = None\n    for feat in (features or {}).get(\"features\") or []:\n        heading = metadata.item_heading(feat)\n        if feat.get(\"collection\") != sequence or heading is None:\n            continue\n        try:\n            x, y = triangulation._local(*(float(v) for v in feat[\"geometry\"][\"coordinates\"][:2]), lon, lat)\n        except (KeyError, TypeError, ValueError):\n            continue\n        if math.hypot(x, y) <= roads.TRACK_RADIUS:\n            first = heading if first is None else first\n            passes.setdefault(math.cos(math.radians(heading - first)) >= 0, []).append((x, y))\n    pts = []  # positions centrées sur leur passage\n    for group in passes.values():\n        mx, my = sum(p[0] for p in group) / len(group), sum(p[1] for p in group) / len(group)\n        pts += [(x - mx, y - my) for x, y in group]\n    if len(pts) < 5:\n        return None\n    sxx, syy, sxy = sum(x * x for x, _ in pts), sum(y * y for _, y in pts), sum(x * y for x, y in pts)\n    angle = 0.5 * math.atan2(2 * sxy, sxx - syy)  # depuis l'est, sens trigonométrique\n    ux, uy = math.cos(angle), math.sin(angle)\n    along = [x * ux + y * uy for x, y in pts]\n    across = [y * ux - x * uy for x, y in pts]\n    if max(along) - min(along) < TRACK_SPAN or math.sqrt(sum(d * d for d in across) / len(pts)) > TRACK_STRAIGHT:\n        return None\n    return (90.0 - math.degrees(angle)) % 180\n\n\ndef _length_text(value, sigma):\n    \"\"\"« 7,60 m ± 0,38 m », ou « 7,60 m hors vue » (longueur sur le fond de carte seul, voir App.add_map_length).\"\"\"\n    return \"{} m {}\".format(measures._num(value, 2), \"hors vue\" if sigma is None else \"± {} m\".format(measures._num(sigma, 2)))\n\n\ndef _area_text(area):\n    \"\"\"« 123,4 m² » (surface sur la carte, voir App.add_map_area).\"\"\"\n    return \"{} m²\".format(measures._num(area, 1))\n\n\nclass WebItem:\n    \"\"\"Dessin d'une mesure sur la carte (voir measures.MeasureTool.new_item) : gardé ici, rendu\n    en GeoJSON par App.map_geojson.\"\"\"\n\n    def __init__(self):\n        self.points, self.label, self.extras = [], \"\", []\n        self.removed = False\n\n    def set_data(self, points, label=\"\", extras=None):\n        self.points, self.label, self.extras = list(points), label, list(extras or [])\n\n    def remove(self):\n        self.removed = True\n\n\nclass RaysItem:\n    \"\"\"Visées de la triangulation sur la carte : voir tools.Triangulator.new_item.\"\"\"\n\n    def __init__(self):\n        self.rays, self.point = [], None\n        self.removed = False\n\n    def set_data(self, rays, point):\n        self.rays, self.point = list(rays), point\n\n    def remove(self):\n        self.removed = True\n\n\nclass RankPrecisionChecker(precision.PrecisionChecker):\n    \"\"\"Vérification de la position RTK (voir precision.PrecisionChecker) dont les autres portions de la\n    séquence, essayées quand celle de la photo échoue, sont prises par rang : RANK_STEP photos avant et\n    après. Le cœur les cherche parmi les 100 photos de la séquence les plus proches, toutes au même\n    endroit quand elle y passe plusieurs fois : sur un pont (le LiDAR donne le terrain sous le tablier),\n    aucune autre portion n'était essayée et toute la séquence restait non vérifiée.\"\"\"\n    RANK_STEP = 150\n\n    def __init__(self):\n        super().__init__()\n        self._items = {}  # séquence -> photo dont la vérification a été demandée (rang, adresse de la séquence)\n\n    def _check_sequence(self, item, sequence, lon, lat, done):\n        self._items[sequence] = item\n        super()._check_sequence(item, sequence, lon, lat, done)\n\n    def _other_portions(self, sequence, lon, lat, failed, done):\n        item = self._items.get(sequence) or {}\n        links = {l.get(\"rel\"): l.get(\"href\") or \"\" for l in item.get(\"links\") or []}\n        base = links.get(\"collection\", \"\")\n        if base.startswith(web_host.API_URL):  # le méta-catalogue ignore les rangs : instance d'origine (« via »)\n            base = links.get(\"via\") and \"{}/api/collections/{}\".format(links[\"via\"].rstrip(\"/\"), sequence)\n        rank = (item.get(\"properties\") or {}).get(\"geovisio:rank_in_collection\")\n        if not base or not isinstance(rank, int):\n            return super()._other_portions(sequence, lon, lat, failed, done)\n        ranks = [r for r in (rank + self.RANK_STEP, rank - self.RANK_STEP) if r >= 1]\n        tried, unread = [0], [0]\n\n        def next_portion():\n            if not ranks:\n                plural = \"s\" if tried[0] > 1 else \"\"\n                done(dict(failed, reason=\"{} ; {} autre{p} portion{p} de la séquence non vérifiée{p}\".format(\n                    failed[\"reason\"], tried[0], p=plural)) if tried[0]\n                     else dict(failed, transient=True) if unread[0] else failed)  # rien lu : à refaire plus tard\n                return\n            r = ranks.pop(0)\n\n            def got_item(data, error):\n                if error:  # au-delà de la fin de la séquence (HTTP 404), ou instance injoignable\n                    unread[0] += 1\n                    next_portion()\n                    return\n                feats = (data or {}).get(\"features\") or []\n                try:\n                    clon, clat = (float(v) for v in feats[0][\"geometry\"][\"coordinates\"][:2])\n                except (IndexError, KeyError, TypeError, ValueError):\n                    next_portion()  # au-delà de la fin de la séquence\n                    return\n\n                def got(kind, value):\n                    if kind in (\"photos\", \"ground\"):\n                        done(dict(failed, transient=True))\n                    elif kind == \"result\" and value[\"precise\"]:\n                        done(dict(value, reason=\"{}, à {:.0f} m de la photo (même séquence)\".format(\n                            value[\"reason\"], round(precision._metres((clon, clat), (lon, lat)), -1))))\n                    else:\n                        tried[0] += 1\n                        next_portion()\n\n                self._portion(sequence, clon, clat, got)\n\n            host.fetch_json(\"{}/items?limit=1&startAfterRank={}\".format(base.rstrip(\"/\"), r - 1), got_item)\n\n        next_portion()\n\n\nclass App(Pose, Chutes, Nez, session.Session):\n    def __init__(self, notify, remote=None, api_url=web_host.API_URL):\n        web_host.install(remote, api_url)\n        if remote is not None:\n            autotilt.HAS_NUMPY = True  # verticales calculées dans le Pyodide d'arrière-plan, qui a numpy\n        super().__init__(notify, precision_checker=RankPrecisionChecker())\n        self.mode = \"height\"  # mode de départ : première option de la liste Mode (index.html)\n        self.tool.set_mode(self.mode)\n        self.items, self.rays = [], []\n        self.tool.new_item = self._new_item\n        self.triangulator.new_item = self._new_rays\n        self.photo_filter = filters.PhotoFilter()\n        self.aim_frame = False  # photo affichée pas encore tournée vers le point à viser (take_aim_frame)\n        # Calage de l'inclinaison : pied et sommet de l'objet vertical cliqués, gardés ici jusqu'à\n        # « Valider l'objet vertical » (le cœur cale dès le second clic, sans laisser les voir ni\n        # les déplacer) ; indice de la croix sélectionnée pour être déplacée, ou None\n        self.tilt_clicks, self.tilt_sel = [], None\n        self.fall_cells = {}  # maille -> tronçons BD TOPO avec leur largeur (hauteur de chute, voir fall)\n        self.falls = {}  # (séquence, pont) -> hauteur de chute calculée (dict text, title) ou en cours\n        self.lidar_falls = {}  # tronçon du pont -> réponse du nuage LiDAR (use_bridge_lidar)\n        self.edges = {}  # (photo, largeur examinée) -> chute et dévers des bords de route (voir _edges)\n        self.paved = {}  # repère du profil -> bords d'enrobé de l'analyse fine (use_paved_edges)\n        self.paved_redo = {}  # repère du profil -> (clé de self.edges, calcul à refaire sans relire le terrain)\n        self.edges_asked = {}  # photo -> largeur examinée au dernier appui sur « Profils »\n        self.long_tracks = {}  # photo -> trajectoire de la caméra autour d'elle (_track_line), None pendant la lecture\n        self.edge_zone = self.EDGE_ZONE\n        self.bdtopo = {}  # (couche BD TOPO, maille) -> objets lus (voir _bdtopo)\n        self.fall_error = {}  # maille -> raison du dernier échec de lecture des tronçons (dite dans le message)\n        self.fall_retry = {}  # maille -> instant du nouvel essai après un échec de lecture des tronçons\n        self.bdtopo_retry = {}  # (couche BD TOPO, maille) -> instant du nouvel essai après un échec\n        self.map_line = None  # droite de mesure tracée sur la carte, pour le prochain point A (ticket #28)\n        # Longueurs mesurées sur la vue du dessus (src/dessus.js), mode « carte » : rien à viser dans la photo\n        # Longueurs et surfaces de la carte : {\"ends\": [[lon, lat], …] (2 points ; une surface : son contour ouvert),\n        # \"valeur_m\" (une surface : son périmètre), \"incert_m\", \"photos\", \"commentaire\", \"surface_m2\" (surfaces seules)}\n        self.map_lengths = []\n        self.map_mode = False\n        self.redo_stack, self.redo_key = [], None  # états d'avant chaque « Effacer » (Ctrl+Y, voir redo)\n        self.overlay = []  # couche importée : (n° de l'objet, \"point\" ou \"ligne\", [(lon, lat, z)]), voir set_overlay\n        self.overlay_ground = {}  # (lon, lat) -> altitude LiDAR HD ou None (absente), sommets et caméras (_overlay_ground)\n        self.overlay_asked = set()  # (lon, lat) dont l'altitude est en cours de lecture\n        self.point_ground = {}  # (lon, lat caméra, lon, lat point) -> (z caméra, z point) ou None (_point_ground)\n        self.nose_ground = {}  # (lon, lat, axe, direction, d) -> (source, sigma, [(décalage, dz)]), {} en lecture, None indisponible (_nose_ground)\n        self.nose_ground_last = None  # (caméra et distance, relief) du dernier relief lu : sert pendant le glissement de la rotation\n        self.tilt_reasons = {}  # photo -> raison de l'échec de l'inclinaison automatique (ticket #29)\n        self.birdeye_loose = {}  # photo -> verticales refusées pour les mesures, gardées pour la vue du dessus (web_tilt.LOOSE_SIGMA)\n        self.birdeye_ground = {}  # photo -> inclinaison de la vue du dessus tirée de la route : {up, sigma, manual} (birdeye_tilt_set)\n        self.tilts.run = self._run_tilt\n        # Inclinaison par le terrain hors agglomération, expérimentale (option, voir web_terrain)\n        self.terrain_relay = False\n        self.relay_tilts = {}  # photo -> inclinaison par le terrain (dict comme Calibration.auto_tilt)\n        self.birdeye_items, self.birdeye_checks = [], (autotilt.TiltChecker(), autotilt.TiltChecker())  # voir birdeye_neighbours\n        self.birdeye_far_items = []  # voir birdeye_far\n        self.relay_pending = {}  # photo -> étape du calcul en cours\n        self.relay_failed = {}  # photo -> raison de l'échec\n        self.relay_models = {}  # séquence -> références, modèle (web_terrain.model), raison d'un échec\n        self._core_auto_tilt = self.calibration.auto_tilt\n        self.calibration.auto_tilt = self._auto_tilt\n        # Relevé d'objets (mode \"releve\" de la page) : la mesure libre du cœur, sans distance entre les\n        # points, chacun gardé avec les champs saisis par l'utilisateur (values[\"releve\"])\n        self.releve = False\n\n    # Données pour la page (JSON) -------------------------------------------------------\n    def set_picture(self, item_json):\n        \"\"\"Photo affichée dans la visionneuse : sa fiche STAC (texte JSON).\"\"\"\n        self.aim_frame = True\n        return super().set_picture(json.loads(item_json))\n\n    def set_active(self, on):\n        \"\"\"Bouton « Mesure » : l'inclinaison automatique de la photo est calculée dès l'activation,\n        pas au premier clic comme dans le cœur (_check_tilt), qui la lance encore au premier clic\n        sur une autre photo.\"\"\"\n        super().set_active(on and not self.map_mode)  # mesure sur la carte : clics dans la photo sans effet\n        self._check_tilt()  # rien hors mesure, en mesure libre ou si déjà calculée\n        return self.status()\n\n    def state(self):\n        out = dict(super().state(), tilt_ready=self._tilt_pending() and len(self.tilt_clicks) == 2)\n        out[\"tilt_reason\"] = self._tilt_reason()\n        # Effacer, Refaire, Tout effacer : grisés quand ils n'auraient pas d'effet\n        single = self.releve_single()  # relevé : objet sur cette seule photo, à proposer avec sa précision\n        out[\"single_m\"] = round(single[2], 2) if single else None\n        out.update(can_undo=self._can_undo(), can_redo=bool(self.redo_stack) and self._redo_state() == self.redo_key,\n                   can_clear=self._can_clear())\n        if self.item:  # inclinaison de la ligne d'état : textes du web (_tilt_line), pas ceux du cœur\n            text, alert = self._tilt_line()\n            quality = precision.state_text(self.quality, metadata.item_accuracy(self.item), (text, False))\n            out[\"quality\"] = \"⚠ \" + quality if alert and not quality.startswith(\"⚠\") else quality\n        return json.dumps(out)\n\n    # Mesures faites : seulement sur leur photo (ticket #24) ---------------------------------------\n    # Projetées sur les autres photos, elles y paraissent décalées. Le cœur les montre partout :\n    # le filtre ne vaut que pour les repères de la visionneuse et la sélection des croix, pas pour\n    # la carte ni les résultats.\n    here_only = False\n\n    def _here(self):\n        return (self.item or {}).get(\"id\")\n\n    def _heights(self):\n        heights = super()._heights()\n        return [m for m in heights if m.clicks[0].get(\"pic\") == self._here()] if self.here_only else heights\n\n    def _height_points(self, m):\n        \"\"\"Session._height_points, mais sur la photo de la mesure, chaque point au cap où il a été cliqué :\n        calée sur le point de référence, la hauteur décale son sommet sur le côté quand le pied change de\n        profondeur (même écart latéral en mètres, vu de plus près ou de plus loin), alors que sa valeur ne\n        dépend que de l'élévation ; les hauteurs suivantes resteraient hors de la ligne de la première.\"\"\"\n        pts = super()._height_points(m)\n        if (self.item or {}).get(\"id\") == m.clicks[0].get(\"pic\"):\n            for p, c in zip(pts, m.clicks):\n                pos, raw = c.get(\"pos\") or [None, None], c.get(\"raw\")\n                if pos[0] is not None:\n                    p[\"yaw\"] = pos[0]\n                    if raw:\n                        p[\"abs_yaw\"] = raw[0] % 360\n            _keep_view(m, pts)\n        return pts\n\n    def _widths(self):\n        found = super()._widths()\n        return [m for m in found if m.clicks[1].get(\"pic\") == self._here()] if self.here_only else found\n\n    def _free_mark_point(self, k):\n        \"\"\"Point gardé de la mesure libre : seulement là où il a été visé (sans repère ailleurs). Objet\n        relevé : sur toutes les photos, projeté au sol, à OVERLAY_REACH m au plus (comme la couche).\"\"\"\n        lon, lat, values = self.points[k]\n        if \"releve\" in values and self.item:\n            camera = [float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2]]\n            x, y = triangulation._local(lon, lat, *camera)\n            if math.hypot(x, y) <= self.OVERLAY_REACH:\n                view = self.point_views.get(values[\"nom\"], {}).get(self._here())\n                alt = (host.ngf_altitude(*camera, metadata.item_altitude(self.item))\n                       if (self.quality or {}).get(\"precise\") else None)\n                if view is None and values.get(\"z_ngf\") is not None and alt is not None:\n                    # à son altitude, vue depuis la caméra de cette photo (RTK) : pas ramené au sol\n                    seen = self._view_of(math.degrees(math.atan2(x, y)),\n                                         math.degrees(math.atan2(values[\"z_ngf\"] - alt, max(math.hypot(x, y), 0.5))))\n                    return {\"pic\": self._here(), \"yaw\": seen[\"yaw\"], \"pitch\": seen[\"pitch\"]}\n                return super()._free_mark_point(k)  # visé d'ici, sinon projeté au sol\n        if self.here_only and self._here() not in self.point_views.get(values[\"nom\"], {}):\n            return {\"pic\": self._here(), \"yaw\": None, \"pitch\": None}\n        return super()._free_mark_point(k)\n\n    def _free_marks(self):\n        # distance : seulement sur une photo d'où ses deux points ont été visés\n        return [m for m in super()._free_marks() if all(p[\"yaw\"] is not None for p in m[\"points\"])]\n\n    def _filtered(self, method, *args):\n        self.here_only = True\n        try:\n            return method(*args)\n        finally:\n            self.here_only = False\n\n    def _height_near(self, click):\n        return self._filtered(super()._height_near, click)\n\n    # Croix sous le clic : la page le sait en pixels (CROSS_PX autour de la croix, quel que soit le zoom), le calcul\n    # seulement en degrés (measures.SELECT_ANGLE : une centaine de pixels quand on zoome). cross_hit : True, False, ou\n    # None (pas d'information : essais, plugin) ; quand la page a vu une croix, la plus proche à CROSS_REACH° au plus\n    CROSS_REACH = 10.0\n    cross_hit = None\n\n    _picks = None  # liste : _nearest y relève ses candidats au lieu de chercher (pick_points)\n\n    def pick_points(self):\n        \"\"\"JSON [[cap, élévation]] (radians, repère de la photo) des croix qu'un clic sélectionnerait dans le mode en cours :\n        celles que cherche _nearest (hauteurs et point de référence, largeurs), ou celles du calage de l'inclinaison. La\n        page les teste en pixels (on_cross) : une croix d'un autre mode ou de visée ne compte pas.\"\"\"\n        if not (self.active and self.item) or self._aiming():\n            return \"[]\"\n        if self.mode == \"tilt\":\n            return json.dumps([list(c[\"pos\"][:2]) for c in self.tilt_clicks if self._tilt_pending()])\n        self._picks, probe = [], {\"raw\": [0.0, 0.0]}\n        try:\n            if self.mode == \"height\":\n                self._height_near(probe)\n                self._ref_near(probe)\n            elif self.mode == \"road\":\n                self._width_near(probe)\n            picks = self._picks\n        finally:\n            self._picks = None\n        heading = self._heading()\n        return json.dumps([[math.radians((p[\"abs_yaw\"] - heading + 540) % 360 - 180), math.radians(p[\"elev\"])]\n                           for p in picks if p.get(\"abs_yaw\") is not None and p.get(\"elev\") is not None])\n\n    def _nearest(self, click, candidates):\n        if self._picks is not None:\n            self._picks += [p for _, points in candidates for p in points]\n            return None\n        if self.cross_hit is None:\n            return super()._nearest(click, candidates)\n        if not self.cross_hit:\n            return None\n        raw = click.get(\"raw\") or [click[\"yaw\"], click[\"elev\"]]  # comme Session._nearest, à CROSS_REACH° au plus\n        best, best_d = None, self.CROSS_REACH\n        for m, points in candidates:\n            for index, p in enumerate(points):\n                dyaw = (raw[0] - p[\"abs_yaw\"] + 540) % 360 - 180\n                d = math.hypot(dyaw * math.cos(math.radians(raw[1])), raw[1] - p[\"elev\"])\n                if d < best_d:\n                    best, best_d = (m, index), d\n        return best\n\n    def _with_cross(self, on_cross, method, *args):\n        \"\"\"method(*args), la croix sous le clic connue de la page (on_cross, ou None).\"\"\"\n        self.cross_hit = None if on_cross is None else bool(on_cross)\n        try:\n            return method(*args)\n        finally:\n            self.cross_hit = None\n\n    def select_point(self, yaw, pitch, on_cross=None):\n        return self._with_cross(on_cross, super().select_point, yaw, pitch)\n\n    def _width_near(self, click):\n        return self._filtered(super()._width_near, click)\n\n    def _epipolar_mark(self, s):\n        \"\"\"Session._epipolar_mark raccourcie : de EPIPOLAR_START m (pas 0,5 m) depuis la caméra de la visée\n        jusqu'un peu au-delà du sol touché (80 m au plus), sans les points à moins de EPIPOLAR_NEAR m de\n        la caméra affichée (caméras à la hauteur de celle-ci, au-dessus d'un sol plat).\"\"\"\n        lon, lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n        height = self._camera_height()\n        sx, sy = triangulation._local(s[\"lon\"], s[\"lat\"], lon, lat)\n        a, e = math.radians(s[\"heading\"]), math.radians(s.get(\"elev\") or 0.0)\n        reach = 80.0 if e >= -0.002 else min(80.0, height / -math.tan(e) * 1.2 + 1.0)\n        reach = max(reach, EPIPOLAR_START * 1.5)\n        points = []\n        for k in range(41):  # pas plus serrés près de la caméra de la visée\n            t = EPIPOLAR_START * (reach / EPIPOLAR_START) ** (k / 40)\n            x, y, z = sx + t * math.sin(a), sy + t * math.cos(a), t * math.tan(e)\n            d = math.hypot(x, y)\n            if d < EPIPOLAR_NEAR:\n                continue\n            view = self._view_of(math.degrees(math.atan2(x, y)), math.degrees(math.atan2(z, d)))\n            points.append({\"pic\": self.item.get(\"id\"), \"yaw\": view[\"yaw\"], \"pitch\": view[\"pitch\"]})\n        return {\"points\": points, \"guide\": True, \"epipolar\": True}\n\n    def viewer_marks(self):\n        marks = self._filtered(super().viewer_marks)\n        if self.item and json.loads(self.axis_state())[\"drawn\"]:\n            marks.insert(0, self._line_mark())  # droite tracée sur la carte, avant le point A\n        if self.active and self.item and self.mode == \"height\" and self._aiming():\n            # Visées des autres photos tracées aussi en hauteur (le cœur : largeur, mesure libre) :\n            # le pied visé est sur leur trait, même parmi des objets semblables (ticket #26)\n            pic = self.item.get(\"id\")\n            lines = [self._epipolar_mark(s)[\"points\"] for s in self.triangulator.sightings if s[\"pic\"] != pic]\n            marks = [{\"points\": [[p[\"yaw\"], p[\"pitch\"], False] for p in pts], \"label\": \"\", \"guide\": True,\n                      \"epipolar\": True} for pts in lines if pts] + marks\n        if self._tilt_pending():  # objet vertical en cours (croix et trait du calage), effacé une fois validé\n            marks.append({\"points\": [c[\"pos\"] + [k == self.tilt_sel] for k, c in enumerate(self.tilt_clicks)],\n                          \"label\": \"\", \"calage\": True})\n        return json.dumps(marks)\n\n    def focus(self):\n        return json.dumps(super().focus())\n\n    def handles(self):\n        return json.dumps(super().handles())\n\n    def results(self):\n        \"\"\"Liste des résultats (ticket #30) : une entrée par point de référence, ses hauteurs et\n        largeurs dessous (« sous »), nommées par leur point d'arrivée : « ↕ B 3,77 m ± 0,12 m ».\n        Les autres points gardés et les distances n'y figurent pas (ils restent exportés).\"\"\"\n        rows = super().results()\n        measures_by_id = {id(m): m for m in self.tool.measures()}\n        under = {}  # nom du point de référence -> lignes de ses mesures\n        orphans = []  # mesure sans point de référence gardé : gardée visible, à la fin\n        for r in rows:\n            m = measures_by_id.get(r[\"id\"]) if r[\"kind\"] == \"mesure\" else None\n            if m is None:\n                continue\n            end = self._end_name(m)\n            if end:\n                r = dict(r, text=\"{}{} {}\".format(r[\"text\"][:2], end[\"name\"], r[\"text\"][2:]))\n            ref = (getattr(m, \"edge\", None) or getattr(m, \"reference\", None) or {}).get(\"name\")  # largeur : bord A\n            under.setdefault(ref, []).append(dict(r, sous=True))\n        current = (self.ref_point or {}).get(\"name\")\n        out = []\n        for r in rows:\n            if r[\"kind\"] != \"point\":\n                continue\n            lon, lat, values = self.points[r[\"id\"]]\n            name = values[\"nom\"]\n            if \"releve\" in values:  # objet relevé : son nom, sa précision et son premier champ\n                first = next((v for v in values[\"releve\"].values() if v not in (None, \"\")), None)\n                where = \"sur la carte\" if values[\"nb_visees\"] == 0 else \"±{} m\".format(measures._num(values[\"incert_m\"], 2))\n                r = dict(r, releve=True, lonlat=[lon, lat], text=\"Objet {} {}{}\".format(\n                    name, where, \"\" if first is None else \" — {}\".format(_field_text(first))))\n                out.append(r)\n            elif name in under or name == current:\n                out += [r] + under.pop(name, [])\n        for subs in under.values():\n            orphans += [dict(r, sous=False) for r in subs]\n        lengths = [{\"id\": k, \"kind\": \"longueur\",\n                    \"text\": (\"▱ {} (carte)\".format(_area_text(v[\"surface_m2\"])) if \"surface_m2\" in v\n                             else \"↔ {} (carte)\".format(_length_text(v[\"valeur_m\"], v[\"incert_m\"]))),\n                    \"comment\": v[\"commentaire\"]} for k, v in enumerate(self.map_lengths)]\n        return json.dumps(out + orphans + lengths)\n\n    # Fiche PDF d'un point de référence (src/fiche.js, makeFiche) ------------------------------------\n    def _fiche_measures(self, name):\n        \"\"\"Hauteurs et largeurs faites depuis le point de référence nommé name.\"\"\"\n        return [m for m in self.tool.measures() if m.result\n                and (getattr(m, \"edge\", None) or getattr(m, \"reference\", None) or {}).get(\"name\") == name]\n\n    def fiche(self, k):\n        \"\"\"JSON de la fiche du point gardé n° k et de ses mesures : nom, position, lignes du tableau\n        (point, mesure, valeur, incertitude, commentaire), textes de méthode (ceux des mesures),\n        photo de la plus grande mesure (celle de la fiche) et emprise de la mini-carte (points,\n        mesures et caméra de cette photo).\"\"\"\n        lon, lat, values = self.points[int(k)]\n        name = values[\"nom\"]\n        found = self._fiche_measures(name)\n        kept = {v[\"nom\"]: v for _, _, v in self.points}\n\n        def point_row(v, what):  # point gardé (A, ou le bord B triangulé) : sa ligne, comme A\n            how = \"posé sur la droite tracée sur la carte\" if v.get(\"nb_visees\") == 1 else \"triangulé\"\n            return {\"kind\": \"point\", \"point\": v[\"nom\"], \"mesure\": \"{}, {}\".format(what, how), \"valeur\": \"\",\n                    \"incert\": \"± {} m\".format(measures._num(v[\"incert_m\"], 2)), \"commentaire\": v.get(\"commentaire\", \"\")}\n\n        # Le point de référence, puis pour chaque mesure son point d'arrivée (comme A s'il est\n        # triangulé, sinon cliqué sur la photo) et, dessous, la mesure elle-même\n        rows = [point_row(values, \"Point de référence\")]\n        texts, lonlats = [], [(lon, lat)]\n        for m in found:\n            r, end = m.result, self._end_name(m)\n            height = m.kind == \"height\"\n            end_name = end[\"name\"] if end else \"?\"\n            if end_name in kept and not height:\n                rows.append(point_row(kept[end_name], \"Bord opposé\"))\n            else:\n                rows.append({\"kind\": \"point\", \"point\": end_name, \"valeur\": \"\", \"incert\": \"\", \"commentaire\": \"\",\n                             \"mesure\": \"Sommet, cliqué sur la photo\" if height else \"Bord opposé, cliqué sur la photo\"})\n            rows.append({\"kind\": \"mesure\", \"point\": \"{} {} {}\".format(name, \"↕\" if height else \"↔\", end_name),\n                         \"mesure\": \"{} entre {} et {}\".format(\"Hauteur\" if height else \"Largeur\", name, end_name),\n                         \"valeur\": \"{} m\".format(measures._num(r[\"value\"], 2)),\n                         \"incert\": \"± {} m\".format(measures._num(r[\"uncertainty\"], 2)),\n                         \"commentaire\": getattr(m, \"comment\", \"\")})\n            texts.append(self._fiche_note(m, rows[-1][\"point\"]))\n            lonlats += [tuple(p) for p in r[\"points\"]]\n        largest = max(found, key=lambda m: m.result[\"value\"], default=None)\n        if largest is not None:\n            pic = largest.clicks[0 if largest.kind == \"height\" else 1].get(\"pic\")  # photo d'où elle a été prise\n        else:\n            pic = next(iter(self.point_views.get(name, {})), None) or values.get(\"photos\", \"\").split(\",\")[0] or None\n        item = self.photo_items.get(pic) if pic else None\n        if item is not None:\n            lonlats.append(tuple(float(v) for v in item[\"geometry\"][\"coordinates\"][:2]))\n        xs, ys = [p[0] for p in lonlats], [p[1] for p in lonlats]\n        return json.dumps({\"name\": name, \"lon\": lon, \"lat\": lat, \"rows\": rows, \"texts\": _without_repeats(texts), \"photo\": pic,\n                           \"kind\": largest.kind if largest is not None else None,\n                           \"bounds\": [[min(xs), min(ys)], [max(xs), max(ys)]]}, ensure_ascii=False)\n\n    def _fiche_note(self, m, label):\n        \"\"\"(label, morceaux) de la ligne courte de « Méthode et précision » pour la mesure m (fiche) : ce\n        qui n'est pas dans le tableau. Hauteur : distance de l'objet, hauteur de caméra ; largeur : axe,\n        angle de visée.\"\"\"\n        if m.kind == \"height\":\n            item = self.photo_items.get(m.clicks[0].get(\"pic\"))\n            height, source, _ = self.camera_of(item, self.precision.known(item)) if item else (self.tool.camera_height, None, 0)\n            parts = [\"objet à {} m de la photo\".format(measures._num(m.result[\"ranges\"][0], 1)),\n                     \"caméra à {} m{}\".format(measures._num(height, 2), \" ({})\".format(source) if source else \"\")]\n        else:\n            axis = (m.road or {}).get(\"source\", \"\")\n            if axis.startswith(MAP_SOURCE):\n                parts = [\"droite tracée sur la carte ({})\".format(axis.split(\", \", 1)[-1])]\n            else:\n                parts = [\"axe de la route : {}\".format(axis)]\n            if m.angle is not None:\n                parts.append(\"visée à {}° de la droite{}\".format(\n                    measures._num(m.angle, 0), \" (rasante)\" if m.angle < widths.GRAZING_ANGLE else \"\"))\n        return label, parts\n\n    def fiche_frame(self, k):\n        \"\"\"JSON [[cap, élévation]] (radians, repère de la photo affichée) des bouts de la plus grande\n        mesure du point gardé n° k, pour cadrer la photo de la fiche ; [] s'il n'y en a pas ici.\"\"\"\n        name = self.points[int(k)][2][\"nom\"]\n        found = self._fiche_measures(name)\n        largest = max(found, key=lambda m: m.result[\"value\"], default=None)\n        if largest is None or not self.item:\n            return \"[]\"\n        pts = (self._height_points if largest.kind == \"height\" else self._width_points)(largest)\n        return json.dumps([[p[\"yaw\"], p[\"pitch\"]] for p in pts if p[\"yaw\"] is not None])\n\n    # Relevé d'objets (mode \"releve\") ------------------------------------------------------------\n    def keep_point(self):\n        \"\"\"Relevé : point triangulé gardé comme objet, sans distance au précédent ; la page demande\n        ensuite ses champs (set_releve).\"\"\"\n        if not self.releve:\n            return super().keep_point()\n        n, r, sightings = len(self.points), self.triangulator.result, list(self.triangulator.sightings)\n        self.last_free = None\n        super().keep_point()\n        self.last_free = None\n        if len(self.points) > n:\n            self._releve_kept(_aimed_z(r, sightings))\n        return self.status()\n\n    def _releve_kept(self, z=None):\n        \"\"\"Dernier point gardé devenu objet relevé ; z : altitude NGF du point visé (m) ou None.\"\"\"\n        values = self.points[-1][2]\n        values[\"id\"] = 1 + max((v.get(\"id\") or 0 for _, _, v in self.points[:-1]), default=0)  # n° d'objet, croissant\n        self._releve_name(values)\n        values[\"z_ngf\"] = None if z is None else round(z, 2)\n        values[\"releve\"] = {}\n        how = \"posé sur la carte\" if values[\"nb_visees\"] == 0 else \"gardé (±{} m)\".format(measures._num(values[\"incert_m\"], 2))\n        self.message = \"Objet {} {} : renseignez ses champs, puis visez l'objet suivant.\".format(values[\"nom\"], how)\n\n    def _check_tilt(self):\n        \"\"\"Relevé : inclinaison de la photo calculée comme en mesure (le cœur s'en passe en mesure\n        libre), car un objet posé sur une seule photo en dépend (voir releve_single).\"\"\"\n        if self.releve and self.active and self.item:\n            pic = self.item.get(\"id\")\n            before = self.calibration.auto.get(pic)\n            self.tilts.check(self.item, self.calibration, lambda: self._on_tilt(pic, before))\n            return\n        super()._check_tilt()\n\n    def releve_single(self):\n        \"\"\"Relevé, une seule visée faite depuis la photo affichée : (lon, lat, incertitude en m,\n        distance en m) du point où elle touche le sol, ou None (autre photo, visée trop près de\n        l'horizon). Incertitude : somme quadratique de la visée (AIM_ERROR) et de l'inclinaison de la\n        photo (calée, sinon UNCALIBRATED) en élévation et en cap, du cap de la séquence, de la hauteur\n        de caméra et de la position GPS de la photo.\"\"\"\n        # shortcut: sol supposé plat entre la caméra et l'objet ; prendre le LiDAR HD au point si l'écart gêne\n        sightings = self.triangulator.sightings\n        if not self.releve or len(sightings) != 1 or not self.item or sightings[0][\"pic\"] != self.item.get(\"id\"):\n            return None\n        s = sightings[0]\n        elev = -(s.get(\"elev\") or 0.0)\n        if elev < SINGLE_MIN_ELEV:\n            return None\n        h = self._camera_height()\n        q = self.quality or {}\n        cam = self.calibration.camera(self.item.get(\"collection\"))\n        sigma_h = (measures.CAMERA_ERRORS[\"altitude GPS\"] if q.get(\"precise\") and q.get(\"lidar\") is True\n                   else cam[\"sigma\"] if cam else measures.CAMERA_ERRORS[None])\n        tilt = self.calibration.tilt(s[\"pic\"])\n        sigma_tilt = tilt[\"sigma\"] if tilt and tilt.get(\"sigma\") is not None else calibration.UNCALIBRATED\n        e = math.radians(elev)\n        d = h / math.tan(e)\n        sigma_e = math.radians(math.hypot(calibration.AIM_ERROR, sigma_tilt))\n        sigma_az = math.radians(math.hypot(calibration.AIM_ERROR, sigma_tilt, s.get(\"heading_error\") or 0.0))\n        gps = s[\"accuracy\"] or triangulation.GPS_ACCURACY\n        unc = math.sqrt((h / math.sin(e) ** 2 * sigma_e) ** 2 + (sigma_h / math.tan(e)) ** 2\n                        + (d * sigma_az) ** 2 + gps ** 2)\n        lon, lat = triangulation.offset(s[\"lon\"], s[\"lat\"], s[\"heading\"], d)\n        return lon, lat, unc, d\n\n    def keep_single(self):\n        \"\"\"Relevé : garde l'objet visé sur la seule photo affichée (voir releve_single).\"\"\"\n        single = self.releve_single()\n        if single is None:\n            return self.status()\n        lon, lat, unc, d = single\n        s = self.triangulator.sightings[0]\n        name = session._point_name(self.named)\n        self.named += 1\n        self.points.append((lon, lat, {\n            \"nom\": name, \"nb_visees\": 1, \"angle\": None, \"incert_m\": round(unc, 2), \"ecart_m\": None,\n            \"dist_max_m\": round(d, 1), \"gps_m\": round(s[\"accuracy\"] or triangulation.GPS_ACCURACY, 1), \"photos\": s[\"pic\"],\n            \"date_mesure\": datetime.now().isoformat(timespec=\"seconds\"), \"commentaire\": \"\"}))\n        self.point_views[name] = {s[\"pic\"]: s[\"view\"]} if s.get(\"view\") else {}\n        self.triangulator.clear()\n        self._releve_kept(None if s.get(\"alt\") is None else s[\"alt\"] - self._camera_height())  # au sol\n        return self.status()\n\n    def clear_releve(self):\n        \"\"\"« Vider le relevé » : objets relevés retirés, les points des mesures restent.\"\"\"\n        for k in reversed([k for k, (_, _, v) in enumerate(self.points) if \"releve\" in v]):\n            self.point_views.pop(self.points[k][2][\"nom\"], None)\n            self.delete_result(\"point\", k)\n        self.message = \"Relevé vidé : le prochain objet commencera un nouveau relevé, avec ses champs.\"\n        return self.status()\n\n    def _releve_name(self, values):\n        \"\"\"Objet relevé nommé par son id (carte, photo, résultats, fiche) au lieu d'une lettre ; la\n        lettre prise resservira aux points des mesures.\"\"\"\n        old, new = values[\"nom\"], str(values[\"id\"])\n        if old == new:\n            return\n        self.point_views[new] = self.point_views.pop(old, {})\n        values[\"nom\"] = new\n        if old == session._point_name(self.named - 1):\n            self.named -= 1\n\n    def keep_map(self, lon, lat):\n        \"\"\"Relevé : objet posé d'un clic sur la mini-carte, sans visée (nb_visees 0, précision MAP_PLACE_ERROR,\n        altitude inconnue) ; dans les photos, projeté au sol.\"\"\"\n        if not self.releve:\n            return self.status()\n        self.points.append((float(lon), float(lat), {\n            \"nom\": session._point_name(self.named), \"nb_visees\": 0, \"angle\": None, \"incert_m\": MAP_PLACE_ERROR, \"ecart_m\": None,\n            \"dist_max_m\": None, \"gps_m\": None, \"photos\": \"\", \"date_mesure\": datetime.now().isoformat(timespec=\"seconds\"),\n            \"commentaire\": \"\"}))\n        self.named += 1\n        self._releve_kept()\n        return self.status()\n\n    def set_releve(self, k, text):\n        \"\"\"Champs saisis de l'objet relevé n° k (JSON {nom du champ: valeur}, dans l'ordre du formulaire).\"\"\"\n        k = int(k)\n        if 0 <= k < len(self.points) and \"releve\" in self.points[k][2]:\n            self.points[k][2][\"releve\"] = json.loads(text)\n        return self.status()\n\n    def clear_all(self):\n        \"\"\"« Tout effacer » : hors du mode relevé, les objets relevés restent (exportés à part).\"\"\"\n        kept = [] if self.releve else [p for p in self.points if \"releve\" in p[2]]\n        views, named = {p[2][\"nom\"]: self.point_views.get(p[2][\"nom\"], {}) for p in kept}, self.named\n        super().clear_all()\n        self.map_lengths = []\n        if kept:\n            self.points, self.point_views, self.named = kept, views, named\n        return self.status()\n\n    def has_results(self):\n        \"\"\"Mesures, points triangulés ou distances à exporter (les objets relevés à part : has_releve).\"\"\"\n        return bool(self.links or self.map_lengths) or any(\"releve\" not in v for _, _, v in self.points) or any(\n            m.result for m in self.tool.measures())\n\n    def has_releve(self):\n        return any(\"releve\" in v for _, _, v in self.points)\n\n    def releve_json(self):\n        \"\"\"Objets relevés, à garder dans le navigateur entre deux séances (load_releve).\"\"\"\n        return json.dumps({\"named\": self.named, \"points\": [\n            [lon, lat, v, self.point_views.get(v[\"nom\"], {})] for lon, lat, v in self.points if \"releve\" in v]},\n            ensure_ascii=False)\n\n    def load_releve(self, text):\n        \"\"\"Objets relevés de la séance précédente (releve_json), ajoutés aux points gardés.\"\"\"\n        data = json.loads(text or \"null\") or {}\n        for lon, lat, values, views in data.get(\"points\", []):\n            values.setdefault(\"id\", 1 + max((v.get(\"id\") or 0 for _, _, v in self.points), default=0))\n            self.points.append((lon, lat, values))\n            self.point_views[values[\"nom\"]] = views\n            self._releve_name(values)  # relevé gardé avant la numérotation : lettre remplacée\n        self.named = max(self.named, data.get(\"named\", 0))\n        return self.status()\n\n    def take_proposal(self):\n        return json.dumps(super().take_proposal())\n\n    def take_frame(self):\n        return json.dumps(super().take_frame())\n\n    def take_bridge_alert(self):\n        return json.dumps(super().take_bridge_alert())\n\n    # Calage de l'inclinaison : objet vertical validé par un bouton -----------------------------\n    TILT_NEAR = 1.5  # degrés : clic sur une croix de l'objet en cours (sélection pour la déplacer)\n\n    def _tilt_pending(self):\n        \"\"\"Objet vertical en cours sur la photo affichée (calage de l'inclinaison).\"\"\"\n        return bool(self.active and self.mode == \"tilt\" and self.item and self.tilt_clicks\n                    and self.tilt_clicks[0][\"pic\"] == self.item.get(\"id\"))\n\n    def status(self):\n        text = super().status()\n        if self.releve:\n            text = text.replace(\"Mesure libre (distance au point gardé précédent)\", \"Relevé d'objets\")\n        return _map_line_text(text) if MAP_SOURCE in text else text\n\n    # Couche importée (GeoJSON, src/couche.js) : objets dans la photo, à leur altitude (z du fichier,\n    # NGF) ou posés sur le sol LiDAR HD, lu sous la caméra et sous leurs sommets (lignes redécoupées\n    # tous les OVERLAY_STEP m pour suivre le terrain) ; dessinés une fois le sol de la caméra lu (pas de saut), chaque\n    # objet une fois ses sommets lus ; à plat à la hauteur de caméra sans LiDAR ou sans réponse en OVERLAY_TIMEOUT_MS ----------\n    OVERLAY_REACH = 100.0  # m : objets dessinés dans la photo s'ils ont un sommet à cette distance\n    OVERLAY_STEP = 5.0  # m : pas des lignes, pour suivre le terrain entre leurs sommets\n    OVERLAY_CHUNK = 150  # points par requête d'altitude (longueur de l'adresse)\n    POINT_GROUND_MAX = 200  # couples (caméra, point) dont l'altitude est gardée (view_point)\n    OVERLAY_TIMEOUT_MS = 5000  # ms : sans réponse, sol supposé de niveau avec la caméra (objets à plat)\n    OVERLAY_MAX = 900  # points d'altitude au plus demandés par photo (sommets pas encore lus)\n\n    def set_overlay(self, text):\n        \"\"\"Couche importée, JSON [{id, geometry}] en WGS 84, z éventuel en NGF (vide : retirée) : points,\n        et lignes (contours des polygones compris), multi-géométries éclatées en parties.\"\"\"\n        self.overlay, self.overlay_ground, self.overlay_asked = [], {}, set()\n        for f in json.loads(text or \"[]\"):\n            g, i = f.get(\"geometry\") or {}, f.get(\"id\")\n            kind, coords = g.get(\"type\", \"\"), g.get(\"coordinates\") or []\n            if kind == \"Point\":\n                parts = [[coords]]\n            elif kind == \"MultiPoint\":\n                parts = [[p] for p in coords]\n            elif kind == \"LineString\":\n                parts = [coords]\n            elif kind in (\"MultiLineString\", \"Polygon\"):\n                parts = coords\n            elif kind == \"MultiPolygon\":\n                parts = [ring for poly in coords for ring in poly]\n            else:\n                parts = []\n            for part in parts:\n                # z = 0 : « pas d'altitude » des exports KML (altitudeMode clampToGround), posé sur le sol\n                pts = [(float(p[0]), float(p[1]), float(p[2]) if len(p) > 2 and p[2] else None)\n                       for p in part if len(p) >= 2]\n                if pts:\n                    line = not kind.endswith(\"Point\")\n                    self.overlay.append((i, \"ligne\" if line else \"point\", _densified(pts, self.OVERLAY_STEP) if line else pts))\n        return len(self.overlay)\n\n    def view_point(self, lon, lat, up):\n        \"\"\"JSON {yaw, pitch} (radians, repère de la photo affichée, calage compris) du point de la carte (lon, lat) à up m\n        au-dessus du sol ; null sans photo. Sol lu sur le LiDAR HD (RGE ALTI s'il manque) sous la caméra et sous le point :\n        la caméra est à _camera_height au-dessus du sien. En attendant la lecture (redessin à son arrivée), ou sans\n        altitude, sol supposé de niveau avec celui de la caméra. Sert à l'étiquette de la parcelle cadastrale visée,\n        à 1,50 m du sol à la limite de la parcelle et du domaine public.\"\"\"\n        if not self.item:\n            return \"null\"\n        here_lon, here_lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n        lon, lat = float(lon), float(lat)\n        x, y = triangulation._local(lon, lat, here_lon, here_lat)\n        ground = self._point_ground(here_lon, here_lat, lon, lat)  # (sol caméra, sol du point) ou None\n        drop = self._camera_height() - float(up) + (ground[0] - ground[1] if ground else 0.0)\n        v = self._view_of(math.degrees(math.atan2(x, y)), -math.degrees(math.atan2(drop, max(math.hypot(x, y), 0.5))))\n        return json.dumps({\"yaw\": v[\"yaw\"], \"pitch\": v[\"pitch\"]})\n\n    def _point_ground(self, here_lon, here_lat, lon, lat):\n        \"\"\"Altitudes du sol (LiDAR HD, sinon RGE ALTI) sous la caméra et sous le point : (z caméra, z point), ou None\n        (lecture en cours, ou altitude manquante). Une lecture par couple de points, gardée ; redessin à l'arrivée.\"\"\"\n        key = tuple(round(v, 7) for v in (here_lon, here_lat, lon, lat))\n        if key in self.point_ground:\n            return self.point_ground[key]\n        self.point_ground[key] = None\n        if len(self.point_ground) > self.POINT_GROUND_MAX:  # les plus anciennes oubliées\n            del self.point_ground[next(iter(self.point_ground))]\n\n        def done(zs, source, error):\n            if not error and zs and len(zs) == 2 and None not in zs:\n                self.point_ground[key] = (zs[0], zs[1])\n                self.notify()\n\n        precision.fetch_terrain([(here_lon, here_lat), (lon, lat)], done)\n        return self.point_ground.get(key)  # réponse déjà là (lecture en cache) : prise tout de suite\n\n    def overlay_marks(self):\n        \"\"\"JSON [{id, kind, points: [[cap, élévation]], dist}] (radians, repère de la photo affichée ;\n        dist : distance en m de la caméra au sommet le plus proche) des parties de la couche importée\n        qui ont un sommet à OVERLAY_REACH m de la photo, de la plus proche à la plus lointaine.\"\"\"\n        if not self.item or not self.overlay:\n            return \"[]\"\n        lon, lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n        k = math.cos(math.radians(lat))\n        reach = self.OVERLAY_REACH / 111320.0\n        near = [(i, kind, pts) for i, kind, pts in self.overlay\n                if any(abs(p[1] - lat) < reach and abs(p[0] - lon) * k < reach for p in pts)]\n        ground = self._overlay_ground(lon, lat, near)  # {(lon, lat): z}, sol sous la caméra en (lon, lat)\n        if (lon, lat) not in ground:  # sol de la caméra en cours de lecture : rien, plutôt qu'à plat puis un saut\n            return \"[]\"\n        height, base = self._camera_height(), ground[(lon, lat)]\n        out = []\n        for i, kind, pts in near:\n            if any((p[0], p[1]) in self.overlay_asked for p in pts):  # sommet en cours de lecture : dessiné à son arrivée\n                continue\n            views, dist = [], None\n            for plon, plat, z in pts:\n                z = z if z is not None else ground.get((plon, plat))\n                x, y = triangulation._local(plon, plat, lon, lat)\n                drop = height + base - z if base is not None and z is not None else height  # sinon : à plat\n                v = self._view_of(math.degrees(math.atan2(x, y)), -math.degrees(math.atan2(drop, max(math.hypot(x, y), 0.5))))\n                views.append([v[\"yaw\"], v[\"pitch\"]])\n                dist = math.hypot(x, y) if dist is None else min(dist, math.hypot(x, y))\n            out.append({\"id\": i, \"kind\": kind, \"points\": views, \"dist\": round(dist, 1)})\n        out.sort(key=lambda o: o[\"dist\"])\n        return json.dumps(out)\n\n    def _overlay_ground(self, lon, lat, near):\n        \"\"\"Altitudes LiDAR HD sous la caméra et sous les sommets proches sans z (à une fois et demie OVERLAY_REACH) :\n        {(lon, lat): z}, gardées pour toute la couche (les objets ne bougent pas : photo suivante de la séquence sans\n        relecture) ; seuls les points pas encore lus sont demandés, OVERLAY_MAX au plus par photo. Absente : None.\"\"\"\n        k, reach = math.cos(math.radians(lat)), 1.5 * self.OVERLAY_REACH / 111320.0\n        known, asked = self.overlay_ground, self.overlay_asked\n        points = [p for p in dict.fromkeys([(lon, lat)] + [\n            (p[0], p[1]) for _, _, pts in near for p in pts\n            if p[2] is None and abs(p[1] - lat) < reach and abs(p[0] - lon) * k < reach])\n            if p not in known and p not in asked][:self.OVERLAY_MAX]\n        if not points:\n            return known\n        asked.update(points)\n        chunks = [points[n:n + self.OVERLAY_CHUNK] for n in range(0, len(points), self.OVERLAY_CHUNK)]\n\n        def got(chunk):\n            def done(data, error):\n                if known is not self.overlay_ground:  # couche changée entre-temps : réponse jetée\n                    return\n                z = None if error else precision._ground(data)\n                # sans réponse (OVERLAY_TIMEOUT_MS) ou en erreur : à plat ; shortcut: pas relu avant le prochain import\n                known.update(zip(chunk, z if z and len(z) == len(chunk) else [None] * len(chunk)))\n                asked.difference_update(chunk)\n                self.notify()  # objets de ce paquet dessinés\n            return done\n\n        for chunk in chunks:\n            host.fetch_json(precision.lidar_url(chunk, precision.LIDAR_RESOURCE), got(chunk), timeout_ms=self.OVERLAY_TIMEOUT_MS)\n        return known\n\n    # Hauteurs suivantes depuis le point de référence, sur l'axe de la première -------------------\n    # Une fois une hauteur faite depuis A sur la photo affichée (ligne A–C), le sommet des suivantes\n    # (« Nouvelle mesure depuis A ») est pris sur le prolongement de cette ligne, au plus près du clic :\n    # même objet, même verticale. La page y tient le réticule, avec un trait jaune en travers.\n\n    def height_axis(self):\n        \"\"\"JSON [[cap, élévation] du pied, [cap, élévation] du sommet] (radians, repère de la photo) de\n        la première hauteur depuis le point de référence prise sur la photo affichée, quand le\n        prochain clic donnera le sommet d'une autre hauteur depuis lui ; sinon null.\"\"\"\n        return json.dumps(self._height_axis())\n\n    def _height_axis(self):\n        ref, tool = self.ref_point, self.tool\n        if not (self.active and self.item and self.mode == \"height\" and ref) or self._aiming() or self._locked() \\\n                or self.ref_sel or tool.selected is not None:\n            return None\n        if tool.current is not None and len(tool.current.clicks) < tool.current.needed():\n            return None\n        pic = self.item.get(\"id\")\n        first = next((m for m in self._heights() if (m.reference or {}).get(\"name\") == ref[\"name\"]\n                      and m.clicks[0].get(\"pic\") == pic), None)\n        if first is None:\n            return None\n        foot, top = self._height_points(first)[:2]\n        if foot[\"yaw\"] is None or top[\"yaw\"] is None:\n            return None\n        return [[foot[\"yaw\"], foot[\"pitch\"]], [top[\"yaw\"], top[\"pitch\"]]]\n\n    def click(self, yaw, pitch, on_cross=None):\n        \"\"\"Clic dans la photo ; on_cross : la page a vu une croix sous le pointeur (CROSS_PX), ou None (en degrés).\"\"\"\n        return self._with_cross(on_cross, self._click, yaw, pitch)\n\n    def _click(self, yaw, pitch):\n        axis = self._height_axis() if self.mode == \"height\" else None\n        if axis:\n            click = tools.photo_click(self.item, (math.degrees(yaw) + self._heading()) % 360, math.degrees(pitch),\n                                      self.calibration, self.quality, [yaw, pitch], self._axis(self.item))\n            if click is not None and self._height_near(click) is None and not self._ref_near(click):\n                # pas sur une croix : ramené sur l'axe, et plus une sélection (le pied, A et les sommets depuis A sont\n                # sur l'axe : le point ramené tomberait près d'eux)\n                yaw, pitch = _on_axis(axis, yaw, pitch)\n                self.cross_hit = False\n        if not (self.active and self.mode == \"tilt\" and self.item):\n            return super().click(yaw, pitch)\n        self._check_tilt()\n        raw_yaw = (math.degrees(yaw) + self._heading()) % 360\n        click = tools.photo_click(self.item, raw_yaw, math.degrees(pitch), self.calibration, self.quality, [yaw, pitch])\n        if click is None:\n            self.message = \"Position de la photo inconnue.\"\n            return self.status()\n        self.message = \"\"\n        if not self._tilt_pending():\n            self.tilt_clicks, self.tilt_sel = [], None  # le sommet doit être sur la même photo que le pied\n        if self.tilt_sel is not None:  # croix sélectionnée : nouvelle position\n            self.tilt_clicks[self.tilt_sel], self.tilt_sel = click, None\n            return self.status()\n        reach = self.TILT_NEAR if self.cross_hit is None else self.CROSS_REACH if self.cross_hit else 0.0\n        gaps = [(math.hypot(math.degrees(c[\"pos\"][0] - yaw), math.degrees(c[\"pos\"][1] - pitch)), k)\n                for k, c in enumerate(self.tilt_clicks)]\n        near = [k for d, k in sorted(gaps) if d < reach]\n        if near:\n            self.tilt_sel = near[0]\n        elif len(self.tilt_clicks) < 2:\n            self.tilt_clicks.append(click)\n        else:\n            self.message = (\"Pied et sommet déjà placés : cliquez une de leurs croix pour la déplacer, puis \"\n                            \"« ✔ Valider l'objet vertical » (« Effacer » retire son dernier clic).\")\n        return self.status()\n\n    def validate_tilt(self):\n        \"\"\"« Valider l'objet vertical » : le pied et le sommet cliqués calent l'inclinaison de la photo.\"\"\"\n        if self._tilt_pending() and len(self.tilt_clicks) == 2:\n            clicks, self.tilt_clicks, self.tilt_sel = self.tilt_clicks, [], None\n            for c in clicks:\n                self.calibrator.add_click(c)\n            self._after_calibration(self.calibrator)\n        return self.status()\n\n    def _calibration_text(self):\n        if not self._tilt_pending():\n            return super()._calibration_text()\n        n = len(self.calibration.verticals.get(self.item.get(\"id\"), [])) + 1\n        if self.tilt_sel is not None:\n            return \"{} de l'objet {} sélectionné : cliquez sa position exacte.\".format(\n                \"Pied\" if self.tilt_sel == 0 else \"Sommet\", n)\n        if len(self.tilt_clicks) == 1:\n            return (\"Calage de l'inclinaison, objet {} : cliquez maintenant son sommet, le plus haut possible sur \"\n                    \"la même verticale (zoomez pour être précis).\").format(n)\n        return (\"Objet {} : pied et sommet placés. Pour en déplacer un, cliquez sa croix puis sa position exacte ; \"\n                \"sinon « ✔ Valider l'objet vertical ».\").format(n)\n\n    # État remis par Ctrl+Y : listes copiées (les objets gardés tels quels : « Effacer » ne fait que\n    # les retirer), sauf le calage du cap et de la position (CalibrationTool), non rétabli\n    REDO_ATTRS = (\"points\", \"links\", \"named\", \"last_free\", \"point_views\", \"ref_point\", \"measure_done\", \"width_sel\",\n                  \"ref_sel\", \"b_aiming\", \"proposal\", \"tilt_clicks\", \"tilt_sel\", \"map_line\", \"map_lengths\")\n\n    def _snapshot(self):\n        snap = {k: getattr(self, k, None) for k in self.REDO_ATTRS}\n        for k in (\"points\", \"links\", \"tilt_clicks\", \"map_lengths\"):\n            snap[k] = list(snap[k])\n        snap[\"point_views\"] = dict(snap[\"point_views\"])\n        tool = self.tool\n        snap[\"tool\"] = (list(tool.done), tool.current, tool.selected, list(self.triangulator.sightings))\n        return snap\n\n    def _redo_state(self):\n        \"\"\"Empreinte de ce que les gestes changent : un geste fait depuis le dernier « Effacer »\n        rend Ctrl+Y sans objet.\"\"\"\n        tool, current = self.tool, self.tool.current\n        return (len(self.points), len(self.links), len(tool.done), id(current), len(current.clicks) if current else 0,\n                len(self.triangulator.sightings), id(self.ref_point), len(self.tilt_clicks), self.mode,\n                id(self.b_aiming), self.measure_done, len(self.map_lengths))\n\n    def redo(self):\n        \"\"\"Ctrl+Y (ou Ctrl+Maj+Z) : rétablit ce que le dernier « Effacer » a retiré, si rien n'a été fait\n        depuis.\"\"\"\n        if not self.redo_stack or self._redo_state() != self.redo_key:\n            self.redo_stack, self.redo_key = [], None\n            self.message = \"Rien à rétablir.\"\n            return self.status()\n        snap = self.redo_stack.pop()\n        done, current, selected, sightings = snap.pop(\"tool\")\n        for k, v in snap.items():\n            setattr(self, k, v)\n        tool = self.tool\n        tool.done, tool.current, tool.selected = done, current, selected\n        for m in tool.measures():\n            m._draw()  # dessin sur la carte retiré par l'effacement\n        self.triangulator.sightings = list(sightings)\n        if sightings:\n            self.triangulator.recompute()\n        else:\n            self.triangulator.clear()\n        self.redo_key = self._redo_state()\n        self.message = \"Rétabli.\"\n        return self.status()\n\n    def undo(self):\n        before = self._redo_state()\n        snap = None if self.active and self._active() is self.calibrator else self._snapshot()\n        stack = self.redo_stack if self.redo_key == before else []\n        text = self._undo()\n        if snap is not None and self._redo_state() != before:  # quelque chose a été retiré\n            stack.append(snap)\n        self.redo_stack, self.redo_key = stack, self._redo_state()\n        return text\n\n    def _can_undo(self):\n        \"\"\"« Effacer » aurait-il un effet ? (mêmes cas que _undo et Session.clear)\"\"\"\n        if self.map_mode:  # mesure sur la carte : la dernière longueur\n            return bool(self.map_lengths)\n        if self.mode == \"tilt\":  # objet vertical en cours, ou inclinaison calée à la main de la photo\n            pic = (self.item or {}).get(\"id\")\n            return bool(self._tilt_pending() or self.calibrator.clicks or (pic and pic in self.calibration.verticals))\n        tool = self.tool\n        if self.b_aiming is not None or self.triangulator.sightings or self.width_sel is not None or self.ref_sel \\\n                or tool.selected is not None or (tool.current is not None and tool.current.clicks):\n            return True\n        return bool(self.points) if self.mode == \"tri\" else self.ref_point is not None\n\n    def _can_clear(self):\n        \"\"\"« Tout effacer » aurait-il un effet ?\"\"\"\n        return bool(self.points or self.links or self.map_lengths or self.tool.measures() or self.triangulator.sightings\n                    or self.ref_point is not None or self.tilt_clicks or self.calibrator.clicks)\n\n    def _undo(self):\n        \"\"\"« Effacer » et Ctrl+Z : annule le dernier geste. Visées : la dernière seule (le bord B garde sa première,\n        le clic de la mesure) ; objet vertical du calage : son dernier clic ; sinon comme Session.clear\n        (sélection, mesure en cours, puis dernier point posé).\"\"\"\n        if self.map_mode:\n            if self.map_lengths:\n                self.map_lengths.pop()\n                self.message = \"Dernière mesure sur la carte effacée.\"\n            return self.status()\n        if self._tilt_pending() and self.tilt_clicks:\n            self.tilt_clicks.pop()\n            self.tilt_sel = None\n            self.message = \"Dernier clic de l'objet vertical annulé.\"\n            return self.status()\n        sightings = self.triangulator.sightings\n        if self.active and self._active() is self.triangulator and len(sightings) > (1 if self.b_aiming else 0):\n            sightings.pop()\n            if sightings:\n                self.triangulator.recompute()\n            else:\n                self.triangulator.clear()\n            self.message = \"Dernière visée annulée ({} restante{}).\".format(len(sightings), \"s\" if len(sightings) > 1 else \"\")\n            return self.status()\n        return self.clear()\n\n    def clear(self):\n        if self._tilt_pending():\n            self.tilt_clicks, self.tilt_sel = [], None\n            self.message = \"Objet vertical abandonné.\"\n            return self.status()\n        return super().clear()\n\n\n    # Droite de mesure tracée sur la mini-carte (ticket #28) ---------------------------------------\n    # Giratoire, carrefour, place : avant la première visée de A, la droite de mesure est tracée sur\n    # la carte (deux clics, en travers de la voie) au lieu d'être perpendiculaire à l'axe calculé. A\n    # se pose alors d'un clic, là où sa direction coupe la droite (comme le bord B), sans visées.\n\n    def axis_state(self):\n        \"\"\"Droite tracée, pour la page (JSON) : tracé possible (largeur, avant la première visée de A),\n        droite tracée en attente du point A (annulable), et ses deux points [[lon, lat], [lon, lat]].\"\"\"\n        waiting = bool(self.active and self.mode == \"road\" and self.ref_point is None and self.b_aiming is None)\n        line = self.map_line if waiting else None\n        return json.dumps({\"can\": waiting and not self.triangulator.sightings and line is None,\n                           \"drawn\": line is not None, \"line\": line and line[\"ends\"]})\n\n    def set_measure_line(self, lon1, lat1, lon2, lat2):\n        \"\"\"Droite de mesure tracée par deux clics sur la mini-carte : A et B seront posés dessus.\"\"\"\n        if not json.loads(self.axis_state())[\"can\"]:\n            self.message = \"La droite se trace en largeur, avant la première visée du premier bord.\"\n            return self.status()\n        x, y = triangulation._local(lon2, lat2, lon1, lat1)\n        span = math.hypot(x, y)\n        if span < MAP_LINE_MIN:\n            self.message = (\"Droite non tracée : {} m entre les deux clics ; tracez-la sur {} m au moins, en travers \"\n                            \"de la voie.\").format(measures._num(span, 1), measures._num(MAP_LINE_MIN, 0))\n            return self.status()\n        error = math.degrees(math.atan2(MAP_CLICK * math.sqrt(2), span))\n        self.map_line = {\"ends\": [[lon1, lat1], [lon2, lat2]], \"bearing\": math.degrees(math.atan2(x, y)) % 360,\n                         \"error\": error}\n        self.message = (\"Droite de mesure tracée (±{}°) : cliquez le premier bord sur la droite bleue de la photo ; \"\n                        \"seule la direction du clic compte. « Annuler la droite » pour revenir à l'axe \"\n                        \"automatique.\").format(measures._num(error, 1))\n        return self.status()\n\n    def cancel_measure_line(self):\n        self.map_line = None\n        self.message = \"Droite tracée annulée : droite de mesure perpendiculaire à l'axe automatique.\"\n        return self.status()\n\n    def set_mode(self, mode):\n        self.tilt_clicks, self.tilt_sel = [], None\n        self.map_line = None\n        self.releve = mode == \"releve\"\n        self.map_mode = mode == \"carte\"  # mesure sur la carte : le cœur reste en mesure libre, inactif\n        return super().set_mode(\"tri\" if self.releve or self.map_mode else mode)\n\n    def add_map_length(self, lon1, lat1, lon2, lat2, value, sigma, photos):\n        \"\"\"Longueur mesurée sur la vue du dessus (deux clics sur la carte) : valeur et incertitude (m) calculées par\n        la page (src/dessus.js), photos qui ont fourni l'image (séparées par des virgules). Incertitude None : un bout\n        hors de la vue, longueur sur le fond de carte seul (contrôle rapide de cohérence).\"\"\"\n        sigma = float(sigma) if isinstance(sigma, (int, float)) else None  # null de la page : JsNull, pas None\n        self.map_lengths.append({\"ends\": [[lon1, lat1], [lon2, lat2]], \"valeur_m\": float(value), \"incert_m\": sigma,\n                                 \"photos\": photos, \"commentaire\": \"\"})\n        self.message = \"Longueur sur la carte : {}.\".format(_length_text(value, sigma))\n        return self.status()\n\n    def add_map_area(self, ring):\n        \"\"\"Surface tracée sur la carte (≥ 3 sommets, texte JSON [[lon, lat], …], contour ouvert) : aire (m²) et périmètre (m)\n        sur le plan local du premier sommet. Pas d'incertitude (fond de carte ou image du dessus, sans calcul d'erreur).\"\"\"\n        pts = json.loads(ring)\n        local = [triangulation._local(lon, lat, *pts[0]) for lon, lat in pts]\n        pairs = list(zip(local, local[1:] + local[:1]))\n        area = abs(sum(x1 * y2 - x2 * y1 for (x1, y1), (x2, y2) in pairs)) / 2\n        self.map_lengths.append({\"ends\": pts, \"valeur_m\": sum(math.hypot(x2 - x1, y2 - y1) for (x1, y1), (x2, y2) in pairs),\n                                 \"incert_m\": None, \"photos\": \"\", \"commentaire\": \"\", \"surface_m2\": area})\n        self.message = \"Surface sur la carte : {}.\".format(_area_text(area))\n        return self.status()\n\n    def delete_result(self, kind, ident):\n        if kind == \"longueur\":\n            if 0 <= ident < len(self.map_lengths):\n                del self.map_lengths[ident]\n                self.message = \"Longueur effacée.\"\n            return self.status()\n        return super().delete_result(kind, ident)\n\n    def set_comment(self, kind, ident, text):\n        if kind == \"longueur\":\n            if 0 <= ident < len(self.map_lengths):\n                self.map_lengths[ident][\"commentaire\"] = text\n            return\n        super().set_comment(kind, ident, text)\n\n    def aim(self, yaw, pitch):\n        if self.mode == \"road\" and self.map_line is not None and self.ref_point is None and self.b_aiming is None:\n            return self._point_on_line(yaw, pitch)\n        return super().aim(yaw, pitch)\n\n    def _line_mark(self):\n        \"\"\"Droite tracée dans la photo affichée (comme Session._guide_mark : sol plat à la hauteur de\n        caméra), prolongée de 5 m de chaque côté.\"\"\"\n        lon, lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n        (lon1, lat1), (lon2, lat2) = self.map_line[\"ends\"]\n        (x1, y1), (x2, y2) = triangulation._local(lon1, lat1, lon, lat), triangulation._local(lon2, lat2, lon, lat)\n        span = math.hypot(x2 - x1, y2 - y1)\n        ux, uy = (x2 - x1) / span, (y2 - y1) / span\n        height, points = self._camera_height(), []\n        for k in range(41):\n            t = -5.0 + k * (span + 10.0) / 40\n            x, y = x1 + t * ux, y1 + t * uy\n            d = math.hypot(x, y)\n            if d >= 1.0:\n                view = self._view_of(math.degrees(math.atan2(x, y)), -math.degrees(math.atan2(height, d)))\n                points.append([view[\"yaw\"], view[\"pitch\"], False])\n        return {\"points\": points, \"label\": \"\", \"guide\": True}\n\n    def _point_on_line(self, yaw, pitch):\n        \"\"\"Point A posé là où la direction du clic coupe la droite tracée (sur la carte, à plat) : point\n        de référence de la largeur, comme Session.keep_point, la droite tracée pour droite de mesure.\"\"\"\n        if not self.item:\n            self.message = \"Aucune photo affichée.\"\n            return self.status()\n        s = tools.photo_sighting(self.item, (math.degrees(yaw) + self._heading()) % 360, math.degrees(pitch),\n                                 self.calibration, self.quality)\n        if s is None:\n            self.message = \"Position de la photo inconnue : impossible de poser le point.\"\n            return self.status()\n        line = self.map_line\n        lon0, lat0 = line[\"ends\"][0]\n        cx, cy = triangulation._local(s[\"lon\"], s[\"lat\"], lon0, lat0)\n        h, b = math.radians(s[\"heading\"]), math.radians(line[\"bearing\"])\n        dx, dy, ux, uy = math.sin(h), math.cos(h), math.sin(b), math.cos(b)\n        det = ux * dy - dx * uy  # sinus de l'angle entre la visée et la droite\n        if abs(det) < math.sin(math.radians(MAP_MIN_ANGLE)):\n            self.message = (\"Visée presque parallèle à la droite tracée : cliquez depuis une photo prise quelques \"\n                            \"mètres avant ou après, qui la voit plus en travers.\")\n            return self.status()\n        t = (cx * uy - cy * ux) / det  # distance de la caméra au point, le long de la visée\n        if t <= 0:\n            self.message = \"La direction du clic ne coupe pas la droite tracée devant la caméra.\"\n            return self.status()\n        u = (cx + t * dx) * ux + (cy + t * dy) * uy  # abscisse du point sur la droite\n        plon, plat = triangulation._geographic(u * ux, u * uy, lon0, lat0)\n        # Le long de la droite : position de la caméra et cap, vus sous l'angle de la visée\n        sigma = math.hypot(s[\"accuracy\"], t * math.radians(MAP_HEADING_ERROR)) / abs(det)\n        name = session._point_name(self.named)\n        self.named += 1\n        values = {\"nom\": name, \"nb_visees\": 1, \"angle\": round(math.degrees(math.asin(min(1.0, abs(det)))), 1),\n                  \"incert_m\": round(sigma, 2), \"ecart_m\": 0.0, \"dist_max_m\": round(t, 1),\n                  \"gps_m\": round(s[\"accuracy\"], 1), \"photos\": s[\"pic\"],\n                  \"date_mesure\": datetime.now().isoformat(timespec=\"seconds\"), \"commentaire\": \"\"}\n        self.points.append((plon, plat, values))\n        s[\"view\"] = [yaw, pitch]\n        self.point_views[name] = {s[\"pic\"]: [yaw, pitch]}\n        self.triangulator.clear()\n        self.ref_photo = s[\"pic\"]\n        self.ref_point = {\"lon\": plon, \"lat\": plat, \"uncertainty\": sigma, \"name\": name,\n                          \"sequences\": [s.get(\"sequence\")], \"sightings\": [s], \"ground_z\": None,\n                          \"road\": {\"axis\": (line[\"bearing\"] + 90) % 360,\n                                   \"source\": \"{}, ±{}°\".format(MAP_SOURCE, measures._num(line[\"error\"], 1))}}\n        self.map_line = None\n        self._ref_ground()\n        self.message = (\"Point {} posé sur la droite tracée (±{} m). Cliquez maintenant le bord opposé, au sol, sur \"\n                        \"la droite bleue : seule la direction du clic compte.\").format(name, measures._num(sigma))\n        self.message += self._rtk_warning([s.get(\"sequence\")])\n        return self.status()\n\n    def _road_at_reference(self):\n        \"\"\"Axe de la route au point de référence (voir Session) ; sur une séquence RTK vérifiée, la\n        direction de la trajectoire à la place de celle du tronçon de la BD TOPO (±2°), quand elle est\n        droite et concorde avec lui.\n        shortcut: vérification RTK pas encore arrivée au point de référence : BD TOPO gardée ; reprendre\n        l'axe à son arrivée si des largeurs prises juste après l'ouverture d'une photo restent en BD TOPO.\"\"\"\n        super()._road_at_reference()\n        ref = self.ref_point\n        road = ref.get(\"road\")\n        if not road or not road[\"source\"].startswith(\"BD TOPO\") or not (self.quality or {}).get(\"precise\"):\n            return\n        seq = (self.item or {}).get(\"collection\")\n        key = (seq, roads._cell(ref[\"lon\"], ref[\"lat\"]))  # cache des trajectoires du cœur\n        track = self.roads._get((\"track\",) + key, self.roads._tracks, key, lambda: metadata.search_url(\n            ref[\"lon\"], ref[\"lat\"], roads.TRACK_RADIUS + 10, 20, seq, host.api_url), lambda data: data)\n        if track is roads.PENDING:\n            ref[\"road\"] = None  # repris par _roads_ready\n            return\n        axis = _straight_track_axis(track, seq, ref[\"lon\"], ref[\"lat\"])\n        if axis is None or roads._axis_diff(axis, road[\"axis\"]) > TRACK_AGREE:\n            return\n        if math.cos(math.radians(axis - road[\"axis\"])) < 0:\n            axis += 180  # sens du tronçon gardé\n        ref[\"road\"] = {\"axis\": axis % 360, \"source\": RTK_SOURCE + \", contrôlée par la \" + road[\"source\"]}\n\n\n    # Largeur : bord sur la droite de mesure (ticket #18) ----------------------------------------\n    def _width_points(self, m):\n        \"\"\"Repères d'une largeur (voir Session._width_points), le bord cliqué (pas triangulé) posé sur la\n        droite de mesure dans la direction du clic, là où le calcul le place : seule la direction du clic\n        compte (widths.PerpendicularWidth), sa hauteur dans la photo non. Croix, trait et valeur\n        concordent ; la sélection d'une croix (Session._width_near) la cherche là aussi.\"\"\"\n        points = super()._width_points(m)\n        pic = (self.item or {}).get(\"id\")\n        if pic is not None and pic == m.clicks[1].get(\"pic\") and m.edge_b is None:\n            anchor = self._aim_anchor() if m.edge is self.ref_point else None  # comme la droite tracée\n            points[1] = self._project(*m.result[\"points\"][1], anchor[2] if anchor else None)\n        if pic is not None and pic == m.clicks[1].get(\"pic\"):\n            _keep_view(m, points)\n        return points\n\n    def start_edge_b(self):\n        \"\"\"Trianguler le bord B (voir Session.start_edge_b) : la première visée est le bord tel qu'il est\n        posé sur la droite de mesure (direction du clic, élévation de la droite), pas l'élévation du\n        clic, qui ne compte pas : croix bleue sur la croix B, visée 3D cohérente.\"\"\"\n        m = self._edge_b_candidate()\n        out = super().start_edge_b()\n        tri = self.triangulator\n        if m is None or self.b_aiming is not m or len(tri.sightings) != 1 \\\n                or (self.item or {}).get(\"id\") != m.clicks[1].get(\"pic\"):\n            return out\n        p = self._width_points(m)[1]\n        s = tri.sightings[0]\n        s[\"raw\"] = [p[\"abs_yaw\"], p[\"elev\"]]\n        if self._resight(s):\n            s[\"view\"] = [p[\"yaw\"], p[\"pitch\"]]\n        return self.status()\n\n    def take_aim_frame(self):\n        \"\"\"Visées guidées : repère dans la photo affichée ([[cap, élévation]] en radians, JSON) du\n        point à viser : triangulé par les visées déjà faites (dès la 3e visée), sinon tel qu'il est\n        placé avant de l'être (voir _provisional_point). Une seule fois par photo affichée, et\n        seulement si elle n'a pas encore servi à le viser ; null sinon. Propre à la page (pas dans\n        le cœur).\"\"\"\n        if not self.aim_frame or not self.active or not self.item:\n            return \"null\"\n        self.aim_frame = False\n        sightings = self.triangulator.sightings\n        if not sightings or any(s[\"pic\"] == self.item.get(\"id\") for s in sightings):\n            return \"null\"\n        r = self.triangulator.result\n        if r:  # point triangulé : son altitude, si elle est connue, donne l'élévation depuis cette caméra\n            lon, lat = (float(v) for v in self.item[\"geometry\"][\"coordinates\"][:2])\n            alt = host.ngf_altitude(lon, lat, metadata.item_altitude(self.item)) \\\n                if (self.quality or {}).get(\"precise\") else None\n            z = r.get(\"z\")\n            p = self._project(r[\"lon\"], r[\"lat\"], alt - z if alt is not None and z is not None else None)\n        else:\n            target = self._provisional_point()\n            if target is None:\n                return \"null\"\n            p = self._project(*target)\n        return json.dumps([[p[\"yaw\"], p[\"pitch\"]]])\n\n    def _provisional_point(self):\n        \"\"\"Point visé tel qu'il est placé avant d'être triangulé (lon, lat), ou None : le bord B\n        d'une largeur là où l'a mis le clic de la mesure, ou le point de référence là où la\n        première visée touche le sol plat.\"\"\"\n        sightings = self.triangulator.sightings\n        if self.b_aiming is not None:\n            return tuple(self.b_aiming.result[\"points\"][1])\n        if not sightings or self.mode not in session.REF_MODES or self.ref_point is not None:\n            return None\n        first = sightings[0]\n        elev = first.get(\"elev\") or 0.0\n        if elev > -0.5:  # visée au-dessus de l'horizon ou presque : pas de sol touché\n            return None\n        return triangulation.offset(first[\"lon\"], first[\"lat\"], first[\"heading\"],\n                                    self._camera_height() / math.tan(math.radians(-elev)))\n\n    def guide(self):\n        \"\"\"Visées guidées (voir Session.guide), chaque photo proposée avec « expect » : incertitude\n        du point (m) une fois visé aussi depuis elle, d'après une visée simulée vers le point triangulé\n        (ou provisoire), et « now » : celle d'aujourd'hui (None avec une seule visée). Largeur : en travers\n        de la route seulement, ce qui compte pour elle (« across »).\"\"\"\n        guide = super().guide()\n        tri = self.triangulator\n        r = tri.result\n        target = (r[\"lon\"], r[\"lat\"], r.get(\"z\")) if r else self._provisional_point()\n        if not guide or target is None or not tri.sightings:\n            return guide\n        lon, lat = target[:2]\n        z = target[2] if len(target) > 2 else tri.sightings[0].get(\"ground\")\n        base = tri.sightings[-1]  # même séquence : précision GPS, cap, hauteur de caméra\n        across = self._aim_across() if self.mode == \"road\" else None\n\n        def sigma(result):\n            return triangulation.projected(result, *across) if across else result[\"uncertainty\"]\n\n        for choice in guide[\"choices\"]:\n            if choice[\"lon\"] is None:\n                continue\n            x, y = triangulation._local(lon, lat, choice[\"lon\"], choice[\"lat\"])\n            dist = math.hypot(x, y)\n            alt = base.get(\"alt\")\n            sim = dict(base, pic=choice[\"id\"], lon=choice[\"lon\"], lat=choice[\"lat\"],\n                       heading=math.degrees(math.atan2(x, y)) % 360, raw=None, gps=[choice[\"lon\"], choice[\"lat\"]],\n                       elev=None if alt is None or z is None or dist < 0.5 else math.degrees(math.atan2(z - alt, dist)))\n            try:\n                res = tools.solve_on_ground(tri.sightings + [sim], tri.ground, tri.ground_z if tri.lidar else None)\n            except triangulation.TriangulationError:\n                continue\n            choice[\"expect\"], choice[\"now\"] = sigma(res), sigma(r) if r else None\n            choice[\"across\"] = across is not None\n        return guide\n\n    # Dessin ------------------------------------------------------------------------------\n    def _new_item(self):\n        item = WebItem()\n        self.items.append(item)\n        return item\n\n    def _new_rays(self):\n        item = RaysItem()\n        self.rays.append(item)\n        return item\n\n    def set_filter(self, text):\n        \"\"\"Filtre des photos (JSON : since, kind, max_gps, producer [id, nom]).\"\"\"\n        data = json.loads(text) if text else {}\n        producer = data.get(\"producer\")\n        self.photo_filter = filters.PhotoFilter(data.get(\"since\") or None, data.get(\"kind\") or None,\n                                                data.get(\"max_gps\"), tuple(producer) if producer else None)\n\n    def filter_matches(self, item_json):\n        return self.photo_filter.matches(json.loads(item_json))\n\n    def filter_text(self):\n        return self.photo_filter.describe()\n\n    def producer(self):\n        \"\"\"Producteur de la photo affichée (JSON [id, nom] ou null).\"\"\"\n        p = filters.item_producer(self.item)\n        return json.dumps(list(p) if p else None)\n\n    # Calage enregistré ---------------------------------------------------------------\n    def calibration_json(self):\n        return json.dumps(self.calibration.to_dict(), separators=(\",\", \":\"))\n\n    def load_calibration(self, text):\n        \"\"\"Calage enregistré dans le navigateur : remplace celui en mémoire. Retourne False\n        s'il est illisible.\"\"\"\n        try:\n            data = json.loads(text) if text else None\n        except ValueError:\n            return False\n        self.calibration.load(data)\n        return True\n\n    def merge_calibration(self, text):\n        \"\"\"Calage d'un fichier : complète celui en mémoire. Retourne le nombre de photos ou\n        séquences ajoutées, ou -1 si le fichier est illisible.\"\"\"\n        try:\n            added = self.calibration.merge(json.loads(text))\n        except (ValueError, TypeError, AttributeError):\n            return -1\n        if added:\n            self._calibration_changed()\n        return added\n\n    def map_geojson(self):\n        \"\"\"Mesures, visées et points triangulés à dessiner sur la carte (GeoJSON, texte).\"\"\"\n        features = []\n\n        def add(kind, geometry_type, coordinates, label=\"\", sublabel=\"\"):\n            properties = {\"kind\": kind, \"label\": label}\n            if sublabel:  # sous le trait, le long de celui-ci\n                properties[\"sublabel\"] = sublabel\n            features.append({\"type\": \"Feature\", \"properties\": properties,\n                             \"geometry\": {\"type\": geometry_type, \"coordinates\": coordinates}})\n\n        self.items = [i for i in self.items if not i.removed]\n        for item in self.items:\n            if not item.points:\n                continue\n            if len(item.points) >= 2:  # sans étiquette : pas de longueur sur la carte (demande de l'utilisateur)\n                add(\"mesure\", \"LineString\", [list(p) for p in item.points])\n            for p in item.points:\n                add(\"point\", \"Point\", list(p))\n        self.rays = [r for r in self.rays if not r.removed]\n        for item in self.rays:\n            for lon, lat, elon, elat in item.rays:\n                add(\"visee\", \"LineString\", [[lon, lat], [elon, elat]])\n            if item.point:\n                add(\"cible\", \"Point\", list(item.point))\n        road = (self.ref_point or {}).get(\"road\") if self.active and self.mode == \"road\" else None\n        if road:  # largeur : droite de mesure passant par le point de référence\n            add(\"trace\", \"LineString\", [list(p) for p in widths.guide(self.ref_point, road[\"axis\"])])\n        for lon, lat, values in self.points:\n            add(\"triangule\", \"Point\", [lon, lat], values[\"nom\"])  # nom seul : pas d'incertitude sur la carte\n        for i, j, _values in self.links:  # distance entre deux points gardés : trait rouge, sans longueur\n            add(\"distance\", \"LineString\", [list(self.points[i][:2]), list(self.points[j][:2])])\n        for v in self.map_lengths:  # longueur sur la carte : trait et valeur, comme une mesure\n            if \"surface_m2\" in v:  # surface : contour fermé, valeur au centre (genre « surface » : étiquette seule)\n                add(\"mesure\", \"LineString\", v[\"ends\"] + v[\"ends\"][:1])\n                add(\"surface\", \"Point\", [sum(p[i] for p in v[\"ends\"]) / len(v[\"ends\"]) for i in (0, 1)], _area_text(v[\"surface_m2\"]))\n            else:\n                add(\"mesure\", \"LineString\", v[\"ends\"], \"{} m\".format(measures._num(v[\"valeur_m\"], 2)))\n            for p in v[\"ends\"]:\n                add(\"point\", \"Point\", p)\n        return json.dumps({\"type\": \"FeatureCollection\", \"features\": features})\n\n    # Export ------------------------------------------------------------------------------\n    def _records(self, releve=False):\n        \"\"\"Mesures terminées et points triangulés : (géométrie [(lon, lat)], attributs), comme\n        pour l'export ; releve : les objets relevés seuls, leurs champs en colonnes.\"\"\"\n        if releve:\n            kept = [(lon, lat, values) for lon, lat, values in self.points if \"releve\" in values]\n            # Champs ajoutés en cours de relevé : à leur place, vides pour les objets d'avant\n            names = list(dict.fromkeys(k for _, _, v in kept for k in v[\"releve\"] if k not in RELEVE_PLACE))\n            return [([(lon, lat)], _releve_attrs(values, names)) for lon, lat, values in kept]\n        out = []\n        for m in self.tool.measures():\n            r = m.result\n            if not r:\n                continue\n            d = r[\"decomposition\"]\n            ends = r[\"points\"] if len(r[\"points\"]) >= 2 else r[\"picks\"]\n            # Hauteur de caméra de la photo du premier clic, pour information (la mesure n'en dépend pas) ; photo oubliée\n            # (plus de 500 vues depuis) : le réglage\n            item = self.photo_items.get(m.clicks[0].get(\"pic\"))\n            height, source, _ = self.camera_of(item, self.precision.known(item)) if item else (self.tool.camera_height, None, 0)\n\n            def num(value, digits=3):\n                return None if value is None else round(value, digits)\n\n            out.append((ends, {\n                \"type\": measures.KIND_NAMES[m.kind],\n                \"surface\": measures.SURFACE_NAMES.get(m.surface, m.surface),\n                \"valeur_m\": num(r[\"value\"]), \"incert_m\": num(r[\"uncertainty\"]),\n                \"horiz_m\": num(d[\"horizontal\"]), \"vert_m\": num(d[\"vertical\"]),\n                \"long_route_m\": num(d[\"along\"]), \"travers_m\": num(d[\"across\"]),\n                \"dist_photo_m\": num(max(r[\"ranges\"]), 1), \"camera_m\": num(height, 2),\n                \"camera_calee\": self.CAMERA_CODES.get(source, 0),\n                \"axe_route\": m.axis_source if m.kind == \"road\" else None,\n                \"recales\": len(m.overrides),\n                \"photos\": \",\".join(dict.fromkeys(c.get(\"pic\") or \"\" for c in m.clicks)),\n                \"date_mesure\": datetime.now().isoformat(timespec=\"seconds\"),\n                \"commentaire\": getattr(m, \"comment\", \"\"),\n                # Pour la revoir à l'import (src/choix.js, reviewMeasure) : photo d'où elle a été prise (celle\n                # de la fiche) et repères tels que dessinés dessus ([[cap, élévation]] en radians, texte JSON)\n                \"photo_ref\": m.clicks[0 if m.kind == \"height\" else 1].get(\"pic\"),\n                \"vue_ref\": json.dumps(m.view_ref) if getattr(m, \"view_ref\", None) else None,\n                \"etiquette\": m.label()[2:],  # sans le symbole ; « ≈ » : bord cliqué, une estimation\n            }))\n        for lon, lat, values in self.points:\n            if \"releve\" not in values:  # objets relevés : export à part, gardés à part dans le navigateur\n                out.append(([(lon, lat)], dict({\"type\": \"point triangulé\"}, **values)))\n        for v in self.map_lengths:\n            if \"surface_m2\" in v:  # contour fermé ; périmètre en valeur_m\n                out.append(([tuple(p) for p in v[\"ends\"] + v[\"ends\"][:1]], {\n                    \"type\": \"surface sur la carte\", \"surface_m2\": round(v[\"surface_m2\"], 2), \"valeur_m\": round(v[\"valeur_m\"], 3),\n                    \"date_mesure\": datetime.now().isoformat(timespec=\"seconds\"), \"commentaire\": v[\"commentaire\"]}))\n                continue\n            out.append(([tuple(p) for p in v[\"ends\"]], {\n                \"type\": \"longueur sur la carte ({})\".format(\"vue du dessus\" if v[\"incert_m\"] is not None else \"hors vue du dessus\"),\n                \"valeur_m\": round(v[\"valeur_m\"], 3), \"incert_m\": None if v[\"incert_m\"] is None else round(v[\"incert_m\"], 3),\n                \"horiz_m\": round(v[\"valeur_m\"], 3), \"photos\": v[\"photos\"],\n                \"photo_ref\": v[\"photos\"].split(\",\")[0] or None, \"date_mesure\": datetime.now().isoformat(timespec=\"seconds\"),\n                \"commentaire\": v[\"commentaire\"]}))\n        for i, j, values in self.links:\n            (lon1, lat1, v1), (lon2, lat2, v2) = self.points[i], self.points[j]\n            out.append(([(lon1, lat1), (lon2, lat2)], {\n                \"type\": \"distance entre points triangulés\", \"valeur_m\": values[\"valeur_m\"],\n                \"incert_m\": values[\"incert_m\"], \"horiz_m\": values[\"valeur_m\"], \"points\": \"{}-{}\".format(v1[\"nom\"], v2[\"nom\"]),\n                \"photos\": \",\".join(dict.fromkeys(p for v in (v1, v2) for p in v.get(\"photos\", \"\").split(\",\") if p)),\n                \"date_mesure\": datetime.now().isoformat(timespec=\"seconds\"),\n                \"commentaire\": values.get(\"commentaire\", \"\"),\n            }))\n        return out\n\n    def export_geojson(self, releve=False):\n        features = [{\"type\": \"Feature\", \"properties\": attrs,\n                     \"geometry\": ({\"type\": \"LineString\", \"coordinates\": [list(p) for p in ends]} if len(ends) >= 2\n                                  else {\"type\": \"Point\", \"coordinates\": list(ends[0])})}\n                    for ends, attrs in self._records(releve)]\n        return json.dumps({\"type\": \"FeatureCollection\", \"features\": features}, ensure_ascii=False, indent=1)\n\n    def export_csv(self):\n        \"\"\"CSV (séparateur point-virgule, virgule décimale : tableurs français), coordonnées\n        des extrémités en WGS 84 ; mesures et points triangulés dans le même tableau.\"\"\"\n        records = self._records()\n        if not records:\n            return \"\"\n        keys = list(dict.fromkeys(k for _, attrs in records for k in attrs))\n        rows = [\";\".join(keys + [\"lon1\", \"lat1\", \"lon2\", \"lat2\"])]\n        for ends, attrs in records:\n            a, b = ends[0], ends[-1]\n            values = [attrs.get(k) for k in keys] + [a[0], a[1], b[0], b[1]]\n            rows.append(\";\".join(_csv(v) for v in values))\n        return \"\\n\".join(rows) + \"\\n\"\n\n    # Captures --------------------------------------------------------------------------\n    def capture_args(self, yaw, pitch, vfov):\n        \"\"\"Paramètres de la capture HD de la vue (JSON), pour le Pyodide d'arrière-plan :\n        photo, cadrage (cap absolu, inclinaison, champ vertical, en degrés), redressement,\n        cartouche d'attribution, nom du fichier. \"\" sans photo HD.\"\"\"\n        item = self.item\n        href = (((item or {}).get(\"assets\") or {}).get(\"hd\") or {}).get(\"href\")\n        if not href:\n            return \"\"\n        props = item.get(\"properties\") or {}\n        fov = (props.get(\"pers:interior_orientation\") or {}).get(\"field_of_view\")\n        rounded = metadata.item_heading(item) or 0.0\n        heading = _view_heading(item, yaw)\n        tilt = self.calibration.tilt(item.get(\"id\")) if item.get(\"id\") else None\n        date = \"\".join(ch for ch in (props.get(\"datetime\") or \"\") if ch.isdigit())[:8] or \"sansdate\"\n        return json.dumps({\"href\": href, \"azimuth\": rounded, \"is360\": bool(fov and float(fov) >= 360),\n                           \"heading\": heading, \"pitch\": math.degrees(pitch), \"vfov\": float(vfov),\n                           \"photo_hfov\": float(fov) if fov else None,\n                           \"up\": list(tilt[\"up\"]) if tilt else None,  # vue redressée\n                           \"caption\": capture.caption_for(item, None),  # sans le cap\n                           \"name\": \"panoramax_{}_cap{:03.0f}_{}\".format(date, heading, (item.get(\"id\") or \"\")[:8])})\n\n    def caption(self):\n        \"\"\"Cartouche d'attribution de la vue (obligation des licences Panoramax) : auteur, date,\n        catégorie de la licence.\"\"\"\n        if not self.item:\n            return \"Panoramax\"\n        return capture.caption_for(self.item, None)\n\n\ndef _view_heading(item, yaw):\n    \"\"\"Cap (degrés) du centre de la vue : la visionneuse s'oriente sur view:azimuth.\"\"\"\n    return (math.degrees(yaw) + (metadata.item_heading(item) or 0.0)) % 360\n\n\nRELEVE_PLACE = (\"voie\", \"pr\", \"commune\")  # lieu de l'objet, ajouté par la page à ses champs\n\n\ndef _releve_attrs(values, names):\n    \"\"\"Colonnes d'un objet relevé : id, champs de l'utilisateur (names, dans l'ordre de leur création ;\n    None s'il n'en a pas la valeur), lieu, commentaire, puis le reste des attributs du point (sans\n    « nom », qui reprend l'id, ni « type », laissé à l'utilisateur).\"\"\"\n    fields = values[\"releve\"]\n    out = {\"id\": values.get(\"id\")}\n    out.update((k, fields.get(k)) for k in names)\n    out.update((k, fields.get(k, \"\")) for k in RELEVE_PLACE)\n    out[\"commentaire\"] = values.get(\"commentaire\", \"\")\n    out.update((k, v) for k, v in values.items() if k not in (\"id\", \"nom\", \"releve\", \"commentaire\"))\n    return out\n\n\ndef _aimed_z(r, sightings):\n    \"\"\"Altitude NGF (m) du point triangulé r : celle de la triangulation 3D, sinon la moyenne des\n    visées dont la caméra a son altitude (alt + distance × tangente de l'inclinaison) ; None sans.\"\"\"\n    if r is None:\n        return None\n    if r.get(\"z\") is not None:\n        return r[\"z\"]\n    zs = [s[\"alt\"] + d * math.tan(math.radians(s.get(\"elev\") or 0.0))\n          for s, d in zip(sightings, r[\"distances\"]) if s.get(\"alt\") is not None]\n    return sum(zs) / len(zs) if zs else None\n\n\ndef _field_text(value):\n    \"\"\"Valeur d'un champ d'objet relevé pour la fiche : oui/non, nombre à virgule, texte.\"\"\"\n    if isinstance(value, bool):\n        return \"oui\" if value else \"non\"\n    if isinstance(value, float):\n        return str(value).replace(\".\", \",\")\n    return \"\" if value is None else str(value)\n\n\ndef _csv(value):\n    if value is None:\n        return \"\"\n    if isinstance(value, float):\n        return repr(round(value, 7)).replace(\".\", \",\")\n    text = str(value)\n    return '\"' + text.replace('\"', '\"\"') + '\"' if any(c in text for c in ';\"\\n') else text\n\n\ndef _without_repeats(notes):\n    \"\"\"Lignes des mesures d'un même point (fiche, voir App._fiche_note), sans leur nom (« ↔ B ») ni\n    les morceaux déjà écrits plus haut (même caméra, même axe) ; une mesure sans rien de nouveau n'a\n    pas de ligne.\"\"\"\n    seen, out = set(), []\n    for _, parts in notes:\n        fresh = [p for p in parts if p not in seen]\n        seen.update(parts)\n        if fresh:\n            text = \" · \".join(fresh)\n            out.append(text[0].upper() + text[1:])\n    return out\n\n\ndef _keep_view(m, points):\n    \"\"\"Repères de la mesure m tels que dessinés sur sa photo ([[cap, élévation]], radians), gardés pour l'export.\"\"\"\n    if all(p.get(\"yaw\") is not None for p in points):\n        m.view_ref = [[round(p[\"yaw\"], 5), round(p[\"pitch\"], 5)] for p in points]\n\n\ndef _densified(pts, step):\n    \"\"\"Ligne [(lon, lat, z ou None)] redécoupée tous les step m au plus (z interpolé s'il est connu aux\n    deux bouts) : elle suit le terrain entre ses sommets.\"\"\"\n    out = [pts[0]]\n    for (lon1, lat1, z1), (lon2, lat2, z2) in zip(pts, pts[1:]):\n        x, y = triangulation._local(lon2, lat2, lon1, lat1)\n        n = min(200, int(math.hypot(x, y) // step))\n        for j in range(1, n + 1):\n            t = j / (n + 1)\n            out.append((lon1 + t * (lon2 - lon1), lat1 + t * (lat2 - lat1),\n                        z1 + t * (z2 - z1) if z1 is not None and z2 is not None else None))\n        out.append((lon2, lat2, z2))\n    return out\n\n\ndef _map_line_text(text):\n    \"\"\"Texte de la largeur (widths.PerpendicularWidth.status) prise sur une droite tracée sur la carte\n    (ticket #28) : ni perpendiculaire à la chaussée, ni depuis un point triangulé (A posé d'un clic).\"\"\"\n    on_line = r\"(?=[^.]*\" + re.escape(MAP_SOURCE) + \")\"\n    text = re.sub(\"Largeur perpendiculaire à la chaussée\" + on_line, \"Largeur le long de la droite tracée sur la carte\", text)\n    text = re.sub(\"depuis le point triangulé \" + on_line, \"depuis le point \", text)\n    text = re.sub(\"entre les points triangulés \" + on_line, \"entre les points \", text)\n    return re.sub(r\"axe (\\d+)° \\(\" + re.escape(MAP_SOURCE),  # axe : perpendiculaire à la droite\n                  lambda m: \"droite à {}° (tracée sur la carte\".format((int(m.group(1)) + 90) % 180), text)\n\n\ndef _on_axis(axis, yaw, pitch):\n    \"\"\"(cap, élévation) en radians du point du grand cercle passant par les deux directions de axis\n    (droite dans la vue) le plus proche de (yaw, pitch).\"\"\"\n    def vec(y, p):\n        return (math.cos(p) * math.sin(y), math.sin(p), math.cos(p) * math.cos(y))\n    a, c, v = vec(*axis[0]), vec(*axis[1]), vec(yaw, pitch)\n    n = (a[1] * c[2] - a[2] * c[1], a[2] * c[0] - a[0] * c[2], a[0] * c[1] - a[1] * c[0])\n    norm = math.sqrt(sum(k * k for k in n))\n    if norm < 1e-9:\n        return yaw, pitch\n    d = sum(vk * nk for vk, nk in zip(v, n)) / norm\n    w = [vk - d * nk / norm for vk, nk in zip(v, n)]\n    length = math.sqrt(sum(k * k for k in w))\n    return math.atan2(w[0], w[2]), math.asin(max(-1.0, min(1.0, w[1] / length)))\n",
 "web_chutes.py": "# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Hauteurs de chute et dévers, sortis de web_app.py : sur un pont (ticket #15) et sur les bords de route hors pont\n(ticket #31), avec leurs utilitaires (ponts de la BD TOPO, profil de la plateforme, noms des voies et de l'eau).\nChutes est une base de web_app.App : ses méthodes lisent l'état de l'application (self).\"\"\"\n\nimport json\nimport math\nimport re\nimport time\n\nfrom core import host, measures, metadata, precision, roads, tools, triangulation\n\n\n# Mots laissés en minuscules dans un nom remis en forme (sauf au début) : « Pont de France »\n_SMALL_WORDS = {\"de\", \"du\", \"des\", \"la\", \"le\", \"les\", \"et\", \"en\", \"sur\", \"sous\", \"aux\", \"à\"}\n\n\ndef _bridge_name(text):\n    \"\"\"Nom de pont tiré du nom d'un tronçon BD TOPO en majuscules (« PONT DE FRANCE » -> « Pont de\n    France »), ou None s'il ne nomme pas un ouvrage (nom de la rue qui passe dessus).\"\"\"\n    words = (text or \"\").strip().lower().split()\n    if not words or words[0] not in (\"pont\", \"viaduc\", \"passerelle\"):\n        return None\n    return _title(words)\n\n\ndef _title(words, first=True):\n    \"\"\"Mots en minuscules remis en forme d'un nom : capitales sauf petits mots (_SMALL_WORDS).\"\"\"\n    def word(w, first):\n        if \"'\" in w:  # d'or -> d'Or\n            head, tail = w.split(\"'\", 1)\n            return (head.capitalize() if first else head) + \"'\" + word(tail, False)\n        if not first and w in _SMALL_WORDS:\n            return w\n        return \"-\".join(part.capitalize() for part in w.split(\"-\"))\n\n    return \" \".join(word(w, first and k == 0) for k, w in enumerate(words))\n\n\n# Voies de la BD TOPO (nom en abréviations, « R DE PARIS ») : nom en clair, avec son article\n_STREETS = {\"R\": \"la rue\", \"AV\": \"l'avenue\", \"BD\": \"le boulevard\", \"CHE\": \"le chemin\", \"CHEM\": \"le chemin\",\n            \"RTE\": \"la route\", \"PL\": \"la place\", \"IMP\": \"l'impasse\", \"ALL\": \"l'allée\", \"QU\": \"le quai\",\n            \"QUAI\": \"le quai\", \"CRS\": \"le cours\", \"PROM\": \"la promenade\", \"FG\": \"le faubourg\", \"VC\": \"la voie communale\"}\n\n\ndef _road_label(name):\n    \"\"\"Route franchie, avec son article : « l'A6 », « la D905 », « la rue de Paris », sinon « une route ».\"\"\"\n    if re.match(r\"[A-Z]+\\d\", name or \"\"):\n        return (\"l'\" if name[0] in \"AEIOUY\" else \"la \") + name\n    words = (name or \"\").split()\n    if len(words) > 1 and name.isupper() and words[0] in _STREETS:\n        return _STREETS[words[0]] + \" \" + _title([w.lower() for w in words[1:]], first=False)\n    return \"une route\"\n\n\n# Cours d'eau nommés sans article par la BD TOPO (« Canal de Bourgogne ») : genre du nom commun\n_WATERS = {\"canal\": \"le\", \"ruisseau\": \"le\", \"bief\": \"le\", \"fossé\": \"le\", \"fleuve\": \"le\", \"torrent\": \"le\",\n           \"ru\": \"le\", \"rû\": \"le\", \"bras\": \"le\", \"déversoir\": \"le\", \"aqueduc\": \"le\", \"étang\": \"le\",\n           \"rivière\": \"la\", \"rigole\": \"la\", \"noue\": \"la\", \"dérivation\": \"la\", \"ravine\": \"la\", \"source\": \"la\"}\n\n\ndef _water_label(name):\n    \"\"\"Cours d'eau franchi, avec son article : « l'Armançon » (déjà dans la BD TOPO), « le canal de\n    Bourgogne », « la rivière … », « l'étang … » ; sans nom commun connu, le nom tel quel.\"\"\"\n    article = re.match(r\"(l'|la |le |les )\", name, re.IGNORECASE)\n    if article:  # article en minuscule en milieu de phrase : « de la Vouge »\n        return article.group(1).lower() + name[article.end():]\n    first, _, rest = name.partition(\" \")\n    article = _WATERS.get(first.lower())\n    if article is None:\n        return name\n    noun = first.lower() + (\" \" + rest if rest else \"\")\n    return (\"l'\" if noun[0] in \"aeiouyéèêh\" else article + \" \") + noun\n\n\ndef _of(label):\n    \"\"\"« de » devant un nom avec article : de l'Armançon, de la D905, du chemin…, d'une route ; d'Ouche.\"\"\"\n    for article, of in ((\"le \", \"du \"), (\"les \", \"des \"), (\"un \", \"d'un \"), (\"une \", \"d'une \")):\n        if label.startswith(article):\n            return of + label[len(article):]\n    if label[:1].lower() in \"aeiouyéèêh\" and not label.startswith(\"l'\"):\n        return \"d'\" + label  # nom propre sans article : d'Ouche\n    return \"de \" + label\n\n\ndef _distance(metres, whole=False):\n    \"\"\"Distance au bord écrite : au décimètre sous 10 m, au mètre au-delà (ou si whole), arrondie au plus proche comme dans\n    la page (profil.js, dist) : « 0,5 m » et non « 0 m », « 11 m » pour 10,5 et non « 10 m » (format arrondit au pair).\"\"\"\n    digits = 0 if whole or metres >= 9.95 else 1\n    return measures._num(math.floor(metres * 10 ** digits + 0.5) / 10 ** digits, digits)\n\n\ndef _line_slope(points):\n    \"\"\"Pente (%, positive si le terrain descend vers les x croissants) de la droite des moindres carrés, ou None sous 3 points.\"\"\"\n    if len(points) < 3:\n        return None\n    mx, mz = sum(p[0] for p in points) / len(points), sum(p[1] for p in points) / len(points)\n    sxx = sum((p[0] - mx) ** 2 for p in points)\n    return -100 * sum((p[0] - mx) * (p[1] - mz) for p in points) / sxx if sxx else None\n\n\ndef _spread(values):\n    \"\"\"Écart type des valeurs.\"\"\"\n    mean = sum(values) / len(values)\n    return math.sqrt(sum((v - mean) ** 2 for v in values) / len(values))\n\n\nPLATFORM_MIN_CROSSINGS = 3  # travers exploitables au moins\n\n\nPLATFORM_SPREAD = 1.0  # points : écart entre travers au-delà duquel le dévers n'est pas déterminé\n\n\nPLATFORM_SIDE_MIN = 0.8  # points : moitiés de sens opposés seulement si chacune penche au moins de cela\n\n\nPLATFORM_TWIN_GAP = 1.0  # points : chaussées séparées : un chiffre par chaussée dès cet écart\n\n\nPLATFORM_ROOF_GAP = 1.0  # points : toit symétrique, pente moyenne affichée, jusqu'à cet écart entre ses deux pentes\n\n\ndef platform_slope(drawn):\n    \"\"\"Dévers de la plateforme (ticket #38) d'après les travers du profil (entrées de App._compute_edges), en %, positif\n    s'il descend vers la droite : droite ajustée sur chaque moitié (chaque chaussée, séparateur exclu) et sur l'ensemble,\n    moyennées sur les travers. Retourne {\"type\": ...} : \"sens\" (pente), \"toit\" (pente moyenne, gauche, droite), \"demi\"\n    (gauche, droite) ou \"indetermine\" : travers trop différents (voir docs/CALCULS.md, 8.7).\"\"\"\n    crossings = {}\n    for entry in drawn:\n        sign = -1 if entry[\"cote\"] == \"gauche\" else 1\n        c = crossings.setdefault(entry[\"le_long\"], {\"points\": set(), \"edges\": {}, \"between\": None})\n        c[\"points\"].update((sign * o, z) for o, z in entry[\"points\"])\n        c[\"edges\"][entry[\"cote\"]] = sign * entry[\"bord\"]\n        if entry.get(\"separateur\"):\n            c[\"between\"] = sorted(sign * v for v in entry[\"separateur\"])\n    whole, left, right, twin = [], [], [], False\n    for c in crossings.values():\n        if len(c[\"edges\"]) < 2:\n            continue\n        low, high = c[\"edges\"][\"gauche\"], c[\"edges\"][\"droit\"]\n        twin = twin or bool(c[\"between\"])\n        a, b = c[\"between\"] or ((low + high) / 2, (low + high) / 2)\n        points = [p for p in c[\"points\"] if low <= p[0] <= high]\n        slopes = (_line_slope([p for p in points if p[0] <= a or p[0] >= b]), _line_slope([p for p in points if p[0] <= a]),\n                  _line_slope([p for p in points if p[0] >= b]))\n        if None not in slopes:\n            whole.append(slopes[0])\n            left.append(slopes[1])\n            right.append(slopes[2])\n    if len(whole) < PLATFORM_MIN_CROSSINGS:\n        return {\"type\": \"indetermine\"}\n    mean = lambda values: sum(values) / len(values)\n    s, g, d = mean(whole), mean(left), mean(right)\n    opposed = g * d < 0 and min(abs(g), abs(d)) >= PLATFORM_SIDE_MIN\n    if opposed or (twin and abs(g - d) >= PLATFORM_TWIN_GAP):\n        if max(_spread(left), _spread(right)) > PLATFORM_SPREAD:\n            return {\"type\": \"indetermine\"}\n        sides = {\"gauche\": round(g, 2), \"droite\": round(d, 2)}\n        if opposed and g < 0 < d and abs(abs(g) - abs(d)) <= PLATFORM_ROOF_GAP:  # chaque moitié descend vers son bord\n            return dict(sides, type=\"toit\", pente=round((abs(g) + abs(d)) / 2, 2))\n        return dict(sides, type=\"demi\")\n    if _spread(whole) > PLATFORM_SPREAD:\n        return {\"type\": \"indetermine\"}\n    return {\"type\": \"sens\", \"pente\": round(s, 2)}\n\n\ndef _ign_bridges(data):\n    \"\"\"Ponts nommés de la BD TOPO (constructions linéaires de nature « Pont ») : [(ligne, nom)].\"\"\"\n    out = []\n    for feat in data.get(\"features\") or []:\n        props, geom = feat.get(\"properties\") or {}, feat.get(\"geometry\") or {}\n        if props.get(\"nature\") == \"Pont\" and props.get(\"toponyme\"):\n            coords = geom.get(\"coordinates\") or []\n            for line in coords if geom.get(\"type\") == \"MultiLineString\" else [coords]:\n                out.append(([tuple(p[:2]) for p in line], props[\"toponyme\"]))\n    return out\n\n\n# Natures de la BD TOPO : nom d'une voie sans numéro ni nom (roads.parse_sections) ; ces voies ne sont pas citées aux carrefours\n_WAY_KINDS = {\"Route à 1 chaussée\": \"une route\", \"Route à 2 chaussées\": \"une route\", \"Route empierrée\": \"un chemin empierré\",\n              \"Chemin\": \"un chemin\", \"Sentier\": \"un sentier\", \"Rond-point\": \"un rond-point\", \"Bretelle\": \"une bretelle\",\n              \"Type autoroutier\": \"une voie rapide\", \"Piste cyclable\": \"une piste cyclable\", \"Escalier\": \"un escalier\"}\n\n\ndef _deck_at(decks, x, y):\n    \"\"\"Altitude du tablier en (x, y) (repère local, m) d'après les photos de la séquence prises sur le pont, decks\n    [(x, y, altitude, rang)] : point ramené sur le segment le plus proche entre deux photos consécutives (rangs) et\n    altitude interpolée entre elles (pont long et pentu) ; une seule photo : son altitude.\"\"\"\n    path = sorted(decks, key=lambda d: d[3])\n    if len(path) == 1:\n        return path[0][2]\n    best = None\n    for a, b in zip(path, path[1:]):\n        dx, dy = b[0] - a[0], b[1] - a[1]\n        u = max(0.0, min(1.0, ((x - a[0]) * dx + (y - a[1]) * dy) / ((dx * dx + dy * dy) or 1.0)))\n        d = math.hypot(a[0] + u * dx - x, a[1] + u * dy - y)\n        if best is None or d < best[0]:\n            best = (d, a[2] + u * (b[2] - a[2]))\n    return best[1]\n\n\ndef _crossing(a, b, c, d):\n    \"\"\"Point (x, y) où les segments [a, b] et [c, d] se coupent ou se touchent (sommet commun : la BD TOPO\n    en met un au croisement de deux niveaux), ou None (pas de contact, ou parallèles).\"\"\"\n    den = (b[0] - a[0]) * (d[1] - c[1]) - (b[1] - a[1]) * (d[0] - c[0])\n    if not den:\n        return None\n    t = ((c[0] - a[0]) * (d[1] - c[1]) - (c[1] - a[1]) * (d[0] - c[0])) / den\n    u = ((c[0] - a[0]) * (b[1] - a[1]) - (c[1] - a[1]) * (b[0] - a[0])) / den\n    eps = 1e-9\n    return (a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1])) if -eps <= t <= 1 + eps and -eps <= u <= 1 + eps else None\n\n\ndef _nearest_name(bridges, lon, lat, reach):\n    \"\"\"Nom du pont le plus proche de (lon, lat), à reach m au plus de sa ligne, ou None.\"\"\"\n    best = None\n    for line, name in bridges or []:\n        pts = [triangulation._local(p[0], p[1], lon, lat) for p in line]\n        for (ax, ay), (bx, by) in zip(pts, pts[1:] or pts):  # distance du point (0, 0) au segment\n            t = max(0.0, min(1.0, -(ax * (bx - ax) + ay * (by - ay)) / ((bx - ax) ** 2 + (by - ay) ** 2 or 1.0)))\n            d = math.hypot(ax + t * (bx - ax), ay + t * (by - ay))\n            if d <= reach and (best is None or d < best[0]):\n                best = (d, name)\n    return best and best[1]\n\n\nclass Chutes:\n    \"\"\"Chutes sur un pont et bords de route (voir web_app.App).\"\"\"\n\n    # Hauteur de chute sur un pont (ticket #15) ---------------------------------------------\n    # m au-delà du bord de la chaussée, de chaque côté : du pied du garde-corps jusqu'au fond, à\n    # l'écart du tablier (le MNT, interpolé sous lui, y descend en pente douce : ticket #27)\n    FALL_SIDES = (1.0, 3.0, 6.0, 10.0)\n    FALL_STEP = 2.0  # m entre deux travers le long du pont (plus si le pont est long)\n    FALL_REQUESTS = 6  # requêtes au plus au service d'altimétrie pour les coupes du pont (FALL_POINTS points chacune)\n    FALL_DECK_TOL = 0.5  # m : terrain sous l'axe à cela près du tablier (GPS) : tablier classé sol, compris dans le MNT\n    FALL_POINTS = 160  # points par requête au service d'altimétrie (longueur de l'adresse ; voir _terrain)\n    FALL_MIN = 0.5  # m : en dessous, terrain non distingué du tablier (végétation, buse)\n    FALL_WIDTH = 6.0  # m : largeur type d'une route d'importance inconnue (_road_width)\n    # Largeur type de la chaussée (m) par importance BD TOPO, pour les bords de route (_road_width) : la largeur BD TOPO n'est\n    # qu'une valeur par catégorie, pas fiable (piste P17). Valeurs prudentes choisies par l'auteur le 20/11/2026 : les médianes\n    # de l'analyse fine (9 m en 1-2, 6,5 m en 3, 6 m en 4) comptaient trottoirs et gravier (P21) ; à refaire sur des largeurs\n    # vérifiées à la main. ROAD_TWIN par chaussée d'une route à chaussées séparées ; 3,5 m : voie unique\n    ROAD_WIDTHS, ROAD_TWIN = {\"1\": 7.0, \"2\": 7.0, \"3\": 6.0, \"4\": 5.5, \"5\": 3.5}, 7.0\n    FALL_TOUCH = 1.0  # m : tronçons en pont bout à bout (un pont coupé en plusieurs tronçons)\n    FALL_RETRY = 60.0  # s avant de refaire un calcul qui a échoué (service injoignable)\n    FALL_LIDAR_REACH = 10.0  # m : dessous cherché à cette distance du tablier (DECK_REACH de src/nuage.js)\n    FALL_NO_RTK = (\"Hauteur de chute non calculée : la position GPS de cette séquence n'est pas vérifiée RTK. \"\n                   \"L'altitude du tablier, tirée de l'altitude GPS de la caméra, serait fausse de plusieurs mètres.\")\n\n    def fall(self):\n        \"\"\"Photo prise sur un pont (BD TOPO) : hauteur de chute la plus grande sur toute la longueur du\n        pont ({text, title}), son explication sans RTK vérifié, ou l'attente de son calcul ; hors d'un\n        pont, chute et dévers des bords de la route (_edges, ticket #31). D'abord le nuage LiDAR HD (Nuage.bridgeFall, lu par la\n        page : champ « lidar » ; use_bridge_lidar), même valeur sur tout le pont, sans GPS. Sans points classés pont, ou nuage\n        illisible : tablier = altitude GPS RTK (NGF) moins hauteur de caméra, aux photos de la séquence\n        prises sur le pont (la plus proche de chaque point) ; dessous : MNT LiDAR HD (RGE ALTI en\n        secours), le point le plus bas en travers du pont, de 1 à 10 m au-delà du bord du tablier, des deux côtés (FALL_SIDES ;\n        bord lu dans le relief si le MNT contient le tablier, sinon la demi-largeur type ; sous un tablier absent du MNT,\n        celui-ci est interpolé à sa hauteur).\"\"\"\n        item = self.item or {}\n        try:\n            lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        except (KeyError, TypeError, ValueError):\n            return None\n        sections = self._fall_sections(lon, lat)\n        if sections is None and item.get(\"id\") in self.edges_asked:\n            why = self.fall_error.get(roads._cell(lon, lat))\n            return {\"text\": \"Bords de route\\nCalcul impossible (BD TOPO injoignable{})\".format(\" : \" + why if why else \"\"),\n                    \"title\": \"\", \"edges\": True}\n        if not sections or sections is roads.PENDING:\n            return None\n        axis = self._axis(item)\n        sec = roads.on_bridge(sections, lon, lat, metadata.item_heading(item) if axis is None else axis)\n        if sec is None:\n            return self._edges(item, sections, lon, lat)\n        chain = self._bridge_chain(sections, sec)\n        # Nom du pont (BD TOPO), et sa route : « Pont de France (D905) », sinon « Pont de la D111 »,\n        # « Pont de l'A38 » (élision devant une voyelle)\n        name = next((c[\"bridge_name\"] for c in chain if c.get(\"bridge_name\")), None) or self._named_bridge(lon, lat)\n        road = next((c[\"name\"] for c in chain if re.match(r\"[A-Z]+\\d\", c.get(\"name\") or \"\")), None)\n        of_road = road and (\"Pont de l'\" if road[0] in \"AEIOUY\" else \"Pont de la \") + road\n        bridge = \"{} ({})\".format(name, road) if name and road else name or of_road or \"Pont\"\n        over = self._crossed(chain, sections, lon, lat)  # « Au-dessus de l'Armançon », sous le nom\n        bridge += \"\\n\" + over if over else \"\"\n        lidar_key = \"{:.6f},{:.6f}\".format(*min(p for c in chain for p in c[\"line\"]))\n        lidar = self.lidar_falls.get(lidar_key)\n        if lidar is None or time.monotonic() >= lidar.get(\"retry_at\", float(\"inf\")):\n            return {\"text\": bridge + \"\\nHauteur de chute : lecture du nuage LiDAR HD…\", \"title\": \"\",\n                    \"lidar\": {\"key\": lidar_key, \"lon\": lon, \"lat\": lat, \"chain\": [list(p[:2]) for c in chain for p in c[\"line\"]]}}\n        if \"text\" in lidar:\n            return {\"text\": bridge + \"\\n\" + lidar[\"text\"], \"title\": lidar[\"title\"]}\n        if self.quality is None:\n            return {\"text\": bridge + \"\\nHauteur de chute : vérification de la position GPS en cours…\", \"title\": \"\"}\n        if not self.quality.get(\"precise\"):\n            return {\"text\": bridge + \"\\n\" + self.FALL_NO_RTK, \"title\": \"\"}\n        camera = self._fall_camera()\n        if camera is None:  # ni mesurée ni calée : le réglage, seulement si l'utilisateur l'accepte\n            return {\"text\": bridge + \"\\nHauteur de chute : hauteur de caméra inconnue sur ce pont\", \"title\": self.FALL_ASK,\n                    \"ask\": \"Calculer avec « Caméra à » ({} m)\".format(measures._num(self.tool.camera_height, 2))}\n        key = (item.get(\"collection\"), min(p for c in chain for p in c[\"line\"]), camera)\n        res = self.falls.get(key)\n        if res is None or time.monotonic() >= res.get(\"retry_at\", float(\"inf\")):\n            res = self.falls[key] = {\"text\": \"Hauteur de chute : calcul en cours…\", \"title\": \"\"}\n            self._compute_fall(key, chain, item, lon, lat)\n        return {\"text\": bridge + \"\\n\" + res[\"text\"], \"title\": res[\"title\"]}\n\n    def use_bridge_lidar(self, key, answer):\n        \"\"\"Réponse de Nuage.bridgeFall pour le pont key (JSON) : { height, below } ; { none } : pas de points classés pont, ou\n        { error } : nuage illisible (nouvel essai après FALL_RETRY s) ; dans ces deux cas, la méthode par l'altitude GPS.\"\"\"\n        found = json.loads(answer)\n        if found.get(\"error\"):\n            self.lidar_falls[key] = {\"retry_at\": time.monotonic() + self.FALL_RETRY}\n        elif found.get(\"none\"):\n            self.lidar_falls[key] = {}\n        elif found.get(\"height\") is None or found[\"height\"] < self.FALL_MIN:\n            self.lidar_falls[key] = {\"text\": \"Hauteur de chute non mesurée : le terrain sous le pont ne se distingue \"\n                                             \"pas du tablier (végétation, buse ?)\", \"title\": \"\"}\n        else:\n            sigma = math.hypot(triangulation.LIDAR_ERROR, triangulation.LIDAR_ERROR)\n            self.lidar_falls[key] = {\n                \"text\": \"Hauteur de chute max : {} m (±{} m), LiDAR\".format(measures._num(found[\"height\"], 1), measures._num(sigma, 1)),\n                \"title\": (\"Plus grande hauteur entre le tablier (points du nuage LiDAR HD classés pont) et {} sous le pont \"\n                          \"ou à côté, jusqu'à {} m du tablier ; même valeur sur tout le pont. Au-dessus de l'eau : niveau \"\n                          \"au relevé, pas le fond.\").format(\"l'eau\" if found[\"below\"] == \"eau\" else \"le sol\",\n                                                           measures._num(self.FALL_LIDAR_REACH, 0))}\n        return self.status()\n\n    # Hauteur de caméra du tablier : mesurée sur la séquence vérifiée (médiane de l'altitude RTK moins le sol LiDAR, photos du\n    # pont écartées), sinon calée pour la séquence. Une photo de précision déclarée n'a que sa propre hauteur, altitude moins\n    # le sol sous elle : sur un pont, le fond franchi (plausible encore sur un pont bas) ; le réglage « Caméra à » prend sa\n    # place, seulement si l'utilisateur l'accepte (use_fall_setting)\n    FALL_ASK = (\"La hauteur de caméra n'est ni mesurée sur la séquence (précision déclarée dans la photo : sa hauteur est \"\n                \"prise au-dessus du sol sous elle, ici le fond franchi) ni calée. Le calcul peut utiliser le réglage \"\n                \"« Caméra à » : la hauteur de chute en dépend directement.\")\n    fall_setting = False  # l'utilisateur accepte le réglage « Caméra à » pour la hauteur de chute\n\n    def _fall_camera(self):\n        \"\"\"(hauteur de caméra en m, sa source, son incertitude en m) pour le tablier, ou None (à demander) : mesurée sur la\n        séquence, calée, monture du CD21 d'après la date, sinon le réglage si l'utilisateur l'accepte (camera_of).\"\"\"\n        h, source, sigma = self.camera_of(self.item, self.quality, sequence_only=True)\n        if source is None and not self.fall_setting:\n            return None\n        return round(h, 3), {\"altitude GPS\": \"séquence\", None: \"réglage\"}.get(source, source), sigma\n\n    def use_fall_setting(self):\n        \"\"\"Bouton de l'encadré du pont : la hauteur de chute utilise le réglage « Caméra à » (pour la session).\"\"\"\n        self.fall_setting = True\n        return self.status()\n\n    def _fall_sections(self, lon, lat):\n        \"\"\"Tronçons BD TOPO de la maille du point, avec leur importance et leur nature (la largeur BD TOPO n'est plus lue :\n        voir _road_width), lues ici : ceux du cœur (roads) ne les gardent pas. roads.PENDING pendant la lecture, None si la BD\n        TOPO n'a pas répondu (nouvel essai FALL_RETRY s après, comme _bdtopo : une panne passagère de la Géoplateforme ne\n        prive plus de bords de route jusqu'au rechargement de la page).\"\"\"\n        cell = roads._cell(lon, lat)\n        if cell in self.fall_cells and time.monotonic() < self.fall_retry.get(cell, float(\"inf\")):\n            return self.fall_cells[cell]\n        self.fall_cells[cell] = roads.PENDING\n        self.fall_retry.pop(cell, None)\n\n        def done(data, error):\n            out = None\n            if not error:\n                out = []\n                for feat in (data or {}).get(\"features\") or []:\n                    props = feat.get(\"properties\") or {}\n                    out += [dict(sec, importance=str(props.get(\"importance\") or \"\"), nature=props.get(\"nature\"),\n                                 bridge_name=_bridge_name(props.get(\"nom_collaboratif_gauche\")))\n                            for sec in roads.parse_sections({\"features\": [feat]})]\n            self.fall_cells[cell] = out\n            if error:\n                self.fall_retry[cell] = time.monotonic() + self.FALL_RETRY\n                self.fall_error[cell] = str(error)\n            self.notify()\n\n        host.fetch_json(roads.wfs_url(cell), done, timeout_ms=15000)\n        return self.fall_cells[cell]\n\n    BRIDGE_REACH = 25.0  # m au plus entre la photo et le pont nommé (bord du tablier)\n    CROSS_END = 2.0  # m : contact aussi près d'un bout du pont, raccordement et non franchissement\n\n    def _named_bridge(self, lon, lat):\n        \"\"\"Nom du pont le plus proche de la photo (BRIDGE_REACH m au plus) quand le tronçon ne le nomme pas\n        (il porte le nom de la rue) : ouvrage « Pont » de la BD TOPO (constructions linéaires), une requête\n        par maille comme les tronçons ; None sinon, pendant la lecture ou si la BD TOPO n'a pas répondu.\"\"\"\n        found = self._bdtopo(\"construction_lineaire\", roads._cell(lon, lat))\n        return _nearest_name(_ign_bridges({\"features\": found or []}), lon, lat, self.BRIDGE_REACH)\n\n    def _bdtopo(self, layer, cell):\n        \"\"\"Objets GeoJSON d'une couche de la BD TOPO dans la maille (et MARGIN m autour), lus comme les\n        tronçons : liste, None pendant la lecture, [] si la BD TOPO n'a pas répondu (nouvel essai FALL_RETRY s après).\"\"\"\n        key = (layer, cell)\n        if key not in self.bdtopo or time.monotonic() >= self.bdtopo_retry.get(key, float(\"inf\")):\n            self.bdtopo[key] = None\n            self.bdtopo_retry.pop(key, None)\n\n            def done(data, error):\n                self.bdtopo[key] = [] if error else (data or {}).get(\"features\") or []\n                if error:\n                    self.bdtopo_retry[key] = time.monotonic() + self.FALL_RETRY\n                if self.bdtopo[key]:\n                    self.notify()\n\n            host.fetch_json(roads.wfs_url(cell).replace(\"troncon_de_route\", layer), done, timeout_ms=15000)\n        return self.bdtopo[key]\n\n    def _crossed(self, chain, sections, lon, lat):\n        \"\"\"Ce que le pont (chain) franchit, d'après la BD TOPO : cours d'eau, sinon voies ferrées et routes\n        plus basses, dont la ligne croise la sienne ; « Au-dessus de l'Armançon », « Au-dessus de la voie\n        ferrée et de la D905 », ou None (rien trouvé, ou lecture en cours).\"\"\"\n        cell, level = roads._cell(lon, lat), max(c[\"level\"] for c in chain)\n        deck = [[triangulation._local(p[0], p[1], lon, lat) for p in c[\"line\"]] for c in chain]\n        ends = [p for seg in deck for p in (seg[0], seg[-1])]\n        ends = [p for p in ends if sum(math.hypot(p[0] - q[0], p[1] - q[1]) < self.FALL_TOUCH for q in ends) == 1]\n\n        def crosses(line):  # contact avec le pont ailleurs qu'à ses bouts (routes qui s'y raccordent)\n            pts = [triangulation._local(p[0], p[1], lon, lat) for p in line]\n            for seg in deck:\n                for a, b in zip(seg, seg[1:]):\n                    for c, d in zip(pts, pts[1:]):\n                        x = _crossing(a, b, c, d)\n                        if x and all(math.hypot(x[0] - e[0], x[1] - e[1]) > self.CROSS_END for e in ends):\n                            return True\n            return False\n\n        def lines(feat):\n            geom = feat.get(\"geometry\") or {}\n            coords = geom.get(\"coordinates\") or []\n            return coords if geom.get(\"type\") == \"MultiLineString\" else [coords]\n\n        def below(feat):\n            try:\n                return int((feat.get(\"properties\") or {}).get(\"position_par_rapport_au_sol\") or 0) < level\n            except (TypeError, ValueError):\n                return True\n\n        labels = []\n        for feat in self._bdtopo(\"troncon_hydrographique\", cell) or []:\n            if below(feat) and any(crosses(line) for line in lines(feat)):\n                name = (feat.get(\"properties\") or {}).get(\"cpx_toponyme_de_cours_d_eau\")\n                labels.append(_water_label(name) if name else \"un cours d'eau\")\n        if not labels:  # cours d'eau franchi : lui seul (routes et voies ferrées des berges en plus)\n            for feat in self._bdtopo(\"troncon_de_voie_ferree\", cell) or []:\n                if below(feat) and any(crosses(line) for line in lines(feat)):\n                    labels.append(\"la voie ferrée\")\n            labels += [_road_label(sec[\"name\"]) for sec in sections\n                       if sec[\"level\"] < level and sec not in chain and crosses(sec[\"line\"])]\n        labels = list(dict.fromkeys(labels))\n        return \"Au-dessus \" + \" et \".join(_of(x) for x in labels) if labels else None\n\n    def _bridge_chain(self, sections, first):\n        \"\"\"Tronçons en pont bout à bout avec first : le pont entier.\"\"\"\n        chain = [first]\n        grown = True\n        while grown:\n            grown = False\n            ends = [p for c in chain for p in (c[\"line\"][0], c[\"line\"][-1])]\n            for sec in sections:\n                if sec[\"level\"] > 0 and sec not in chain and any(\n                        tools._metres(p, q) < self.FALL_TOUCH for p in (sec[\"line\"][0], sec[\"line\"][-1]) for q in ends):\n                    chain.append(sec)\n                    grown = True\n        return chain\n\n    def _compute_fall(self, key, chain, item, lon, lat):\n        \"\"\"Calcul de la hauteur de chute du pont (chain), rangé dans self.falls[key], puis notify() ; key[2] : hauteur de\n        caméra (_fall_camera).\"\"\"\n        camera, camera_source, camera_error = key[2]\n        lines = [[triangulation._local(p[0], p[1], lon, lat) for p in c[\"line\"]] for c in chain]\n        total = sum(math.hypot(b[0] - a[0], b[1] - a[1]) for line in lines for a, b in zip(line, line[1:]))\n        # Coupes en travers du pont, de l'axe BD TOPO vers chaque côté, un point tous les EDGE_STEP m : bord du tablier cherché\n        # dans le relief jusqu'à la demi-largeur type + EDGE_SEARCH m, dessous lu jusqu'à FALL_SIDES[-1] m au-delà\n        cuts = []  # (largeur type / 2, distances, points (x, y) en m depuis la photo), une coupe par côté et par station\n        widths = [self._road_width(c) / 2 for c in chain]\n        far = max(widths) + self.EDGE_SEARCH + self.FALL_SIDES[-1]\n        offsets = [k * self.EDGE_STEP for k in range(int(far / self.EDGE_STEP) + 1)]\n        step = max(self.FALL_STEP, 2 * len(offsets) * total / (self.FALL_REQUESTS * self.FALL_POINTS))\n        for half, line in zip(widths, lines):\n            length = sum(math.hypot(b[0] - a[0], b[1] - a[1]) for a, b in zip(line, line[1:]))\n            n = max(1, round(length / step))\n            for k in range(n + 1):\n                s = k * length / n\n                (x, y), a, b = roads._at(line, s), roads._at(line, s - 1.0), roads._at(line, s + 1.0)\n                t = math.hypot(b[0] - a[0], b[1] - a[1]) or 1.0\n                nx, ny = -(b[1] - a[1]) / t, (b[0] - a[0]) / t\n                cuts += [(half, offsets, [(x + side * o * nx, y + side * o * ny) for o in offsets]) for side in (-1, 1)]\n        samples = [p for _, _, pts in cuts for p in pts]\n        reach = max(math.hypot(x, y) for x, y in samples) + 10.0\n\n        def failed(reason=\"service injoignable\", retry=True):\n            self.falls[key] = {\"text\": \"Hauteur de chute : calcul impossible ({})\".format(reason), \"title\": \"\",\n                               \"retry_at\": time.monotonic() + self.FALL_RETRY if retry else float(\"inf\")}\n            self.notify()\n\n        def got_photos(data, error):\n            if error:\n                return failed()\n            decks = []  # (x, y, altitude du tablier) aux photos de la séquence prises sur le pont\n            for feat in (data or {}).get(\"features\") or []:\n                try:\n                    plon, plat = (float(v) for v in feat[\"geometry\"][\"coordinates\"][:2])\n                except (KeyError, TypeError, ValueError):\n                    continue\n                ngf = host.ngf_altitude(plon, plat, metadata.item_altitude(feat))\n                if ngf is None or feat.get(\"collection\") != item.get(\"collection\") or \\\n                        roads.on_bridge(chain, plon, plat) is None:\n                    continue\n                rank = (feat.get(\"properties\") or {}).get(\"geovisio:rank_in_collection\")\n                decks.append(triangulation._local(plon, plat, lon, lat) + (ngf - camera, rank if isinstance(rank, int) else 0))\n            if not decks:\n                return failed(\"pas d'altitude GPS de la séquence sur le pont\")  # grille du géoïde pas encore lue ?\n            self._terrain([triangulation._geographic(x, y, lon, lat) for x, y in samples],\n                          lambda ground, source, error: got_ground(decks, ground, source, error))\n\n        def got_ground(decks, ground, source, error):\n            if error:\n                return failed()\n            best, relief, start = None, 0, 0\n            for half, offs, pts in cuts:\n                zs = (ground or [])[start:start + len(offs)]\n                start += len(offs)\n                if len(zs) < len(offs):\n                    continue\n                # Bord du tablier : dans le relief si le MNT le contient (tablier classé sol, petits ponts : terrain sous l'axe\n                # au niveau du tablier), comme le bord d'une route ; sinon (MNT au fond franchi) la demi-largeur type\n                i = None\n                if zs[0] is not None and abs(zs[0] - _deck_at(decks, *pts[0])) <= self.FALL_DECK_TOL:\n                    i = self._edge_border(zs, offs, half + self.EDGE_SEARCH)\n                relief += i is not None\n                edge = offs[i] if i is not None else half\n                for d in self.FALL_SIDES:\n                    k = min(range(len(offs)), key=lambda j: abs(offs[j] - (edge + d)))\n                    if zs[k] is None:\n                        continue\n                    deck = _deck_at(decks, *pts[k])\n                    if best is None or deck - zs[k] > best[0]:\n                        best = (deck - zs[k], math.hypot(*pts[k]))\n            if best is None:\n                return failed(\"pas de modèle de terrain sous le pont\", retry=False)\n            if best[0] < self.FALL_MIN:\n                self.falls[key] = {\"text\": \"Hauteur de chute non mesurée : le terrain sous le pont ne se distingue \"\n                                           \"pas du tablier (végétation, buse ?)\", \"title\": \"\"}\n                return self.notify()\n            terrain = triangulation.RGE_ALTI_ERROR if source == \"RGE ALTI\" else triangulation.LIDAR_ERROR\n            # Mesurée sur la séquence : tablier = altitude RTK moins (altitude RTK moins sol LiDAR) des photos voisines, le\n            # biais vertical du GPS s'annule ; restent la dispersion de cette hauteur et le sol sous ces photos. Calée ou\n            # réglage : l'altitude RTK elle-même compte (VERIFIED_ACCURACY), avec l'incertitude de la hauteur\n            if camera_source == \"séquence\":\n                sigma = math.hypot(camera_error, triangulation.LIDAR_ERROR, terrain)\n            else:\n                sigma = math.hypot(precision.VERIFIED_ACCURACY, camera_error, terrain)\n            self.falls[key] = {\n                \"text\": \"Hauteur de chute max : {} m (±{} m), RTK\".format(measures._num(best[0], 1), measures._num(sigma, 1)),\n                \"title\": (\"Plus grande hauteur entre le tablier (altitude GPS RTK moins hauteur de caméra) et le \"\n                          \"terrain sous le pont ({}), le long des deux bords jusqu'à {} m de la chaussée, à {} m de la photo. Bords \"\n                          \"du tablier : {}. Au-dessus de l'eau : niveau au relevé, pas le fond. Hauteur de caméra : {} m ({}).\").format(\n                    source, measures._num(self.FALL_SIDES[-1], 0), measures._num(best[1], 0),\n                    f\"trouvés dans le relief (tablier compris dans le modèle de terrain) sur {relief} coupes sur {len(cuts)}\"\n                    if relief else \"demi-largeur type de la route de part et d'autre de l'axe BD TOPO (tablier absent du modèle \"\n                    \"de terrain)\", measures._num(camera, 2),\n                    {\"séquence\": \"mesurée sur la séquence\", \"calée\": \"calée pour la séquence\",\n                     \"monture\": \"monture du CD21 d'après la date\", \"réglage\": \"réglage « Caméra à »\"}[camera_source])}\n            self.notify()\n\n        host.fetch_json(metadata.search_url(lon, lat, reach, 100, item.get(\"collection\"), host.api_url), got_photos)\n\n    # Hauteur de chute et dévers des bords de route, hors pont (ticket #31) -----------------------\n    # Calcul lancé seulement par le bouton « Profils » de la page (request_edges), pour la photo\n    # affichée. Travers de part et d'autre de la route, à EDGE_ALONG m de la photo le long du tronçon,\n    # depuis la caméra (séquence vérifiée RTK ; sinon l'axe BD TOPO) ;\n    # chute et dévers jusqu'à edge_zone m du milieu de la chaussée (réglette de la page, _edge_falls) ; terrain MNT LiDAR HD (RGE ALTI en secours). Bord : rupture de\n    # pente du terrain (EDGE_BREAK), sinon la médiane des travers voisins (EDGE_CONSENSUS), sinon la demi-largeur\n    # type (_road_width). Référence : le terrain au bord, pas l'altitude GPS.\n    EDGE_ZONE = 10.0  # m examinés par défaut de part et d'autre du milieu de la chaussée (réglette ; 20/11/2026, auteur)\n    EDGE_ZONE_MIN = 1.0  # m au-delà du bord examinés au moins, réglette plus courte que la demi-largeur de la chaussée\n    EDGE_ALONG = (-10.0, -5.0, 0.0, 5.0, 10.0)  # m le long de la route, depuis la photo\n    EDGE_WINDOW = 2.0  # m en travers : pente lue entre deux points au moins aussi écartés (bruit du MNT ±5 cm)\n    EDGE_TALUS = 0.10  # pente vers le bas (sur EDGE_WINDOW m) d'une descente : en dessous, plat\n    EDGE_CORE = 1 / 3  # talus : partie de la descente dont la pente vaut au moins ce rapport de sa pente la plus forte\n    EDGE_FLAT = 0.05  # m : pied du talus, et point le plus bas de la chute, le plus proche du bord à cela près du plus bas\n    EDGE_STEP = 0.5  # m entre deux points du profil, de l'origine jusqu'où la chute peut être lue (_edge_profiles)\n    EDGE_SEARCH = 3.0  # m au-delà du bord BD TOPO où la rupture de pente est encore cherchée\n    EDGE_BREAK = 0.08  # écart de pente sur 1 m à celle de la chaussée sous l'origine : bord (bombement : ~0,05)\n    EDGE_HOLD = 3  # pas consécutifs où l'écart doit tenir : un seul pas de 1 m tient du bruit du MNT (±5 cm)\n    EDGE_NEAR = 1.5  # m : pas de bord plus près de l'origine (le véhicule occupe sa voie ; demi-voie sur l'axe)\n    PAVED_REDO_MAX = 50  # profils gardés avec leur terrain, pour use_paved_edges sans relecture\n    EDGE_RISE = 1.0  # m : terrain remonté d'autant au-dessus du bord (talus, butte) : lecture arrêtée, derrière n'est pas une chute\n    # Dévers du talus au-delà (56°) : paroi quasi verticale (mur, enrochement), écrite sans pourcentage. Le MNT adoucit les\n    # parois (un mur de 2 m y fait 100 à 200 %) et le pas de 0,5 m plafonne à 400 % : le chiffre serait une fausse précision\n    WALL_SLOPE = 1.5\n    # Chaussées séparées (autoroute, voie express : un tronçon BD TOPO par sens, ticket #34) : tronçon de même nom, au sol,\n    # parallèle (TWIN_ANGLE° près), son axe à TWIN_MIN à TWIN_REACH m de celui de la photo en travers ; de son côté, la\n    # plateforme va jusqu'au bord extérieur de l'autre chaussée (séparateur de chaussée, ou terre-plein central, compris)\n    TWIN_MIN, TWIN_REACH, TWIN_ANGLE = 4.0, 40.0, 30.0\n    TWIN_LENGTHWISE = 2.0  # m : axe de l'autre chaussée en travers du point, pas au bout d'un tronçon décalé le long\n    TWIN_SEARCH = 6.0  # m de plus où le bord extérieur de l'autre chaussée est cherché (largeurs BD TOPO souvent trop\n    # faibles sur ces routes : 5 m pour deux voies)\n    # Marche du terrain (bordure, séparateur surélevé ou en creux) : au moins STEP_Z m sur un pas de EDGE_STEP m, et encore\n    # STEP_HOLD m sur trois pas (pas un seul point du MNT qui saute, ±5 cm)\n    STEP_Z, STEP_HOLD = 0.05, 0.04\n    STEP_SHARP = 0.5  # après un bombement, pas voisins d'une marche : moins de la moitié de son saut (_edge_step)\n    SEPARATOR_WIDTH = (0.5, 10.0)  # m : largeurs possibles d'un séparateur de chaussée trouvé dans le relief\n    SEPARATOR_NEAR = 4.0  # m au plus entre son milieu et celui que donne la BD TOPO\n    # Profil en long : terrain sur ±LONG_REACH m le long du tronçon, tous les LONG_STEP m ; pente moyenne (moindres carrés)\n    # et la plus forte sur LONG_WINDOW m\n    LONG_REACH, LONG_STEP, LONG_WINDOW = 50, 2, 10\n    LONG_JUNCTION = 30.0  # m : repères de carrefour avec la même voie plus proches : un seul carrefour (îlot séparateur)\n    # m le long de la route : carrefour avec une voie nommée aussi près de la photo, bords signalés peu sûrs (la chaussée\n    # s'y élargit, le bord n'y est pas continu : pas de bonne réponse, D16 d946f2cf-cddc-4476-a414-35aee429c05a, auteur,\n    # 20/11/2026) ; les travers vont jusqu'à 10 m (EDGE_ALONG), la voie qui arrive a quelques mètres de large\n    JUNCTION_NEAR = 12.0\n    # Creux du profil en long : le MNT n'a pas les ponts (fond franchi), et le tronçon BD TOPO en pont est souvent plus court\n    # que la brèche, ou absent ; une route ne plonge pas de plus de DIP_SLOPE (15 % au plus), le terrain qui le fait est sous\n    # un ouvrage, comblé d'un bord à l'autre (_bridged)\n    DIP_SLOPE = 0.2\n    # Tablier : enveloppe haute du terrain, cordes de DIP_SPAN m au plus (le fond d'un creux plus large n'est pas un pont) ;\n    # gardée là où elle passe à plus de DIP_TOL m du terrain et recouvre un pont de la route ou une plongée de DIP_SLOPE\n    DIP_SPAN, DIP_TOL = 40.0, 0.1\n    EDGE_CONSENSUS = 3.0  # m : bord (ou séparateur) d'un travers plus loin de la médiane des autres : ramené à elle\n    # Bombement (piste P16) : rupture à CROWN_NEAR m au plus de l'axe BD TOPO, suivie d'une pente de CROWN_SLOPE au plus qui\n    # tient sur CROWN_HOLD m : sommet du bombement ou changement de dévers d'une voie à l'autre, pas le bord (_edge_border) ;\n    # chaussée de CROWN_WIDTH m au moins (largeur type : deux voies possibles ; sur une voie unique, le bord peut être près de\n    # l'axe) ; le bord est alors cherché CROWN_SEARCH m plus loin (chaussées plus larges que leur type : D70\n    # 229abfcd-868c-4eca-bfc1-3979ca94d28f, 9,3 m)\n    CROWN_NEAR, CROWN_SLOPE, CROWN_HOLD, CROWN_WIDTH, CROWN_SEARCH = 1.25, 0.10, 1.5, 4.0, 3.0\n    # Séparateur étroit sans marches (glissières dos à dos, muret : le MNT n'en garde que l'assise) : pic de 1 ou 2 points au\n    # moins PEAK_Z m au-dessus des points voisins, au même endroit (PEAK_SPREAD m près) sur PEAK_TRAVERS travers au moins\n    PEAK_Z, PEAK_SPREAD, PEAK_TRAVERS, PEAK_HALF = 0.04, 1.0, 2, 0.4\n\n    def set_edge_zone(self, metres):\n        \"\"\"Réglette du bouton « Profils » : distance (m) examinée de part et d'autre du milieu de la chaussée au prochain appui\n        (le résultat déjà affiché reste celui de sa largeur).\"\"\"\n        self.edge_zone = float(metres)\n        self.notify()\n\n    def request_edges(self):\n        \"\"\"Bouton « Profils » : calcul pour la photo affichée et la largeur de la réglette (voir _edges).\"\"\"\n        if self.item:\n            self.edges_asked[self.item.get(\"id\")] = self.edge_zone\n            self.notify()\n\n    def edges_ready(self):\n        \"\"\"Le bouton « Profils » aurait un effet : photo affichée, pas déjà calculée à cette largeur.\"\"\"\n        return bool(self.item) and self.edges_asked.get(self.item.get(\"id\")) != self.edge_zone\n\n    def _edges(self, item, sections, lon, lat):\n        \"\"\"Photo hors pont où le bouton « Profils » a été pressé : chute et dévers des deux bords de la route\n        la plus proche (roads.MAX_DISTANCE m au plus), {text, title, edges}, l'attente du calcul ou sa raison\n        d'échouer ; None sans appui sur le bouton pour cette photo.\"\"\"\n        zone = self.edges_asked.get(item.get(\"id\"))\n        if zone is None:\n            return None\n\n        def told(text):\n            return {\"text\": \"Bords de route\\n\" + text, \"title\": \"\", \"edges\": True}\n\n        # Tronçons des mailles voisines aussi (±LONG_REACH m et plus) : la route prolongée (_chained) sort de la maille de la\n        # photo ; doublons (un tronçon lu dans deux mailles) fusionnés\n        reach = self.LONG_REACH + 10.0\n        dlat, dlon = reach / 111320.0, reach / (111320.0 * math.cos(math.radians(lat)))\n        merged, seen = [], set()\n        for cell in {roads._cell(lon + i * dlon, lat + j * dlat) for i in (-1, 0, 1) for j in (-1, 0, 1)}:\n            corner = (cell[0] * roads.CELL + 1e-9, cell[1] * roads.CELL + 1e-9)\n            more = sections if cell == roads._cell(lon, lat) else self._fall_sections(*corner)\n            if more is roads.PENDING:\n                return told(\"Calcul en cours…\")\n            for sec in more or []:\n                tag = (sec.get(\"name\"), sec.get(\"level\"), tuple(sec[\"line\"][0]), tuple(sec[\"line\"][-1]))\n                if tag not in seen:\n                    seen.add(tag)\n                    merged.append(sec)\n        sections = merged\n\n        # Route de la photo : le tronçon au sol le plus proche parmi ceux orientés comme la route parcourue (à ROAD_TURN°\n        # près, sens de la trajectoire de la caméra au droit de la photo, sinon son cap) ; à un carrefour, la voie qui\n        # croise peut passer plus près ; aucun ainsi orienté : le plus proche\n        track = self.long_tracks.get(item.get(\"id\"))\n        heading = metadata.item_heading(item)\n        if track and len(track) >= 2:\n            k0 = track.index((0.0, 0.0))\n            p, q = track[max(0, k0 - 1)], track[min(len(track) - 1, k0 + 1)]\n            heading = math.degrees(math.atan2(q[0] - p[0], q[1] - p[1]))\n        near, aligned = None, None\n        for sec in sections:\n            if sec.get(\"level\", 0) != 0:\n                continue  # pont ou tunnel\n            line = [triangulation._local(p[0], p[1], lon, lat) for p in sec[\"line\"]]\n            d, s = roads._project(line, 0.0, 0.0)\n            if d > roads.MAX_DISTANCE:\n                continue\n            a, b = roads._at(line, s - roads.TANGENT), roads._at(line, s + roads.TANGENT)\n            course = math.degrees(math.atan2(b[0] - a[0], b[1] - a[1]))\n            if near is None or d < near[0]:\n                near = (d, s, line, sec)\n            if (heading is None or roads._axis_diff(course, heading) <= self.ROAD_TURN) and (aligned is None or d < aligned[0]):\n                aligned = (d, s, line, sec)\n        near = aligned or near\n        if near is None:\n            return told(\"Pas de route de la BD TOPO à moins de {} m de la photo\".format(\n                measures._num(roads.MAX_DISTANCE, 0)))\n        _, s, line, sec = near\n        line, ends, works = self._chained(line, sec, sections, lon, lat)  # prolongé par les tronçons voisins de la même route\n        s = roads._project(line, 0.0, 0.0)[1]\n        # Autres chaussées possibles (voir TWIN_REACH) : [(tronçon en mètres locaux, largeur)], vérifiées travers par\n        # travers (_compute_edges) : un tronçon voisin de la même chaussée, dans son prolongement, n'en est pas une\n        twin = []\n        for other in sections:\n            if other is sec or other.get(\"level\", 0) != 0 or not sec.get(\"name\") or other.get(\"name\") != sec.get(\"name\"):\n                continue\n            other_line = [triangulation._local(p[0], p[1], lon, lat) for p in other[\"line\"]]\n            if roads._project(other_line, 0.0, 0.0)[0] <= self.TWIN_REACH:\n                twin.append((other_line, self._road_width(other)))\n        camera = bool(self.quality and self.quality.get(\"precise\"))  # position RTK : profils depuis la caméra\n        key = (item.get(\"id\"), zone, camera)\n        res = self.edges.get(key)\n        if res is None or time.monotonic() >= res.get(\"retry_at\", float(\"inf\")):\n            track = self._track_line(item, lon, lat)  # profil en long le long de la trajectoire de la caméra\n            if track is None:\n                return told(\"Calcul en cours…\")\n            if track is False:  # pas de repli silencieux sur l'axe BD TOPO : nouvel essai plus tard\n                res = self.edges[key] = {\"text\": \"Calcul impossible (service injoignable)\", \"title\": \"\",\n                                         \"retry_at\": time.monotonic() + self.FALL_RETRY}\n            else:\n                res = self.edges[key] = {\"text\": \"Calcul en cours…\", \"title\": \"\"}\n                self._compute_edges(key, line, s, self._road_width(sec), metadata.item_heading(item), lon, lat, twin, track,\n                                    (ends, sec.get(\"name\"), works))\n        road = sec.get(\"name\") if re.match(r\"[A-Z]+\\d\", sec.get(\"name\") or \"\") else None\n        profile = res.get(\"profile\")\n        if profile:  # eau de la BD TOPO sur le travers de la photo (lue à part : None pendant la lecture)\n            profile = dict(profile, eau=self._water_across(res[\"frame\"], lon, lat))\n        return {\"text\": \"Bords de route\" + (\" ({})\".format(road) if road else \"\") + \"\\n\" + res[\"text\"],\n                \"title\": res[\"title\"], \"edges\": True, \"profile\": profile, \"road\": road}\n\n    def _road_width(self, sec):\n        \"\"\"Largeur type de la chaussée du tronçon sec (m) d'après sa catégorie BD TOPO (ROAD_WIDTHS, ROAD_TWIN), pas d'après sa\n        largeur BD TOPO (piste P17).\"\"\"\n        if sec.get(\"nature\") in (\"Route à 2 chaussées\", \"Type autoroutier\"):\n            return self.ROAD_TWIN\n        return self.ROAD_WIDTHS.get(sec.get(\"importance\") or \"\", self.FALL_WIDTH)\n\n    ROAD_TURN = 45.0  # degrés au plus entre le tronçon de la photo et la route parcourue (_edges)\n    CHAIN_TURN = 60.0  # degrés de déviation au plus d'un tronçon à l'autre en prolongeant la route\n    CHAIN_REACH, CHAIN_TOUCH = 60.0, 2.0  # m ajoutés au plus de chaque côté ; bouts de tronçons qui se touchent\n\n    def _bridged(self, pts, bridges=()):\n        \"\"\"Profil en long [(d, z)] sans ses creux (le MNT n'a pas les ponts : il donne le fond franchi).\n        1. Enveloppe haute du terrain par des cordes de DIP_SPAN m au plus : là où elle passe à plus de DIP_TOL m au-dessus,\n        un creux, dont les bouts (le terrain touche la corde) sont les culées ; gardé s'il recouvre un pont de la route\n        (bridges : [(de, à)], souvent plus court que la brèche) ou une plongée de plus de DIP_SLOPE d'un point au suivant\n        (pont absent de la BD TOPO).\n        2. Plongée de plus de DIP_SLOPE qui reste : droite du bord jusqu'au point où le terrain revient au niveau de la route\n        (pas plus bas que DIP_SLOPE depuis le bord), poussé jusqu'en haut de la remontée ; dans les deux sens, un creux\n        ouvert au bout du profil (pas d'autre bord) y est coupé.\n        Rend (profil, [(de, à)] des creux comblés).\"\"\"\n        slope, out, dips = self.DIP_SLOPE, list(pts), []\n        top = [(z, None) for _, z in out]  # plus haute corde au-dessus de chaque point : (altitude, (bout, bout))\n        for i, (da, za) in enumerate(out):\n            for j in range(i + 2, len(out)):\n                db, zb = out[j]\n                if db - da > self.DIP_SPAN:\n                    break\n                for k in range(i + 1, j):\n                    z = za + (zb - za) * (out[k][0] - da) / (db - da)\n                    if z > top[k][0]:\n                        top[k] = (z, (i, j))\n        lift = [t - z for (t, _), (_, z) in zip(top, out)]\n        steep = lambda a, b: abs(out[b][1] - out[a][1]) > slope * (out[b][0] - out[a][0])\n        k = 1\n        while k < len(out) - 1:\n            if lift[k] <= self.DIP_TOL:\n                k += 1\n                continue\n            core = k\n            while k < len(out) - 1 and lift[k] > self.DIP_TOL:\n                k += 1\n            # creux : la corde la plus haute au-dessus de son point le plus profond, d'une culée (appui) à l'autre\n            deep = max(range(core, k), key=lambda m: lift[m])\n            a, b = top[deep][1]\n            # appuis rapprochés tant que le point suivant est sur la corde (à DIP_TOL près) : la route, pas encore le creux\n            on = lambda m, a, b: out[m][1] >= (out[a][1] + (out[b][1] - out[a][1]) * (out[m][0] - out[a][0])\n                                               / (out[b][0] - out[a][0])) - self.DIP_TOL\n            while a + 1 < deep and on(a + 1, a, b):\n                a += 1\n            while b - 1 > deep and on(b - 1, a, b):\n                b -= 1\n            lo, hi = out[a][0], out[b][0]\n            if any(b0 <= hi and b1 >= lo for b0, b1 in bridges) or any(steep(m, m + 1) for m in range(a, b)):\n                (da, za), (db, zb) = out[a], out[b]\n                out = out[:a + 1] + [(d, za + (zb - za) * (d - da) / (db - da)) for d, _ in out[a + 1:b]] + out[b:]\n                lift[a:b] = [0.0] * (b - a)\n                dips.append((lo, hi))\n                k = max(k, b)\n        for rev in (False, True):\n            if rev:\n                out = [(-d, v) for d, v in reversed(out)]\n            k = 0\n            while k < len(out) - 1:\n                (da, za), (db, zb) = out[k], out[k + 1]\n                if za - zb <= slope * (db - da):\n                    k += 1\n                    continue\n                j = next((j for j in range(k + 2, len(out)) if out[j][1] >= za - slope * (out[j][0] - da)), None)\n                if j is None:\n                    out = out[:k + 1]\n                    break\n                while j < len(out) - 1 and out[j + 1][1] - out[j][1] > slope * (out[j + 1][0] - out[j][0]):\n                    j += 1\n                d1, z1 = out[j]\n                out = out[:k + 1] + [(d, za + (z1 - za) * (d - da) / (d1 - da)) for d, _ in out[k + 1:j]] + out[j:]\n                dips.append((-d1, -da) if rev else (da, d1))\n                k = j\n            if rev:\n                out = [(-d, v) for d, v in reversed(out)]\n        return out, dips\n\n    def _chained(self, line, sec, sections, lon, lat):\n        \"\"\"Ligne du tronçon de la photo (mètres locaux) prolongée à chaque bout par les tronçons au sol de la même route\n        (même nom) qui s'y raccordent, jusqu'à CHAIN_REACH m de plus : le profil en long et les travers ne s'arrêtent pas\n        au bout du tronçon. Un seul voisin pris par bout (le premier trouvé) ; sans nom ou sans voisin, la ligne telle quelle.\n        Rend aussi les points remarquables de cette route : [(point, \"fin\" ou \"carrefour\", voies nommées qui s'y raccordent)],\n        « fin » au bout de la ligne prolongée (la route s'arrête, ou continue sous un autre nom), « carrefour » là où une\n        voie carrossable nommée (numéro ou nom, pas une simple nature ; roads.parse_sections) s'y raccorde sans\n        l'interrompre. Les tronçons en pont ou en tunnel de la route en font partie : leurs bouts sont rendus à part,\n        [(niveau, bout, bout)] (le MNT y est le fond franchi ou le dessus du tunnel, pas la chaussée).\"\"\"\n        touch = lambda a, b: math.hypot(a[0] - b[0], a[1] - b[1]) <= self.CHAIN_TOUCH\n        if not sec.get(\"name\"):\n            return line, [], []\n        others = [[triangulation._local(p[0], p[1], lon, lat) for p in o[\"line\"]] for o in sections\n                  if o is not sec and o.get(\"name\") == sec[\"name\"]]\n        levels = [o.get(\"level\", 0) for o in sections if o is not sec and o.get(\"name\") == sec[\"name\"]]\n        works = []  # ouvrages de la route : (niveau, bout, bout)\n        foreign = [(o.get(\"name\") or \"\", [triangulation._local(p[0], p[1], lon, lat) for p in (o[\"line\"][0], o[\"line\"][-1])])\n                   for o in sections if o.get(\"level\", 0) == 0 and o.get(\"name\") != sec[\"name\"] and o.get(\"drivable\")]\n        joints = [line[0], line[-1]]  # bouts des tronçons de la route mis bout à bout\n        out = list(line)\n        for at_end in (True, False):\n            added, used = 0.0, set()\n            while added < self.CHAIN_REACH:\n                tip, back = (out[-1], out[-2]) if at_end else (out[0], out[1])\n                way = (tip[0] - back[0], tip[1] - back[1])  # sens de la route en sortant par ce bout\n                # le tronçon qui la continue le plus dans l'alignement (à un nœud, plusieurs tronçons du même nom peuvent\n                # partir : l'autre branche d'une intersection, un pont…), à moins de CHAIN_TURN° de déviation\n                best = None\n                for k, o in enumerate(others):\n                    if k in used or not (touch(o[0], tip) or touch(o[-1], tip)):\n                        continue\n                    o = o if touch(o[0], tip) else o[::-1]  # part du bout touché\n                    v = (o[1][0] - o[0][0], o[1][1] - o[0][1])\n                    turn = (way[0] * v[0] + way[1] * v[1]) / ((math.hypot(*way) * math.hypot(*v)) or 1.0)\n                    if turn >= math.cos(math.radians(self.CHAIN_TURN)) and (best is None or turn > best[0]):\n                        best = (turn, k, o)\n                if best is None:\n                    break\n                _, k, o = best\n                used.add(k)\n                if levels[k]:\n                    works.append((levels[k], o[0], o[-1]))\n                joints.append(o[-1])\n                o = o[1:]\n                added += sum(math.hypot(q[0] - p[0], q[1] - p[1]) for p, q in zip([tip] + o, o))\n                out = out + o if at_end else o[::-1] + out\n        ends = []\n        for j in joints:\n            names = sorted({n for n, tips in foreign if n and n not in _WAY_KINDS and any(touch(t, j) for t in tips)})\n            if touch(j, out[0]) or touch(j, out[-1]):  # bout de la ligne prolongée : la route s'arrête là\n                ends.append((j, \"fin\", names))\n            elif names:\n                ends.append((j, \"carrefour\", names))\n        return out, ends, works\n\n    WATER_REACH = 45.0  # m de part et d'autre de l'origine du travers où l'eau de la BD TOPO est cherchée\n\n    def _water_across(self, frame, lon, lat):\n        \"\"\"Eau de la BD TOPO sur le travers de la photo (frame : origine et unité vers la droite, mètres locaux) : cours\n        d'eau croisés ({\"x\", \"nom\", \"nature\"}) et plans ou surfaces d'eau traversés ({\"de\", \"a\", \"nature\"}), en m vers la\n        droite ; None pendant la lecture. Souterrains et tronçons fictifs (à travers un lac) écartés.\"\"\"\n        ox, oy, rx, ry = frame\n        a, b = (ox - self.WATER_REACH * rx, oy - self.WATER_REACH * ry), (ox + self.WATER_REACH * rx, oy + self.WATER_REACH * ry)\n        cell = roads._cell(lon, lat)\n        lines, surfaces = self._bdtopo(\"troncon_hydrographique\", cell), self._bdtopo(\"surface_hydrographique\", cell)\n        if lines is None or surfaces is None:\n            return None\n        across = lambda p: round((p[0] - ox) * rx + (p[1] - oy) * ry, 1)\n\n        def kept(props):\n            try:\n                return int(props.get(\"position_par_rapport_au_sol\") or 0) >= 0 and not props.get(\"fictif\")\n            except (TypeError, ValueError):\n                return not props.get(\"fictif\")\n\n        def cuts(ring):  # abscisses où le travers coupe la ligne (ou l'anneau) ring, en lon, lat\n            pts = [triangulation._local(q[0], q[1], lon, lat) for q in ring]\n            return [across(x) for c, d in zip(pts, pts[1:]) for x in [_crossing(a, b, c, d)] if x]\n\n        out = []\n        for feat in lines:\n            props, geom = feat.get(\"properties\") or {}, feat.get(\"geometry\") or {}\n            if not kept(props):\n                continue\n            coords = geom.get(\"coordinates\") or []\n            for line in coords if geom.get(\"type\") == \"MultiLineString\" else [coords]:\n                for x in cuts(line):\n                    out.append({\"x\": x, \"nom\": props.get(\"cpx_toponyme_de_cours_d_eau\"), \"nature\": props.get(\"nature\")})\n        for feat in surfaces:\n            props, geom = feat.get(\"properties\") or {}, feat.get(\"geometry\") or {}\n            if not kept(props):\n                continue\n            coords = geom.get(\"coordinates\") or []\n            xs = sorted(x for poly in (coords if geom.get(\"type\") == \"MultiPolygon\" else [coords]) for ring in poly\n                        for x in cuts(ring))\n            # shortcut: traversées prises deux à deux ; un bout du travers dans l'eau laisse une traversée seule, écartée\n            out += [{\"de\": xs[k], \"a\": xs[k + 1], \"nature\": props.get(\"nature\")} for k in range(0, len(xs) - 1, 2)]\n        return out\n\n    def _track_line(self, item, lon, lat):\n        \"\"\"Trajectoire de la caméra autour de la photo : positions des photos de la même séquence, de rangs qui se suivent\n        (un trou d'une photo admis), en mètres locaux, dans le sens de la photo, la photo à (0, 0) ; [] si moins de 3\n        photos ou rang inconnu (profil en long sur l'axe BD TOPO) ; None pendant la lecture ; False si Panoramax n'a pas\n        répondu (relue à l'appel suivant).\"\"\"\n        key = item.get(\"id\")\n        if self.long_tracks.get(key, False) is not False:\n            return self.long_tracks[key]\n        self.long_tracks[key] = None\n        seq, rank0 = item.get(\"collection\"), (item.get(\"properties\") or {}).get(\"geovisio:rank_in_collection\")\n\n        def done(data, error):\n            out = []\n            if not error and seq is not None and isinstance(rank0, int):\n                at = {rank0: (0.0, 0.0)}\n                for feat in (data or {}).get(\"features\") or []:\n                    rank = (feat.get(\"properties\") or {}).get(\"geovisio:rank_in_collection\")\n                    try:\n                        if feat.get(\"collection\") == seq and isinstance(rank, int) and rank != rank0:\n                            at[rank] = triangulation._local(*(float(v) for v in feat[\"geometry\"][\"coordinates\"][:2]), lon, lat)\n                    except (KeyError, TypeError, ValueError):\n                        continue\n                ranks = [rank0]\n                for step in (1, -1):  # de proche en proche, un trou d'une photo admis\n                    r = rank0\n                    while True:\n                        r = next((r + step * g for g in (1, 2) if r + step * g in at), None)\n                        if r is None:\n                            break\n                        ranks.append(r)\n                ranks.sort()\n                out = [at[r] for r in ranks]\n                heading, k = metadata.item_heading(item), ranks.index(rank0)\n                if len(out) >= 3 and heading is not None:\n                    a, b = out[max(0, k - 1)], out[min(len(out) - 1, k + 1)]\n                    if abs((math.degrees(math.atan2(b[0] - a[0], b[1] - a[1])) - heading + 180) % 360 - 180) > 90:\n                        out = out[::-1]  # dans le sens de la photo\n                else:\n                    out = []\n            self.long_tracks[key] = False if error else out\n            self.notify()\n\n        host.fetch_json(metadata.search_url(lon, lat, self.LONG_REACH + 15, 100, seq, host.api_url), done)\n        return None\n\n    def _compute_edges(self, key, line, s, width, heading, lon, lat, twin=None, track=None, ends=([], None, [])):\n        \"\"\"Calcul des bords (voir _edges), rangé dans self.edges[key], puis notify() ; twin : autre chaussée\n        (tronçon, largeur) d'une route à chaussées séparées, ou None. Étapes : travers à lire (_edge_profiles), profil en\n        long (_long_samples), puis, le terrain lu, bords et séparateurs (_edge_reads) et chutes et dévers (_edge_falls).\"\"\"\n        _, zone, camera = key\n        x, y, nx, ny = self._line_frame(line, s)\n        shift = -(x * nx + y * ny) if camera else 0.0  # origine à gauche de l'axe (m) : la caméra est en (0, 0)\n        a, b = roads._at(line, s - roads.TANGENT), roads._at(line, s + roads.TANGENT)\n        course = math.degrees(math.atan2(b[0] - a[0], b[1] - a[1]))  # sens du tronçon\n        forward = heading is None or abs((course - heading + 180) % 360 - 180) <= 90\n        sides = ((\"droit\", -1), (\"gauche\", 1)) if forward else ((\"droit\", 1), (\"gauche\", -1))\n        # Repère du travers de la photo pour l'analyse fine (src/nuage.js) : son origine et le point à 1 m à droite\n        right = dict(sides)[\"droit\"]\n        across0 = (x + shift * nx, y + shift * ny, right * nx, right * ny)  # pour l'eau de la BD TOPO (_water_across)\n        frame0 = [triangulation._geographic(x + shift * nx + k * right * nx, y + shift * ny + k * right * ny, lon, lat)\n                  for k in (0, 1)]\n        frame_key = tuple(tuple(round(v, 8) for v in p) for p in frame0)\n        profiles, samples = self._edge_profiles(line, s, (width or self.FALL_WIDTH) / 2, zone, shift, sides, twin)\n        lengthwise, long_samples, followed = self._long_samples(line, s, shift, forward, track)\n        samples += long_samples\n\n        def along_of(p):  # distance d'une fin de tronçon le long de la route BD TOPO (la caméra a pu couper le carrefour)\n            return (1 if forward else -1) * (roads._project(line, p[0], p[1])[1] - s)\n\n        def got_ground(ground, source, error):\n            if error or not source:\n                self.edges[key] = {\"text\": \"Calcul impossible ({})\".format(\n                    \"service injoignable\" if error else \"pas de modèle de terrain ici\"), \"title\": \"\",\n                    \"retry_at\": time.monotonic() + self.FALL_RETRY if error else float(\"inf\")}\n                return self.notify()\n            if len(self.paved_redo) >= self.PAVED_REDO_MAX:\n                self.paved_redo.clear()\n            self.paved_redo[frame_key] = (key, lambda: got_ground(ground, source, None))\n            paved = self.paved.get(frame_key, {})\n            read, twins = self._edge_reads(profiles, ground, sides, paved)\n            found, borders, stops, drawn = self._edge_falls(read, sides, paved, zone)\n            # Profil en long (derniers points lus) : pente moyenne, montée > 0 dans le sens de la photo, et la plus forte\n            pts = [(d, v) for d, v in zip(lengthwise, ground[len(ground) - len(lengthwise):]) if v is not None] if lengthwise else []\n            grade = self._long_profile(pts, ends, along_of, followed)\n            terrain = triangulation.RGE_ALTI_ERROR if source == \"RGE ALTI\" else triangulation.LIDAR_ERROR\n            sigma = math.hypot(terrain, terrain)  # deux altitudes du même MNT\n            origin = \"la caméra\" if camera else \"l'axe BD TOPO\"\n            lines, seen, shown = self._edges_sides(sides, borders, found, stops, drawn, twins, sigma, origin)\n            junction = self._junction_near(ends, along_of)\n            self.edges[key] = {\n                \"frame\": across0,\n                \"profile\": {\"origine\": \"caméra\" if camera else \"axe\", \"source\": source, \"erreur\": round(sigma, 2),\n                            \"repere\": [[round(v, 8) for v in p] for p in frame0],\n                            \"axe\": round(-shift * right, 2),  # axe de la chaussée de la photo, en m vers la droite\n                            \"zone\": zone, \"fenetre\": self.EDGE_WINDOW, \"remontee\": self.EDGE_RISE, \"profils\": drawn,\n                            \"plateforme\": platform_slope(drawn) if source == triangulation.LIDAR_NAME else None,  # RGE ALTI trop imprécis\n                            \"resultats\": shown, \"arrets\": {name: sorted(v)[len(v) // 2] for name, v in stops.items() if v},\n                            \"en_long\": grade, \"carrefour\": junction},\n                \"text\": (self._junction_text(junction) + \"\\n\" if junction else \"\") + (\"\\n\".join(lines) or \"Aucun bord ne descend de {} m ou plus jusqu'à {} m du milieu de la chaussée\".format(\n                    measures._num(self.FALL_MIN, 1), measures._num(zone, 0))) + (\"\\nPente en long : {} de {} % sur {} m{}\".format(\n                        \"montée\" if grade[\"pente\"] >= 0 else \"descente\", measures._num(abs(grade[\"pente\"]), 1),\n                        measures._num(grade[\"points\"][-1][0] - grade[\"points\"][0][0], 0),\n                        \", jusqu'à {} % sur {} m\".format(measures._num(abs(grade[\"max\"][0]), 1), self.LONG_WINDOW)\n                        if grade[\"max\"] else \"\") if grade else \"\"),\n                \"title\": self._edges_title(source, origin, zone, seen)}\n            self.notify()\n\n        self._terrain([triangulation._geographic(x, y, lon, lat) for x, y in samples], got_ground)\n\n    @staticmethod\n    def _line_frame(line, at):\n        \"\"\"Point de l'axe et normale à gauche du sens du tronçon, à l'abscisse at : (x, y, nx, ny).\"\"\"\n        (x, y), p, q = roads._at(line, at), roads._at(line, at - 1.0), roads._at(line, at + 1.0)\n        t = math.hypot(q[0] - p[0], q[1] - p[1]) or 1.0\n        return x, y, -(q[1] - p[1]) / t, (q[0] - p[0]) / t\n\n    def _twin_across(self, twin, x, y, nx, ny, along_x, along_y):\n        \"\"\"Axe de l'autre chaussée (twin, voir _compute_edges) sur le travers du point (x, y) de l'axe : (décalage en m le\n        long de la normale, demi-largeur) de la plus proche, ou None (pas d'autre chaussée, pas parallèle, pas en travers,\n        trop près ou trop loin).\"\"\"\n        best = None\n        for other, other_width in twin or []:\n            _, s2 = roads._project(other, x, y)\n            (qx, qy), p, q = roads._at(other, s2), roads._at(other, s2 - 1.0), roads._at(other, s2 + 1.0)\n            t = math.hypot(q[0] - p[0], q[1] - p[1]) or 1.0\n            cos = abs(((q[0] - p[0]) * along_x + (q[1] - p[1]) * along_y) / t)\n            offset = (qx - x) * nx + (qy - y) * ny\n            lengthwise = abs((qx - x) * along_x + (qy - y) * along_y)  # bout d'un tronçon dans le prolongement\n            if (cos >= math.cos(math.radians(self.TWIN_ANGLE)) and lengthwise <= self.TWIN_LENGTHWISE\n                    and self.TWIN_MIN <= abs(offset) <= self.TWIN_REACH and (best is None or abs(offset) < abs(best[0]))):\n                best = (offset, (other_width or self.FALL_WIDTH) / 2)\n        return best\n\n    def _edge_profiles(self, line, s, half, zone, shift, sides, twin):\n        \"\"\"Travers à lire (EDGE_ALONG), de chaque côté : (profils [(le long, côté, bord BD TOPO depuis l'origine, distances\n        depuis l'origine, axe de l'autre chaussée, séparateur BD TOPO, portée, axe de la chaussée ou None)], points à lire\n        (m, repère de la photo)).\"\"\"\n        profiles = []\n        samples = []\n        for along in self.EDGE_ALONG:\n            # shortcut: _at borne aux bouts de la ligne prolongée (_chained) : au-delà, les travers s'y superposent\n            x, y, nx, ny = self._line_frame(line, s + along)\n            other = self._twin_across(twin, x, y, nx, ny, ny, -nx)  # sens du tronçon : normale tournée d'un quart de tour à droite\n            for name, sign in sides:\n                guess = max(self.EDGE_NEAR, half - sign * shift)\n                beyond, between = 0.0, None  # autre chaussée de ce côté : bord cherché au-delà de son axe (m depuis\n                # l'origine) ; séparateur de chaussée d'après la BD TOPO, du bord de la chaussée de la photo à celui de l'autre\n                if other and other[0] * sign > 0:\n                    beyond = sign * other[0] - sign * shift\n                    if beyond - other[1] > guess:\n                        between = (guess, beyond - other[1])\n                    guess = beyond + other[1]\n                reach = guess + self.EDGE_SEARCH + (self.TWIN_SEARCH if beyond else 0)  # bord cherché jusque-là\n                # axe BD TOPO de la chaussée de la photo, en m depuis l'origine de ce côté (négatif : de l'autre côté) ; s'il est\n                # de ce côté, un bombement peut prolonger la recherche de CROWN_SEARCH m : pas de EDGE_STEP m jusque-là aussi\n                axis = -sign * shift if 2 * half >= self.CROWN_WIDTH else None\n                fine = reach + (self.CROWN_SEARCH if axis is not None and axis > 0 else 0)\n                # au pas de EDGE_STEP m (résolution du MNT LiDAR HD) jusqu'où la chute peut être lue (_edge_falls : zone m du\n                # milieu de la chaussée, le bord de ce côté avant fine, l'autre à l'origine ou au-delà : zone + fine / 2 au plus),\n                # EDGE_ZONE_MIN m au moins au-delà de fine. Avant le 20/11/2026 : 16 points au-delà de fine, espacés de zone / 16\n                # (1,9 m à 30 m : dévers du talus faussé)\n                far = max(fine + self.EDGE_ZONE_MIN, zone + fine / 2)\n                offsets = [k * self.EDGE_STEP for k in range(int(far / self.EDGE_STEP + 1e-6) + 1)]\n                profiles.append((along, name, guess, offsets, beyond, between, reach, axis))\n                samples += [(x + (shift + sign * o) * nx, y + (shift + sign * o) * ny) for o in offsets]\n        return profiles, samples\n\n    def _long_samples(self, line, s, shift, forward, track):\n        \"\"\"Profil en long, d > 0 dans le sens de la photo : le long de la trajectoire de la caméra (track, _track_line : là\n        où elle a roulé, sol sous elle) ; sans elle, sur l'axe BD TOPO prolongé par les tronçons voisins (_chained), à la\n        même distance de l'axe que l'origine (l'axe peut s'écarter de la voie de quelques mètres) ; borné aux bouts.\n        Rend (distances d, points à lire, ce qui a été suivi).\"\"\"\n        samples = []\n        if track and len(track) >= 3:\n            k0 = track.index((0.0, 0.0))\n            cum = [0.0]\n            for p, q in zip(track, track[1:]):\n                cum.append(cum[-1] + math.hypot(q[0] - p[0], q[1] - p[1]))\n            cum = [c - cum[k0] for c in cum]\n            lengthwise = [d for d in range(-self.LONG_REACH, self.LONG_REACH + 1, self.LONG_STEP) if cum[0] <= d <= cum[-1]]\n            for d in lengthwise:\n                j = max(1, next((j for j in range(1, len(cum)) if cum[j] >= d), len(cum) - 1))\n                t = (d - cum[j - 1]) / ((cum[j] - cum[j - 1]) or 1.0)\n                (x0, y0), (x1, y1) = track[j - 1][:2], track[j][:2]\n                samples.append((x0 + t * (x1 - x0), y0 + t * (y1 - y0)))\n            return lengthwise, samples, \"trajectoire de la caméra\"\n        ahead = 1 if forward else -1\n        length = sum(math.hypot(q[0] - p[0], q[1] - p[1]) for p, q in zip(line, line[1:]))\n        lengthwise = [d for d in range(-self.LONG_REACH, self.LONG_REACH + 1, self.LONG_STEP) if 0 <= s + ahead * d <= length]\n        for d in lengthwise:\n            px, py, qx, qy = self._line_frame(line, s + ahead * d)\n            samples.append((px + shift * qx, py + shift * qy))\n        return lengthwise, samples, \"axe BD TOPO\"\n\n    @staticmethod\n    def _edge_slope(z, offsets, i, span):\n        \"\"\"Pente vers le bas en s'éloignant, de i au premier point à span m au moins (None sans altitude).\"\"\"\n        j = next((j for j in range(i + 1, len(offsets)) if offsets[j] - offsets[i] >= span - 1e-6), None)\n        return None if j is None or z[i] is None or z[j] is None else (z[i] - z[j]) / (offsets[j] - offsets[i])\n\n    def _edge_step(self, z, offsets, i, sharp=False):\n        \"\"\"Marche du terrain juste après le point i (voir STEP_Z) : +1 en montant, -1 en descendant, 0 sinon. sharp : plus\n        abrupte que les pas voisins (STEP_SHARP), pour la recherche dans l'autre voie après un bombement (_edge_border) : une\n        pente soutenue de plus de 10 % (dévers en courbe) ou un défaut de la chaussée y fait aussi 5 cm par pas sans être le\n        bord. Pas ailleurs : bordures et séparateurs, adoucis par le MNT, ne sont pas nets (piste P16).\"\"\"\n        if i < 1 or i + 2 >= len(offsets) or offsets[i + 1] - offsets[i] > self.EDGE_STEP + 1e-6:\n            return 0\n        if None in (z[i - 1], z[i], z[i + 1], z[i + 2]):\n            return 0\n        jump, held = z[i + 1] - z[i], z[i + 2] - z[i - 1]\n        if sharp and max(abs(z[i] - z[i - 1]), abs(z[i + 2] - z[i + 1])) >= self.STEP_SHARP * abs(jump):\n            return 0\n        if abs(jump) >= self.STEP_Z and abs(held) >= self.STEP_HOLD and jump * held > 0:\n            return 1 if jump > 0 else -1\n        return 0\n\n    def _edge_border(self, z, offsets, reach, beyond=0.0, axis=None):\n        \"\"\"Indice du bord : premier point, à EDGE_NEAR m au moins de l'origine (chaussées séparées : au-delà de\n        l'axe de l'autre chaussée, à beyond m), d'où la pente sur 1 m s'écarte de plus de EDGE_BREAK de celle de\n        la chaussée sous l'origine (ou sous l'axe de l'autre), dans le même sens sur EDGE_HOLD pas, ou d'où le\n        terrain marque une marche (bordure, accotement plus bas : STEP_Z), jusqu'à reach m ; sinon None (le bord BD\n        TOPO). La pente sur 1 m voit la rupture jusqu'à 1 m avant elle : le bord avance d'un pas tant que la pente de\n        ce pas reste celle de la chaussée (à EDGE_BREAK près), soit le dernier point de la chaussée (0,5 m plus tôt\n        sinon : piste P7 de docs/analyses/pistes-profil.md).\n        Bombement (piste P16) : une rupture à CROWN_NEAR m au plus de l'axe BD TOPO (axis, m depuis l'origine de ce côté),\n        suivie d'une pente de chaussée (voir _crown_slope), est le sommet du bombement ou le changement de dévers d'une\n        voie à l'autre, que la recherche franchit depuis la caméra : la pente qui suit devient la référence, une seule\n        fois, et le bord est cherché CROWN_SEARCH m plus loin ; sans autre rupture ensuite, le bord est cette première rupture.\"\"\"\n        slope = self._edge_slope\n        start = min(range(len(offsets)), key=lambda k: abs(offsets[k] - beyond))\n        road = slope(z, offsets, start, 1.0)\n        crown = None  # rupture prise pour un bombement : le bord si aucune autre ne suit\n        i = start\n        while i + 1 < len(offsets):\n            i += 1\n            if road is None or offsets[i] > reach:\n                break\n            if offsets[i] < max(self.EDGE_NEAR, beyond) - 1e-6:\n                continue\n            d = [slope(z, offsets, k, 1.0) for k in range(i, i + self.EDGE_HOLD)]\n            if self._edge_step(z, offsets, i, sharp=crown is not None):\n                # marche : une pente de plus de 10 % sur un pas en fait une aussi (bombement prononcé, D70\n                # 229abfcd-868c-4eca-bfc1-3979ca94d28f)\n                j = i\n            elif None not in d and (all(v - road > self.EDGE_BREAK for v in d) or all(road - v > self.EDGE_BREAK for v in d)):\n                # dans la fenêtre de 1 m, un point au plus encore sur la chaussée (pas de EDGE_STEP m)\n                j = i + 1\n                if not (j < len(offsets) and offsets[j] - offsets[i] <= self.EDGE_STEP + 1e-6 and offsets[j] <= reach\n                        and z[i] is not None and z[j] is not None\n                        and abs((z[i] - z[j]) / (offsets[j] - offsets[i]) - road) <= self.EDGE_BREAK):\n                    j = i\n            else:\n                continue\n            after = (self._crown_slope(z, offsets, j, reach)\n                     if crown is None and axis is not None and abs(offsets[j] - axis) <= self.CROWN_NEAR + 1e-6 else None)\n            if after is None:\n                return j\n            crown, (i, road) = j, after\n            reach += self.CROWN_SEARCH\n            i -= 1  # reprise au premier point après le bombement\n        return crown\n\n    def _crown_slope(self, z, offsets, j, reach):\n        \"\"\"Après une rupture au point j : (indice du point à EDGE_STEP m au-delà, sa pente sur 1 m) si la pente y est une\n        pente de chaussée (CROWN_SLOPE au plus) qui tient à EDGE_BREAK près sur CROWN_HOLD m, avant reach ; sinon None.\"\"\"\n        k0 = next((k for k in range(j + 1, len(offsets)) if offsets[k] - offsets[j] >= self.EDGE_STEP - 1e-6), None)\n        if k0 is None or offsets[k0] + self.CROWN_HOLD > reach + 1e-6:\n            return None\n        s0 = self._edge_slope(z, offsets, k0, 1.0)\n        if s0 is None or abs(s0) > self.CROWN_SLOPE:\n            return None\n        for k in range(k0 + 1, len(offsets)):\n            if offsets[k] + 1.0 > offsets[k0] + self.CROWN_HOLD + 1e-6:\n                break\n            s = self._edge_slope(z, offsets, k, 1.0)\n            if s is None or abs(s - s0) > self.EDGE_BREAK:\n                return None\n        return k0, s0\n\n    def _edge_peaks(self, z, offsets, between, beyond):\n        \"\"\"Pics étroits (voir PEAK_Z) avant l'axe de l'autre chaussée, à SEPARATOR_NEAR m au plus du milieu BD TOPO\n        du séparateur : leurs positions en m depuis l'origine.\"\"\"\n        mid, out = (between[0] + between[1]) / 2, []\n        for k in range(1, len(offsets) - 2):\n            if offsets[k] >= beyond or abs(offsets[k] - mid) > self.SEPARATOR_NEAR:\n                continue\n            if offsets[k + 1] - offsets[k] > self.EDGE_STEP + 1e-6 or None in z[k - 1:k + 3]:\n                continue\n            if z[k] - z[k - 1] >= self.PEAK_Z and z[k] - z[k + 1] >= self.PEAK_Z:\n                out.append(offsets[k])\n            elif (abs(z[k + 1] - z[k]) < self.PEAK_Z and z[k] - z[k - 1] >= self.PEAK_Z\n                  and z[k + 1] - z[k + 2] >= self.PEAK_Z):  # deux points de large\n                out.append((offsets[k] + offsets[k + 1]) / 2)\n        return out\n\n    def _edge_separator(self, z, offsets, between, beyond):\n        \"\"\"Séparateur de chaussée trouvé dans le relief : (début, fin) en m depuis l'origine, entre deux marches de\n        sens contraires (surélevé : montée puis descente ; en creux : l'inverse), avant l'axe de l'autre chaussée,\n        large de SEPARATOR_WIDTH, au milieu le plus proche de celui de la BD TOPO (between, SEPARATOR_NEAR m au\n        plus) ; None sinon.\"\"\"\n        steps = []  # (m depuis l'origine, sens), une seule par suite de marches de même sens\n        for i in range(len(offsets)):\n            if offsets[i] >= beyond:\n                break\n            k = self._edge_step(z, offsets, i)\n            if k and not (steps and steps[-1][1] == k and offsets[i] - steps[-1][2] <= self.EDGE_STEP + 1e-6):\n                steps.append((offsets[i] + self.EDGE_STEP / 2, k, offsets[i]))\n            elif k:\n                steps[-1] = steps[-1][:2] + (offsets[i],)\n        mid, best = (between[0] + between[1]) / 2, None\n        for (a, ka, _), (b, kb, _) in zip(steps, steps[1:]):\n            if ka == kb or not self.SEPARATOR_WIDTH[0] <= b - a <= self.SEPARATOR_WIDTH[1]:\n                continue\n            gap = abs((a + b) / 2 - mid)\n            if gap <= self.SEPARATOR_NEAR and (best is None or gap < best[0]):\n                best = (gap, a, b)\n        return best and best[1:]\n\n    def _edge_reads(self, profiles, ground, sides, paved):\n        \"\"\"Bord et séparateur de chaque travers lus sur le terrain (ground, dans l'ordre des profils) : 1er passage travers par\n        travers, puis, côté par côté, ceux qui s'écartent de la médiane des travers trouvés dans le relief (une marche dans\n        l'autre chaussée, un bord flou) y sont ramenés, comme ceux sans rupture de pente (bord d'après les travers\n        voisins, pas trouvé dans leur relief) ; analyse fine (paved) : le bord de l'enrobé l'emporte. Rend (lectures [le\n        long, côté, bord BD TOPO, distances, altitudes, indice du bord, séparateur, son origine, pics, axe de l'autre\n        chaussée, bord ramené à la médiane], nombre de travers par côté où l'autre chaussée est comprise).\"\"\"\n        twins = {name: 0 for name, _ in sides}  # côté -> travers où l'autre chaussée est comprise\n        read = []\n        start = 0\n        for along, name, guess, offsets, beyond, between, reach, axis in profiles:\n            z = ground[start:start + len(offsets)]\n            start += len(offsets)\n            if z[0] is None:\n                continue\n            twins[name] += beyond > 0\n            found_sep = between and self._edge_separator(z, offsets, between, beyond)\n            i = self._edge_border(z, offsets, reach, beyond, axis)\n            read.append([along, name, guess, offsets, z, i, found_sep or between, \"marches\" if found_sep else None,\n                         self._edge_peaks(z, offsets, between, beyond) if between else [], beyond, False])\n        for name, _ in sides:\n            mine = [r for r in read if r[1] == name]\n            edges = sorted(r[3][r[5]] for r in mine if r[5] is not None)\n            seps = [r[6] for r in mine if r[7]]\n            if not seps:  # pas de séparateur à deux marches : un pic étroit qui revient d'un travers à l'autre\n                tops = sorted(p for r in mine for p in r[8])\n                groups = [[q for q in tops if abs(q - p) <= self.PEAK_SPREAD] for p in tops]\n                group = max(groups, key=len, default=[])\n                if len({r[0] for r in mine if any(abs(q - p) <= self.PEAK_SPREAD for q in group for p in r[8])}) >= self.PEAK_TRAVERS:\n                    top = group[len(group) // 2]\n                    seps = [(top - self.PEAK_HALF, top + self.PEAK_HALF)]\n                    for r in mine:\n                        if r[6]:\n                            r[6], r[7] = seps[0], \"bosse\"\n            med = edges[(len(edges) - 1) // 2] if len(edges) >= 3 else None  # médiane basse : le bord le plus proche\n            sep_med = [sorted(v[k] for v in seps)[len(seps) // 2] for k in (0, 1)] if seps else None\n            for r in mine:\n                if med is not None and (r[5] is None or abs(r[3][r[5]] - med) > self.EDGE_CONSENSUS):\n                    r[5], r[10] = min(range(len(r[3])), key=lambda k: abs(r[3][k] - med)), True\n                if sep_med and r[6] and (not r[7] or max(abs(r[6][k] - sep_med[k]) for k in (0, 1)) > self.EDGE_CONSENSUS):\n                    r[6], r[7] = sep_med, \"marches\"\n                if name in paved:  # analyse fine : le bord de l'enrobé remplace celui du relief\n                    r[5] = min(range(len(r[3])), key=lambda k: abs(r[3][k] - paved[name]))\n        return read, twins\n\n    def _edge_falls(self, read, sides, paved, zone):\n        \"\"\"Chute et dévers de chaque côté depuis les bords lus (_edge_reads), jusqu'à zone m du milieu de la chaussée (entre\n        les deux bords du travers), soit zone moins la demi-largeur au-delà du bord, EDGE_ZONE_MIN m au moins. Rend (côté ->\n        [(chute, à m du bord, bout du profil, travers), (dévers, haut du talus à m du bord, travers, pied du talus à m du\n        bord, hauteur du talus)], bords [(m depuis l'origine, relief, d'après les travers voisins)], côté -> distances au\n        bord où le terrain remonte de EDGE_RISE, profils pour le graphique de la page (bouton « Graphiques »)).\"\"\"\n        found = {name: [None, None] for name, _ in sides}\n        borders = {name: [] for name, _ in sides}\n        stops = {name: [] for name, _ in sides}\n        drawn = []\n        def edge_of(r):  # bord du travers r, m depuis l'origine (analyse fine, sinon relief, sinon largeur type)\n            k = r[5] if r[5] is not None else min(range(len(r[3])), key=lambda j: abs(r[3][j] - r[2]))\n            return paved.get(r[1], r[3][k])\n        edges_at = {(r[0], r[1]): edge_of(r) for r in read}\n        for along, name, guess, offsets, z, i, between, sep_relief, _, beyond, moved in read:\n            relief = i is not None and not moved  # trouvé dans le relief de ce travers, pas ramené à la médiane des autres\n            if i is None:\n                i = min(range(len(offsets)), key=lambda k: abs(offsets[k] - guess))\n            borders[name].append((offsets[i], relief, moved))\n            entry = {\"le_long\": along, \"cote\": name, \"bord\": round(paved.get(name, offsets[i]), 2), \"relief\": relief,\n                     \"voisins\": moved, \"enrobe\": name in paved, \"arret\": None,\n                     \"separateur\": [round(v, 2) for v in between] if between else None,\n                     \"autre_axe\": round(beyond, 2) if beyond else None,  # axe de l'autre chaussée, m depuis l'origine\n                     \"separateur_relief\": sep_relief if between else None,  # \"marches\", \"bosse\" ou None (BD TOPO)\n                     \"points\": [[round(o, 2), round(v, 2)] for o, v in zip(offsets, z) if v is not None]}\n            drawn.append(entry)\n            # jusqu'à zone m du milieu de la chaussée : au-delà du bord, zone moins sa demi-largeur (l'autre bord absent : l'origine)\n            other = next((edge for (a, n), edge in edges_at.items() if a == along and n != name), 0.0)\n            past = max(self.EDGE_ZONE_MIN, zone - (edges_at[(along, name)] + other) / 2)\n            kept = [k for k in range(i, len(offsets)) if offsets[k] - offsets[i] <= past + 1e-6]\n            zz, oo = [z[k] for k in kept], [offsets[k] - offsets[i] for k in kept]\n            if zz[0] is None:\n                continue\n            # Terrain qui remonte de EDGE_RISE au-dessus du bord : lecture arrêtée (on ne passe pas la butte)\n            cut = next((k for k, v in enumerate(zz) if v is not None and v - zz[0] >= self.EDGE_RISE), None)\n            end = oo[-1]  # bout du profil : le terrain y descend peut-être encore\n            if cut is not None:\n                stops[name].append(oo[cut])\n                entry[\"arret\"] = round(offsets[i] + oo[cut], 2)\n                zz, oo, end = zz[:cut], oo[:cut], float(\"inf\")\n            # point le plus bas le plus proche du bord (à 5 cm près) : le pied du talus\n            low = max(((zz[0] - v, o) for v, o in zip(zz, oo) if v is not None),\n                      key=lambda c: (round(c[0] / self.EDGE_FLAT), -c[1]))\n            if found[name][0] is None or low[0] > found[name][0][0]:\n                found[name][0] = low + (end, along)\n            # Dévers : pente moyenne du talus le plus raide (FALL_MIN m de haut au moins), du haut au pied,\n            # tous travers confondus (le cas le plus défavorable), et non la pente la plus forte sur\n            # 2 m (un détail). Talus : pentes sur EDGE_WINDOW m d'au moins EDGE_TALUS, resserrées autour de la plus\n            # forte sur celles d'au moins EDGE_CORE fois elle (sans l'accotement en pente douce ni la queue du pied)\n            slopes = [self._edge_slope(zz, oo, j, self.EDGE_WINDOW) or 0 for j in range(len(oo))]\n            for mean, top, foot, height in self._taluses(zz, oo, slopes):\n                if height >= self.FALL_MIN and (found[name][1] is None or mean > found[name][1][0]):\n                    found[name][1] = (mean, top, along, foot, height)\n        return found, borders, stops, drawn\n\n    def _edges_sides(self, sides, borders, found, stops, drawn, twins, sigma, origin):\n        \"\"\"Bords, chutes et dévers de chaque côté (voir _compute_edges) : (lignes du texte, bords trouvés pour l'infobulle,\n        résultats par côté pour le graphique de la page).\"\"\"\n        lines, seen, shown = [], [], {}\n        for name, _ in sides:\n            if borders[name]:\n                by_relief = sum(r for _, r, _ in borders[name])\n                by_others = sum(m for _, _, m in borders[name])  # ramenés à la médiane des autres travers\n                seen.append(\"côté {} à {} m de {} ({}{}{})\".format(\n                    name, measures._num(sorted(o for o, _, _ in borders[name])[len(borders[name]) // 2], 1), origin,\n                    \"relief sur {} travers sur {}\".format(by_relief, len(borders[name])) if by_relief\n                    else \"largeur type\", f\", {by_others} d'après les travers voisins\" if by_others else \"\",\n                    \", au-delà du séparateur de chaussée ({}) et de l'autre chaussée\".format(\n                        \"trouvé dans le relief\" if any(e.get(\"separateur_relief\") for e in drawn if e[\"cote\"] == name)\n                        else \"d'après la BD TOPO\") if twins[name] else \"\"))\n            fall, slope_max = found[name]\n            stop = sorted(stops[name])[len(stops[name]) // 2] if stops[name] else None\n            if fall is None or fall[0] < self.FALL_MIN:\n                if stop is not None:\n                    lines.append(\"Côté {} : pas de chute avant le terrain qui remonte de {} m, à {} m du bord\".format(\n                        name, measures._num(self.EDGE_RISE, 0), _distance(stop)))\n                continue\n            beyond = fall[1] >= fall[2] - 1e-6  # le plus bas au bout du profil : le terrain descend encore\n            text = \"Côté {} : chute {}{} m (±{} m) {} {} m du bord\".format(\n                name, \"≥ \" if beyond else \"\", measures._num(fall[0], 1), measures._num(sigma, 1),\n                \"au-delà de\" if beyond else \"à\", _distance(fall[1], whole=beyond))  # au-delà : le bout du profil, au mètre\n            wall = bool(slope_max) and slope_max[0] >= self.WALL_SLOPE\n            if wall:\n                text += \", paroi quasi verticale (mur, enrochement) sur {} m de haut\".format(measures._num(slope_max[4], 1))\n            elif slope_max and slope_max[0] > 0:\n                text += \", dévers du talus {} % ({}°) sur {} m de haut\".format(\n                    measures._num(100 * slope_max[0], 0), measures._num(math.degrees(math.atan(slope_max[0])), 0),\n                    measures._num(slope_max[4], 1))\n            lines.append(text)\n            # devers : [pente, haut, travers, pied, hauteur, paroi quasi verticale]\n            shown[name] = {\"chute\": [round(fall[0], 2), round(fall[1], 2), beyond, fall[3]],\n                           \"devers\": [round(slope_max[0], 3), round(slope_max[1], 2), slope_max[2],\n                                      round(slope_max[3], 2), round(slope_max[4], 2), wall]\n                           if slope_max and slope_max[0] > 0 else None}\n        return lines, seen, shown\n\n    def _edges_title(self, source, origin, zone, seen):\n        \"\"\"Infobulle des bords : méthode, puis les bords trouvés (seen).\"\"\"\n        return (\"Terrain ({}) en travers de la route, depuis {} jusqu'à {} m du milieu de la chaussée (1 m au moins au-delà du bord), \"\n                \"sur ±{} m le long de la route ; côtés vus dans le sens de la photo. Bord : rupture de pente \"\n                \"ou marche du terrain (bordure), sinon demi-largeur type de la catégorie de la route (importance BD TOPO) ; dès 3 travers trouvés \"\n                \"dans le relief, un travers sans rupture ou au bord à plus de {} m de leur médiane prend cette \"\n                \"médiane (d'après les travers voisins) ; chaussées séparées : \"\n                \"bord extérieur de l'autre chaussée, séparateur de chaussée compris (entre deux marches du \"\n                \"terrain, sinon d'après la BD TOPO). Chute : plus grande descente sous le \"\n                \"terrain du bord, lue jusqu'à ce que le terrain remonte de {} m au-dessus du bord (talus, \"\n                \"butte). Dévers : pente moyenne du talus le plus raide, de son haut à son pied (pente sur {} m \"\n                \"repassée sous {} %). Bords trouvés : {}.\").format(\n            source, origin, measures._num(zone, 0), measures._num(self.EDGE_ALONG[-1], 0),\n            measures._num(self.EDGE_CONSENSUS, 0), measures._num(self.EDGE_RISE, 0),\n            measures._num(self.EDGE_WINDOW, 0),\n            measures._num(100 * self.EDGE_TALUS, 0), \" ; \".join(seen) or \"aucun\")\n\n    def _junction_near(self, ends, along_of):\n        \"\"\"Carrefour avec une voie nommée (ends, voir _chained) à JUNCTION_NEAR m au plus de la photo le long de la route, le\n        plus proche : {\"d\" : m dans le sens de la photo, \"avec\" : voies, \"texte\" : ligne de l'encadré}, ou None.\"\"\"\n        near = [(along_of(p), names) for p, kind, names in ends[0] if kind == \"carrefour\"]\n        near = [(d, names) for d, names in near if abs(d) <= self.JUNCTION_NEAR]\n        if not near:\n            return None\n        d, names = min(near, key=lambda e: abs(e[0]))\n        out = {\"d\": round(d, 1), \"avec\": names}\n        out[\"texte\"] = self._junction_text(out)  # pour le graphique et sa légende (src/profil.js)\n        return out\n\n    @staticmethod\n    def _junction_text(junction):\n        \"\"\"Ligne de l'encadré pour un carrefour proche (_junction_near).\"\"\"\n        where = (\"au droit de la photo\" if abs(junction[\"d\"]) < 1 else \"{} m {}\".format(\n            measures._num(abs(junction[\"d\"]), 0), \"devant\" if junction[\"d\"] > 0 else \"derrière\"))\n        names = \" et \".join(_road_label(n) for n in junction[\"avec\"]) or \"une autre voie\"\n        return \"Carrefour avec {} {} : bords peu sûrs (la chaussée s'y élargit, pas de bord continu)\".format(names, where)\n\n    def _long_profile(self, pts, ends, along_of, followed):\n        \"\"\"Profil en long de la route sous la photo (pts : [(d en m dans le sens de la photo, altitude)]) : fins de la route\n        et carrefours avec une voie nommée (ends, voir _chained), creux et ponts comblés (_bridged), tunnels ; pente moyenne\n        et la plus forte sur LONG_WINDOW m. None avec moins de 5 points. along_of(p) : position d'un point le long de la route.\"\"\"\n        # Fin de la route de la photo et carrefours avec une voie nommée, le long d'elle ; au-delà d'une fin, pas de profil\n        # (la caméra a pu continuer sur une autre route)\n        cuts = []\n        for p, kind, names in ends[0]:\n            d = round(along_of(p), 1)\n            if -self.LONG_REACH - 1 <= d <= self.LONG_REACH + 1 and all(abs(d - e[\"d\"]) > 1 for e in cuts):\n                cuts.append({\"d\": d, \"type\": kind, \"voie\": ends[1], \"avec\": names})\n        # Carrefour à îlot séparateur : la voie qui arrive y est faite d'un tronçon par sens, qui touchent la route en deux\n        # points proches ; un seul repère au milieu (LONG_JUNCTION m au plus entre eux, même voie)\n        cuts.sort(key=lambda e: e[\"d\"])\n        merged = []\n        for e in cuts:\n            last = merged[-1] if merged else None\n            if (last and e[\"type\"] == last[\"type\"] == \"carrefour\" and set(e[\"avec\"]) & set(last[\"avec\"])\n                    and e[\"d\"] - last[\"d0\"] <= self.LONG_JUNCTION):\n                last[\"d\"] = round((last[\"d0\"] + e[\"d\"]) / 2, 1)\n                last[\"avec\"] = sorted(set(last[\"avec\"]) | set(e[\"avec\"]))\n            else:\n                merged.append(dict(e, d0=e[\"d\"]))\n        cuts = [{k: v for k, v in e.items() if k != \"d0\"} for e in merged]\n        for e in cuts:\n            if e[\"type\"] == \"fin\":\n                pts = [(d, v) for d, v in pts if (d <= e[\"d\"] + 1e-6 if e[\"d\"] > 0 else d >= e[\"d\"] - 1e-6)]\n        cuts = [e for e in cuts if pts and pts[0][0] - 1 <= e[\"d\"] <= pts[-1][0] + 1]\n        # Creux (ponts, même absents de la BD TOPO) : terrain remplacé par la droite d'un bord à l'autre (le tablier, à peu\n        # près), pente comprise ; nommés « pont » s'ils recouvrent un pont de la route\n        bridges = [sorted((along_of(a), along_of(b))) for level, a, b in ends[2] if level > 0]\n        pts, dips = self._bridged(pts, bridges)\n        spans = [{\"de\": round(lo, 1), \"a\": round(hi, 1),\n                  \"type\": \"pont\" if any(b0 <= hi and b1 >= lo for b0, b1 in bridges) else \"creux\"} for lo, hi in dips]\n        # Tunnels de la route : le MNT y donne le dessus, remplacé par la droite d'une tête à l'autre\n        for level, a, b in ends[2]:\n            lo, hi = sorted((along_of(a), along_of(b)))\n            before = [(d, v) for d, v in pts if d <= lo + 1e-6]\n            after = [(d, v) for d, v in pts if d >= hi - 1e-6]\n            if level > 0 or not pts or hi < pts[0][0] or lo > pts[-1][0]:\n                continue\n            if before and after:\n                (d0, z0), (d1, z1) = before[-1], after[0]\n                pts = [(d, z0 + (z1 - z0) * (d - d0) / ((d1 - d0) or 1.0)) if d0 < d < d1 else (d, v) for d, v in pts]\n            else:  # tunnel au bout du profil, une seule tête : pas de terrain dessus\n                pts = [(d, v) for d, v in pts if not lo < d < hi]\n            spans.append({\"de\": round(lo, 1), \"a\": round(hi, 1), \"type\": \"tunnel\"})\n        grade = None\n        if len(pts) >= 5:\n            md, mz = sum(d for d, _ in pts) / len(pts), sum(v for _, v in pts) / len(pts)\n            mean = sum((d - md) * (v - mz) for d, v in pts) / (sum((d - md) ** 2 for d, _ in pts) or 1.0)\n            windows = [((b[1] - a[1]) / (b[0] - a[0]), a[0], b[0]) for k, a in enumerate(pts) for b in pts[k + 1:]\n                       if abs(b[0] - a[0] - self.LONG_WINDOW) < 1e-6]  # (pente, de, à) sur LONG_WINDOW m\n            steep = max(windows, key=lambda c: abs(c[0]), default=None)\n            grade = {\"points\": [[d, round(v, 2)] for d, v in pts], \"pente\": round(100 * mean, 1), \"suivi\": followed,\n                     \"fins\": sorted(cuts, key=lambda e: e[\"d\"]), \"ouvrages\": spans,\n                     \"max\": [round(100 * steep[0], 1), steep[1], steep[2]] if steep else None}\n        return grade\n\n    def _taluses(self, zz, oo, slopes):\n        \"\"\"Talus d'un travers, depuis le bord : [(pente moyenne, haut et pied en m du bord, hauteur)]. Talus : pentes sur\n        EDGE_WINDOW m (slopes, une par point) d'au moins EDGE_TALUS, resserrées autour de la plus forte sur celles d'au moins\n        EDGE_CORE fois elle (sans l'accotement en pente douce ni la queue du pied). Les fenêtres de EDGE_WINDOW m débordent\n        sur le plat du haut et du fond : le haut avance tant que le pas suivant descend de moins de EDGE_TALUS / 2, le pied\n        est le premier point à EDGE_FLAT m du plus bas (jusqu'au bout de la dernière fenêtre en pente) ; sinon le talus\n        compte ces plats et sa pente est minorée (50 % lu à 33 % : piste P8 de docs/analyses/pistes-profil.md).\"\"\"\n        out, k = [], 0\n        while k < len(oo):\n            if slopes[k] < self.EDGE_TALUS:\n                k += 1\n                continue\n            first = k\n            while k < len(oo) and slopes[k] >= self.EDGE_TALUS:\n                k += 1\n            steep = max(range(first, k), key=lambda j: slopes[j])\n            floor = max(self.EDGE_TALUS, self.EDGE_CORE * slopes[steep])\n            top, end = steep, steep + 1\n            while top > first and slopes[top - 1] >= floor:\n                top -= 1\n            while end < k and slopes[end] >= floor:\n                end += 1\n            last = next((j for j in range(end - 1, len(oo)) if oo[j] - oo[end - 1] >= self.EDGE_WINDOW - 1e-6), len(oo) - 1)\n            foot = min((j for j in range(top, last + 1) if zz[j] is not None), key=lambda j: zz[j])\n            foot = next(j for j in range(top, foot + 1) if zz[j] is not None and zz[j] <= zz[foot] + self.EDGE_FLAT)\n            while (top + 1 < foot and zz[top] is not None and zz[top + 1] is not None\n                   and zz[top] - zz[top + 1] < self.EDGE_TALUS / 2 * (oo[top + 1] - oo[top])):\n                top += 1\n            height = zz[top] - zz[foot]\n            out.append((height / (oo[foot] - oo[top]) if foot > top else 0, oo[top], oo[foot], height))\n        return out\n\n    def _terrain(self, points, done):\n        \"\"\"precision.fetch_terrain par paquets de FALL_POINTS points (une requête chacun), l'un après l'autre ;\n        done(altitudes, source, erreur). Une seule source pour des altitudes comparées entre elles : chaque paquet choisit\n        la sienne (LiDAR HD, RGE ALTI s'il y manque un point) ; si l'un est passé en RGE ALTI, tous sont relus en RGE ALTI.\"\"\"\n        out, sources = [], []\n        chunks = [points[k:k + self.FALL_POINTS] for k in range(0, len(points), self.FALL_POINTS)]\n\n        def step(k):\n            def got(ground, source, error):\n                if error or not source:\n                    return done(None, source, error)\n                out.extend(ground if len(ground) == len(chunks[k]) else [None] * len(chunks[k]))  # incomplète : pas décalée\n                sources.append(source)\n                if k + 1 < len(chunks):\n                    return step(k + 1)\n                if len(set(sources)) == 1:\n                    return done(out, source, None)\n                relay(0, [])  # sources mêlées\n\n            precision.fetch_terrain(chunks[k], got)\n\n        def relay(k, zs):  # tous les paquets en RGE ALTI\n            def got(data, error):\n                if error:\n                    return done(None, None, error)\n                z = precision._ground(data) if data else []\n                zs.extend(z if len(z) == len(chunks[k]) else [None] * len(chunks[k]))  # réponse incomplète : pas décalée\n                if k + 1 < len(chunks):\n                    return relay(k + 1, zs)\n                done(zs, \"RGE ALTI\", None)\n\n            host.fetch_json(precision.lidar_url(chunks[k], precision.RGE_RESOURCE), got, timeout_ms=precision.TIMEOUT_MS)\n\n        step(0)\n\n    def use_paved_edges(self, frame, edges):\n        \"\"\"Bords d'enrobé de l'analyse fine (src/nuage.js) pour le profil de repère frame (JSON de profile.repere) : edges,\n        en JSON, m depuis l'origine par côté (« gauche », « droit »). Plateforme, dévers, chute et dévers du talus de ce\n        profil se relisent depuis eux, sur tous les travers, sans nouvelle lecture du terrain s'il vient d'être calculé.\"\"\"\n        frame = tuple(tuple(p) for p in json.loads(frame))\n        self.paved[frame] = json.loads(edges)\n        redo = self.paved_redo.get(frame)\n        for key, res in list(self.edges.items()):  # autre largeur examinée : recalculée à la demande\n            profile = res.get(\"profile\")\n            if profile and tuple(tuple(p) for p in profile[\"repere\"]) == frame and (not redo or key != redo[0]):\n                del self.edges[key]\n        if redo:\n            redo[1]()\n\n    def fall_json(self):\n        \"\"\"Hauteur de chute (voir fall), en JSON : demandée par la page hors lecture de la séquence\n        (sinon une lecture BD TOPO par maille de 100 m traversée).\"\"\"\n        return json.dumps(self.fall())\n",
 "web_host.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Services du navigateur pour le cœur de calcul (voir core/host.py), dans Pyodide.\n\n- Réseau : fetch du navigateur (pyodide.http.pyfetch), en tâche asyncio ; le rappel est\n  appelé à l'arrivée de la réponse, comme avec QgsNetworkAccessManager dans le plugin.\n- Altitude NGF : grille RAF20 de l'IGN (voir geoid.py), chargée par load_geoid.\n- Calculs lourds (inclinaison automatique, capture HD) : dans un second Pyodide, en\n  arrière-plan (Web Worker, voir src/calcul.js), qui décode aussi les photos (Pillow).\n\"\"\"\n\nimport asyncio\nimport json\nimport traceback\n\nfrom pyodide.ffi import to_js\nfrom pyodide.http import pyfetch\n\nimport geoid\nfrom core import host\n\nAPI_URL = \"https://api.panoramax.xyz/api\"\n# Service d'altimétrie de l'IGN : il refuse les rafales (HTTP 429). Ses requêtes partent une à\n# une, espacées, et un refus est retenté après une pause.\nTHROTTLED = \"data.geopf.fr/altimetrie/\"\nSPACING = 0.25  # s entre deux requêtes au service\nRETRIES = (1.0, 3.0)  # pauses (s) avant de retenter après un refus\nTIMEOUT_MS = 30000  # délai par défaut d'une requête sans délai propre (images : le double), pas d'attente sans fin\n_throttle = None  # verrou des requêtes au service (créé dans la boucle asyncio)\n\n_local_run = host.run_task  # calcul sur place, sans arrière-plan (valeur par défaut du cœur)\n_geoid = None  # grille RAF20, une fois chargée\n_remote = None  # fonction JS (module, fonction, arguments) -> promesse du résultat (texte JSON)\n\n\nclass Reply:\n    \"\"\"Requête en cours : abort() l'abandonne sans appeler son rappel.\"\"\"\n\n    def __init__(self, task):\n        self.task = task\n\n    def abort(self):\n        self.task.cancel()\n\n\nasync def _fetch(url, timeout_ms):\n    request = pyfetch(url)\n    return await (asyncio.wait_for(request, timeout_ms / 1000.0) if timeout_ms else request)\n\n\nasync def _fetch_throttled(url, timeout_ms):\n    global _throttle\n    if _throttle is None:\n        _throttle = asyncio.Lock()\n    for pause in RETRIES + (None,):\n        async with _throttle:\n            response = await _fetch(url, timeout_ms)\n            await asyncio.sleep(SPACING)\n        if response.status != 429 or pause is None:\n            return response\n        await asyncio.sleep(pause)\n\n\nasync def _get(url, callback, as_json, timeout_ms):\n    timeout_ms = timeout_ms or (TIMEOUT_MS if as_json else 2 * TIMEOUT_MS)\n    try:\n        response = await (_fetch_throttled if THROTTLED in url else _fetch)(url, timeout_ms)\n        if not response.ok:\n            result = (None, \"HTTP {}\".format(response.status))\n        elif as_json:\n            result = (await response.json(), None)\n        else:\n            result = (await response.bytes(), None)\n    except asyncio.CancelledError:\n        return  # abandonnée (voir Reply.abort)\n    except asyncio.TimeoutError:\n        result = (None, \"pas de réponse en {:.0f} s\".format(timeout_ms / 1000.0))\n    except Exception as exc:  # réseau, CORS, JSON illisible\n        result = (None, str(exc) or exc.__class__.__name__)\n    try:\n        callback(*result)\n    except Exception:\n        traceback.print_exc()  # erreur du rappel : signalée dans la console, pas avalée\n\n\ndef fetch(url, callback, prefer_cache=False, timeout_ms=None):\n    return Reply(asyncio.ensure_future(_get(url, callback, False, timeout_ms)))\n\n\ndef fetch_json(url, callback, prefer_cache=False, timeout_ms=None):\n    return Reply(asyncio.ensure_future(_get(url, callback, True, timeout_ms)))\n\n\ndef ngf_altitude(lon, lat, ellipsoidal):\n    return geoid.ngf_altitude(_geoid, lon, lat, ellipsoidal)\n\n\nasync def _run(function, args, done):\n    try:\n        args = [to_js(a) if isinstance(a, (bytes, bytearray)) else a for a in args]\n        text = await _remote(function.__module__, function.__name__, to_js(args))\n        result = json.loads(text) if text else None\n    except Exception:\n        traceback.print_exc()\n        result = None\n    done(result)\n\n\ndef run_task(function, args, done):\n    \"\"\"function(*args) dans le Pyodide d'arrière-plan (fonction d'un module du cœur, arguments\n    et résultat simples : nombres, textes, octets, listes, dicts), puis done(résultat ou None).\"\"\"\n    if _remote is None:\n        _local_run(function, args, done)\n    else:\n        asyncio.ensure_future(_run(function, args, done))\n\n\nasync def load_geoid():\n    \"\"\"Charge la grille du géoïde (altitude NGF) ; sans elle, pas d'altitude GPS de la caméra.\"\"\"\n    global _geoid\n    try:\n        response = await pyfetch(geoid.URL)\n        if response.ok:\n            _geoid = geoid.Grid(await response.bytes())\n    except Exception:\n        traceback.print_exc()\n    return _geoid is not None\n\n\ndef install(remote=None, api_url=API_URL):\n    \"\"\"remote : exécution en arrière-plan (voir run_task), ou None (pas d'arrière-plan).\"\"\"\n    global _remote\n    _remote = remote\n    host.install(fetch=fetch, fetch_json=fetch_json, ngf_altitude=ngf_altitude, run_task=run_task,\n                 api_url=api_url)\n",
 "web_nez.py": "# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"« Largeur dans la visionneuse » (expérimental, piste P22 de docs/analyses/pistes-profil.md) : droite tracée au sol juste devant le\nnez du véhicule, perpendiculaire à la trajectoire de la séquence, vue dans la photo affichée (src/nez.js). Nez est une base de\nweb_app.App : ses méthodes lisent l'état de l'application (self).\"\"\"\n\nimport json\nimport math\n\nfrom core import autotilt, calibration, metadata, precision, triangulation\n\nNOSE_STEP = 0.05  # m : pas des points de la droite\nNOSE_REACH = 12.0  # m : de part et d'autre du droit de la caméra\nNOSE_DISTANCE = {1.93: 4.4, 2.07: 4.8}  # m : capot du CD21 (visible à 4,1 m et 4,5 m, src/dessus.js OUTLINES) plus 0,3 m\nNOSE_DISTANCE_DEFAULT = 4.5  # m : autres véhicules\nNOSE_GROUND_STEP = 0.5  # m : pas des points où le relief est lu (pas du MNT LiDAR HD), interpolé linéairement entre eux\nNOSE_GROUND_MAX = 50  # lectures du relief gardées (une par photo et par droite)\nNOSE_ROTATION_MAX = 45.0  # degrés : rotation à la main de la droite, de part et d'autre de la perpendiculaire au trajet\nNOSE_FLAT = \"plat (relief indisponible)\"  # source du sol quand le MNT manque ou échoue\n\n\nclass Nez:\n    \"\"\"Droite au sol devant le véhicule (voir web_app.App).\"\"\"\n\n    def _nose_tilt(self, roll):\n        \"\"\"(verticale vraie vue de la caméra ou None, source, incertitude en degrés ou None) de la photo affichée. D'abord\n        l'inclinaison que la vue du dessus applique à cette photo quand elle la tire de la route (birdeye_tilt_set : « vue du\n        dessus », « vue du dessus (réglée à la main) » si le tangage ou la part du dévers est réglé à la main) : c'est ce\n        qu'elle montre, tangage lu et défaut de roulis compris. Sinon, dans le même ordre que la vue du dessus\n        (_birdeye_of, qui lit alors les mêmes sources) : inclinaison calée à la main (« clics »), puis verticales de la photo\n        (Calibration.tilt : « verticales », sinon « lidar » lu sous le véhicule), les verticales plus lâches (birdeye_loose,\n        web_tilt.LOOSE_SIGMA) quand elles sont plus sûres que celle-ci sans être calées à la main, enfin le roulis de campagne\n        (`roll`, degrés ; « roulis de campagne », up None : voir _nose_view) ou rien (« aucune »). Les verticales sont lancées par\n        birdeye_request (calcul en arrière-plan, le même que pour la vue du dessus, gardé par photo dans Calibration.auto).\"\"\"\n        pic = self.item.get(\"id\")\n        tilt, loose = self.calibration.tilt(pic), self.birdeye_loose.get(pic)\n        ground = self.birdeye_ground.get(pic)\n        if ground:\n            return tuple(ground[\"up\"]), \"vue du dessus (réglée à la main)\" if ground[\"manual\"] else \"vue du dessus\", ground[\"sigma\"]\n        if loose and (not tilt or (loose[\"sigma\"] < tilt[\"sigma\"] and not tilt[\"source\"].startswith(\"clics\"))):\n            return tuple(loose[\"up\"]), \"verticales (seuil élargi)\", loose[\"sigma\"]\n        if tilt:\n            return tuple(tilt[\"up\"]), tilt[\"source\"], tilt[\"sigma\"]\n        return None, \"roulis de campagne\" if roll else \"aucune\", None\n\n    def birdeye_tilt_set(self, pic, tilt_json):\n        \"\"\"Inclinaison que la vue du dessus applique à la photo `pic` quand elle la tire de la route (src/dessus.js, layerOf :\n        groundUp, avec le tangage lu ou réglé à la main, la part du dévers et le défaut de roulis de la campagne) : JSON\n        {up (même convention que Calibration.tilt : verticale vraie vue de la caméra [est, nord, haut]), sigma (degrés), manual\n        (tangage ou part du dévers réglés à la main)}, ou « null » quand la vue du dessus lit les verticales de la photo (mêmes\n        sources que _nose_tilt, rien à retenir) ou n'a plus d'inclinaison pour elle. Rend vrai si la valeur retenue a changé\n        (la droite est alors refaite, src/nez.js). Gardée par photo (les 20 dernières) : une autre photo ne la reçoit pas.\"\"\"\n        tilt = json.loads(tilt_json)\n        if not tilt:\n            return self.birdeye_ground.pop(pic, None) is not None\n        tilt = {\"up\": [round(float(v), 6) for v in tilt[\"up\"]], \"sigma\": round(float(tilt[\"sigma\"]), 2), \"manual\": bool(tilt.get(\"manual\"))}\n        if self.birdeye_ground.get(pic) == tilt:\n            return False\n        self.birdeye_ground.pop(pic, None)\n        self.birdeye_ground[pic] = tilt\n        while len(self.birdeye_ground) > 20:\n            del self.birdeye_ground[next(iter(self.birdeye_ground))]\n        return True\n\n    def _nose_view(self, bearing, elev, roll, up=None):\n        \"\"\"Comme Session._view_of (cap vrai, élévation en degrés → {yaw, pitch} radians du repère de la photo), mais avec la\n        verticale `up` de _nose_tilt quand elle ne vient pas du calage de la photo (verticales plus lâches), ou, sans inclinaison\n        calée ni lue pour la photo, avec le défaut de roulis de la campagne (Pose.ROLL_DEFECTS, en degrés ; 0 : rien) : la\n        caméra est supposée penchée de ce roulis, seul à connaître (sinon le véhicule serait droit). Avec une inclinaison\n        calée ou lue (up None, roll 0.0 ou calibration.tilt), c'est _view_of. Même signe que groundUp de src/dessus.js :\n        roulis positif, verticale penchée vers la droite du cap.\"\"\"\n        item = self.item\n        sequence = item.get(\"collection\")\n        if up is None and (roll == 0.0 or self.calibration.tilt(item.get(\"id\"))):\n            return self._view_of(bearing, elev)\n        lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        yaw = bearing % 360\n        pose = self.calibration.pose(sequence, lon, lat)\n        if pose:\n            yaw = (yaw - pose[\"offset\"]) % 360\n        if up is None:\n            r, h = math.tan(math.radians(roll)), math.radians(self._nose_axis())\n            norm = math.sqrt(1 + r * r)\n            up = (r * math.cos(h) / norm, -r * math.sin(h) / norm, 1 / norm)\n        yaw, pitch = calibration.untilt(up, yaw, elev, inverse=True)\n        return {\"yaw\": math.radians((yaw - self._heading() + 540) % 360 - 180), \"pitch\": math.radians(pitch)}\n\n    def _nose_axis(self):\n        \"\"\"Axe de la séquence (cap en degrés) à la photo affichée : entre ses voisines, sinon le cap de la photo.\"\"\"\n        axis = self._axis(self.item)\n        return axis if axis is not None else self._heading()\n\n    def _nose_axis_at(self, d):\n        \"\"\"(cap en degrés, écart au cap de la photo) de la trajectoire à `d` m devant la caméra, là où est tracée la droite :\n        la route a tourné entre la photo et la droite (giratoire de 15 à 20 m de rayon : 15 à 20° pour 4,4 m). Interpolation\n        angulaire entre l'axe à la photo (θ0, _nose_axis) et l'axe à la photo suivante dans le sens de marche (θ1), θ = θ0 +\n        t (θ1 - θ0), t = d / distance entre les deux photos (bornée à [0, 1]). θ1 se déduit de la seule photo suivante : sur un\n        arc de cercle, l'axe à la suivante est le symétrique de θ0 par rapport à la corde photo → suivante, θ1 = θ0 + 2 (c -\n        θ0), c = cap de la corde (écarts ramenés à ±180°), |θ1 - θ0| borné à 45°. Pas besoin de la suivante de la suivante.\n        Axe de la photo si la suivante manque ou est à moins de 1 m ou à plus de 20 m.\"\"\"\n        axis = self._nose_axis()\n        item = self.item\n        following = self.neighbours.get(metadata.id_from_href(metadata.item_link(item, \"next\")))\n        if not following:\n            return axis, 0.0\n        try:\n            here = [float(v) for v in item[\"geometry\"][\"coordinates\"][:2]]\n            there = [float(v) for v in following[\"geometry\"][\"coordinates\"][:2]]\n        except (KeyError, TypeError, ValueError):\n            return axis, 0.0\n        east = (there[0] - here[0]) * math.cos(math.radians(here[1])) * 111320.0\n        north = (there[1] - here[1]) * 111320.0\n        gap = math.hypot(east, north)\n        if not 1.0 <= gap <= 20.0:\n            return axis, 0.0\n        chord = math.degrees(math.atan2(east, north))\n        turn = max(-45.0, min(45.0, 2.0 * ((chord - axis + 540) % 360 - 180)))\n        t = min(max(d / gap, 0.0), 1.0)\n        return (axis + t * turn) % 360, t * turn\n\n    def _nose_ground(self, lon, lat, axis, along, d, read=True):\n        \"\"\"(relief, en lecture) sous la droite. relief : (source, sigma en m, [(décalage x en m, écart de sol dz en m)]) ou None\n        (relief indisponible : la droite est alors posée sur un sol plat). Lu une fois par droite (MNT LiDAR HD au pas de 0,5 m,\n        sinon RGE ALTI : precision.fetch_terrain, une requête pour la caméra et les points tous les NOSE_GROUND_STEP m), gardé ;\n        `dz` = z du MNT au point moins z du MNT sous la caméra (relatif : aucun souci de géoïde). La lecture est asynchrone\n        (hôte JS) : tant qu'elle n'est pas arrivée, en lecture est vrai (sol plat en attendant) et src/nez.js redemande la droite.\"\"\"\n        key = tuple(round(v, 6) for v in (lon, lat, axis, along, d))\n        base = key[:3] + key[4:]\n        if key in self.nose_ground:\n            ground = self.nose_ground[key]\n            if ground:\n                self.nose_ground_last = (base, ground)\n            return (ground or None), ground == {}\n        if not read:\n            # glissement de la rotation : pas de nouvelle lecture, relief déjà lu pour cette caméra à l'angle précédent\n            last = getattr(self, \"nose_ground_last\", None)\n            if last and last[0] == base:\n                return last[1], False\n            ground = self.nose_ground.get(key)\n            return (ground or None), False\n        self.nose_ground[key] = {}  # {} : en lecture\n        if len(self.nose_ground) > NOSE_GROUND_MAX:\n            del self.nose_ground[next(iter(self.nose_ground))]\n        a, b = math.radians(axis), math.radians(along)\n        half = int(NOSE_REACH / NOSE_GROUND_STEP)\n        offsets = [k * NOSE_GROUND_STEP for k in range(-half, half + 1)]\n        points = [(lon, lat)] + [triangulation._geographic(d * math.sin(a) + x * math.cos(b), d * math.cos(a) - x * math.sin(b),\n                                                           lon, lat) for x in offsets]\n\n        def done(zs, source, error):\n            if error or not zs or len(zs) != len(points) or None in zs:\n                self.nose_ground[key] = None  # relief indisponible : sol plat\n            else:\n                sigma = triangulation.RGE_ALTI_ERROR if source == \"RGE ALTI\" else triangulation.LIDAR_ERROR\n                self.nose_ground[key] = (source, sigma, [(x, z - zs[0]) for x, z in zip(offsets, zs[1:])])\n\n        precision.fetch_terrain(points, done)  # synchrone dans les essais, asynchrone dans la page\n        ground = self.nose_ground.get(key)\n        if ground:\n            self.nose_ground_last = (base, ground)\n        return (ground or None), ground == {}\n\n    def _neighbours_here(self):\n        \"\"\"Vrai si la précédente et la suivante de la photo affichée (celles qui existent) sont chargées : l'axe est alors définitif.\"\"\"\n        for rel in (\"prev\", \"next\"):\n            nid = metadata.id_from_href(metadata.item_link(self.item, rel))\n            if nid and nid not in self.neighbours:\n                return False\n        return True\n\n    def nose_line(self, distance=None, rotation=0.0, relief=True):\n        \"\"\"JSON de la droite au sol à `distance` m devant la caméra (None : au-delà du capot, NOSE_DISTANCE), perpendiculaire\n        à l'axe de la séquence à l'endroit de la droite (_nose_axis_at) : {d, virage (écart en degrés entre l'axe à la photo et à la droite, si > 3°, pas affiché), lonlat: [[lon, lat] à -NOSE_REACH, [lon, lat] à +NOSE_REACH] (position recalée de la photo), hauteur, hauteur_source, sigma_h, roulis_campagne, inclinaison_source (_nose_tilt : vue du dessus, clics, verticales, verticales (seuil élargi), lidar, roulis de campagne, aucune), inclinaison_sigma (degrés ou None), inclinaison_en_calcul (verticales pas encore arrivées : droite refaite à leur arrivée), points: [[décalage en m (positif à\n        droite de l'axe de la droite), yaw, pitch]]} (radians, repère de la photo affichée), de -NOSE_REACH à +NOSE_REACH tous les\n        NOSE_STEP m. Les décalages sont des positions horizontales ; le relief est celui du MNT LiDAR HD (_nose_ground) : un point de\n        la droite dont le sol est à dz au-dessus du sol sous la caméra est vu à l'élévation -atan2(H - dz, distance horizontale).\n        Champs du relief : sol (source : « LiDAR HD », « RGE ALTI » ou « plat (relief indisponible) »), sol_sigma (m, None à plat),\n        sol_dz ([[décalage, dz]] tous les 0,5 m, absent à plat), sol_en_lecture (MNT pas encore arrivé : sol plat en attendant, droite\n        refaite à son arrivée). {\"error\": …} sans photo 360°.\n        `rotation` (degrés, borné à ±NOSE_ROTATION_MAX ; positif = sens trigonométrique vu du dessus, donc le côté droit de la droite\n        avance vers l'avant) tourne la droite autour de son point au droit de la caméra (x = 0), dans le plan du sol : direction\n        = direction perpendiculaire à l'axe du trajet tournée de `rotation`. Le relief est lu pour l'angle arrondi à 0,5° ; avec\n        `relief` faux (glissement), aucune lecture n'est lancée : le relief déjà lu à l'angle précédent sert en attendant.\"\"\"\n        item = self.item\n        if not item:\n            return json.dumps({\"error\": \"Aucune photo affichée.\"})\n        if not autotilt.is_360(item):\n            return json.dumps({\"error\": \"Photo non 360° : la droite au sol n'est tracée que sur les photos 360°.\"})\n        height, source, sigma = self.camera_of(item, self.quality)\n        mount = self._fleet_mount(item)\n        d = float(distance) if distance else NOSE_DISTANCE.get(mount, NOSE_DISTANCE_DEFAULT)\n        roll = self._roll_defect(item)\n        up, tilt_source, tilt_sigma = self._nose_tilt(roll)\n        axis = self._nose_axis()  # cap de la caméra : le centre de la droite est à d devant\n        along, turn = self._nose_axis_at(d)  # direction de la droite : perpendiculaire à celle-ci\n        rot = max(-NOSE_ROTATION_MAX, min(NOSE_ROTATION_MAX, float(rotation or 0.0)))\n        along -= rot  # direction de la droite tournée (cap de sa perpendiculaire, rotation positive = sens trigonométrique)\n        gap = math.radians(turn - rot)\n        lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        fixed = self.calibration.position(item.get(\"collection\"), lon, lat)  # position recalée de la séquence, si elle l'est\n        if fixed:\n            lon, lat = fixed[0], fixed[1]\n        ground, reading = self._nose_ground(lon, lat, axis, along + rot - round(rot * 2) / 2, d, relief)\n        dzs = ground[2] if ground else None\n        points = []\n        for k in range(-int(NOSE_REACH / NOSE_STEP), int(NOSE_REACH / NOSE_STEP) + 1):\n            x = k * NOSE_STEP\n            right, forward = x * math.cos(gap), d - x * math.sin(gap)  # repère de la caméra (cap `axis`)\n            dz = 0.0\n            if dzs:\n                f = min(max((x + NOSE_REACH) / NOSE_GROUND_STEP, 0.0), len(dzs) - 1.0)\n                i = min(int(f), len(dzs) - 2)\n                dz = dzs[i][1] + (f - i) * (dzs[i + 1][1] - dzs[i][1])\n            v = self._nose_view(axis + math.degrees(math.atan2(right, forward)),\n                                -math.degrees(math.atan2(height - dz, math.hypot(right, forward))), roll,\n                                up if tilt_source.startswith((\"verticales (seuil\", \"vue du dessus\")) else None)\n            points.append([round(x, 2), round(v[\"yaw\"], 6), round(v[\"pitch\"], 6)])\n        a, b = math.radians(axis), math.radians(along)\n        ends = []  # extrémités (-NOSE_REACH, +NOSE_REACH) de la droite sur la carte : une droite, le reste s'interpole\n        for x in (-NOSE_REACH, NOSE_REACH):\n            east, north = d * math.sin(a) + x * math.cos(b), d * math.cos(a) - x * math.sin(b)\n            ends.append([round(v, 7) for v in triangulation._geographic(east, north, lon, lat)])\n        out = {\"d\": d, \"hauteur\": height, \"hauteur_source\": source, \"sigma_h\": sigma,\n               \"roulis_campagne\": roll, \"inclinaison_source\": tilt_source, \"inclinaison_sigma\": tilt_sigma,\n               \"inclinaison_en_calcul\": self.tilts.pending(item.get(\"id\")), \"points\": points, \"lonlat\": ends, \"reach\": NOSE_REACH,\n               \"voisines\": self._neighbours_here(), \"sol\": ground[0] if ground else NOSE_FLAT,\n               \"sol_sigma\": ground[1] if ground else None, \"sol_en_lecture\": reading}\n        if ground:\n            out[\"sol_dz\"] = [[x, round(z, 3)] for x, z in ground[2]]\n        if abs(turn) > 3.0:\n            out[\"virage\"] = round(turn)  # écart (degrés) entre l'axe à la photo et l'axe à la droite (pas encore affiché)\n        return json.dumps(out)\n",
 "web_pose.py": "# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Pose de la caméra, sortie de web_app.py : inclinaison automatique (raison d'un échec, ticket #29), inclinaison par le\nterrain hors agglomération (expérimentale, web_terrain), monture et défaut de roulis du producteur, pose de la vue du\ndessus (src/dessus.js : photo affichée, voisines, photos à deux pas). Pose est une base de web_app.App : ses méthodes\nlisent l'état de l'application (self).\"\"\"\n\nimport json\nimport math\nfrom urllib.parse import urlencode\n\nimport web_host\nimport web_terrain\nimport web_tilt\nfrom core import autotilt, calibration, host, measures, metadata, precision, roads, triangulation\n\n\ndef _inside(point, ring):\n    \"\"\"Point (lon, lat) dans le polygone ring ([[lon, lat]]) ? Règle du nombre de croisements.\"\"\"\n    x, y, inside = float(point[0]), float(point[1]), False\n    for a, b in zip(ring, ring[1:] + ring[:1]):\n        (x1, y1), (x2, y2) = a[:2], b[:2]\n        if (y1 > y) != (y2 > y) and x < x1 + (y - y1) * (x2 - x1) / (y2 - y1):\n            inside = not inside\n    return inside\n\n\nclass Pose:\n    \"\"\"Inclinaison et pose de la caméra (voir web_app.App).\"\"\"\n\n    # Inclinaison automatique : raison d'un échec (ticket #29) -----------------------------------\n    def _run_tilt(self, function, args, done):\n        \"\"\"Calcul des verticales demandé par autotilt.TiltChecker (à la place de autotilt.estimate) :\n        web_tilt.estimate, dont la raison d'un échec est gardée pour la photo analysée.\"\"\"\n        pic = self.tilts.current\n\n        def got(res):\n            if res and res.get(\"loose\"):\n                self.birdeye_loose[pic] = res[\"loose\"]\n            if res is None or \"reason\" in res:\n                self.tilt_reasons[pic] = (res or {}).get(\"reason\", \"calcul des verticales indisponible\")\n                res = None\n            done(res)\n            if res is None and self.terrain_relay and (self.item or {}).get(\"id\") == pic:\n                self._relay(self.item)\n\n        web_host.run_task(web_tilt.estimate, args, got)\n\n    def _tilt_tried(self, pic):\n        \"\"\"Inclinaison automatique de la photo déjà calculée (ou abandonnée), dans cette session ou\n        une précédente (calage conservé) ? Le cœur ne la lance qu'au premier clic (_check_tilt).\"\"\"\n        return pic in self.calibration.auto or pic in self.tilt_reasons\n\n    def _tilt_final(self):\n        \"\"\"Photo affichée sans inclinaison automatique à attendre : calcul fait, ou impossible.\"\"\"\n        return self._tilt_tried((self.item or {}).get(\"id\")) or not autotilt.is_360(self.item or {})\n\n    def _lights(self, pic):\n        \"\"\"Voyants du cœur ; inclinaison pas encore calculée : « avant » (jaune), pas « non » (rouge,\n        pris pour un échec) ; calcul par le terrain en cours : « attente ».\"\"\"\n        def light_of(name, light):\n            if name != \"Inclinaison\" or light != \"non\":\n                return light\n            return \"attente\" if pic in self.relay_pending else \"non\" if self._tilt_final() else \"avant\"\n        return [(name, light_of(name, light)) for name, light in super()._lights(pic)]\n\n    def _tilt_reason(self):\n        \"\"\"Pourquoi la photo affichée n'a pas d'inclinaison, ou None (calée, en cours) : raison de\n        l'échec, ou moment du calcul s'il n'est pas encore fait (voir _tilt_final).\"\"\"\n        item, pic = self.item or {}, (self.item or {}).get(\"id\")\n        if not pic or self.calibration.tilt(pic) or self.tilts.pending(pic):\n            return None\n        if not autotilt.is_360(item):\n            return \"photo non 360°\"\n        if not self._tilt_tried(pic):\n            if self.mode == \"tri\":\n                return \"pas calculée en mesure libre\"\n            return \"calculée au premier clic sur la photo\" if self.active else \"calculée à l'activation de la mesure\"\n        reason = self.tilt_reasons.get(pic, web_tilt.FEW_EDGES)\n        if self.terrain_relay and pic in self.relay_failed:\n            reason += \" ; par le terrain : \" + self.relay_failed[pic]\n        return reason\n\n    def _tilt_line(self):\n        \"\"\"(texte, alerte) de l'inclinaison dans la ligne d'état. Un seul vocabulaire (ticket #29) :\n        « calée » (par les verticales de la photo, par le terrain, à la main) ou « non calée », avec\n        l'incertitude ; « calcul » pour ce qui est en cours ou à venir.\"\"\"\n        pic = (self.item or {}).get(\"id\")\n        tilt = self.calibration.tilt(pic) if pic else None\n        if tilt:\n            sigma = \"±{}°\".format(measures._num(max(tilt[\"sigma\"], 0.1), 1))\n            source = tilt[\"source\"]\n            if source == \"clics\":\n                how = \"à la main ({} objet{}, {})\".format(tilt[\"count\"], \"s\" if tilt[\"count\"] > 1 else \"\", sigma)\n            elif source.startswith(\"clics + \"):\n                how = \"à la main et par {} ({})\".format(\n                    \"les verticales de la photo\" if source.endswith(\"verticales\") else \"le terrain\", sigma)\n            elif source == \"terrain web\":\n                how = \"par le terrain, expérimental ({})\".format(sigma)\n            else:\n                how = \"par {} ({})\".format(\"les verticales de la photo\" if source == \"verticales\" else \"le terrain\", sigma)\n            return \"inclinaison calée \" + how, False\n        if pic and self.tilts.pending(pic):\n            return \"inclinaison : calcul en cours…\", False\n        if pic in self.relay_pending:\n            return \"inclinaison : calcul par le terrain en cours ({})…\".format(self.relay_pending[pic]), False\n        reason = self._tilt_reason()\n        if not self._tilt_final():\n            return \"inclinaison \" + reason, False\n        return \"inclinaison non calée (±{}°) : {}\".format(\n            measures._num(calibration.UNCALIBRATED, 0), reason), True\n\n    # Inclinaison par le terrain hors agglomération, expérimentale (ticket #29) -------------------\n    # Option de la page, décochée par défaut. Quand les verticales de la photo manquent : terrain\n    # LiDAR HD sous la caméra (web_terrain), plus le décalage de la fixation, appris sur des photos\n    # de la séquence calées par leurs verticales en zone d'habitation.\n    RELAY_RADIUS = 15000.0  # m autour de la photo : zones d'habitation (BD TOPO) où chercher les références\n    RELAY_ZONE = 300.0  # m autour du centre d'une zone : photos de la séquence candidates\n    RELAY_TRIES = 12  # photos de référence analysées au plus par séquence (une photo HD chacune)\n    RELAY_PER_ZONE = 3  # photos analysées au plus par zone : le centre du village n'est pas toujours la meilleure\n    RELAY_NATURES = (\"Lieu-dit habité\", \"Quartier\")\n\n    def set_terrain_relay(self, on):\n        \"\"\"Option « Inclinaison par le terrain hors agglomération » : cochée, calcul lancé pour la photo\n        affichée si ses verticales ont déjà échoué ; mesures recalculées dans les deux sens.\"\"\"\n        self.terrain_relay = bool(on)\n        if self.terrain_relay and self.item and self.item.get(\"id\") in self.tilt_reasons:\n            self._relay(self.item)\n        self._calibration_changed()\n        self.notify()\n        return self.status()\n\n    def _auto_tilt(self, pic):\n        \"\"\"Calibration.auto_tilt : celle du cœur (verticales, modèle LiDAR du cœur), sinon, l'option\n        cochée, l'inclinaison par le terrain de la page.\"\"\"\n        tilt = self._core_auto_tilt(pic)\n        if tilt is None and self.terrain_relay:\n            tilt = self.relay_tilts.get(pic)\n        return tilt\n\n    def _relay(self, item):\n        \"\"\"Inclinaison par le terrain de la photo item (fiche STAC) : terrain sous elle, puis modèle de\n        sa séquence ; rangée dans relay_tilts, ou la raison de l'échec dans relay_failed.\"\"\"\n        pic = item.get(\"id\")\n        if not pic or pic in self.relay_tilts or pic in self.relay_pending:\n            return\n        self.relay_failed.pop(pic, None)\n        self.relay_pending[pic] = \"terrain sous la photo\"\n\n        def failed(reason):\n            self.relay_pending.pop(pic, None)\n            self.relay_failed[pic] = reason\n            self.notify()\n\n        def got_own(entry, reason):\n            if entry is None:\n                return failed(reason)\n            self.relay_pending[pic] = \"photos de référence de la séquence\"\n            self.notify()\n            self._sequence_model(item, lambda m, why: got_model(entry, m, why))\n\n        def got_model(entry, m, reason):\n            if m is None:\n                return failed(reason)\n            self.relay_pending.pop(pic, None)\n            self.relay_tilts[pic] = web_terrain.predict(m, entry[\"slopes\"], entry[\"heading\"])\n            self._calibration_changed({pic})\n            self.notify()\n\n        self._terrain_of(item, got_own)\n        self.notify()\n\n    @staticmethod\n    def _heading_of(item):\n        heading = metadata.precise_heading(item)\n        return metadata.item_heading(item) if heading is None else heading\n\n    def birdeye_request(self):\n        \"\"\"Vue du dessus demandée sur la photo affichée : son inclinaison automatique est lancée\n        (une fois par photo : Calibration.auto la garde, sinon ce sont les clics qui la relancent).\"\"\"\n        if self.item and autotilt.is_360(self.item):\n            pic = self.item.get(\"id\")\n            before = self.calibration.auto.get(pic)\n            self.tilts.check(self.item, self.calibration, lambda: self._birdeye_tilt_done(pic, before))\n            self._birdeye_relook(self.item)\n\n    def _birdeye_relook(self, item):\n        \"\"\"Photo déjà analysée sans verticales retenues (calage gardé d'une séance précédente : l'analyse\n        n'est pas refaite) : refaite une fois pour la vue du dessus, pour ses verticales moins sûres\n        (web_tilt.LOOSE_SIGMA).\"\"\"\n        pic, entry = item.get(\"id\"), self.calibration.auto.get(item.get(\"id\"))\n        href = ((item.get(\"assets\") or {}).get(\"hd\") or {}).get(\"href\")\n        if not href or entry is None or entry.get(\"verticals\") is not None or pic in self.birdeye_loose:\n            return\n        self.birdeye_loose[pic] = None  # en cours (ou sans résultat) : pas relancée\n        heading = metadata.precise_heading(item)\n        heading = metadata.item_heading(item) if heading is None else heading\n\n        def got_estimate(res):\n            if res and res.get(\"loose\"):\n                self.birdeye_loose[pic] = res[\"loose\"]\n                self.notify()\n\n        def got_image(data, error):\n            if not error and data and heading is not None:\n                web_host.run_task(web_tilt.estimate, (bytes(data), float(heading)), got_estimate)\n\n        host.fetch(href, got_image, prefer_cache=True)\n\n    def _birdeye_tilt_done(self, pic, before):\n        \"\"\"Analyse d'une photo de la vue du dessus finie : la page est prévenue même sans inclinaison\n        nouvelle (_on_tilt se tait alors : verticales et LiDAR en échec), sinon elle attend la photo\n        sans fin.\"\"\"\n        if self.calibration.auto.get(pic) == before:\n            self.notify()\n        else:\n            self._on_tilt(pic, before)\n\n    def birdeye_neighbours(self, items_json):\n        \"\"\"Photos voisines de la vue du dessus (fiches STAC, photo précédente puis suivante) : leur\n        inclinaison est lancée à part, chacune son vérificateur (TiltChecker n'en suit qu'une).\"\"\"\n        self.birdeye_items = json.loads(items_json)\n\n        def runner(pic):\n            def got(res, done):\n                if res and res.get(\"loose\"):\n                    self.birdeye_loose[pic] = res[\"loose\"]\n                done(None if res is None or \"reason\" in res else res)\n            return lambda function, args, done: web_host.run_task(web_tilt.estimate, args, lambda res: got(res, done))\n\n        for item, checker in zip(self.birdeye_items, self.birdeye_checks):\n            pic = item.get(\"id\")\n            checker.run = runner(pic)\n            before = self.calibration.auto.get(pic)\n            checker.check(item, self.calibration, lambda pic=pic, before=before: self._birdeye_tilt_done(pic, before))\n            self._birdeye_relook(item)\n\n    def birdeye_far(self, items_json):\n        \"\"\"Photos à deux pas de la vue du dessus (fiches STAC, avant la précédente et après la suivante) : leur raccord à\n        la photo affichée sert seulement à lire le tangage (src/dessus.js, learnPitch), inclinées par la route, sans\n        inclinaison lancée pour elles.\"\"\"\n        self.birdeye_far_items = json.loads(items_json)\n\n    def _birdeye_of(self, item, pending):\n        \"\"\"Pose d'une photo pour la vue du dessus (voir birdeye_pose), ou None sans position, sans\n        cap ou hors 360°.\"\"\"\n        heading = self._heading_of(item)\n        if not autotilt.is_360(item) or heading is None:\n            return None\n        try:\n            lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        except (KeyError, TypeError, ValueError):\n            return None\n        pic, sequence, cal, q = item.get(\"id\"), item.get(\"collection\"), self.calibration, self.quality or {}\n        fixed, pose, tilt, cam = cal.position(sequence, lon, lat), cal.pose(sequence, lon, lat), cal.tilt(pic), cal.camera(sequence)\n        loose = self.birdeye_loose.get(pic)  # verticales moins sûres : mieux que la pente de la route, ou que le relais par le\n        if loose and (not tilt or loose[\"sigma\"] < tilt[\"sigma\"]):  # terrain (±0,5°, sans le véhicule penché en virage)\n            tilt = loose\n        verified = q.get(\"precise\") and q.get(\"lidar\") is True\n        return {\"pic\": pic, \"lon\": fixed[0] if fixed else lon, \"lat\": fixed[1] if fixed else lat,\n                \"heading\": float(heading), \"offset\": pose[\"offset\"] if pose else 0.0,\n                \"up\": list(tilt[\"up\"]) if tilt else None,\n                \"sigma\": tilt[\"sigma\"] if tilt else calibration.UNCALIBRATED,\n                \"pending\": pending(pic), \"height\": self._camera_height(mount=False),\n                \"height_sigma\": max(q.get(\"spread\") or 0, 0.05) if verified else cam[\"sigma\"] if cam else 0.3,\n                \"relative_sigma\": 0.05 if verified else 0.3,  # position d'une photo à sa voisine (trajectoire)\n                \"fleet\": any(p.get(\"id\") == self.FLEET_PRODUCER for p in item.get(\"providers\") or []),\n                \"roll_defect\": self._roll_defect(item), \"mount\": self._fleet_mount(item)}\n\n    def birdeye_pose(self):\n        \"\"\"Pose de la photo affichée pour la vue du dessus (src/dessus.js), en JSON : position\n        (recalée si la séquence l'est), cap du centre de l'image, correction de cap de la séquence\n        (degrés), verticale vraie vue de la caméra (None sans calage) et son incertitude (degrés),\n        hauteur de caméra, son incertitude et celle de la position relative entre photos voisines (m) ;\n        neighbours : les poses des photos voisines ; far : celles à deux pas (birdeye_far) ; bridge : pont à portée\n        de la vue (None en lecture), la vue se passe alors du terrain LiDAR et la hauteur de caméra ne vient pas du\n        sol LiDAR. null si la photo ne convient pas.\"\"\"\n        pose = self._birdeye_of(self.item, self.tilts.pending) if self.item else None\n        if pose is None:\n            return \"null\"\n        near = [p for p in (self._birdeye_of(item, checker.pending)\n                            for item, checker in zip(self.birdeye_items, self.birdeye_checks)) if p]\n        bridge = self._near_bridge(pose[\"lon\"], pose[\"lat\"])\n        if bridge:  # altitude RTK moins sol LiDAR : le sol sous le pont, ou la brèche sous la photo\n            cam, mount = self.calibration.camera(self.item.get(\"collection\")), self._fleet_mount(self.item)\n            height = ({\"height\": cam[\"height\"], \"height_sigma\": cam[\"sigma\"]} if cam\n                      else {\"height\": mount, \"height_sigma\": self.MOUNT_SIGMA} if mount\n                      else {\"height\": self.tool.camera_height, \"height_sigma\": 0.3})\n            pose.update(height)\n            near = [dict(p, **height) for p in near]\n        far = [p for p in (self._birdeye_of(item, lambda pic: False) for item in self.birdeye_far_items) if p]\n        if bridge:\n            far = [dict(p, **height) for p in far]\n        return json.dumps(dict(pose, neighbours=near, far=far, bridge=bridge))\n\n    BIRDEYE_BRIDGE = 20.0  # m : portée de la vue (15 m) et un peu plus\n    FLEET_PRODUCER = \"8f943f10-a781-4e03-a18c-de035be6f6f8\"  # CD21 : imajbox sur Clio 5, deux montures (voir src/dessus.js, MOUNTS)\n    # Défaut de roulis de la caméra par rapport à la route, par producteur et campagne de prise de vue : (producteur, premier\n    # jour, jour de fin exclu, degrés ajoutés au roulis tiré du dévers, signe de groundUp dans src/dessus.js). Seulement pour\n    # l'inclinaison par la route de la vue du dessus ; à mesurer pour chaque campagne ou producteur, sur des passages piétons\n    # (docs/BIRDEYE.md § 4.1). CD21, campagne 2025 (tests/passages-pietons.js, 13/11/2026) : roulis restant de +0,98° en\n    # médiane sur 23 vues, sans lien avec le dévers ni avec la monture, nul avec les verticales ; -1° le ramène près de 0.\n    ROLL_DEFECTS = ((FLEET_PRODUCER, \"2025-01-01\", \"2026-01-01\", -1.0),)\n\n    # Monture de la caméra du CD21 par date de prise de vue (premier jour, jour de fin exclu, hauteur en m) : hauteur de caméra\n    # de la vue du dessus (pose « mount »), avant la hauteur lue entre photos, qui se joue à quelques cm du seuil entre les deux\n    # montures, et sur un pont, où ni le sol LiDAR ni la lecture sans verticales ne la donnent (sinon 1,90 m par défaut : bandes\n    # de passage piéton à 0,44 m au lieu de 0,50, f2a245d0-aeea-4249-ba9c-fad83b442a23 et\n    # 7dcdccf9-3c52-4c54-bc5b-de72740a7967, 13/11/2026). Hauteurs de src/dessus.js (MOUNTS) :\n    # basse lue du 28/05 au 23/06/2025, haute dès le 03/07. shortcut: limite du 01/07 prise entre les deux (hauteurs\n    # et dates de montage non disponibles : prises de vue d'un prestataire)\n    FLEET_MOUNTS = ((\"2025-01-01\", \"2025-07-01\", 1.93), (\"2025-07-01\", \"2026-01-01\", 2.07))\n    MOUNT_SIGMA = 0.04  # m : comme src/dessus.js (MOUNT_SIGMA)\n    # Colonne camera_calee de l'export des mesures : 0 réglage, 1 calée, 2 altitude GPS (measures.CAMERA_SOURCES), 3 monture\n    CAMERA_CODES = {**measures.CAMERA_SOURCES, \"monture\": 3}\n\n    def _fleet_mount(self, item):\n        \"\"\"Hauteur de la monture du CD21 (FLEET_MOUNTS) à la date de prise de vue de la photo, ou None.\"\"\"\n        date = str((item.get(\"properties\") or {}).get(\"datetime\") or \"\")[:10]\n        if not any(p.get(\"id\") == self.FLEET_PRODUCER for p in item.get(\"providers\") or []):\n            return None\n        return next((h for first, end, h in self.FLEET_MOUNTS if first <= date < end), None)\n\n    def _mount_height(self, item):\n        \"\"\"Monture du CD21 d'après la date (FLEET_MOUNTS) : (hauteur, MOUNT_SIGMA), ou None (voir Session.camera_of).\"\"\"\n        mount = self._fleet_mount(item)\n        return (mount, self.MOUNT_SIGMA) if mount else None\n\n    def _roll_defect(self, item):\n        \"\"\"Défaut de roulis (degrés, ROLL_DEFECTS) du producteur de la photo à sa date de prise de vue, ou 0.\"\"\"\n        date = str((item.get(\"properties\") or {}).get(\"datetime\") or \"\")[:10]\n        producers = {p.get(\"id\") for p in item.get(\"providers\") or []}\n        return next((roll for who, first, end, roll in self.ROLL_DEFECTS if who in producers and first <= date < end), 0.0)\n\n    def _near_bridge(self, lon, lat):\n        \"\"\"Tronçon BD TOPO en pont à moins de BIRDEYE_BRIDGE m de la photo, dessus ou dessous : le MNT LiDAR\n        n'y donne pas le sol vu par la caméra (tablier retiré). None en lecture ; BD TOPO injoignable : False.\"\"\"\n        sections = self._fall_sections(lon, lat)\n        if sections is roads.PENDING:\n            return None\n        return any(sec.get(\"level\", 0) > 0 and roads._project(\n            [triangulation._local(q[0], q[1], lon, lat) for q in sec[\"line\"]], 0.0, 0.0)[0] <= self.BIRDEYE_BRIDGE\n            for sec in sections or [])\n\n    def _terrain_of(self, item, done):\n        \"\"\"Terrain sous la photo item : done({slopes, heading}, None), ou done(None, raison). Grille\n        LiDAR HD (web_terrain.grid_points), une requête.\"\"\"\n        try:\n            lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n            heading = float(self._heading_of(item))\n        except (KeyError, TypeError, ValueError):\n            return done(None, \"position ou cap de la photo inconnus\")\n        points = web_terrain.grid_points(lon, lat, heading)\n\n        def got_ground(data, error):\n            if error:\n                return done(None, \"service d'altitude injoignable\")\n            z = precision._ground(data)\n            if not z or len(z) != len(points) or None in z:\n                return done(None, \"pas de LiDAR HD sous la photo\")\n            done({\"slopes\": web_terrain.slopes(z), \"heading\": heading}, None)\n\n        host.fetch_json(precision.lidar_url(points, precision.LIDAR_RESOURCE), got_ground, timeout_ms=15000)\n\n    def _sequence_model(self, item, done):\n        \"\"\"Modèle de la séquence de item (web_terrain.model) : done(modèle, None) ou done(None, raison).\n        Cherché une fois par séquence, les demandes suivantes attendent le même calcul.\"\"\"\n        seq = item.get(\"collection\")\n        s = self.relay_models.get(seq)\n        if s is None:\n            s = self.relay_models[seq] = {\"waiting\": [done], \"refs\": [], \"tried\": 0, \"zones\": None}\n            self._find_refs(item, s)\n        elif \"waiting\" in s:\n            s[\"waiting\"].append(done)\n        else:\n            done(s[\"model\"], s[\"reason\"])\n\n    def _find_refs(self, item, s):\n        \"\"\"Références de la séquence (s, voir _sequence_model) : jusqu'à RELAY_PER_ZONE photos par zone\n        d'habitation (réparties dans la zone), des zones les plus proches aux plus lointaines, calées\n        par leurs verticales, jusqu'à web_terrain.MIN_REFS réussies ou RELAY_TRIES analysées.\"\"\"\n        lon, lat = (float(v) for v in item[\"geometry\"][\"coordinates\"][:2])\n        seq = item.get(\"collection\")\n\n        def progress():\n            text = \"photos de référence : {} calée{} sur {} analysée{}\".format(\n                len(s[\"refs\"]), \"s\" if len(s[\"refs\"]) > 1 else \"\", s[\"tried\"], \"s\" if s[\"tried\"] > 1 else \"\")\n            for p in self.relay_pending:\n                self.relay_pending[p] = text\n            self.notify()\n\n        def finish(reason):\n            s[\"model\"] = web_terrain.model(s[\"refs\"])\n            s[\"reason\"] = None if s[\"model\"] else reason\n            for cb in s.pop(\"waiting\"):\n                cb(s[\"model\"], s[\"reason\"])\n\n        queue = []  # photos de la zone en cours, à analyser\n\n        def next_zone():\n            if len(s[\"refs\"]) >= web_terrain.MIN_REFS:\n                return finish(None)\n            if queue and s[\"tried\"] < self.RELAY_TRIES:\n                return analyse(queue.pop(0))\n            if s[\"tried\"] >= self.RELAY_TRIES or not s[\"zones\"]:\n                return finish(\"{} photo{} de village calée{} sur {} (il en faut {})\".format(\n                    len(s[\"refs\"]), \"s\" if len(s[\"refs\"]) > 1 else \"\", \"s\" if len(s[\"refs\"]) > 1 else \"\",\n                    s[\"tried\"], web_terrain.MIN_REFS))\n            ring, (clon, clat) = s[\"zones\"].pop(0)\n            host.fetch_json(metadata.search_url(clon, clat, self.RELAY_ZONE, 100, seq, host.api_url),\n                            lambda data, error: got_photos(ring, clon, clat, data, error), timeout_ms=15000)\n\n        def got_photos(ring, clon, clat, data, error):\n            feats = [f for f in ([] if error else (data or {}).get(\"features\") or [])\n                     if f.get(\"collection\") == seq and f.get(\"id\") != item.get(\"id\")\n                     and _inside(f[\"geometry\"][\"coordinates\"][:2], ring)]\n            feats.sort(key=lambda f: math.hypot(f[\"geometry\"][\"coordinates\"][0] - clon,\n                                                f[\"geometry\"][\"coordinates\"][1] - clat))\n            n = self.RELAY_PER_ZONE\n            queue[:] = [feats[k * len(feats) // n] for k in range(n) if k * len(feats) // n < len(feats)]\n            queue[:] = [f for k, f in enumerate(queue) if f not in queue[:k]]\n            next_zone()\n\n        def analyse(f):\n            href = ((f.get(\"assets\") or {}).get(\"hd\") or {}).get(\"href\")\n            if not href:\n                return next_zone()\n            s[\"tried\"] += 1\n            progress()\n            host.fetch(href, lambda data, error: got_image(f, data, error), prefer_cache=True)\n\n        def got_image(f, data, error):\n            if error or not data:\n                return next_zone()\n            heading = float(self._heading_of(f))\n            web_host.run_task(web_tilt.estimate, (bytes(data), heading), lambda res: got_verticals(f, heading, res))\n\n        def got_verticals(f, heading, res):\n            if not res or \"reason\" in res:\n                return next_zone()\n            forward, right = calibration.tilt_components(res[\"up\"], heading)\n\n            def got_ground(entry, reason):\n                if entry is not None:\n                    s[\"refs\"].append(dict(entry, forward=forward, right=right))\n                    progress()\n                next_zone()\n            self._terrain_of(f, got_ground)\n\n        def got_zones(data, error):\n            if error:\n                return finish(\"BD TOPO injoignable (zones d'habitation)\")\n            zones = []\n            for z in (data or {}).get(\"features\") or []:\n                if (z.get(\"properties\") or {}).get(\"nature\") not in self.RELAY_NATURES:\n                    continue\n                g = z.get(\"geometry\") or {}\n                polys = g.get(\"coordinates\") or []\n                ring = max((p[0] for p in (polys if g.get(\"type\") == \"MultiPolygon\" else [polys]) if p), key=len,\n                           default=None)\n                if ring:\n                    c = (sum(p[0] for p in ring) / len(ring), sum(p[1] for p in ring) / len(ring))\n                    zones.append((ring, c))\n            zones.sort(key=lambda z: math.hypot((z[1][0] - lon) * math.cos(math.radians(lat)), z[1][1] - lat))\n            s[\"zones\"] = zones\n            next_zone()\n\n        dlat = self.RELAY_RADIUS / 111320.0\n        dlon = dlat / max(math.cos(math.radians(lat)), 0.01)\n        url = roads.WFS_URL + \"?\" + urlencode({\n            \"SERVICE\": \"WFS\", \"VERSION\": \"2.0.0\", \"REQUEST\": \"GetFeature\", \"TYPENAMES\": \"BDTOPO_V3:zone_d_habitation\",\n            \"OUTPUTFORMAT\": \"application/json\", \"SRSNAME\": \"EPSG:4326\", \"COUNT\": 500,\n            \"BBOX\": \"{},{},{},{},urn:ogc:def:crs:EPSG::4326\".format(lat - dlat, lon - dlon, lat + dlat, lon + dlon)})\n        host.fetch_json(url, got_zones, timeout_ms=20000)\n",
 "web_terrain.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Inclinaison par le terrain hors agglomération, expérimentale (ticket #29), sans toucher au cœur.\n\nQuand les verticales de la photo manquent (rase campagne), l'inclinaison de la caméra est prise\négale à la pente et au dévers du terrain sous elle (MNT LiDAR HD), plus le décalage de sa fixation\nsur le véhicule :\n\n- terrain : plan ajusté sur une grille de GRID_ALONG × GRID_ACROSS m autour de la caméra (plus\n  large que celle du cœur, calibration.LIDAR_GRID : moins sensible aux bordures et aux bosses) ;\n- décalage : appris sur des photos de la même séquence calées par leurs verticales (références,\n  prises en zone d'habitation, où les verticales réussissent).\n\nMesures du 24/10/2026 (docs/GUIDE.md, « Précision ») : 14 photos témoins hors des villages de référence\n(hameaux, sorties de village, 56 à 67 km/h), calées par leurs verticales : dévers à ±0,6°, pente\nà ±0,5° (±1,2° et ±1,6° sans terrain ; ±0,8° et ±0,6° avec la grille du cœur). Le roulis en virage\nn'est pas corrigé : la correction tirée des photos de village (3 à 6°/g) aggravait le seul virage\ntémoin (0,3 g : +0,4° d'écart sans elle, −1,1° avec). LiDAR HD seul : le RGE ALTI prend talus et\nmurs pour la route.\n\"\"\"\n\nimport math\n\nfrom core import calibration\n\nGRID_ALONG = [k * 0.5 for k in range(-5, 6)]  # m en avant de la caméra : −2,5 à +2,5\nGRID_ACROSS = [-1.5, -0.8, 0.0, 0.8, 1.5]  # m à droite\nMIN_REFS = 3  # photos de référence calées pour apprendre le décalage\nSIGMA_MIN = 0.6  # degrés : incertitude au moins égale à l'écart mesuré sur les témoins (dévers)\n\n\ndef grid_points(lon, lat, heading):\n    \"\"\"Points du sol où lire le LiDAR HD : grille GRID_ALONG × GRID_ACROSS (en avant, à droite).\"\"\"\n    out = []\n    for along in GRID_ALONG:\n        p = calibration.offset(lon, lat, heading, along) if along else (lon, lat)\n        for right in GRID_ACROSS:\n            out.append(calibration.offset(p[0], p[1], heading + 90, right) if right else p)\n    return out\n\n\ndef slopes(z):\n    \"\"\"(pente en long, dévers) en degrés du plan ajusté sur les altitudes de grid_points (grille\n    symétrique : moyennes pondérées indépendantes ; mêmes signes que calibration.lidar_slopes).\"\"\"\n    cells = [(a, c) for a in GRID_ALONG for c in GRID_ACROSS]\n    sa = sum(a * h for (a, _), h in zip(cells, z)) / sum(a * a for a, _ in cells)\n    sc = sum(c * h for (_, c), h in zip(cells, z)) / sum(c * c for _, c in cells)\n    return math.degrees(math.atan(sa)), math.degrees(math.atan(sc))\n\n\ndef residual(entry):\n    \"\"\"(avant, droite) en degrés : inclinaison de la caméra moins terrain (fixation).\"\"\"\n    return entry[\"forward\"] - entry[\"slopes\"][0], entry[\"right\"] - entry[\"slopes\"][1]\n\n\ndef model(refs):\n    \"\"\"Décalage de la fixation (avant, droite), son incertitude sigma (degrés) et le nombre de\n    références, d'après les références calées de la séquence (dicts forward, right, slopes) ; None\n    s'il y en a moins de MIN_REFS.\"\"\"\n    if len(refs) < MIN_REFS:\n        return None\n    res = [residual(r) for r in refs]\n    n = len(res)\n    mf, mr = sum(r[0] for r in res) / n, sum(r[1] for r in res) / n\n    spread = math.sqrt(sum((r[0] - mf) ** 2 + (r[1] - mr) ** 2 for r in res) / (2 * max(n - 1, 1)))\n    return {\"offset\": (mf, mr), \"sigma\": max(spread, SIGMA_MIN), \"count\": n}\n\n\ndef predict(m, slope, heading):\n    \"\"\"Inclinaison de la caméra (dict comme calibration.Calibration.auto_tilt) d'après le modèle m\n    et le terrain sous la photo (slopes).\"\"\"\n    f = slope[0] + m[\"offset\"][0]\n    r = slope[1] + m[\"offset\"][1]\n    up = calibration.up_from_components(f, r, heading)\n    return {\"up\": up, \"tilt\": math.degrees(math.acos(min(1.0, up[2]))),\n            \"toward\": math.degrees(math.atan2(up[0], up[1])) % 360, \"residual\": None, \"partial\": False,\n            \"count\": m[\"count\"], \"sigma\": m[\"sigma\"], \"source\": \"terrain web\"}\n\n\nif __name__ == \"__main__\":  # contrôles : plan incliné retrouvé, modèle et prédiction cohérents\n    z = [0.05 * a - 0.02 * c for a in GRID_ALONG for c in GRID_ACROSS]\n    s = slopes(z)\n    assert abs(s[0] - math.degrees(math.atan(0.05))) < 1e-9 and abs(s[1] - math.degrees(math.atan(-0.02))) < 1e-9\n    refs = [{\"forward\": 1.0 + k * 0.1, \"right\": 0.5, \"slopes\": (k * 0.1, 0.0)} for k in range(3)]\n    m = model(refs)\n    assert abs(m[\"offset\"][0] - 1.0) < 1e-9 and abs(m[\"offset\"][1] - 0.5) < 1e-9 and m[\"sigma\"] == SIGMA_MIN\n    t = predict(m, (2.0, 1.0), 30.0)\n    f, r = calibration.tilt_components(t[\"up\"], 30.0)\n    assert abs(f - 3.0) < 1e-6 and abs(r - 1.5) < 1e-6\n    print(\"web_terrain : contrôles réussis\")\n",
 "web_tilt.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Inclinaison automatique avec la raison d'un échec (ticket #29), sans toucher au cœur.\n\nautotilt.estimate ne dit pas pourquoi il échoue : estimate refait son calcul et, s'il échoue,\nle refait sans les seuils de autotilt.fit (nombre de segments, incertitude, inclinaison\nmaximale) pour savoir lequel a refusé. Calculé dans le Pyodide d'arrière-plan\n(web_host.run_task), qui a numpy.\n\"\"\"\n\nimport math\n\nfrom core import autotilt, calibration, host\n\nFEW_EDGES = \"pas assez d'arêtes verticales dans la photo\"  # raison la plus courante (campagne)\n# Vue du dessus : verticales refusées pour les mesures (incertitude au-delà de autotilt.MAX_SIGMA) mais gardées jusqu'à\n# LOOSE_SIGMA (degrés), mieux que la pente de la route (±1°, sans le véhicule penché en virage). Giratoire b47b4351\n# (08/11/2026) : 73 segments à ±0,42°, roulis de 3,0° contre 0,95° par la route ; largeur 8,06 m pour 8,0 m mesurés\n# sur le terrain (9,08 m par la route).\nLOOSE_SIGMA = 0.5\n\n\ndef estimate(data, azimuth):\n    \"\"\"Comme autotilt.estimate, mais un échec rend {\"reason\": texte court} au lieu de None, avec\n    \"loose\" ({up, sigma}) si les verticales passent à LOOSE_SIGMA près (vue du dessus seulement).\"\"\"\n    band = host.decode_band(data, autotilt.WIDTH, autotilt.ELEV_MIN, autotilt.ELEV_MAX)\n    if band is None:\n        return {\"reason\": \"photo HD illisible\"}\n    pairs = autotilt.segments(*band, azimuth)\n    res = autotilt.fit(pairs)\n    if res:\n        return res\n    limits = autotilt.MIN_SEGMENTS, autotilt.MAX_SIGMA, calibration.MAX_TILT\n    autotilt.MIN_SEGMENTS, autotilt.MAX_SIGMA, calibration.MAX_TILT = 3, math.inf, 90.0\n    try:\n        loose = autotilt.fit(pairs)\n    finally:\n        autotilt.MIN_SEGMENTS, autotilt.MAX_SIGMA, calibration.MAX_TILT = limits\n    # Dans l'ordre des refus de autotilt.fit ; arêtes trop peu nombreuses ou trop imprécises : même\n    # texte pour l'utilisateur\n    if loose is not None and loose[\"count\"] >= limits[0] and loose[\"sigma\"] <= limits[1]:\n        return {\"reason\": \"inclinaison trouvée trop forte\"}\n    if loose is not None and loose[\"count\"] >= limits[0] and loose[\"sigma\"] <= LOOSE_SIGMA and loose[\"tilt\"] <= limits[2]:\n        return {\"reason\": FEW_EDGES, \"loose\": {\"up\": list(loose[\"up\"]), \"sigma\": loose[\"sigma\"]}}\n    return {\"reason\": FEW_EDGES}\n\n",
 "web_worker.py": "# -*- coding: utf-8 -*-\n# SPDX-FileCopyrightText: 2026 Cédric COCHART\n# SPDX-License-Identifier: GPL-2.0-or-later\n\"\"\"Calculs lourds de la page, dans un second Pyodide en arrière-plan (Web Worker, voir\nsrc/calcul.js) : la page reste fluide pendant l'analyse d'une photo HD.\n\n- call : fonction d'un module du cœur (inclinaison automatique : autotilt.estimate),\n  demandée par web_host.run_task ;\n- capture : capture HD de la vue (core/capture.py), en JPEG.\n\nLes photos sont décodées par Pillow : réduites dès le décodage (mise à l'échelle du JPEG),\ncomme QImageReader dans le plugin.\n\"\"\"\n\nimport base64\nimport importlib\nimport io\nimport json\n\nfrom core import host\n\ntry:\n    from pyodide.ffi import JsProxy\nexcept ImportError:  # hors du navigateur (essais)\n    JsProxy = ()\n\nCAPTURE_WIDTH = 6144  # largeur de travail de la photo source d'une capture (HD imajbox : 12 288)\n\n\ndef _open(data, width, gray=False):\n    \"\"\"Image Pillow réduite à environ `width` de large dès le décodage ; gray : décodée\n    directement en niveaux de gris (JPEG : luminance seule, plus rapide).\"\"\"\n    from PIL import Image\n\n    img = Image.open(io.BytesIO(_python(data)))\n    w, h = img.size\n    mode = \"L\" if gray else (img.mode if img.mode in (\"L\", \"RGB\") else \"RGB\")\n    if w > width or gray:\n        img.draft(mode, (min(width, w), round(min(width, w) * h / w)))\n    return img\n\n\ndef decode_band(data, width, elev_min, elev_max):\n    \"\"\"Voir core/host.py : photo équirectangulaire en niveaux de gris, réduite et rognée.\"\"\"\n    import numpy as np\n    from PIL import Image\n\n    try:\n        img = _open(data, width, gray=True)\n    except Exception:\n        return None\n    full_w, full_h = img.size\n    if full_w < 2 * full_h - 2:\n        return None  # pas une photo équirectangulaire\n    w = min(width, full_w)\n    h = round(w * full_h / full_w)\n    img = img.convert(\"L\")\n    if img.size != (w, h):\n        img = img.resize((w, h), Image.Resampling.BILINEAR)\n    row0, row1 = int((90 - elev_max) / 180 * h), int((90 - elev_min) / 180 * h)\n    band = np.asarray(img.crop((0, row0, w, row1)), dtype=np.float32)\n    return band, row0, h, w\n\n\ndef _python(value):\n    \"\"\"Valeur venue du navigateur en Python : octets (Uint8Array) en bytes, tableaux en listes.\"\"\"\n    if isinstance(value, JsProxy):\n        value = value.to_py()\n    return bytes(value) if isinstance(value, (memoryview, bytearray)) else value\n\n\ndef _plain(value):\n    \"\"\"Résultat converti en types JSON (numpy compris).\"\"\"\n    if isinstance(value, dict):\n        return {k: _plain(v) for k, v in value.items()}\n    if isinstance(value, (list, tuple)):\n        return [_plain(v) for v in value]\n    if hasattr(value, \"tolist\"):\n        return value.tolist()\n    return value\n\n\ndef call(module, name, args):\n    \"\"\"module.name(*args) ; résultat en texte JSON.\"\"\"\n    function = getattr(importlib.import_module(module), name)\n    args = [_python(a) for a in _python(args)]\n    return json.dumps(_plain(function(*args)))\n\n\ndef capture(data, azimuth, is360, heading, pitch, vfov, photo_hfov, up):\n    \"\"\"Capture HD de la vue (voir core/capture.py) : JPEG en base64, ou \"\" si la photo est\n    illisible. Les cartouches (attribution, localisation) sont ajoutés par la page, avec les\n    polices du navigateur (accents compris).\"\"\"\n    import numpy as np\n    from PIL import Image\n\n    from core import capture as calc\n\n    try:\n        img = _open(data, CAPTURE_WIDTH).convert(\"RGB\")\n    except Exception:\n        return \"\"\n    is360 = bool(is360) or img.size[0] >= 1.9 * img.size[1]\n    up = list(_python(up)) if up else None\n    out = calc.render_view(np.asarray(img), azimuth, is360, heading, pitch, vfov,\n                           None if is360 else photo_hfov, up=up)\n    view = Image.fromarray(np.clip(out, 0, 255).astype(np.uint8), \"RGB\")\n    buf = io.BytesIO()\n    view.save(buf, \"JPEG\", quality=92)\n    return base64.b64encode(buf.getvalue()).decode(\"ascii\")\n\n\nhost.install(decode_band=decode_band)\n"
};
